INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aget-framework/template-consultant-aget/aget-check-evolution', 'aget-check-evolution', 'aget-framework', 'template-consultant-aget', 'community', 'aget-check-evolution aget-framework template-consultant-aget community aget-check-evolution provides AI agents with self-diagnostic capabilities to assess .aget/evolution directory health. It checks file counts, types, naming conventions, and disk usage for optimal performance. aget-check-evolution是一种自诊断能力，用于监控.aget/evolution目录的健康状况，包括文件数量、类型、命名约定和磁盘使用情况 aget-check-evolutionは、.aget/evolutionディレクトリのヘルスをチェックする自診断能力です。ファイル数、タイプ、命名規則、ディスク使用状況を監視します aget-check-evolution은 .aget/evolution 디렉토리의 건강 상태를 진단하는 기능으로, 파일 수, 유형,命名 규칙, 디스크 사용량을 모니터링 합니다 aget-check-evolution es una herramienta para monitorear la salud del directorio .aget/evolution, que verifica el número de archivos, los tipos de archivos y el uso del disco aget-check-evolution est un outil pour surveiller la santé du répertoire .aget/evolution, qui vérifie le nombre de fichiers, les types de fichiers et l''utilisation du disque aget-check-evolution ist ein Tool zur Überwachung der Gesundheit des Verzeichnisses .aget/evolution, das die Anzahl der Dateien, die Dateitypen und die Disknutzung überprüft O aget-check-evolution é uma ferramenta de monitoramento que verifica a saúde do diretório .aget/evolution, contando arquivos e verificando convenções de nomenclatura. Aget-check-evolution - это инструмент мониторинга, который проверяет здоровье директории .aget/evolution, считая файлы и проверяя соглашения об именах. aget-check-evolution هو أداة مراقبة تحقق من صحة الدليل .aget/evolution، وتحسب الملفات وتتحقق من الاتفاقيات المتبعة في التسمية. how to use aget-check-evolution aget-check-evolution setup guide what is aget-check-evolution aget-check-evolution alternative aget-check-evolution vs advisor archetype aget-check-evolution install directory health monitoring for AI agents bash commands for file inventory checks self-diagnostic capabilities for AI agents aget-check-evolution AI工具 自诊断能力 监控.aget/evolution目录 文件数量监控 文件类型检查 命名约定验证 磁盘使用情况监控 Monitors .aget/evolution directory health by checking file counts and types Performs file inventory checks using bash commands like find and wc -l Checks file naming conventions and disk usage for optimal performance Provides self-diagnostic capabilities for AI agents without supervisor intervention Supports execution of specific checks, including file extension checks (e.g., *.md) aget-check-evolution is a consultant template that extends the Advisor archetype, offering evidence-based recommendations for directory health monitoring.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aget-framework/template-operator-aget/aget-check-evolution', 'community', 'aget-framework', 'template-operator-aget', 'aget-framework/template-operator-aget', 'aget-check-evolution', 0, 0, 56, '2026-03-07T01:49:01.776Z', '2026-03-07T03:13:52.928Z', '62225f596bebfa5e6aa19d9cc2fdf738236aaf21bb057aece1bfe1c5b54b6cb3', '{"id":"aget-framework/template-operator-aget/aget-check-evolution","name":"aget-check-evolution","description":{"en":"The aget-check-evolution skill provides self-diagnostic capabilities for AI agents to assess their evolution directory health, ensuring optimal performance and reliability.","zh":"aget-check-evolution是一个操作模板，用于监测.aget/evolution/目录的健康状态，包括文件数量、类型、命名约定和磁盘使用情况","ja":"aget-check-evolutionは、.aget/evolution/ディレクトリのヘルス状態を監視するための操作テンプレートです。ファイル数、タイプ、命名規則、ディスク使用状況などをチェックします","ko":"aget-check-evolution은 .aget/evolution/ 디렉토리의 건강 상태를 모니터링하는 운영 템플릿입니다. 파일 수, 유형, 명명 규칙, 디스크 사용량 등을 확인합니다","es":"aget-check-evolution es una plantilla operativa para la implementación y la respuesta ante incidentes que extiende el arquetipo de trabajador. Monitorea la salud del directorio de evolución comprobando el recuento de archivos, tipos, convenciones de nomenclatura y uso de disco.","fr":"aget-check-evolution est un modèle opérationnel pour le déploiement et la réponse aux incidents qui étend l''archétype de travailleur. Il surveille la santé du répertoire d''évolution en vérifiant le nombre de fichiers, les types, les conventions de nommage et l''utilisation du disque.","de":"aget-check-evolution ist eine operative Vorlage für die Bereitstellung und die Reaktion auf Incidents, die das Worker-Archetyp erweitert. Es überwacht die Gesundheit des Evolution-Verzeichnisses, indem es die Anzahl der Dateien, Dateitypen, Namenskonventionen und die Festplattennutzung überprüft.","pt":"O aget-check-evolution é uma f