INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aget-framework/template-analyst-aget/aget-check-evolution', 'aget-check-evolution', 'aget-framework', 'template-analyst-aget', 'community', 'aget-check-evolution aget-framework template-analyst-aget community aget-check-evolution is a technical skill that provides AI agents with self-diagnostic capabilities to assess their evolution directory health. It benefits AI agent developers by automating file inventory and disk usage checks. aget-check-evolution是一个用于监测.aget/evolution/目录健康状态的分析模板，通过检查文件数量、类型、命名约定和磁盘使用情况 aget-check-evolutionは、.aget/evolution/ディレクトリのヘルス状態を監視するための分析テンプレートで、ファイル数、タイプ、命名規則、ディスク使用状況をチェックする aget-check-evolution은 .aget/evolution/ 디렉토리의 건강 상태를 모니터링하는 분석 템플릿으로 파일 수, 유형, 명명 규칙, 디스크 사용량을 확인합니다 aget-check-evolution es una plantilla analítica para el análisis de datos y la obtención de insights en los directorios de evolución aget-check-evolution est une template analytique pour l''analyse de données et l''obtention d''informations dans les répertoires d''évolution aget-check-evolution ist eine Analyse-Vorlage für die Datenanalyse und die Gewinnung von Erkenntnissen in den Evolution-Verzeichnissen O aget-check-evolution é um modelo analítico para análise de dados e insights que estende o arquétipo Advisor, permitindo a monitoração da saúde do diretório .aget/evolution aget-check-evolution - это аналитический шаблон для анализа данных и получения информации, расширяющий архетип Advisor, который позволяет мониторить здоровье директории .aget/evolution ИИ Агентов aget-check-evolution هو قالب تحليلي لتحليل البيانات والرؤى الذي يمتد إلى نمط Advisor ، مما يسمح بمراقبة صحة الدليل .aget/evolution للأدوات الذكية how to use aget-check-evolution aget-check-evolution setup guide what is aget-check-evolution aget-check-evolution alternative aget-check-evolution vs directory health checkers aget-check-evolution install bash script for directory health check AI agent self-diagnostic tools evolution directory monitoring AI工具 aget-check-evolution 健康状态监测 文件数量检查 文件类型检查 命名约定检查 磁盘使用情况检查 Performs file inventory using find and wc -l commands Checks file types and naming conventions in the .aget/evolution/ directory Monitors disk usage to ensure efficient storage Executes self-diagnostic checks without supervisor intervention Provides insights into evolution directory health using bash scripts aget-check-evolution is an analytical template that monitors the health of the .aget/evolution/ directory by checking file counts, types, naming conventions, and disk usage.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mindfold-ai/Trellis/start', 'community', 'mindfold-ai', 'Trellis', 'mindfold-ai/Trellis', 'start', 2875, 149, 55, '2026-03-01T01:53:07Z', '2026-03-06T06:25:14.437Z', '70b7b098d63b57281b1f89469ac2af41c7bfce558aebea551c109ef59f82bffe', '{"id":"mindfold-ai/Trellis/start","name":"start","description":{"en":"Start is an all-in-one AI framework & toolkit that helps developers initialize and manage their AI development sessions. It benefits developers working with AI agents, AI coding, and workflow management.","zh":"Start技能是AI开发的所有功能和工具包，帮助您初始化开发会话并开始任务","ja":"Startスキルは、AI開発のためのオールインワンフレームワークとツールキットで、開発セッションの初期化とタスクの開始を支援します","ko":"Start 스킬은 AI 개발을 위한 모든 기능과 도구를 포함하는 프레임워크와 툴킷으로, 개발 세션 초기화와 태스크 시작을 도와줍니다","es":"Start es un marco de trabajo y kit de herramientas de AI todo en uno para desarrolladores, que permite inicializar sesiones de desarrollo y trabajar en tareas de codificación","fr":"Start est un cadre de travail et un kit d''outils d''IA tout en un pour les développeurs, qui permet d''initialiser des sessions de développement et de travailler sur des tâches de codage","de":"Start ist ein All-in-one-AI-Framework und -Toolkit für Entwickler, das die Initialisierung von Entwicklungs-Sitzungen und die Arbeit an Codieraufgaben ermöglicht","pt":"O Start é uma estrutura e kit de ferramentas de IA todo-em-um que permite iniciar sessões de desenvolvimento de IA. Inclui recursos como CLI e TypeScript","ru":"Start - это единая платформа и набор инструментов ИИ, позволяющая запустить сессии разработки ИИ. Включает функции, такие как CLI и TypeScript","ar":"بدء هو إطار و أدوات الإستخبارات الاصطناعية شاملة التي تمكنك من بدء جلسات تطوير الإستخبارات الاصطناعية. يتضمن ميزات مثل CLI و TypeScript"},"seo":{"title":{"en":"Start: AI Development Session Setup Guide | AI Agent Skill","zh":"启动AI开发会话：Start技能设置指南","ja":"AIエージェントの開始方法：Startスキルのベストプラクティス","ko":"AI 개발 시작하기: Start 스킬 설정 가이드","es":"Guía de Configuración de Start: Marco de Trabajo de AI","fr":"Guide de Configuration de Start: Cadre de Travail d''IA","de":"Start-Konfigurationsleitfaden: AI-Framework","pt":"Guia de Configuração do Start: Iniciando Sessões de Desen...","ru":"Руководство по Настройке Start: Запуск Сессий Разработки ...","ar":"دليل إعداد بدء الجلسات التطويرية لآليّة الإستخبارات الاصط..."},"description":{"en":"Discover how to initialize your AI development session with Start, the all-in-one AI framework & toolkit. Learn how to get started today!","zh":"了解如何启动AI开发会话并开始任务，使用Start技能和CLI工具","ja":"AIエージェントの開発を開始する方法を学び、StartスキルとCLIツールを使用してタスクを実行する","ko":"AI 개발을 시작하고 태스크를 수행하는 방법을 알아보며, Start 스킬과 CLI 도구를 사용해보세요","es":"Inicialice su sesión de desarrollo de AI con Start, el marco de trabajo y kit de herramientas todo en uno para desarrolladores","fr":"Initialisez votre session de développement d''IA avec Start, le cadre de travail et le kit d''outils tout en un pour les développeurs","de":"Initialisieren Sie Ihre AI-Entwicklungssitzung mit Start, dem All-in-one-AI-Framework und -Toolkit für Entwickler","pt":"Aprenda a iniciar sessões de desenvolvimento de IA com o Start, uma estrutura e kit de ferramentas de IA todo-em-um. Confira os recursos e funcionalidades","ru":"Узнайте, как запустить сессии разработки ИИ с помощью Start, единой платформы и набора инструментов ИИ. Просмотрите функции и возможности","ar":"تعلم كيف تبدأ جلسات تطوير الإستخبارات الاصطناعية مع بدء، إطار و أدوات الإستخبارات الاصطناعية شاملة. استعرض الميزات و الإمكانيات"},"definition":{"en":"Start is an AI development session initializer that provides a workflow guide and supports various operation types, including Bash scripts and tool calls executed by AI.","zh":"Start技能是AI开发的初始化和任务开始工具","ja":"Startスキルは、AI開発の初期化とタスク開始を支援するツールです","ko":"Start 스킬은 AI 개발 초기화와 태스크 시작을 도와주는 도구입니다","es":"Start es un marco de trabajo de AI que permite a los desarrolladores inicializar sesiones de desarrollo y trabajar en tareas de codificación","fr":"Start est un cadre de travail d''IA qui permet aux développeurs d''initialiser des sessions de développement et de travailler sur des tâches de codage","de":"Start ist ein AI-Framework, das es Entwicklern ermöglicht, Entwicklungs-Sitzungen zu initialisieren und an Codieraufgaben zu arbeiten","pt":"O Start é uma ferramenta de desenvolvimento de IA que fornece uma estrutura e kit de ferramentas para iniciar sessões de desenvolvimento de IA","ru":"Start - это инструмент разработки ИИ, предоставляющий платформу и набор инструментов для запуска сессий разработки ИИ","ar":"بدء هو أداة تطوير الإستخبارات الاصطناعية التي توفر إطار و أدوات لبدء جلسات تطوير الإستخبارات الاصطناعية"},"features":{"en":["Initializes AI development sessions using a workflow guide","Supports operation types, including Bash scripts and tool calls executed by AI","Executes skills using markers such as [AI] and [USER]","Provides a workflow guide in Markdown format, accessible via `cat .trellis/workflow.md`","Enables developers to work with AI agents, AI coding, and workflow management","Utilizes technologies such as TypeScript and CLI"],"zh":["支持CLI工具","提供开发工作流指南","包含Bash脚本和工具调用","支持Typescript","提供操作类型标记（[AI]和[USER]）"],"ja":["CLIツールをサポート","開発ワークフローガイドを提供","Bashスクリプトとツール呼び出しを含む","Typescriptをサポート","操作タイプマーカー（[AI]と[USER]）を提供"],"ko":["CLI 도구 지원","개발 워크플로우 가이드 제공","Bash 스크립트와 툴 호출 포함","Typescript 지원","작업 유형 마커([AI]와[USER]) 제공"],"es":["Inicialización de sesiones de desarrollo de AI","Soporte para scripts de Bash y llamadas a herramientas","Integración con TypeScript y otras tecnologías de desarrollo","Funcionalidades de CLI para una mayor eficiencia","Guía de flujo de trabajo para desarrolladores"],"fr":["Initialisation de sessions de développement d''IA","Prise en charge de scripts Bash et d''appels d''outils","Intégration avec TypeScript et d''autres technologies de développement","Fonctionnalités de CLI pour une plus grande efficacité","Guide de flux de travail pour les développeurs"],"de":["Initialisierung von Entwicklungs-Sitzungen für AI","Unterstützung für Bash-Skripte und Tool-Aufrufe","Integration mit TypeScript und anderen Entwicklungstechnologien","CLI-Funktionen für eine höhere Effizienz","Workflow-Leitfaden für Entwickler"],"pt":["Iniciação de sessões de desenvolvimento de IA com CLI","Suporte a TypeScript para desenvolvimento de IA","Integração com workflow de desenvolvimento de IA","Execução de scripts Bash e chamadas de ferramentas por IA","Suporte a operações de usuário e IA"],"ru":["Запуск сессий разработки ИИ с помощью CLI","Поддержка TypeScript для разработки ИИ","Интеграция с рабочим процессом разработки ИИ","Выполнение скриптов Bash и вызовов инструментов ИИ","Поддержка операций пользователя и ИИ"],"ar":["بدء جلسات تطوير الإستخبارات الاصطناعية مع CLI","دعم TypeScript لتنمية الإستخبارات الاصطناعية","التكامل مع سير عمل التطوير الإستخبارات الاصطناعية","تنفيذ البرامج النصية Bash و呼وات الأدوات الإستخبارات الاصطناعية","دعم عمليات المستخدم والإستخبارات الاصطناعية"]},"keywords":{"en":["how to use start","start ai development session","start alternative","start vs claude code","start install","start setup guide","what is start","start workflow management","start ai coding","start ai agent"],"zh":["AI开发工具","Start技能","CLI工具","开发工作流","Bash脚本","Typescript","AIエージェント","启动AI开发会话"],"ja":["AIエージェント","Startスキル","CLIツール","開発ワークフロー","Bashスクリプト","Typescript","AI開発ツール","開発セッションの初期化"],"ko":["AI 개발 도구","Start 스킬","CLI 도구","개발 워크플로우","Bash 스크립트","Typescript","AI 에이전트","개발 세션 초기화"],"es":["agentes de AI","herramientas de AI","desarrollo de AI"," Start AI","marco de trabajo de AI","kit de herramientas de AI","TypeScript","CLI","codificación de AI"],"fr":["agents d''IA","outils d''IA","développement d''IA","Start IA","cadre de travail d''IA","kit d''outils d''IA","TypeScript","CLI","codage d''IA"],"de":["AI-Agents","AI-Tools","AI-Entwicklung","Start AI","AI-Framework","AI-Toolkit","TypeScript","CLI","AI-Codierung"],"pt":["desenvolvimento de IA","ferramentas de IA","CLI para IA","TypeScript para IA","workflow de desenvolvimento de IA","IA todo-em-um","iniciar sessões de desenvolvimento de IA"],"ru":["разработка ИИ","инструменты ИИ","CLI для ИИ","TypeScript для ИИ","рабочий процесс разработки ИИ","ИИ Агенты","запуск сессий разработки ИИ"],"ar":["تطوير الإستخبارات الاصطناعية","أدوات الإستخبارات الاصطناعية","CLI للاستخبارات الاصطناعية","TypeScript للاستخبارات الاصطناعية","سير عمل التطوير الإستخبارات الاصطناعية","آليّة الإستخبارات الاصطناعية","بدء جلسات تطوير الإستخبارات الاصطناعية"]}},"owner":"mindfold-ai","repo":"Trellis","repoPath":"mindfold-ai/Trellis","stars":2875,"forks":149,"updatedAt":"2026-03-01T01:53:07Z","topics":["ai-agent","ai-coding","claude-code","cli","codex","cursor","developer-tools","typescript","workflow"],"category":"community","skillMd":{"name":"start","description":"Start Session","bodyPreview":"# Start Session\n\nInitialize your AI development session and begin working on tasks.\n\n---\n\n## Operation Types\n\n| Marker | Meaning | Executor |\n|--------|---------|----------|\n| `[AI]` | Bash scripts or tool calls executed by AI | You (AI) |\n| `[USER]` | Skills executed by user | User |\n\n---\n\n## Initialization `[AI]`\n\n### Step 1: Understand Development Workflow\n\nFirst, read the workflow guide to understand the development process:\n\n```bash\ncat .trellis/workflow.md\n```\n\n**Follow the instructions in","body":"# Start Session\n\nInitialize your AI development session and begin working on tasks.\n\n---\n\n## Operation Types\n\n| Marker | Meaning | Executor |\n|--------|---------|----------|\n| `[AI]` | Bash scripts or tool calls executed by AI | You (AI) |\n| `[USER]` | Skills executed by user | User |\n\n---\n\n## Initialization `[AI]`\n\n### Step 1: Understand Development Workflow\n\nFirst, read the workflow guide to understand the development process:\n\n```bash\ncat .trellis/workflow.md\n```\n\n**Follow the instructions in workflow.md** - it contains:\n- Core principles (Read Before Write, Follow Standards, etc.)\n- File system structure\n- Development process\n- Best practices\n\n### Step 2: Get Current Context\n\n```bash\npython3 ./.trellis/scripts/get_context.py\n```\n\nThis shows: developer identity, git status, current task (if any), active tasks.\n\n### Step 3: Read Guidelines Index\n\n```bash\ncat .trellis/spec/frontend/index.md  # Frontend guidelines\ncat .trellis/spec/backend/index.md   # Backend guidelines\ncat .trellis/spec/guides/index.md    # Thinking guides\n```\n\n### Step 4: Report and Ask\n\nReport what you learned and ask: \"What would you like to work on?\"\n\n---\n\n## Task Classification\n\nWhen user describes a task, classify it:\n\n| Type | Criteria | Workflow |\n|------|----------|----------|\n| **Question** | User asks about code, architecture, or how something works | Answer directly |\n| **Trivial Fix** | Typo fix, comment update, single-line change, < 5 minutes | Direct Edit |\n| **Simple Task** | Clear goal, 1-2 files, well-defined scope | Quick confirm → Task Workflow |\n| **Complex Task** | Vague goal, multiple files, architectural decisions | **Brainstorm → Task Workflow** |\n\n### Decision Rule\n\n> **If in doubt, use Brainstorm + Task Workflow.**\n>\n> Task Workflow ensures code-specs are injected to the right context, resulting in higher quality code.\n> The overhead is minimal, but the benefit is significant.\n\n> **Subtask Decomposition**: If brainstorm reveals multiple independent work items,\n> consider creating subtasks using `--parent` flag or `add-subtask` command.\n> See the brainstorm skill''s Step 8 for details.\n\n---\n\n## Question / Trivial Fix\n\nFor questions or trivial fixes, work directly:\n\n1. Answer question or make the fix\n2. If code was changed, remind user to run `$finish-work`\n\n---\n\n## Simple Task\n\nFor simple, well-defined tasks:\n\n1. Quick confirm: \"I understand you want to [goal]. Ready to proceed?\"\n2. If yes, proceed to **Task Workflow Phase 1 Path B** (create task, write PRD, then research)\n3. If no, clarify and confirm again\n\n---\n\n## Complex Task - Brainstorm First\n\nFor complex or vague tasks, use the brainstorm process to clarify requirements.\n\nSee `$brainstorm` for the full process. Summary:\n\n1. **Acknowledge and classify** - State your understanding\n2. **Create task directory** - Track evolving requirements in `prd.md`\n3. **Ask questions one at a time** - Update PRD after each answer\n4. **Propose approaches** - For architectural decisions\n5. **Confirm final requirements** - Get explicit approval\n6. **Proceed to Task Workflow** - With clear requirements in PRD\n\n---\n\n## Task Workflow (Development Tasks)\n\n**Why this workflow?**\n- Run a dedicated research pass before coding\n- Configure specs in jsonl context files\n- Implement using injected context\n- Verify with a separate check pass\n- Result: Code that follows project conventions automatically\n\n### Overview: Two Entry Points\n\n```\nFrom Brainstorm (Complex Task):\n  PRD confirmed → Research → Configure Context → Activate → Implement → Check → Complete\n\nFrom Simple Task:\n  Confirm → Create Task → Write PRD → Research → Configure Context → Activate → Implement → Check → Complete\n```\n\n**Key principle: Research happens AFTER requirements are clear (PRD exists).**\n\n---\n\n### Phase 1: Establish Requirements\n\n#### Path A: From Brainstorm (skip to Phase 2)\n\nPRD and task directory already exist from brainstorm. Skip directly to Phase 2.\n\n#### Path B: From Simple Task\n\n**Step 1: Confirm Understanding** `[AI]`\n\nQuick confirm:\n- What is the goal?\n- What type of development? (frontend / backend / fullstack)\n- Any specific requirements or constraints?\n\nIf unclear, ask clarifying questions.\n\n**Step 2: Create Task Directory** `[AI]`\n\n```bash\nTASK_DIR=$(python3 ./.trellis/scripts/task.py create \"<title>\" --slug <name>)\n```\n\n**Step 3: Write PRD** `[AI]`\n\nCreate `prd.md` in the task directory with:\n\n```markdown\n# <Task Title>\n\n## Goal\n<What we''re trying to achieve>\n\n## Requirements\n- <Requirement 1>\n- <Requirement 2>\n\n## Acceptance Criteria\n- [ ] <Criterion 1>\n- [ ] <Criterion 2>\n\n## Technical Notes\n<Any technical decisions or constraints>\n```\n\n---\n\n### Phase 2: Prepare for Implementation (shared)\n\n> Both paths converge here. PRD and task directory must exist before proceeding.\n\n**Step 4: Code-Spec Depth Check** `[AI]`\n\nIf the task touches infra or cross-layer contracts, do not start implementation until code-spec depth is defined.\n\nTrigger this requirement when the change includes any of:\n- New or changed command/API signatures\n- Database schema or migration changes\n- Infra integrations (storage, queue, cache, secrets, env contracts)\n- Cross-layer payload transformations\n\nMust-have before proceeding:\n- [ ] Target code-spec files to update are identified\n- [ ] Concrete contract is defined (signature, fields, env keys)\n- [ ] Validation and error matrix is defined\n- [ ] At least one Good/Base/Bad case is defined\n\n**Step 5: Research the Codebase** `[AI]`\n\nBased on the confirmed PRD, run a focused research pass and produce:\n\n1. Relevant spec files in `.trellis/spec/`\n2. Existing code patterns to follow (2-3 examples)\n3. Files that will likely need modification\n\nUse this output format:\n\n```markdown\n## Relevant Specs\n- <path>: <why it''s relevant>\n\n## Code Patterns Found\n- <pattern>: <example file path>\n\n## Files to Modify\n- <path>: <what change>\n```\n\n**Step 6: Configure Context** `[AI]`\n\nInitialize default context:\n\n```bash\npython3 ./.trellis/scripts/task.py init-context \"$TASK_DIR\" <type>\n# type: backend | frontend | fullstack\n```\n\nAdd specs found in your research pass:\n\n```bash\n# For each relevant spec and code pattern:\npython3 ./.trellis/scripts/task.py add-context \"$TASK_DIR\" implement \"<path>\" \"<reason>\"\npython3 ./.trellis/scripts/task.py add-context \"$TASK_DIR\" check \"<path>\" \"<reason>\"\n```\n\n**Step 7: Activate Task** `[AI]`\n\n```bash\npython3 ./.trellis/scripts/task.py start \"$TASK_DIR\"\n```\n\nThis sets `.current-task` so hooks can inject context.\n\n---\n\n### Phase 3: Execute (shared)\n\n**Step 8: Implement** `[AI]`\n\nImplement the task described in `prd.md`.\n\n- Follow all specs injected into implement context\n- Keep changes scoped to requirements\n- Run lint and typecheck before finishing\n\n**Step 9: Check Quality** `[AI]`\n\nRun a quality pass against check context:\n\n- Review all code changes against the specs\n- Fix issues directly\n- Ensure lint and typecheck pass\n\n**Step 10: Complete** `[AI]`\n\n1. Verify lint and typecheck pass\n2. Report what was implemented\n3. Remind user to:\n   - Test the changes\n   - Commit when ready\n   - Run `$record-session` to record this session\n\n---\n\n## Continuing Existing Task\n\nIf `get_context.py` shows a current task:\n\n1. Read the task''s `prd.md` to understand the goal\n2. Check `task.json` for current status and phase\n3. Ask user: \"Continue working on <task-name>?\"\n\nIf yes, resume from the appropriate step (usually Step 7 or 8).\n\n---\n\n## Skills Reference\n\n### User Skills `[USER]`\n\n| Skill | When to Use |\n|---------|-------------|\n| `$start` | Begin a session (this skill) |\n| `$finish-work` | Before committing changes |\n| `$record-session` | After completing a task |\n\n### AI Scripts `[AI]`\n\n| Script | Purpose |\n|--------|---------|\n| `python3 ./.trellis/scripts/get_context.py` | Get session context |\n| `python3 ./.trellis/scripts/task.py create` | Create task directory |\n| `python3 ./.trellis/scripts/task.py init-context` | Initialize jsonl files |\n| `python3 ./.trellis/scripts/task.py add-context` | Add spec to jsonl |\n| `python3 ./.trellis/scripts/task.py start` | Set current task |\n| `python3 ./.trellis/scripts/task.py finish` | Clear current task |\n| `python3 ./.trellis/scripts/task.py archive` | Archive completed task |\n\n### Workflow Phases `[AI]`\n\n| Phase | Purpose | Context Source |\n|-------|---------|----------------|\n| research | Analyze codebase | direct repo inspection |\n| implement | Write code | `implement.jsonl` |\n| check | Review & fix | `check.jsonl` |\n| debug | Fix specific issues | `debug.jsonl` |\n\n---\n\n## Key Principle\n\n> **Code-spec context is injected, not remembered.**\n>\n> The Task Workflow ensures agents receive relevant code-spec context automatically.\n> This is more reliable than hoping the AI \"remembers\" conventions.\n"},"lastSynced":"2026-03-06T06:25:14.437Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Development Agents needing streamlined workflow management and initialization.","zh":"适合需要简化工作流管理和初始化的AI开发代理。","ja":"ワークフロー管理と初期化を簡素化する必要があるAI開発エージェントに最適です。","ko":"워크플로우 관리와 초기화를 간소화해야 하는 AI 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo de IA que necesitan una gestión de flujo de trabajo y una inicialización optimizadas.","fr":"Idéal pour les agents de développement d''IA nécessitant une gestion de workflow et une initialisation rationalisées.","de":"Ideal für AI-Entwicklungsagenten, die eine optimierte Workflow-Verwaltung und -Initialisierung benötigen.","pt":"Ideal para Agentes de Desenvolvimento de IA que necessitam de gerenciamento de fluxo de trabalho e inicialização otimizados.","ru":"Идеально для агентов по разработке ИИ, которым необходим упрощенный менеджмент рабочего процесса и инициализация.","ar":"مثالي للوكلاء الذين يحتاجون إلى إدارة تدفق عمل وتحسين عملية التشغيل."},"recommendation":{"en":"Empowers agents to manage AI development sessions, execute Bash scripts, and interact with workflow guides using Markdown files like ''workflow.md''. It provides a comprehensive framework for task initialization and workflow understanding.","zh":"赋予代理管理AI开发会话、执行Bash脚本和使用Markdown文件（如''workflow.md''）与工作流指南交互的能力。它为任务初始化和工作流理解提供了一个全面的框架。","ja":"エージェントにAI開発セッションを管理し、Bashスクリプトを実行し、Markdownファイル（例： ''workflow.md''）を使用してワークフローガイドとやりとりする能力を提供します。タスクの初期化とワークフローの理解のための包括的なフレームワークを提供します。","ko":"에이전트가 AI 개발 세션을 관리하고 Bash 스크립트를 실행하며 Markdown 파일(예: ''workflow.md'')을 사용하여 워크플로우 가이드와 상호 작용할 수 있는 능력을 제공합니다. 작업 초기화 및 워크플로 이해를 위한 포괄적인 프레임워크를 제공합니다.","es":"Permite a los agentes gestionar sesiones de desarrollo de IA, ejecutar scripts de Bash y interactuar con guías de flujo de trabajo utilizando archivos Markdown como ''workflow.md''. Proporciona un marco integral para la inicialización de tareas y la comprensión del flujo de trabajo.","fr":"Permet aux agents de gérer des sessions de développement d''IA, d''exécuter des scripts Bash et d''interagir avec des guides de workflow à l''aide de fichiers Markdown tels que ''workflow.md''. Fournit un cadre complet pour l''initialisation des tâches et la compréhension du workflow.","de":"Ermöglicht es Agents, AI-Entwicklungssitzungen zu verwalten, Bash-Skripte auszuführen und mit Workflow-Leitfäden unter Verwendung von Markdown-Dateien wie ''workflow.md'' zu interagieren. Bietet ein umfassendes Framework für die Initialisierung von Aufgaben und das Verständnis des Workflows.","pt":"Habilita os agentes a gerenciar sessões de desenvolvimento de IA, executar scripts Bash e interagir com guias de fluxo de trabalho usando arquivos Markdown como ''workflow.md''. Ele fornece um framework abrangente para inicialização de tarefas e compreensão do fluxo de trabalho.","ru":"Наделяет агентов возможностью управлять сессиями разработки ИИ, выполнять скрипты Bash и взаимодействовать с руководствами по рабочему процессу с помощью файлов Markdown, таких как ''workflow.md''. Он предоставляет всесторонний каркас для инициализации задач и понимания рабочего процесса.","ar":"تمكّن الوكلاء من إدارة جلسات تطوير الذكاء الاصطناعي، وتنفيذ سكريبتات Bash والتفاعل مع إرشادات تدفق العمل باستخدام ملفات Markdown مثل ''workflow.md''. يوفر إطارًا شاملاً لمبادرة المهام وفهم تدفق العمل."},"useCases":{"en":["Initializing AI development sessions","Executing Bash scripts for workflow automation","Reading workflow guides for development process understanding"],"zh":["初始化AI开发会话","执行Bash脚本以实现工作流自动化","阅读工作流指南以了解开发过程"],"ja":["AI開発セッションの初期化","ワークフロー自動化のためのBashスクリプトの実行","開発プロセスの理解のためのワークフローガイドの読み取り"],"ko":["AI 개발 세션 초기화","워크플로우 자동화를 위한 Bash 스크립트 실행","개발 프로세스 이해를 위한 워크플로우 가이드의 읽기"],"es":["Inicialización de sesiones de desarrollo de IA","Ejecución de scripts de Bash para la automatización del flujo de trabajo","Lectura de guías de flujo de trabajo para la comprensión del proceso de desarrollo"],"fr":["Initialisation de sessions de développement d''IA","Exécution de scripts Bash pour l''automatisation du workflow","Lecture de guides de workflow pour la compréhension du processus de développement"],"de":["Initialisierung von AI-Entwicklungssitzungen","Ausführung von Bash-Skripten für die Workflow-Automatisierung","Lesen von Workflow-Leitfäden für das Verständnis des Entwicklungsprozesses"],"pt":["Inicializar sessões de desenvolvimento de IA","Executar scripts Bash para automação de fluxo de trabalho","Ler guias de fluxo de trabalho para compreensão do processo de desenvolvimento"],"ru":["Инициализировать сессии разработки ИИ","Выполнять скрипты Bash для автоматизации рабочего процесса","Читать руководства по рабочему процессу для понимания процесса разработки"],"ar":["تشغيل جلسات تطوير الذكاء الاصطناعي","تشغيل سكريبتات Bash للتحكم الآلي في تدفق العمل","قراءة إرشادات تدفق العمل لفهم عملية التطوير"]},"limitations":{"en":["Requires access to ''.trellis/workflow.md'' file","Limited to Bash script execution"],"zh":["需要访问''.trellis/workflow.md''文件","仅限Bash脚本执行"],"ja":["''.trellis/workflow.md''ファイルへのアクセスが必要","Bashスクリプトの実行のみ"],"ko":["''.trellis/workflow.md'' 파일에 대한 액세스가 필요","Bash 스크립트 실행만 가능"],"es":["Requiere acceso al archivo ''.trellis/workflow.md''","Limitado a la ejecución de scripts de Bash"],"fr":["Nécessite l''accès au fichier ''.trellis/workflow.md''","Limité à l''exécution de scripts Bash"],"de":["Benötigt Zugriff auf die Datei ''.trellis/workflow.md''","Begrenzt auf die Ausführung 