INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('man-group/ArcticDB/review-pr', 'review-pr', 'man-group', 'ArcticDB', 'community', 'review-pr man-group ArcticDB community big-data data data-analysis data-science database dataframe pandas quantitative-analysis quantitative-finance quantitative-trading The review-pr skill automates code reviews for ArcticDB pull requests, benefiting developers and data scientists working with the Python Data Science ecosystem. review-pr 代码审查是优化 ArcticDB 服务器性能的关键步骤，确保数据科学工作流的高效运行 review-pr は、ArcticDB サーバーレスの DataFrame データベースを最適化するための重要なステップです review-pr 코드 리뷰는 ArcticDB 서버리스 DataFrame 데이터베이스를 최적화하는 중요한 단계입니다 Review-pr es una herramienta para revisar código en ArcticDB, una base de datos de DataFrame de alto rendimiento y sin servidor para la ciencia de datos en Python Review-pr est un outil de révision de code pour ArcticDB, une base de données de DataFrame haute performance et sans serveur pour la science des données en Python Review-pr ist ein Tool zur Code-Überprüfung in ArcticDB, einer hochleistungsfähigen und serverlosen DataFrame-Datenbank für Data Science in Python O review-pr é uma ferramenta de análise de código para pull requests no ArcticDB, permitindo uma revisão detalhada do código ИИ Агент review-pr - это инструмент для анализа кода в ArcticDB, позволяющий проводить подробный обзор кода review-pr هو أداة لمراجعة الكود في البيانات العلمية، مما يسمح بمراجعة مفصلة للكود how to use review-pr review-pr setup guide ArcticDB code review automation review-pr alternative review-pr vs GitHub code review what is review-pr review-pr install automating code reviews for data science review-pr ArcticDB 服务器性能优化 数据科学工作流 Pandas DataFrame GitHub Actions 代码审查工具 Resolves PR number and repository using injected context variables Supports invocation from GitHub Actions workflow or as a local slash command Detects PR number from the current branch if $ARGUMENTS is empty Utilizes bash commands for automation Integrates with ArcticDB, a high-performance, serverless DataFrame database review-pr is a skill that performs thorough code reviews of ArcticDB pull requests, utilizing context variables like PR_NUMBER and REPO.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pgplex/pgschema/fix_bug', 'community', 'pgplex', 'pgschema', 'pgplex/pgschema', 'fix_bug', 808, 30, 55, '2026-03-01T03:56:36Z', '2026-03-06T06:27:17.239Z', '3405298c5aac79ae318b9dcdd0980d9642d596874ccb536084cf31e8c3d33399', '{"id":"pgplex/pgschema/fix_bug","name":"fix_bug","description":{"en":"fix_bug is a Terraform-style, declarative schema migration CLI for Postgres, benefiting developers and DevOps teams. It enables end-to-end workflow for fixing bugs reported as GitHub issues.","zh":"Fix Bug是一种Terraform风格的Postgres数据库schema迁移CLI工具，用于修复数据库相关的问题","ja":"Fix BugはPostgresデータベースのスキーマを移行するTerraformスタイルのCLIツールです","ko":"Fix Bug는 Postgres 데이터베이스의 스키마를 마이그레이션하는 Terraform 스타일의 CLI 도구입니다","es":"fix_bug es una herramienta de línea de comandos para migraciones de esquema de Postgres que utiliza un enfoque declarativo similar a Terraform","fr":"fix_bug est un outil en ligne de commande pour les migrations de schéma Postgres qui utilise une approche déclarative similaire à Terraform","de":"fix_bug ist ein Kommandozeilen-Tool für Postgres-Schemamigrationen, das einen deklarativen Ansatz ähnlich wie Terraform verwendet","pt":"O Fix Bug é uma ferramenta de migração de esquema Postgres que utiliza um estilo declarativo, semelhante ao Terraform, para simplificar o processo de atualização de esquemas de banco de dados.","ru":"Fix Bug - это инструмент миграции схемы Postgres, который использует декларативный стиль, похожий на Terraform, для упрощения процесса обновления схем баз данных.","ar":"Fix Bug هو أداة هجرة مخطط قاعدة البيانات Postgres التي تستخدم نمطًا إعلانيًا، مشابهًا لـ Terraform، لتبسيط عملية تحديث مخططات قواعد البيانات."},"seo":{"title":{"en":"fix_bug: Terraform-style Schema Migration CLI Setup Guide...","zh":"Fix Bug Setup Guide: Terraform-style Postgres Schema Migr...","ja":"Fix Bug ベストプラクティス: AIエージェントによるPostgres スキーマ移行","ko":"Fix Bug 설정 가이드: Terraform 스타일의 Postgres 스키마 마이그레이션","es":"Guía de configuración de fix_bug para migraciones de esqu...","fr":"Guide de configuration de fix_bug pour les migrations de ...","de":"Konfigurationsleitfaden für fix_bug zur Postgres-Schemami...","pt":"Guia de Configuração do Fix Bug: Migração de Esquema Post...","ru":"Настройка Fix Bug: Инструмент Миграции Схемы Postgres","ar":"دليل إعداد Fix Bug: أداة هجرة مخطط قاعدة البيانات Postgres"},"description":{"en":"Streamline Postgres schema migrations with fix_bug. Learn how to fix bugs reported as GitHub issues using TDD and Terraform-style declarative schema migratio...","zh":"使用Fix Bug AI Agent进行Terraform风格的Postgres数据库schema迁移和修复，提高开发效率","ja":"Fix Bug AIエージェントを使用してPostgresデータベースのスキーマを移行および修復する","ko":"Fix Bug AI 에이전트를 사용하여 Postgres 데이터베이스의 스키마를 마이그레이션하고 修复하십시오","es":"Aprende a utilizar fix_bug, una herramienta de migración de esquema de Postgres estilo Terraform, para simplificar tus flujos de trabajo de desarrollo","fr":"Découvrez comment utiliser fix_bug, un outil de migration de schéma Postgres de style Terraform, pour simplifier vos flux de travail de développement","de":"Erfahren Sie, wie Sie fix_bug, ein Postgres-Schemamigrations-Tool im Terraform-Stil, verwenden können, um Ihre Entwicklungspipelines zu vereinfachen","pt":"Aprenda a configurar o Fix Bug, uma ferramenta de migração de esquema Postgres estilo Terraform, para melhorar seu fluxo de trabalho de DevOps","ru":"Узнайте, как настроить Fix Bug, инструмент миграции схемы Postgres в стиле Terraform, для улучшения вашего рабочего процесса DevOps","ar":"تعرف على كيفية設定 Fix Bug، أداة هجرة مخطط قاعدة البيانات Postgres بالنمط Terraform، لتحسين تدفق عملك في DevOps"},"definition":{"en":"fix_bug is a command-line interface tool for Terraform-style, declarative schema migration in Postgres, using Test-Driven Development (TDD) for bug fixing.","zh":"Fix Bug是一种用于Postgres数据库schema迁移和修复的Terraform风格的CLI工具","ja":"Fix BugはPostgresデータベースのスキーマを移行および修復するためのTerraformスタイルのCLIツールです","ko":"Fix Bug는 Postgres 데이터베이스의 스키마를 마이그레이션하고 修复하는 Terraform 스타일의 CLI 도구입니다","es":"fix_bug es una herramienta de migración de esquema de Postgres que permite a los desarrolladores gestionar cambios en su esquema de base de datos de manera eficiente","fr":"fix_bug est un outil de migration de schéma Postgres qui permet aux développeurs de gérer les modifications de leur schéma de base de données de manière efficace","de":"fix_bug ist ein Postgres-Schemamigrations-Tool, das es Entwicklern ermöglicht, Änderungen an ihrem Datenbankschema effizient zu verwalten","pt":"Fix Bug é uma ferramenta de migração de esquema Postgres que utiliza um estilo declarativo para atualizar esquemas de banco de dados.","ru":"Fix Bug - это инструмент миграции схемы Postgres, который использует декларативный стиль для обновления схем баз данных.","ar":"Fix Bug هو أداة هجرة مخطط قاعدة البيانات Postgres التي تستخدم نمطًا إعلانيًا لتحديث مخططات قواعد البيانات."},"features":{"en":["Uses gh issue view command to fetch and analyze GitHub issues","Supports Test-Driven Development (TDD) for bug reproduction and verification","Classifies bugs and identifies affected code areas","Integrates with GitOps and CI/CD workflows","Enables declarative schema migration for Postgres using Terraform-style CLI"],"zh":["Terraform风格的Postgres数据库schema迁移","支持GitHub issue追踪和修复","使用TDD（测试驱动开发）进行问题修复","支持多租户和GitOps","CLI工具，易于使用和集成"],"ja":["Postgresデータベースのスキーマを移行するTerraformスタイル","GitHub issueの追跡と修復をサポート","TDD（テスト駆動開発）を使用して問題を修復","マルチテナントとGitOpsをサポート","CLIツール、使用と統合が容易"],"ko":["Postgres 데이터베이스의 스키마를 마이그레이션하는 Terraform 스타일","GitHub issue 추적과 修复을 지원","TDD（테스트 주도 개발）를 사용하여 문제를 修复","멀티 테넌트와 GitOps를 지원","CLI 도구, 사용과 통합이 쉽습니다"],"es":["Migraciones de esquema de Postgres estilo Terraform","Enfoque declarativo para la gestión de cambios en el esquema","Integración con GitHub para la gestión de problemas y solicitudes de extracción","Soporte para pruebas de desarrollo y verificación","Capacidad para reproducir y solucionar problemas de manera eficiente"],"fr":["Migrations de schéma Postgres de style Terraform","Approche déclarative pour la gestion des modifications de schéma","Intégration avec GitHub pour la gestion des problèmes et des demandes d''extraction","Prise en charge des tests de développement et de vérification","Capacité à reproduire et résoudre les problèmes de manière efficace"],"de":["Postgres-Schemamigrationen im Terraform-Stil","Deklarativer Ansatz für die Verwaltung von Änderungen am Schema","Integration mit GitHub für die Verwaltung von Problemen und Pull-Requests","Unterstützung für Entwicklungstests und Verifizierung","Fähigkeit, Probleme effizient zu reproduzieren und zu lösen"],"pt":["Migração de esquema Postgres estilo Terraform","Suporte a fluxo de trabalho de DevOps","Integração com GitHub para relatórios de issues","Análise de problemas e classificação de bugs","Suporte a testes unitários e de integração"],"ru":["Миграция схемы Postgres в стиле Terraform","Поддержка рабочего процесса DevOps","Интеграция с GitHub для отчетов об ошибках","Анализ проблем и классификация ошибок","Поддержка модульных и интеграционных тестов"],"ar":["هجرة مخطط قاعدة البيانات Postgres بالنمط Terraform","دعم تدفق عمل DevOps","التكامل مع GitHub لتقارير الأخطاء","تحليل المشكلات وتصنيف الأخطاء","دعم الاختبارات الوحدة والاختبار التكاملي"]},"keywords":{"en":["how to use fix_bug","fix_bug vs Terraform","fix_bug setup guide","Postgres schema migration tools","TDD for bug fixing","fix_bug alternative to manual schema migration","fix_bug install for CI/CD pipelines","what is fix_bug","fix_bug for GitOps workflows"],"zh":["Postgres数据库schema迁移","Terraform风格的CLI工具","Fix Bug AI Agent","GitHub issue追踪","TDD问题修复","多租户支持","GitOps支持"],"ja":["Postgresデータベースのスキーマ移行","TerraformスタイルのCLIツール","Fix Bug AIエージェント","GitHub issue追跡","TDD問題修復","マルチテナントサポート","GitOpsサポート"],"ko":["Postgres 데이터베이스의 스키마 마이그레이션","Terraform 스타일의 CLI 도구","Fix Bug AI 에이전트","GitHub issue 추적","TDD 문제 修复","멀티 테넌트 지원","GitOps 지원"],"es":["migración de esquema de Postgres","herramientas de desarrollo de Postgres","Terraform para Postgres","gestión de problemas de GitHub","pruebas de desarrollo de Postgres","solución de problemas de Postgres","desarrollo de aplicaciones con Postgres","devops para Postgres","cicd para Postgres"],"fr":["migration de schéma Postgres","outils de développement Postgres","Terraform pour Postgres","gestion des problèmes GitHub","tests de développement Postgres","résolution de problèmes Postgres","développement d''applications avec Postgres","devops pour Postgres","cicd pour Postgres"],"de":["Postgres-Schemamigration","Entwicklungstools für Postgres","Terraform für Postgres","Problemverwaltung in GitHub","Entwicklungstests für Postgres","Fehlerbehebung in Postgres","Anwendungsentwicklung mit Postgres","devops für Postgres","cicd für Postgres"],"pt":["migração de esquema Postgres","ferramenta de migração de esquema","Terraform","DevOps","GitHub","testes unitários","testes de integração","fluxo de trabalho de DevOps"],"ru":["миграция схемы Postgres","инструмент миграции схемы","Terraform","DevOps","GitHub","модульные тесты","интеграционные тесты","рабочий процесс DevOps"],"ar":["هجرة مخطط قاعدة البيانات Postgres","أداة هجرة مخطط","Terraform","DevOps","GitHub","اختبارات الوحدة","اختبارات التكامل","تدفق عمل DevOps"]}},"owner":"pgplex","repo":"pgschema","repoPath":"pgplex/pgschema","stars":808,"forks":30,"updatedAt":"2026-03-01T03:56:36Z","topics":["cicd","cli","ddl","devops","gitops","multi-tenant","postgres","postgresql","schema","schema-change","schema-diff","schema-migration","schema-migrations","terraform"],"category":"community","skillMd":{"name":"fix_bug","description":"Fix a bug from a GitHub issue using TDD. Analyzes the issue, creates a reproducing test case, implements the fix, verifies it, runs refactor-pass, and creates a PR.","bodyPreview":"# Fix Bug\n\nEnd-to-end workflow for fixing bugs reported as GitHub issues. Uses TDD: reproduce first, then fix, then verify.\n\n## Prerequisites\n\n- A GitHub issue URL or issue number (from the pgplex/pgschema repo)\n\n## Workflow\n\n### Phase 1: Analyze the Issue\n\n1. **Fetch the issue** using `gh issue view <number>` to get the full description, labels, and any linked PRs.\n2. **Understand the bug**: Identify what''s broken, what the expected behavior is, and which area of code is affected.\n3. **Classify","body":"# Fix Bug\n\nEnd-to-end workflow for fixing bugs reported as GitHub issues. Uses TDD: reproduce first, then fix, then verify.\n\n## Prerequisites\n\n- A GitHub issue URL or issue number (from the pgplex/pgschema repo)\n\n## Workflow\n\n### Phase 1: Analyze the Issue\n\n1. **Fetch the issue** using `gh issue view <number>` to get the full description, labels, and any linked PRs.\n2. **Understand the bug**: Identify what''s broken, what the expected behavior is, and which area of code is affected.\n3. **Classify the bug type**:\n   - **Dump bug**: `pgschema dump` produces incorrect output (wrong SQL, missing objects, bad formatting). Test goes in `testdata/dump/`.\n   - **Diff/Plan bug**: `pgschema dump` is correct but `pgschema plan` generates wrong migration DDL. Test goes in `testdata/diff/`.\n   - **Both**: If unclear, start with dump. If dump output is correct, it''s a diff bug.\n\n### Phase 2: Create the Test Case (TDD - Red)\n\n#### For Dump Bugs (`testdata/dump/`)\n\n1. **Create test directory**:\n   ```\n   testdata/dump/issue_<NUMBER>_<short_description>/\n   ```\n   Use snake_case for the description. Example: `issue_250_enum_type_missing`\n\n2. **Create test files**:\n   - `manifest.json` - Metadata about the test case:\n     ```json\n     {\n       \"name\": \"issue_<NUMBER>_<short_description>\",\n       \"description\": \"Test case for <bug description> (GitHub issue #<NUMBER>)\",\n       \"source\": \"https://github.com/pgplex/pgschema/issues/<NUMBER>\",\n       \"notes\": [\n         \"Reproduces the bug where <specific behavior>\",\n         \"Tests that <expected correct behavior>\"\n       ]\n     }\n     ```\n   - `raw.sql` - The original DDL that creates the schema (what a user would write)\n   - `pgdump.sql` - What `pg_dump --schema-only` produces for this schema (the input to the test). Generate this by applying `raw.sql` to an embedded-postgres and running pg_dump, or construct it manually based on pg_dump conventions.\n   - `pgschema.sql` - The expected correct output from `pgschema dump`\n\n3. **Register the test** in `cmd/dump/dump_integration_test.go`:\n   ```go\n   func TestDumpCommand_Issue<NUMBER><PascalDescription>(t *testing.T) {\n       if testing.Short() {\n           t.Skip(\"Skipping integration test in short mode\")\n       }\n       runExactMatchTest(t, \"issue_<NUMBER>_<short_description>\")\n   }\n   ```\n\n4. **Run the test to confirm it fails** (red):\n   ```bash\n   go test -v ./cmd/dump -run TestDumpCommand_Issue<NUMBER>\n   ```\n\n#### For Diff/Plan Bugs (`testdata/diff/`)\n\n1. **Create test directory** under the appropriate category:\n   ```\n   testdata/diff/<category>/issue_<NUMBER>_<short_description>/\n   ```\n   Categories: `create_table`, `create_index`, `create_trigger`, `create_view`, `create_function`, `create_procedure`, `create_sequence`, `create_type`, `create_domain`, `create_policy`, `create_materialized_view`, `comment`, `privilege`, `default_privilege`, `dependency`, `online`, `migrate`.\n\n   Example: `testdata/diff/create_index/issue_250_partial_index_diff`\n\n2. **Create test files**:\n   - `old.sql` - The starting schema state (current database)\n   - `new.sql` - The desired schema state (user''s SQL files)\n   - Leave `diff.sql` empty or with expected content — it will be generated\n   - Note: `plan.json`, `plan.sql`, `plan.txt` will also be generated alongside `diff.sql`\n\n3. **Run the diff test to confirm it fails** (red):\n   ```bash\n   PGSCHEMA_TEST_FILTER=\"<category>/issue_<NUMBER>_<short_description>\" go test -v ./internal/diff -run TestDiffFromFiles\n   ```\n\n4. **Generate expected outputs** using `--generate` once you know the correct behavior:\n   ```bash\n   PGSCHEMA_TEST_FILTER=\"<category>/issue_<NUMBER>_<short_description>\" go test -v ./cmd -run TestPlanAndApply --generate\n   ```\n   This overwrites `diff.sql`, `plan.json`, `plan.sql`, and `plan.txt` with actual output.\n\n### Phase 3: Implement the Fix (Green)\n\n1. **Locate the relevant code**. Common locations:\n   - Dump bugs: `ir/inspector.go` (database introspection), `ir/normalize.go` (normalization), `internal/dump/` (output formatting)\n   - Diff bugs: `internal/diff/` (comparison logic — `table.go`, `column.go`, `index.go`, `trigger.go`, `view.go`, `function.go`, `procedure.go`, `sequence.go`, `type.go`, `policy.go`, `constraint.go`)\n   - IR bugs: `ir/ir.go` (data structures), `ir/quote.go` (identifier quoting)\n\n2. **Use reference skills as needed**:\n   - Consult **pg_dump Reference** skill for correct system catalog queries\n   - Consult **PostgreSQL Syntax Reference** skill for grammar questions\n   - Use **Validate with Database** skill to test queries against live PostgreSQL\n\n3. **Make the minimal fix**. Do not refactor surrounding code — focus on the bug.\n\n4. **Run the test to confirm it passes** (green):\n   ```bash\n   # For dump bugs\n   go test -v ./cmd/dump -run TestDumpCommand_Issue<NUMBER>\n\n   # For diff bugs\n   PGSCHEMA_TEST_FILTER=\"<category>/issue_<NUMBER>\" go test -v ./internal/diff -run TestDiffFromFiles\n   PGSCHEMA_TEST_FILTER=\"<category>/issue_<NUMBER>\" go test -v ./cmd -run TestPlanAndApply\n   ```\n\n### Phase 4: Verify No Regressions\n\nRun related tests selectively to verify nothing in the affected area broke. Do NOT run the full test suite (`go test -v ./...`) locally — it often times out due to resource constraints. The full regression suite runs in GitHub CI after the PR is created.\n\n```bash\n# For dump bugs — run the dump test suite\ngo test -v ./cmd/dump\n\n# For diff bugs — run tests in the same category\nPGSCHEMA_TEST_FILTER=\"<category>/\" go test -v ./internal/diff -run TestDiffFromFiles\nPGSCHEMA_TEST_FILTER=\"<category>/\" go test -v ./cmd -run TestPlanAndApply\n```\n\nIf any related tests fail, investigate and fix before proceeding.\n\n### Phase 5: Refactor Pass\n\nInvoke the **refactor-pass** skill to clean up:\n- Remove any dead code introduced or exposed by the fix\n- Simplify logic if the fix revealed unnecessary complexity\n- Ensure the test case is clean and minimal\n- Run build/tests to verify behavior after cleanup\n\n### Phase 6: Create PR\n\n1. **Create a feature branch**:\n   ```bash\n   git checkout -b fix/issue-<NUMBER>-<short-description>\n   ```\n\n2. **Commit the changes** with a descriptive message:\n   ```\n   fix: <concise description of what was fixed> (#<NUMBER>)\n   ```\n\n3. **Push and create PR**:\n   ```bash\n   git push -u origin fix/issue-<NUMBER>-<short-description>\n   gh pr create --title \"fix: <description> (#<NUMBER>)\" --body \"...\"\n   ```\n\n   PR body should include:\n   - `## Summary` — What was broken and how it was fixed\n   - `Fixes #<NUMBER>` — Link to the issue for auto-close\n   - `## Test plan` — What test case was added and how to run it\n\n## Checklist\n\n- [ ] Issue analyzed and bug type classified (dump vs diff)\n- [ ] Test case created with proper naming (`issue_<NUMBER>_<description>`)\n- [ ] Test fails before fix (red)\n- [ ] Minimal fix implemented\n- [ ] Test passes after fix (green)\n- [ ] Related tests pass (no regressions in affected area; full suite runs in CI)\n- [ ] Refactor pass completed\n- [ ] PR created and linked to issue\n"},"lastSynced":"2026-03-06T06:27:17.239Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing streamlined bug-fixing workflows for Postgres databases via GitHub issues","zh":"适合需要为Postgres数据库通过GitHub问题简化错误修复工作流的DevOps代理","ja":"PostgresデータベースのGitHubの問題を介したエラーフィックスのワークフローを簡素化する必要があるDevOpsエージェントに適しています","ko":"Postgres 데이터베이스의 GitHub 이슈를 통한 버그 수정 워크플로를 간소화해야 하는 DevOps 에이전트에 적합합니다","es":"Perfecto para agentes de DevOps que necesitan flujos de trabajo de corrección de errores simplificados para bases de datos Postgres a través de problemas de GitHub","fr":"Parfait pour les agents DevOps qui ont besoin de flux de travail de correction de bogues simplifiés pour les bases de données Postgres via des problèmes GitHub","de":"Perfekt für DevOps-Agents, die optimierte Fehlerbehebungs-Workflows für Postgres-Datenbanken über GitHub-Probleme benötigen","pt":"Perfeito para Agentes DevOps que necessitam de fluxos de trabalho de correção de bugs otimizados para bancos de dados Postgres via problemas do GitHub","ru":"Идеально подходит для агентов DevOps, которым необходимы оптимизированные рабочие процессы исправления ошибок для баз данных Postgres через проблемы GitHub","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى تدفقات عمل محسنة لتصحيح الأخطاء لبيانات Postgres عبر قضايا GitHub"},"recommendation":{"en":"Empowers agents to automate end-to-end bug-fixing workflows using Terraform-style declarative schema migrations, integrating with GitHub issues for seamless issue reproduction, fixing, and verification, leveraging Test-Driven Development (TDD) principles","zh":"赋予代理人使用Terraform风格的声明性模式迁移自动执行端到端的错误修复工作流的能力，集成GitHub问题以实现无缝的问题重现、修复和验证，利用测试驱动开发（TDD）原则","ja":"Terraformスタイルの宣言的なスキーママイグレーションを使用してエンドツーエンドのバグフィックスワークフローを自動化する機能をエージェントに与え、GitHubの問題を統合して問題の再現、修正、検証をシームレスに行い、テスト駆動開発（TDD）原則を利用する","ko":"테라폼 스타일의 선언적 스키마 마이그레이션을 사용하여 에이전트가 종단 간 버그 수정 워크플로를 자동화하도록 하는 기능을 제공하며, GitHub 문제를 통합하여 문제의 재현, 수정 및 확인을 무결점으로 수행하며, 테스트 주도 개발(TDD) 원칙을 활용합니다","es":"Habilita a los agentes a automatizar flujos de trabajo de corrección de errores de extremo a extremo utilizando migraciones de esquemas declarativas de estilo Terraform, integrando con problemas de GitHub para una reproducción, corrección y verificación de problemas sin problemas, aprovechando los principios de Desarrollo Dirigido por Pruebas (TDD)","fr":"Permet aux agents d''automatiser des flux de travail de correction de bogues de bout en bout en utilisant des migrations de schémas déclaratives de style Terraform, en intégrant avec des problèmes GitHub pour une reproduction, une correction et une vérification de problèmes sans accroc, en exploitant les principes de Développement Piloté par les Tests (TDD)","de":"Ermöglicht es Agenten, End-to-End-Fehlerbehebungs-Workflows zu automatisieren, indem sie Terraform-Style-deklarative Schemamigrationen verwenden, integriert mit GitHub-Problemen für eine nahtlose Wiedergabe, Behebung und Überprüfung von Problemen, unter Nutzung von Testgetriebener Entwicklung (TDD)-Prinzipien","pt":"Habilita os agentes a automatizar fluxos de trabalho de correção de bugs de ponta a ponta usando migrações de esquema declarativas no estilo Terraform, integrando com problemas do GitHub para reprodução, correção e verificação sem problemas de problemas, aproveitando os princípios do Desenvolvimento Dirigido por Testes (TDD)","ru":"Позволяет агентам автоматизировать рабочие процессы исправления ошибок от начала до конца, используя декларативные миграции схемы в стиле Terraform, интегрируя с проблемами GitHub для беспрепятственной воспроизведения, исправления и верификации проблем, используя принципы Тест-ориентированного развития (TDD)","ar":"يتمكّن الوكلاء من توفير تدفقات عمل تلقائية لتصحيح الأخطاء من النهاية إلى النهاية باستخدام هجرات مخطط تفصيلي في نمط Terraform، وتكامل مع قضايا GitHub من أجل إعادة إنتاج وتصحيح وتأكيد المشكلات بسلاسة، واستخدام مبادئ التطوير الموجه بالاختبار (TDD)"},"useCases":{"en":["Automating bug reproduction from GitHub issues","Generating schema migrations for Postgres databases","Verifying bug fixes using TDD"],"zh":["从GitHub问题自动化错误再现","为Postgres数据库生成模式迁移","使用TDD验证错误修复"],"ja":["GitHubの問題からバグの再現を自動化する","Postgresデータベースのスキーママイグレーションを生成する","TDDを使用してバグフィックスを検証する"],"ko":["GitHub 이슈에서 버그 재현을 자동화하는 것","Postgres 데이터베이스를 위한 스키마 마이그레이션 생성","TDD를 사용하여 버그 수정 확인"],"es":["Automatización de la reproducción de errores a partir de problemas de GitHub","Generación de migraciones de esquema para bases de datos Postgres","Verificación de correcciones de errores utilizando TDD"],"fr":["Automatisation de la reproduction de bogues à partir de problèmes GitHub","Génération de migrations de schéma pour les bases de données Postgres","Vérification des corrections de bogues en utilisant TDD"],"de":["Automatisierung der Fehlerwiedergabe aus GitHub-Problemen","Generierung von Schemamigrationen für Postgres-Datenbanken","Überprüfung von Fehlerbehebungen unter Verwendung von TDD"],"pt":["Automatizar a reprodução de bugs a partir de problemas do GitHub","Gerar migrações de esquema para bancos de dados Postgres","Verificar correções de bugs usando TDD"],"ru":["Автоматизировать воспроизведение ошибок из проблем GitHub","Генерировать миграции схемы для баз данных Postgres","Верифицировать исправления ошибок, используя TDD"],"ar":["توفير إعادة إنتاج الأخطاء من قضايا GitHub","генерировать هجرات مخطط تفصيلي لبيانات Postgres","التحقق من تصحيح الأخطاء باستخدام TDD"]},"limitations":{"en":["Requires GitHub issue URL or issue number from the pgplex/pgschema repo","Limited to Postgres databases","Dependent on gh CLI for GitHub interactions"],"zh":["需要来自pgplex/pgschema仓库的GitHub问题URL或问题编号","仅限Postgres数据库","依赖于gh CLI进行GitHub交互"],"ja":["pgplex/pgschemaリポジトリからのGitHubの問題URLまたは問題番号が必要","Postgresデータベースのみ","GitHubとのやり取りにはgh CLIに依存"],"ko":["pgplex/pgschema 저장소에서 GitHub 이슈 URL 또는 이슈 번호가 필요합니다","Postgres 데이터베이스만 지원","GitHub 상호 작용을 위해 gh CLI에 의존"],"es":["Requiere la URL del problema de GitHub o el número de problema del repositorio pgplex/pgschema","Limitado a bases de datos Postgres","Dependiente de gh CLI para interacciones con GitHub"],"fr":["Nécessite l''URL du problème GitHub ou le numéro de problème du référentiel pgplex/pgschema","Limité aux bases de données Postgres","Dépend de gh CLI pour les interactions avec GitHub"],"de":["Benötigt die GitHub-Problemm-URL oder die Problemmnummer aus dem pgplex/pgschema-Repository","Begrenzt auf Postgres-Datenbanken","Abhängig von gh CLI für GitHub-Interaktionen"],"pt":["Requer URL do problema do GitHub ou número do problema do repositório pgplex/pgschema","Limitado a bancos de dados Postgres","Dependente do gh CLI para interações com o GitHub"],"ru":["Требует URL проблемы GitHub или номер проблемы репозитория pgplex/pgschema","Ограничен базами данных Postgres","Зависит от gh CLI для взаимодействия с GitHub"],"ar":["يتطلب رابط URL لقضية GitHub أو رقم القضية من مستودع pgplex/pgschema","محدود لبيانات Postgres","يعتمد على واجهة سطر الأوامر gh للتفاعل مع GitHub"]},"version":4},"contentHash":"3405298c5aac79ae318b9dcdd0980d9642d596874ccb536084cf31e8c3d33399","qualityScore":55}');
