INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pgplex/pgschema/fix_bug', 'fix_bug', 'pgplex', 'pgschema', 'community', 'fix_bug pgplex pgschema community cicd cli ddl devops gitops multi-tenant postgres postgresql schema schema-change schema-diff schema-migration schema-migrations terraform fix_bug is a Terraform-style, declarative schema migration CLI for Postgres, benefiting developers and DevOps teams. It enables end-to-end workflow for fixing bugs reported as GitHub issues. Fix Bug是一种Terraform风格的Postgres数据库schema迁移CLI工具，用于修复数据库相关的问题 Fix BugはPostgresデータベースのスキーマを移行するTerraformスタイルのCLIツールです Fix Bug는 Postgres 데이터베이스의 스키마를 마이그레이션하는 Terraform 스타일의 CLI 도구입니다 fix_bug es una herramienta de línea de comandos para migraciones de esquema de Postgres que utiliza un enfoque declarativo similar a Terraform fix_bug est un outil en ligne de commande pour les migrations de schéma Postgres qui utilise une approche déclarative similaire à Terraform fix_bug ist ein Kommandozeilen-Tool für Postgres-Schemamigrationen, das einen deklarativen Ansatz ähnlich wie Terraform verwendet O Fix Bug é uma ferramenta de migração de esquema Postgres que utiliza um estilo declarativo, semelhante ao Terraform, para simplificar o processo de atualização de esquemas de banco de dados. Fix Bug - это инструмент миграции схемы Postgres, который использует декларативный стиль, похожий на Terraform, для упрощения процесса обновления схем баз данных. Fix Bug هو أداة هجرة مخطط قاعدة البيانات Postgres التي تستخدم نمطًا إعلانيًا، مشابهًا لـ Terraform، لتبسيط عملية تحديث مخططات قواعد البيانات. how to use fix_bug fix_bug vs Terraform fix_bug setup guide Postgres schema migration tools TDD for bug fixing fix_bug alternative to manual schema migration fix_bug install for CI/CD pipelines what is fix_bug fix_bug for GitOps workflows Postgres数据库schema迁移 Terraform风格的CLI工具 Fix Bug AI Agent GitHub issue追踪 TDD问题修复 多租户支持 GitOps支持 Uses gh issue view command to fetch and analyze GitHub issues Supports Test-Driven Development (TDD) for bug reproduction and verification Classifies bugs and identifies affected code areas Integrates with GitOps and CI/CD workflows Enables declarative schema migration for Postgres using Terraform-style CLI fix_bug is a command-line interface tool for Terraform-style, declarative schema migration in Postgres, using Test-Driven Development (TDD) for bug fixing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('microbus-io/fabric/Adding an Outbound Event Endpoint', 'community', 'microbus-io', 'fabric', 'microbus-io/fabric', 'Adding an Outbound Event Endpoint', 170, 5, 55, '2026-02-22T16:02:26Z', '2026-03-06T06:29:40.606Z', 'c1b133cf3d352b05e3c37205d378c5d1a7361e26676f53474f6781655cc77cb1', '{"id":"microbus-io/fabric/Adding an Outbound Event Endpoint","name":"Adding an Outbound Event Endpoint","description":{"en":"This skill enables AI agents to master the complex domain of distributed systems, producing enterprise-grade microservices. It teaches the architecture, patterns, and operational discipline for microservices.","zh":"AI工具可以学习分布式系统架构和微服务模式，添加出站事件端点以实现企业级微服务","ja":"AIエージェントは分散システムアーキテクチャとマイクロサービスパターンをマスターし、アウトバウンドイベントエンドポイントを追加してエンタープライズグレードのマイクロサービスを生成する","ko":"AI 에이전트는 분산 시스템 아키텍처 및 마이크로서비스 패턴을 학습하여 아웃바운드 이벤트 엔드포인트를 추가하고 엔터프라이즈급 마이크로서비스를 생성합니다","es":"Agrega un punto de fin de evento de salida con Microbus y mejora tus habilidades en sistemas distribuidos y microservicios. Esta habilidad enseña a tu agente de codificación a dominar el dominio complejo de los sistemas distribuidos.","fr":"Configurez un point de fin d''événement de sortie avec Microbus et améliorez vos compétences en systèmes distribués et microservices. Cette compétence enseigne à votre agent de codage à maîtriser le domaine complexe des systèmes distribués.","de":"Richten Sie einen Outbound-Ereignisendpunkt mit Microbus ein und verbessern Sie Ihre Fähigkeiten in verteilten Systemen und Microservices. Diese Fähigkeit lehrt Ihren Codierungsagenten, das komplexe Gebiet der verteilten Systeme zu beherrschen.","pt":"Adicione pontos de evento de saída com microserviços e frameworks de mensagem, melhorando a arquitetura de sistemas distribuídos","ru":"Настройте конечные точки исходящих событий с микросервисами и фреймворками шины сообщений, оптимизируя архитектуру распределенных систем","ar":"أضف نقطة نهاية للأحداث الخارجية مع خدمات ميكروي و إطارات عمل حافلة الرسائل، لتحسين هندسة الأنظمة الموزعة"},"seo":{"title":{"en":"Adding an Outbound Event Endpoint: Setup Guide for AI Agents","zh":"AIエージェント出站事件端点添加设置指南","ja":"AIエージェントのアウトバウンドイベントエンドポイント追加ベストプラクティス","ko":"AI 에이전트 아웃바운드 이벤트 엔드포인트 추가 설정 가이드","es":"Configuración de Punto de Fin de Evento de Salida: Guía d...","fr":"Configuration d''un Point de Fin d''Événement de Sortie: Me...","de":"Einrichtung eines Outbound-Ereignisendpunkts: Anleitung f...","pt":"Configurando Pontos de Evento de Saída com Ferramentas de AI","ru":"ИИ Агенты: Настройка Конечных Точек Исходящих Событий","ar":"إضافة نقطة نهاية للأحداث الخارجية مع أدوات الإي أى"},"description":{"en":"Discover how to master distributed systems with Adding an Outbound Event Endpoint. Learn to produce enterprise-grade microservices and get started with our s...","zh":"了解如何为AI工具添加出站事件端点，包括分布式系统架构和微服务模式","ja":"AIエージェントのアウトバウンドイベントエンドポイント追加方法を学び、分散システムアーキテクチャとマイクロサービスパターンをマスターする","ko":"AI 에이전트에 아웃바운드 이벤트 엔드포인트를 추가하는 방법을 알아보고 분산 시스템 아키텍처 및 마이크로서비스 패턴을 이해하십시오","es":"Aprende a agregar un punto de fin de evento de salida con Microbus y mejora tus habilidades en sistemas distribuidos y microservicios con herramientas de int...","fr":"Découvrez comment configurer un point de fin d''événement de sortie avec Microbus et améliorez vos compétences en systèmes distribués et microservices avec de...","de":"Erfahren Sie, wie Sie mit Microbus einen Outbound-Ereignisendpunkt einrichten und Ihre Fähigkeiten in verteilten Systemen und Microservices mit KI-Tools verb...","pt":"Aprenda a adicionar pontos de evento de saída com microserviços e frameworks de mensagem, otimizando a arquitetura de sistemas distribuídos","ru":"Изучите, как настроить конечные точки исходящих событий с микросервисами и фреймворками шины сообщений, оптимизируя архитектуру распределенных систем","ar":"تعلم كيفية إضافة نقطة نهاية للأحداث الخارجية مع خدمات ميكروي و إطارات عمل حافلة الرسائل، لتحسين هندسة الأنظمة الموزعة"},"definition":{"en":"Adding an Outbound Event Endpoint is a skill that teaches AI agents to produce enterprise-grade microservices, focusing on distributed systems architecture and operational discipline.","zh":"出站事件端点添加是AI工具的一项技能，用于实现分布式系统架构和微服务模式","ja":"アウトバウンドイベントエンドポイント追加は、AIエージェントのスキルの一つで、分散システムアーキテクチャとマイクロサービスパターンを実現する","ko":"아웃바운드 이벤트 엔드포인트 추가는 AI 에이전트의 기술 중 하나로 분산 시스템 아키텍처 및 마이크로서비스 패턴을 구현합니다","es":"Un punto de fin de evento de salida es un endpoint que permite a un microservicio enviar eventos a otros microservicios en un sistema distribuido.","fr":"Un point de fin d''événement de sortie est un point de terminaison qui permet à un microservice d''envoyer des événements à d''autres microservices dans un système distribué.","de":"Ein Outbound-Ereignisendpunkt ist ein Endpunkt, der es einem Microservice ermöglicht, Ereignisse an andere Microservices in einem verteilten System zu senden.","pt":"Ponto de evento de saída é um endpoint que envia eventos para outros microserviços","ru":"Конечная точка исходящих событий — это конечная точка, которая отправляет события в другие микросервисы","ar":"نقطة نهاية للأحداث الخارجية هي نقطة نهاية ترسل الأحداث إلى خدمات ميكروي أخرى"},"features":{"en":["Produces enterprise-grade microservices using messagebus and microservices framework","Generates code with MARKER comments for future edits","Exposes functional endpoints and web handlers via OpenAPI","Ignores other microservices unless explicitly instructed to do so","Supports opensource microservices development"],"zh":["支持分布式系统架构","实现微服务模式","添加出站事件端点","不注册出站事件在doOpenAPI中","支持MARKER注释","不分析其他微服务"],"ja":["分散システムアーキテクチャをサポート","マイクロサービスパターンを実現","アウトバウンドイベントエンドポイントを追加","doOpenAPIの中でアウトバウンドイベントを登録しない","MARKER注释をサポート","他のマイクロサービスを分析しない"],"ko":["분산 시스템 아키텍처 지원","마이크로서비스 패턴 구현","아웃바운드 이벤트 엔드포인트 추가","doOpenAPI에서 아웃바운드 이벤트 등록 안함","MARKER 주석 지원","他の 마이크로서비스 분석 안함"],"es":["Implementación de puntos de fin de evento de salida con Microbus","Dominio de sistemas distribuidos y microservicios","Uso de marcadores para futuras ediciones","Exposición de endpoints funcionales y controladores web a través de OpenAPI","No registro de eventos de salida en doOpenAPI"],"fr":["Configuration de points de fin d''événement de sortie avec Microbus","Maîtrise des systèmes distribués et microservices","Utilisation de marqueurs pour des éditions futures","Exposition d''endpoints fonctionnels et de contrôleurs web via OpenAPI","Pas d''enregistrement d''événements de sortie dans doOpenAPI"],"de":["Einrichtung von Outbound-Ereignisendpunkten mit Microbus","Beherrschung von verteilten Systemen und Microservices","Verwendung von Markern für zukünftige Bearbeitungen","Exposition von funktionalen Endpunkten und Web-Handlern über OpenAPI","Keine Registrierung von Outbound-Ereignissen in doOpenAPI"],"pt":["Utilização de frameworks de mensagem","Criação de microserviços escaláveis","Otimização da arquitetura de sistemas distribuídos","Integração com OpenAPI","Utilização de marcadores para futuras edições"],"ru":["Использование фреймворков шины сообщений","Создание масштабируемых микросервисов","Оптимизация архитектуры распределенных систем","Интеграция с OpenAPI","Использование маркеров для будущих редакций"],"ar":["استخدام إطارات عمل حافلة الرسائل","إنشاء خدمات ميكروي قابلة للتوسيع","تحسين هندسة الأنظمة الموزعة","التكامل مع OpenAPI","استخدام العلامات للمحررات المستقبلية"]},"keywords":{"en":["how to add an outbound event endpoint","what is adding an outbound event endpoint","adding an outbound event endpoint alternative","adding an outbound event endpoint vs messagebus","adding an outbound event endpoint setup guide","adding an outbound event endpoint install for microservices"],"zh":["AI工具","出站事件端点","分布式系统架构","微服务模式","MARKER注释","doOpenAPI","企业级微服务","AIエージェント"],"ja":["AIエージェント","アウトバウンドイベントエンドポイント","分散システムアーキテクチャ","マイクロサービスパターン","MARKER注释","doOpenAPI","エンタープライズグレードマイクロサービス","AIツール"],"ko":["AI 에이전트","아웃바운드 이벤트 엔드포인트","분산 시스템 아키텍처","마이크로서비스 패턴","MARKER 주석","doOpenAPI","엔터프라이즈급 마이크로서비스","AI 툴"],"es":["punto de fin de evento de salida","microservicios","sistemas distribuidos","Microbus","OpenAPI","agentes de inteligencia artificial","desarrollo de software","arquitectura de software","patrones de diseño"],"fr":["point de fin d''événement de sortie","microservices","systèmes distribués","Microbus","OpenAPI","agents d''intelligence artificielle","développement de logiciels","architecture de logiciels","modèles de conception"],"de":["Outbound-Ereignisendpunkt","Microservices","verteilte Systeme","Microbus","OpenAPI","KI-Tools","Software-Entwicklung","Software-Architektur","Entwurfsmuster"],"pt":["pontos de evento de saída","microserviços","frameworks de mensagem","arquitetura de sistemas distribuídos","OpenAPI","desenvolvimento de software","ferramentas de AI","iot"],"ru":["конечные точки исходящих событий","микросервисы","фреймворки шины сообщений","архитектура распределенных систем","OpenAPI","разработка программного обеспечения","ИИ агенты","iot"],"ar":["نقاط نهاية للأحداث الخارجية","خدمات ميكروي","إطارات عمل حافلة الرسائل","هندسة الأنظمة الموزعة","OpenAPI","تطوير البرمجيات","أدوات الإي أى","iot"]}},"owner":"microbus-io","repo":"fabric","repoPath":"microbus-io/fabric","stars":170,"forks":5,"updatedAt":"2026-02-22T16:02:26Z","topics":["framework","messagebus","microservices","opensource"],"category":"community","skillMd":{"name":"Adding an Outbound Event Endpoint","description":"Creates or modify an outbound event endpoint of a microservice. Use when explicitly asked by the user to create or modify an outbound event endpoint of a microservice.","bodyPreview":"**CRITICAL**: Do NOT explore or analyze other microservices unless explicitly instructed to do so. The instructions in this skill are self-contained to this microservice.\n\n**CRITICAL**: Do not omit the `MARKER` comments when generating the code. They are intended as waypoints for future edits.\n\n**CRITICAL**: Do NOT register outbound events in `doOpenAPI`. Only functional endpoints and web handlers are exposed via OpenAPI.                        \n\n## Workflow\n\nCopy this checklist and track your p","body":"**CRITICAL**: Do NOT explore or analyze other microservices unless explicitly instructed to do so. The instructions in this skill are self-contained to this microservice.\n\n**CRITICAL**: Do not omit the `MARKER` comments when generating the code. They are intended as waypoints for future edits.\n\n**CRITICAL**: Do NOT register outbound events in `doOpenAPI`. Only functional endpoints and web handlers are exposed via OpenAPI.                        \n\n## Workflow\n\nCopy this checklist and track your progress:\n\n```\nCreating or modifying an event endpoint:\n- [ ] Step 1: Read local AGENTS.md file\n- [ ] Step 2: Determine signature\n- [ ] Step 3: Determine the method and route\n- [ ] Step 4: Determine a description\n- [ ] Step 5: Define complex types\n- [ ] Step 6: Define the payload structs\n- [ ] Step 7: Extend the trigger and hook\n- [ ] Step 8: Trigger the event\n- [ ] Step 9: Test the outgoing event\n- [ ] Step 10: Housekeeping\n```\n\n#### Step 1: Read Local `AGENTS.md` File\n\nRead the local `AGENTS.md` file in the microservice''s directory. It contains microservice-specific instructions that should take precedence over global instructions.\n\n#### Step 2: Determine Signature\n\nDetermine the Go signature of the outgoing event endpoint.\n\n```go\nfunc OnMyEvent(ctx context.Context, inArg1 string, inArg2 ThirdPartyStruct) (outArg1 map[string]MyStruct, err error)\n```\n\nConstraints:\n- The first input argument must be `ctx context.Context`\n- The function must return an `err error`\n- Maps must be keyed by string, e.g. `map[string]any`\n- Complex types (structs) are allowed by value or by reference, e.g. `MyStruct` or `*MyStruct`\n- All input or output arguments must be serializable into JSON, including complex types\n- Arguments must not be named `t` or `svc`\n- Argument names must start with a lowercase letter\n- The function name must start with `On` followed by an uppercase letter\n\n#### Step 3: Determine the Method and Route\n\nThe method of the endpoint determines the HTTP method with which it will be addressable. The most common approach is to use `POST`.\n\nThe route of the endpoint is resolved relative to the hostname of the microservice to determine how it is addressed. The common approach is to use the name of the endpoint in kebab-case as its route, e.g. `/my-event`.\n\nEvents should be set on a dedicated port to allow blocking external requests from reaching them. The recommended port to use for events is 417. Prefix the route with the port, e.g. `:417/my-event`.\n\nDo not use path arguments in events.\n\nPrefix the route with `//` to set a hostname other than that of this microservice, e.g. `//another.host.name:417/on-something`\n\n#### Step 4: Determine a Description\n\nDescribe the endpoint starting with its name, in Go doc style: `OnMyEvent is triggered when X`. Embed this description in followup steps wherever you see `OnMyEvent is triggered when X`.\n\n#### Step 5: Define Complex Types\n\nIdentify the struct types in the signature. These complex types must be defined in the `myserviceapi` directory because they are part of the public API of the microservice. Skip this step if there are no complex types.\n\nPlace each definition in a separate file named after the type, e.g. `myserviceapi/mystruct.go`.\n\nIf the complex type is owned by this microservice, define its struct explicitly. Be sure to include `json` tags with camelCase names and the `omitzero` option.\n\n```go\npackage myserviceapi\n\n// MyStruct is X.\ntype MyStruct struct {\n\tFooField string `json:\"fooField,omitzero\"`\n\tBarField int    `json:\"barField,omitzero\"`\n}\n```\n\nIf the complex type is owned by another microservice, define an alias to it instead.\n\n```go\npackage myserviceapi\n\nimport (\n\t\"github.com/path/to/thirdparty\"\n)\n\n// ThirdPartyStruct is X.\ntype ThirdPartyStruct = thirdparty.ThirdPartyStruct\n```\n\n#### Step 6: Define the Payload Structs\n\nAppend the function''s payload structs to `myserviceapi/client.go`.\nUse PascalCase for the field names and camelCase for the `json` tag names.\n\n`OnMyEventIn` holds the input arguments of the function, excluding `ctx context.Context`. If an argument is named `httpRequestBody`, set its `json` tag value to `-`.\n\n```go\n// OnMyEventIn are the input arguments of OnMyEvent.\ntype OnMyEventIn struct { // MARKER: OnMyEvent\n\tInArg1 string           `json:\"inArg1,omitzero\"`\n\tInArg2 ThirdPartyStruct `json:\"inArg2,omitzero\"`\n}\n```\n\n`OnMyEventOut` holds the output arguments of the function, excluding `err error`. If an argument is named `httpStatusCode`, set its `json` tag value to `-`.\n\n```go\n// OnMyEventOut are the output arguments of OnMyEvent.\ntype OnMyEventOut struct { // MARKER: OnMyEvent\n\tOutArg1 map[string]MyStruct `json:\"outArg1,omitzero\"`\n}\n```\n\n`OnMyEventResponse` holds the response of the request. The struct provides a single method `Get` that returns the function''s return arguments.\n\nIf there are output arguments besides `err error`:\n\n```go\n// OnMyEventResponse packs the response of OnMyEvent.\ntype OnMyEventResponse multicastResponse // MARKER: OnMyEvent\n\n// Get retrieves the return values.\nfunc (_res *OnMyEventResponse) Get() (argOut1 map[string]MyStruct, err error) { // MARKER: OnMyEvent\n\t_d := _res.data.(*OnMyEventOut)\n\treturn _d.ArgOut1, _res.err\n}\n```\n\nIf `err error` is the only return argument:\n\n```go\n// OnMyEventResponse packs the response of OnMyEvent.\ntype OnMyEventResponse multicastResponse // MARKER: OnMyEvent\n\n// Get retrieves the return values.\nfunc (_res *OnMyEventResponse) Get() (err error) { // MARKER: OnMyEvent\n\treturn _res.err\n}\n```\n\n#### Step 7: Extend the Trigger and Hook\n\nDefine the endpoint in the `var` block in `myserviceapi/client.go`, after the corresponding `HINT` comment.\n\n```go\nvar (\n\t// HINT: Insert endpoint definitions here\n\t// ...\n\tOnMyEvent = Def{Method: \"POST\", Route: \":417/on-my-event\"} // MARKER: OnMyEvent\n)\n```\n\nAppend the following methods to `myserviceapi/client.go`.\n\n```go\n/*\nOnMyEvent is triggered when X.\n*/\nfunc (_c MulticastTrigger) OnMyEvent(ctx context.Context, argIn1 string, argIn2 ThirdPartyStruct) iter.Seq[*OnMyEventResponse] { // MARKER: OnMyEvent\n\t_in := OnMyEventIn{ArgIn1: argIn1, ArgIn2: argIn2}\n\t_out := OnMyEventOut{}\n\t_queue := marshalPublish(ctx, _c.svc, _c.opts, _c.host, OnMyEvent.Method, OnMyEvent.Route, &_in, &_out)\n\treturn func(yield func(*OnMyEventResponse) bool) {\n\t\tfor _r := range _queue {\n\t\t\t_clone := _out\n\t\t\t_r.data = &_clone\n\t\t\tif !yield((*OnMyEventResponse)(_r)) {\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}\n}\n\n/*\nOnMyEvent is triggered when X.\n*/\nfunc (c Hook) OnMyEvent(handler func(ctx context.Context, argIn1 string, argIn2 ThirdPartyStruct) (argOut1 map[string]MyStruct, err error)) (unsub func() error, err error) { // MARKER: OnMyEvent\n\tdoOnMyEvent := func(w http.ResponseWriter, r *http.Request) error {\n\t\tvar in OnMyEventIn\n\t\tvar out OnMyEventOut\n\t\terr = marshalFunction(w, r, OnMyEvent.Route, &in, &out, func(_ any, _ any) error {\n\t\t\tout.ArgOut1, err = handler(r.Context(), in.ArgIn1, in.ArgIn2)\n\t\t\treturn err\n\t\t})\n\t\treturn err // No trace\n\t}\n\tpath := httpx.JoinHostAndPath(c.host, OnMyEvent.Route)\n\tunsub, err = c.svc.Subscribe(OnMyEvent.Method, path, doOnMyEvent, c.opts...)\n\treturn unsub, errors.Trace(err)\n}\n```\n\n#### Step 8: Trigger the Event\n\nThe event itself does not have an implementation. Rather, trigger the event from within other endpoints using its trigger.\n\nTo fire an event and wait for zero or more responses, loop over the response channel.\n\n```go\nfor r := range myserviceapi.NewMulticastTrigger(svc).OnMyEvent(ctx, argIn1, argIn2) {\n\targOut1, err := r.Get()\n\tif err != nil {\n\t\treturn errors.Trace(err)\n\t}\n\t// ...\n}\n```\n\nTo fire and forget, call the trigger without iterating over its response.\n\n```go\nmyserviceapi.NewMulticastTrigger(svc).OnMyEvent(ctx, argIn1, argIn2)\n```\n\n#### Step 9: Test the Outgoing Event\n\nAppend the integration test to `service_test.go`.\n\n```go\nfunc TestMyService_OnMyEvent(t *testing.T) { // MARKER: OnMyEvent\n\tt.Parallel()\n\tctx := t.Context()\n\n\t// Initialize the microservice under test\n\tsvc := NewService()\n\n\t// Initialize the testers\n\ttester := connector.New(\"tester.client\")\n\tclient := myserviceapi.NewClient(tester)\n\ttrigger := myserviceapi.NewMulticastTrigger(tester)\n\thook := myserviceapi.NewHook(tester)\n\n\t// Run the testing app\n\tapp := application.New()\n\tapp.Add(\n\t\t// HINT: Add microservices or mocks required for this test\n\t\tsvc,\n\t\ttester,\n\t)\n\tapp.RunInTest(t)\n\n\t/*\n\t\tHINT: Use the following pattern for each test case\n\n\t\tt.Run(\"test_case_name\", func(t *testing.T) {\n\t\t\tassert := testarossa.For(t)\n\n\t\t\tunsub, err := hook.WithOptions(sub.Queue(\"UniqueQueueName\")).OnMyEvent(\n\t\t\t\tfunc(ctx context.Context, argIn1 string, argIn2 ThirdPartyStruct) (argOut1 map[string]myserviceapi.MyStruct, err error) {\n\t\t\t\t\tassert.Expect(\n\t\t\t\t\t\targIn1, expectedArgIn1,\n\t\t\t\t\t\targIn2, expectedArgIn2,\n\t\t\t\t\t)\n\t\t\t\t\t// Implement event sink here...\n\t\t\t\t\treturn argOut1, err\n\t\t\t\t},\n\t\t\t)\n\t\t\tif assert.NoError(err) {\n\t\t\t\tdefer unsub()\n\t\t\t}\n\n\t\t\tfor e := range trigger.OnMyEvent(ctx, argIn1, argIn2) {\n\t\t\t\tif frame.Of(e.HTTPResponse).FromHost() == tester.Hostname() {\n\t\t\t\t\targOut1, err := e.Get()\n\t\t\t\t\tassert.Expect(\n\t\t\t\t\t\targOut1, expectedArgOut1,\n\t\t\t\t\t\terr, nil,\n\t\t\t\t\t)\n\t\t\t\t}\n\t\t\t}\n\t\t})\n\t*/\n}\n```\n\nSkip the remainder of this step if instructed to be \"quick\" or to skip tests.\n\nInsert test cases at the bottom of the integration test function using the recommended pattern.\n\n- Enter distinct queue names in `sub.Queue` when hooking multiple times to the event to simulate multiple clients. Use only alphanumeric characters for queue names.\n\n```go\nt.Run(\"test_case_name\", func(t *testing.T) {\n\tassert := testarossa.For(t)\n\n\tunsub, err := hook.WithOptions(sub.Queue(\"UniqueQueueName\")).OnMyEvent(\n\t\tfunc(ctx context.Context, argIn1 string, argIn2 ThirdPartyStruct) (argOut1 map[string]myserviceapi.MyStruct, err error) {\n\t\t\tassert.Expect(\n\t\t\t\targIn1, expectedArgIn1,\n\t\t\t\targIn2, expectedArgIn2,\n\t\t\t)\n\t\t\t// Implement event sink here...\n\t\t\treturn argOut1, err\n\t\t},\n\t)\n\tif assert.NoError(err) {\n\t\tdefer unsub()\n\t}\n\n\tfor e := range trigger.OnMyEvent(ctx, argIn1, argIn2) {\n\t\tif frame.Of(e.HTTPResponse).FromHost() == tester.Hostname() {\n\t\t\targOut1, err := e.Get()\n\t\t\tassert.Expect(\n\t\t\t\targOut1, expectedArgOut1,\n\t\t\t\terr, nil,\n\t\t\t)\n\t\t}\n\t}\n})\n```\n\nDo not remove the `HINT` comments.\n\n#### Step 10: Housekeeping\n\nFollow the `microbus/housekeeping` skill.\n"},"lastSynced":"2026-03-06T06:29:40.606Z","agentAnalysis":{"suitability":{"en":"Perfect for Microservice Agents needing to integrate with distributed systems and produce enterprise-grade outbound event endpoints","zh":"非常适合需要与分布式系统集成并产生企业级出站事件端点的微服务代理","ja":"マイクロサービスエージェントが分散システムと統合してエンタープライズグレードのアウトバウンドイベントエンドポイントを生成する必要がある場合に最適","ko":"분산 시스템과 통합하여 기업급 아웃바운드 이벤트 엔드포인트를 생성해야 하는 마이크로 서비스 에이전트에 적합","es":"Perfecto para Agentes de Microservicio que necesitan integrarse con sistemas distribuidos y producir puntos de conexión de eventos de salida de nivel empresarial","fr":"Parfait pour les agents de microservice qui ont besoin de s''intégrer avec des systèmes distribués et de produire des points de terminaison d''événements de sortie de niveau entreprise","de":"Perfekt für Microservice-Agents, die mit verteilten Systemen integrieren und unternehmensgrade Endpunkte für ausgehende Ereignisse produzieren müssen","pt":"Perfeito para Agentes de Microsserviços que precisam se integrar a sistemas distribuídos e produzir pontos de extremidade de eventos de saída de nível empresarial","ru":"Идеально подходит для агентов микросервисов, которым необходимо интегрироваться с распределенными системами и производить корпоративные конечные точки исходящих событий","ar":"مثالي للوكلاء ميكروسيرفيس الذين يحتاجون إلى التكامل مع الأنظمة الموزعة وإنتاج نقاط النهاية للأحداث الخارجية من الدرجة المؤسسية"},"recommendation":{"en":"Empowers agents to master the architecture, patterns, and operational discipline for microservices, enabling the creation of scalable and secure outbound event endpoints using OpenAPI, while following strict guidelines to avoid exploring or analyzing other microservices and omitting critical `MARKER` comments","zh":"赋予代理掌握微服务的架构、模式和运营纪律，实现使用OpenAPI创建可扩展和安全的出站事件端点，同时遵循严格的指南以避免探索或分析其他微服务并省略关键的`MARKER`注释","ja":"エージェントがマイクロサービスのアーキテクチャ、パターン、運用規範をマスターし、OpenAPIを使用してスケーラブルでセキュアなアウトバウンドイベントエンドポイントを作成できるようにし、他のマイクロサービスを探索または分析したり、重要な`MARKER`コメントを省略したりしないようにするための厳格なガイドラインに従う","ko":"에이전트가 마이크로 서비스의 아키텍처, 패턴 및 운영 규범을 마스터하여 OpenAPI를 사용하여 확장 가능하고 안전한 아웃바운드 이벤트 엔드포인트를 생성할 수 있도록 하며, 다른 마이크로 서비스를 탐색하거나 분석하거나 중요한 `MARKER` 주석을 생략하지 않도록 엄격한 가이드라인을 따름","es":"Habilita a los agentes a dominar la arquitectura, los patrones y la disciplina operativa para microservicios, lo que permite la creación de puntos de conexión de eventos de salida escalables y seguros utilizando OpenAPI, siguiendo estrictas pautas para evitar explorar o analizar otros microservicios y omitir comentarios críticos `MARKER`","fr":"Permet aux agents de maîtriser l''architecture, les modèles et la discipline opérationnelle pour les microservices, permettant ainsi la création de points de terminaison d''événements de sortie évolutifs et sécurisés à l''aide d''OpenAPI, tout en suivant des lignes directrices strictes pour éviter d''explorer ou d''analyser d''autres microservices et d''omettre des commentaires critiques `MARKER`","de":"Ermächtigt die Agenten, die Architektur, Muster und operative Disziplin für Microservices zu beherrschen, wodurch die Erstellung von skalierbaren und sicheren Endpunkten für ausgehende Ereignisse mit OpenAPI ermöglicht wird, unter strenger Einhaltung von Richtlinien, um zu vermeiden, andere Microservices zu erkunden oder zu analysieren und kritische `MARKER`-Kommentare auszulassen","pt":"Habilita os agentes a dominar a arquitetura, padrões e disciplina operacional para microsserviços, permitindo a criação de pontos de extremidade de eventos de saída escaláveis e seguros usando OpenAPI, seguindo diretrizes estritas para evitar explorar ou analisar outros microsserviços e omitir comentários críticos `MARKER`","ru":"Наделяет агентов возможностью овладеть архитектурой, шаблонами и операционной дисциплиной для микросервисов, позволяя создавать масштабируемые и безопасные конечные точки исходящих событий с использованием OpenAPI, следуя строгим рекомендациям, чтобы не исследовать или анализировать другие микросервисы и не опускать критические комментарии `MARKER`","ar":"تمكّن الوكلاء من إتقان الهندسة المعمارية والأنماط والانضباط التشغيلي للميكروسيرفيس، مما يسمح بإنشاء نقاط النهاية للأحداث الخارجية القابلة للتمكين والأمن باستخدام OpenAPI، متبعة إرشادات صارمة لتجنب استكشاف أو تحليل ميكروسيرفيس أخرى وتجاهل تعليقات `MARKER` الحرجة"},"useCases":{"en":["Implementing outbound event endpoints for distributed systems","Generating enterprise-grade microservices with strict operational discipline","Integrating with existing systems using OpenAPI for functional endpoints and web handlers"],"zh":["为分布式系统实现出站事件端点","使用严格的运营纪律生成企业级微服务","使用OpenAPI与现有系统集成以实现功能端点和Web处理程序"],"ja":["分散システムのアウトバウンドイベントエンドポイントを実装する","厳格な運用規範を使用してエンタープライズグレードのマイクロサービスを生成する","OpenAPIを使用して既存のシステムと統合し、機能エンドポイントとWebハンドラーを実現する"],"ko":["분산 시스템을 위한 아웃바운드 이벤트 엔드포인트 구현","严格한 운영 규범을 사용하여 기업급 마이크로 서비스 생성","OpenAPI를 사용하여 기존 시스템과 통합하여 기능 엔드포인트 및 Web 핸들러 구현"],"es":["Implementar puntos de conexión de eventos de salida para sistemas distribuidos","Generar microservicios de nivel empresarial con estricta disciplina operativa","Integrarse con sistemas existentes utilizando OpenAPI para puntos de conexión funcionales y controladores web"],"fr":["Mettre en œuvre des points de terminaison d''événements de sortie pour les systèmes distribués","Générer des microservices de niveau entreprise avec une discipline opérationnelle stricte","S''intégrer avec les systèmes existants en utilisant OpenAPI pour les points de terminaison fonctionnels et les gestionnaires web"],"de":["Implementierung von Endpunkten für ausgehende Ereignisse für verteilte Systeme","Erzeugung von Microservices von Unternehmensniveau mit strenger operativer Disziplin","Integration mit bestehenden Systemen unter Verwendung von OpenAPI für funktionale Endpunkte und Web-Handler"],"pt":["Implementação de pontos de extremidade de eventos de saída para sistemas distribuídos","Geração de microsserviços de nível empresarial com disciplina operacional estrita","Integração com sistemas existentes usando OpenAPI para pontos de extremidade funcionais e manipuladores da web"],"ru":["Реализация конечных точек исходящих событий для распределенных систем","Генерация корпоративных микросервисов с строгой операционной дисциплиной","Интеграция с существующими системами с использованием OpenAPI для функциональных конечных точек и веб-обработчиков"],"ar":["تنفيذ نقاط النهاية للأحداث الخارجية لأنظمة موزعة","توليد ميكروسيرفيس من الدرجة المؤسسية مع انضباط تشغيلي صارم","التكامل مع الأنظمة الحالية باستخدام OpenAPI لنقاط النهاية الوظيفية ومعالجات الويب"]},"limitations":{"en":["Must not explore or analyze other microservices unless explicitly instructed","Must not omit `MARKER` comments in the code","Must not register outbound events in `doOpenAPI`"],"zh":["除非明确指示，否则不得探索或分析其他微服务","不得省略代码中的关键`MARKER`注释","不得在`doOpenAPI`中注册出站事件"],"ja":["明示的に指示されない限り、他のマイクロサービスを探索または分析してはならない","コード内の重要な`MARKER`コメントを省略してはならない","`doOpenAPI`内でアウトバウンドイベントを登録してはならない"],"ko":["명시적으로 지시되지 않는 한 다른 마이크로 서비스를 탐색하거나 분석해서는 안 됨","코드 내의 중요한 `MARKER` 주석을 생략해서는 안 됨","`doOpenAPI` 내에서 아웃바운드 이벤트를 등록해서는 안 됨"],"es":["No debe explorar ni analizar otros microservicios a menos que se le instruya explícitamente","No debe omitir comentarios `MARKER` en el código","No debe registrar eventos de salida en `doOpenAPI`"],"fr":["Ne doit pas explorer ou analyser d''autres microservices à moins d''être explicitement instruit","Ne doit pas omettre les commentaires `MARKER` dans le code","Ne doit pas enregistrer les événements de sortie dans `doOpenAPI`"],"de":["Darf andere Microservices nicht erkunden oder analysieren, es sei denn, es wird explizit angewiesen","Darf keine `MARKER`-Kommentare im Code auslassen","Darf keine ausgehenden Ereignisse in `doOpenAPI` registrieren"],"pt":["Não deve explorar ou analisar outros microsserviços a menos que explicitamente instruído","Não deve omitir comentários `MARKER` no código","Não deve registrar eventos de saída em `doOpenAPI`"],"ru":["Не должно исследовать или анализировать другие микросервисы, если не указано явно","Не должно опускать комментарии `MARKER` в коде","Не должно регистрировать исходящие события в `doOpenAPI`"],"ar":["لا ينبغي أن يستكشف أو يanalyzes ميكروسيرفيس أخرى إلا إذا تم الإشارة إليه явно","لا ينبغي أن يتجاهل تعليقات `MARKER` في الكود","لا ينبغي أن يسجل أحداثًا خارجية في `doOpenAPI`"]},"version":4},"contentHash":"c1b133cf3d352b05e3c37205d378c5d1a7361e26676f53474f6781655cc77cb1","qualityScore":55}');
