INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('microbus-io/fabric/Adding an Outbound Event Endpoint', 'Adding an Outbound Event Endpoint', 'microbus-io', 'fabric', 'community', 'Adding an Outbound Event Endpoint microbus-io fabric community framework messagebus microservices opensource This skill enables AI agents to master the complex domain of distributed systems, producing enterprise-grade microservices. It teaches the architecture, patterns, and operational discipline for microservices. AI工具可以学习分布式系统架构和微服务模式，添加出站事件端点以实现企业级微服务 AIエージェントは分散システムアーキテクチャとマイクロサービスパターンをマスターし、アウトバウンドイベントエンドポイントを追加してエンタープライズグレードのマイクロサービスを生成する AI 에이전트는 분산 시스템 아키텍처 및 마이크로서비스 패턴을 학습하여 아웃바운드 이벤트 엔드포인트를 추가하고 엔터프라이즈급 마이크로서비스를 생성합니다 Agrega un punto de fin de evento de salida con Microbus y mejora tus habilidades en sistemas distribuidos y microservicios. Esta habilidad enseña a tu agente de codificación a dominar el dominio complejo de los sistemas distribuidos. Configurez un point de fin d''événement de sortie avec Microbus et améliorez vos compétences en systèmes distribués et microservices. Cette compétence enseigne à votre agent de codage à maîtriser le domaine complexe des systèmes distribués. Richten Sie einen Outbound-Ereignisendpunkt mit Microbus ein und verbessern Sie Ihre Fähigkeiten in verteilten Systemen und Microservices. Diese Fähigkeit lehrt Ihren Codierungsagenten, das komplexe Gebiet der verteilten Systeme zu beherrschen. Adicione pontos de evento de saída com microserviços e frameworks de mensagem, melhorando a arquitetura de sistemas distribuídos Настройте конечные точки исходящих событий с микросервисами и фреймворками шины сообщений, оптимизируя архитектуру распределенных систем أضف نقطة نهاية للأحداث الخارجية مع خدمات ميكروي و إطارات عمل حافلة الرسائل، لتحسين هندسة الأنظمة الموزعة how to add an outbound event endpoint what is adding an outbound event endpoint adding an outbound event endpoint alternative adding an outbound event endpoint vs messagebus adding an outbound event endpoint setup guide adding an outbound event endpoint install for microservices AI工具 出站事件端点 分布式系统架构 微服务模式 MARKER注释 doOpenAPI 企业级微服务 AIエージェント Produces enterprise-grade microservices using messagebus and microservices framework Generates code with MARKER comments for future edits Exposes functional endpoints and web handlers via OpenAPI Ignores other microservices unless explicitly instructed to do so Supports opensource microservices development Adding an Outbound Event Endpoint is a skill that teaches AI agents to produce enterprise-grade microservices, focusing on distributed systems architecture and operational discipline.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LIDR-academy/AI4Devs-LTI-extended/openspec-ff-change', 'community', 'LIDR-academy', 'AI4Devs-LTI-extended', 'LIDR-academy/AI4Devs-LTI-extended', 'openspec-ff-change', 39, 60, 55, '2026-02-22T18:42:59Z', '2026-03-06T06:37:33.510Z', '130ad13ff44998927f08fd95c225a5b215bd2e82c7183e97c9f29703f5129c64', '{"id":"LIDR-academy/AI4Devs-LTI-extended/openspec-ff-change","name":"openspec-ff-change","description":{"en":"openspec-ff-change is a repository of experiments that enables fast-forwarding through artifact creation, benefiting developers who need to quickly generate project setup. It automates the process using Jira ticket IDs and custom change names.","zh":"openspec-ff-change是一个快速生成项目所需文件的工具，支持Jira票据ID、自定义名称和描述","ja":"openspec-ff-changeは、JiraチケットID、カスタム名、説明を使用してプロジェクトの必要なファイルを一括生成するツールです","ko":"openspec-ff-change는 Jira 티켓 ID, 사용자 정의 이름 및 설명을 사용하여 프로젝트에 필요한 파일을 빠르게 생성하는 도구입니다","es":"openspec-ff-change es una herramienta que permite generar artefactos de implementación en un solo paso, utilizando Jira MCP y nombres en kebab-case","fr":"openspec-ff-change est un outil qui permet de générer des artefacts d''implémentation en un seul étape, en utilisant Jira MCP et des noms en kebab-case","de":"openspec-ff-change ist ein Tool, das die Generierung von Implementierungsartefakten in einem Schritt ermöglicht, unter Verwendung von Jira MCP und Kebab-Case-Namen","pt":"O openspec-ff-change é uma ferramenta que automatiza a criação de artefatos com Jira MCP e kebab-case, permitindo que os desenvolvedores iniciem a implementação rapidamente.","ru":"openspec-ff-change - это инструмент, который автоматизирует создание артефактов с помощью Jira MCP и kebab-case, позволяя разработчикам быстро приступить к реализации для ИИ Агенты","ar":"openspec-ff-change هو أداة تلقيم إنشاء الملفات الفنية باستخدام Jira MCP و kebab-case، مما يسمح للمطورين بدء التنفيذ بسرعة لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"openspec-ff-change: Fast-Forward Artifact Creation Setup ...","zh":"openspec-ff-change 快速实现指南","ja":"openspec-ff-change Setup Guide - AIエージェントを活用","ko":"openspec-ff-change 설정 가이드 - 빠른 구현을 위한 팁","es":"Guía de configuración de openspec-ff-change para implemen...","fr":"Guide de démarrage rapide pour openspec-ff-change","de":"Schnellstartanleitung für openspec-ff-change","pt":"Guia de Configuração do openspec-ff-change: Automação de ...","ru":"Настройка openspec-ff-change: Инструмент для Быстрого Соз...","ar":"دليل إعداد openspec-ff-change: تلقيم إنشاء الملفات الفنية..."},"description":{"en":"Streamline your development workflow with openspec-ff-change, generating everything needed to start implementation in one go - learn how to get started today!","zh":"了解openspec-ff-change的功能和特点，快速实现您的项目需求","ja":"openspec-ff-changeの機能と特徴をご紹介。AIエージェントを活用して開発を効率化","ko":"openspec-ff-change의 기능과 특징을 살펴보세요. 빠른 구현과 개발 효율화를 위한 팁","es":"Aprende a utilizar openspec-ff-change para generar artefactos de implementación en un solo paso. Descubre cómo funciona","fr":"Découvrez comment utiliser openspec-ff-change pour générer des artefacts d''implémentation en un seul étape","de":"Erfahren Sie, wie Sie openspec-ff-change verwenden, um Implementierungsartefakte in einem Schritt zu generieren","pt":"Aprenda a configurar o openspec-ff-change para automatizar a criação de artefatos com Jira MCP e kebab-case","ru":"Узнайте, как настроить openspec-ff-change для автоматизации создания артефактов с помощью Jira MCP и kebab-case для ИИ Агенты","ar":"تعلم كيفية إعداد openspec-ff-change لتلقيم إنشاء الملفات الفنية باستخدام Jira MCP و kebab-case لأدوات الذكاء الاصطناعي"},"definition":{"en":"openspec-ff-change is a technical skill that facilitates rapid artifact creation by generating necessary project files and setup in a single step, utilizing Jira MCP for ticket content fetching.","zh":"openspec-ff-change是一种快速生成项目文件的AI工具","ja":"openspec-ff-changeは、プロジェクトファイルを一括生成するAIエージェントの一種です","ko":"openspec-ff-change는 프로젝트 파일을 빠르게 생성하는 AI 도구입니다","es":"openspec-ff-change es una herramienta de implementación que utiliza Jira MCP para generar artefactos","fr":"openspec-ff-change est un outil d''implémentation qui utilise Jira MCP pour générer des artefacts","de":"openspec-ff-change ist ein Implementierungstool, das Jira MCP verwendet, um Artefakte zu generieren","pt":"O openspec-ff-change é uma ferramenta de automação de criação de artefatos que utiliza Jira MCP e kebab-case","ru":"openspec-ff-change - это инструмент автоматизации создания артефактов, использующий Jira MCP и kebab-case для ИИ Агенты","ar":"openspec-ff-change هو أداة تلقيم إنشاء الملفات الفنية التي تستخدم Jira MCP و kebab-case لأدوات الذكاء الاصطناعي"},"features":{"en":["Generates project setup using Jira ticket IDs (e.g., SCRUM-123) and custom kebab-case change names","Derives kebab-case names from user-provided descriptions for consistent naming conventions","Fetches ticket content using Jira MCP for automated project context determination","Determines input type and gets context based on patterns like SCRUM-1 for streamlined processing","Supports fast-forwarding through artifact creation for rapid project initialization","Uses user-provided descriptions to build project setup for tailored development environments"],"zh":["支持Jira票据ID","自定义名称和描述","快速生成项目所需文件","支持kebab-case名称","自动derive kebab-case名称"],"ja":["JiraチケットIDのサポート","カスタム名と説明","プロジェクトの必要なファイルを一括生成","kebab-case名のサポート","自動的にkebab-case名をderive"],"ko":["Jira 티켓 ID 지원","사용자 정의 이름 및 설명","프로젝트에 필요한 파일을 빠르게 생성","kebab-case 이름 지원","자동으로 kebab-case 이름을 derive"],"es":["Generación de artefactos de implementación en un solo paso","Integración con Jira MCP para obtener contenido de tickets","Uso de nombres en kebab-case para la generación de artefactos","Determinación del tipo de entrada y obtención de contexto","Soporte para IDs de tickets de Jira"],"fr":["Génération d''artefacts d''implémentation en un seul étape","Intégration avec Jira MCP pour obtenir le contenu des tickets","Utilisation de noms en kebab-case pour la génération d''artefacts","Détermination du type d''entrée et obtention de contexte","Prise en charge des IDs de tickets Jira"],"de":["Generierung von Implementierungsartefakten in einem Schritt","Integration mit Jira MCP zur Abrufung von Ticketinhalten","Verwendung von Kebab-Case-Namen für die Generierung von Artefakten","Bestimmung des Eingabetyps und Abruf von Kontext","Unterstützung für Jira-Ticket-IDs"],"pt":["Geração automática de artefatos com Jira MCP","Suporte a kebab-case para nomes de artefatos","Integração com Jira ticket ID para contexto","Derivação de nomes de artefatos em kebab-case","Início rápido da implementação com todos os artefatos necessários"],"ru":["Автоматическое создание артефактов с помощью Jira MCP","Поддержка kebab-case для имен артефактов","Интеграция с Jira ticket ID для контекста","Получение имен артефактов в kebab-case","Быстрый старт реализации со всеми необходимыми артефактами для ИИ Агенты"],"ar":["إنشاء تلقائي للملفات الفنية باستخدام Jira MCP","دعم kebab-case لأسماء الملفات الفنية","تكامل مع Jira ticket ID لسياق","استخراج أسماء الملفات الفنية في kebab-case","بدء التنفيذ بسرعة مع جميع الملفات الفنية الضرورية لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use openspec-ff-change","openspec-ff-change setup guide","Jira MCP integration with openspec-ff-change","openspec-ff-change alternative tools","openspec-ff-change vs other development accelerators","installing openspec-ff-change for AI agents","what is openspec-ff-change and its benefits","openspec-ff-change for rapid artifact creation","openspec-ff-change and Jira ticket integration","openspec-ff-change best practices for developers"],"zh":["openspec-ff-change","AI工具","快速生成项目文件","Jira票据ID","自定义名称和描述","kebab-case名称","自动derive kebab-case名称"],"ja":["openspec-ff-change","AIエージェント","プロジェクトファイルを一括生成","JiraチケットID","カスタム名と説明","kebab-case名","自動的にkebab-case名をderive"],"ko":["openspec-ff-change","AI 도구","프로젝트 파일을 빠르게 생성","Jira 티켓 ID","사용자 정의 이름 및 설명","kebab-case 이름","自動으로 kebab-case 이름을 derive"],"es":["openspec-ff-change","herramientas de implementación","Jira MCP","kebab-case","generación de artefactos","desarrollo de software","integración con Jira","implementación rápida","Agente de IA para desarrolladores"],"fr":["openspec-ff-change","outils d''implémentation","Jira MCP","kebab-case","génération d''artefacts","développement de logiciels","intégration avec Jira","implémentation rapide","Outil d''IA pour les développeurs"],"de":["openspec-ff-change","Implementierungstools","Jira MCP","Kebab-Case","Generierung von Artefakten","Softwareentwicklung","Integration mit Jira","schnelle Implementierung","KI-Tool für Entwickler"],"pt":["openspec-ff-change","automação de criação de artefatos","Jira MCP","kebab-case","desenvolvimento rápido","início de implementação","ferramentas de desenvolvimento"],"ru":["openspec-ff-change","автоматизация создания артефактов","Jira MCP","kebab-case","быстрое развитие","начало реализации","инструменты разработки для ИИ Агенты"],"ar":["openspec-ff-change","تلقيم إنشاء الملفات الفنية","Jira MCP","kebab-case","تنمية سريعة","بدء التنفيذ","أدوات التطوير لأدوات الذكاء الاصطناعي"]}},"owner":"LIDR-academy","repo":"AI4Devs-LTI-extended","repoPath":"LIDR-academy/AI4Devs-LTI-extended","stars":39,"forks":60,"updatedAt":"2026-02-22T18:42:59Z","topics":[],"category":"community","skillMd":{"name":"openspec-ff-change","description":"Fast-forward through OpenSpec artifact creation. Use when the user wants to quickly create all artifacts needed for implementation without stepping through each one individually.","version":"1.0","bodyPreview":"Fast-forward through artifact creation - generate everything needed to start implementation in one go.\n\n**Input**: The user''s request should include:\n- A Jira ticket ID (e.g., `SCRUM-123`) - will fetch ticket content using Jira MCP\n- A change name (kebab-case) - will use that name directly\n- A description of what they want to build - will derive a kebab-case name\n\n**Steps**\n\n1. **Determine input type and get context**\n\n   a. **If input looks like a Jira ticket ID** (matches pattern like `SCRUM-1","body":"Fast-forward through artifact creation - generate everything needed to start implementation in one go.\n\n**Input**: The user''s request should include:\n- A Jira ticket ID (e.g., `SCRUM-123`) - will fetch ticket content using Jira MCP\n- A change name (kebab-case) - will use that name directly\n- A description of what they want to build - will derive a kebab-case name\n\n**Steps**\n\n1. **Determine input type and get context**\n\n   a. **If input looks like a Jira ticket ID** (matches pattern like `SCRUM-123`, `PROJ-456`, etc.):\n      - Use `getAccessibleAtlassianResources` MCP tool to get the cloudId\n      - Use `getJiraIssue` MCP tool with:\n        - `cloudId`: from step above\n        - `issueIdOrKey`: the provided ticket ID\n      - Extract ticket content (title, description, acceptance criteria, etc.)\n      - **Derive a kebab-case change name from the ticket title**:\n        - Convert ticket title to lowercase\n        - Replace spaces and special characters with hyphens\n        - Remove any leading/trailing hyphens\n        - Example: \"Update Position API\" → `update-position-api`, \"Add User Auth\" → `add-user-auth`\n        - If ticket title is unclear or too long, use a shortened meaningful version\n      - Use the derived kebab-case name as `<name>` for the change directory\n      - Use ticket content as context for creating artifacts\n      - Store ticket ID for reference (e.g., in proposal or as metadata)\n\n   b. **If input is a change name** (kebab-case format):\n      - Use the provided name directly\n      - Check if change already exists, if so ask user if they want to continue it\n\n   c. **If input is a description**:\n      - Derive a kebab-case name (e.g., \"add user authentication\" → `add-user-auth`)\n\n   d. **If no input provided**:\n      - Use the **AskUserQuestion tool** (open-ended, no preset options) to ask:\n        > \"What change do you want to work on? Provide a Jira ticket ID (e.g., SCRUM-123), change name, or describe what you want to build.\"\n\n   **IMPORTANT**: Do NOT proceed without understanding what the user wants to build.\n\n2. **Create the change directory**\n   ```bash\n   openspec new change \"<name>\"\n   ```\n   This creates a scaffolded change at `openspec/changes/<name>/`.\n\n2.5. **Handle attached files (if any)**\n   If the user has attached files to this conversation:\n   - Check for any files in the conversation context (attached files will be visible in the file list)\n   - For each attached file:\n     - Read the file to get its current path\n     - Move it to the root of the change directory: `openspec/changes/<name>/<filename>`\n     - Use the file system tools to copy/move the file, preserving the original filename\n   - If files were moved, inform the user: \"Moved N attached file(s) to the change directory root.\"\n\n3. **Get the artifact build order**\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n   Parse the JSON to get:\n   - `applyRequires`: array of artifact IDs needed before implementation (e.g., `[\"tasks\"]`)\n   - `artifacts`: list of all artifacts with their status and dependencies\n\n4. **Create artifacts in sequence until apply-ready**\n\n   Use the **TodoWrite tool** to track progress through the artifacts.\n\n   Loop through artifacts in dependency order (artifacts with no pending dependencies first):\n\n   a. **For each artifact that is `ready` (dependencies satisfied)**:\n      - Get instructions:\n        ```bash\n        openspec instructions <artifact-id> --change \"<name>\" --json\n        ```\n      - The instructions JSON includes:\n        - `context`: Project background (constraints for you - do NOT include in output)\n        - `rules`: Artifact-specific rules (constraints for you - do NOT include in output)\n        - `template`: The structure to use for your output file\n        - `instruction`: Schema-specific guidance for this artifact type\n        - `outputPath`: Where to write the artifact\n        - `dependencies`: Completed artifacts to read for context\n      - **CRITICAL for tasks artifact**: If creating `tasks.md`:\n        - Read `openspec/config.yaml` to get backend-specific rules (mandatory steps, branch naming, etc.)\n        - Read `.claude/rules/openspec-tasks-mandatory-steps.mdc` to understand mandatory testing requirements and agent execution responsibilities\n        - Task structure requirements\n        - All mandatory steps that MUST be included (e.g., Step 0: Create Feature Branch)\n      - **If Jira ticket was provided**: Use ticket content to inform artifact creation (especially proposal and tasks)\n      - Read any completed dependency files for context\n      - Create the artifact file using `template` as the structure\n      - Apply `context` and `rules` as constraints - but do NOT copy them into the file\n      - **For tasks artifact**: Ensure all mandatory steps from `config.yaml` and the rule file are included:\n        - Step 0: Create Feature Branch (MUST be first step for backend changes)\n        - Review and Update Existing Unit Tests (MANDATORY)\n        - Run Unit Tests and Verify Database State (MANDATORY)\n        - Manual Endpoint Testing with curl (MANDATORY - AGENT MUST EXECUTE)\n        - E2E Testing with Playwright MCP (MANDATORY if applicable - AGENT MUST EXECUTE)\n        - Update Technical Documentation (MANDATORY)\n      - **For manual testing tasks**: Include sub-tasks that make it clear the agent must execute tests (e.g., \"Test GET endpoints with curl\", \"Restore database state\", etc.)\n      - Show brief progress: \"✓ Created <artifact-id>\"\n\n   b. **Continue until all `applyRequires` artifacts are complete**\n      - After creating each artifact, re-run `openspec status --change \"<name>\" --json`\n      - Check if every artifact ID in `applyRequires` has `status: \"done\"` in the artifacts array\n      - Stop when all `applyRequires` artifacts are done\n\n   c. **If an artifact requires user input** (unclear context):\n      - Use **AskUserQuestion tool** to clarify\n      - Then continue with creation\n\n5. **Show final status**\n   ```bash\n   openspec status --change \"<name>\"\n   ```\n\n**Output**\n\nAfter completing all artifacts, summarize:\n- Change name and location\n- List of artifacts created with brief descriptions\n- What''s ready: \"All artifacts created! Ready for implementation.\"\n- Prompt: \"Run `/opsx:apply` or ask me to implement to start working on the tasks.\"\n\n**Artifact Creation Guidelines**\n\n- Follow the `instruction` field from `openspec instructions` for each artifact type\n- The schema defines what each artifact should contain - follow it\n- Read dependency artifacts for context before creating new ones\n- Use `template` as the structure for your output file - fill in its sections\n- **IMPORTANT**: `context` and `rules` are constraints for YOU, not content for the file\n  - Do NOT copy `<context>`, `<rules>`, `<project_context>` blocks into the artifact\n  - These guide what you write, but should never appear in the output\n\n**Guardrails**\n- Create ALL artifacts needed for implementation (as defined by schema''s `apply.requires`)\n- Always read dependency artifacts before creating a new one\n- **For tasks.md**: Read `.claude/rules/openspec-tasks-mandatory-steps.mdc` to ensure all mandatory steps are included with proper agent execution requirements\n- If context is critically unclear, ask the user - but prefer making reasonable decisions to keep momentum\n- If a change with that name already exists, suggest continuing that change instead\n- Verify each artifact file exists after writing before proceeding to next\n"},"lastSynced":"2026-03-06T06:37:33.510Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring rapid project setup and automation through Jira ticket integration.","zh":"适用于需要快速项目设置和通过Jira票据集成实现自动化的开发代理。","ja":"Jiraチケットの統合を介した迅速なプロジェクト設定と自動化を必要とする開発エージェントに適しています。","ko":"Jira 티켓 통합을 통해 빠른 프로젝트 설정 및 자동화를 요구하는 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una configuración de proyecto rápida y automatización a través de la integración de ticket de Jira.","fr":"Idéal pour les agents de développement nécessitant une configuration de projet rapide et une automatisation via l''intégration de ticket Jira.","de":"Ideal für Development Agents, die eine schnelle Projektsetup und Automatisierung durch Jira-Ticket-Integration benötigen.","pt":"Ideal para Agentes de Desenvolvimento que exigem configuração rápida de projeto e automação por meio da integração de tickets Jira.","ru":"Идеально для агентов разработки, требующих быстрой настройки проекта и автоматизации через интеграцию с Jira.","ar":"مثالي للوكلاء النموذجيين الذين يتطلبون إعدادًا سريعًا لمشروع وتنفيذ تلقائي عبر تطبيق تكامل تذاكر Jira."},"recommendation":{"en":"Empowers agents to fast-forward through artifact creation using Jira MCP, automating project setup with custom change names and descriptions, leveraging kebab-case naming conventions and Jira ticket IDs like SCRUM-123.","zh":"赋予代理人使用Jira MCP快速创建项目的能力，自动设置项目，使用自定义的更改名称和描述，利用短横线命名约定和Jira票据ID，如SCRUM-123。","ja":"エージェントはJira MCPを使用してアーティファクトの作成を高速化でき、プロジェクトの設定を自動化し、カスタムの変更名と説明を使用し、ケバブケース命名規則とJiraチケットID（例：SCRUM-123）を利用できます。","ko":"에이전트는 Jira MCP를 사용하여 아티팩트 생성을 가속화 할 수 있으며, 프로젝트 설정을 자동화하고, 사용자 정의 변경 이름 및 설명을 사용하며, 케밥 케이스命名 규칙 및 Jira 티켓 ID(예: SCRUM-123)를 활용할 수 있습니다.","es":"Habilita a los agentes a avanzar rápidamente en la creación de artefactos utilizando Jira MCP, automatizando la configuración del proyecto con nombres y descripciones de cambios personalizados, aprovechando las convenciones de nomenclatura kebab-case y los IDs de ticket de Jira como SCRUM-123.","fr":"Permet aux agents d''accélérer la création d''artefacts en utilisant Jira MCP, en automatisant la configuration du projet avec des noms et des descriptions de modifications personnalisées, en exploitant les conventions de nommage kebab-case et les IDs de ticket Jira comme SCRUM-123.","de":"Ermächtigt Agenten, die Erstellung von Artefakten mithilfe von Jira MCP zu beschleunigen, indem sie die Projektsetup mit benutzerdefinierten Änderungsnamen und -beschreibungen automatisieren, die kebab-case-Namenskonventionen und Jira-Ticket-IDs wie SCRUM-123 nutzt.","pt":"Permite que os agentes avancem rapidamente na criação de artefatos usando Jira MCP, automatizando a configuração do projeto com nomes e descrições de alterações personalizadas, aproveitando convenções de nomenclatura em kebab-case e IDs de ticket Jira como SCRUM-123.","ru":"Наделяет агентов возможностью быстро проходить через создание артефактов с помощью Jira MCP, автоматизируя настройку проекта с помощью пользовательских имен изменений и описаний, используя соглашения об именах в kebab-case и идентификаторы тикетов Jira, такие как SCRUM-123.","ar":"تمكن الوكلاء من التنقل بسرعة خلال إنشاء الملفات الشخصية باستخدام Jira MCP، وتنفيذ تلقائي لإعداد المشروع مع أسماء ووصفات التغيير المخصصة، والاستفادة من اتفاقيات التسمية في kebab-case وأرقام تذاكر Jira مثل SCRUM-123."},"useCases":{"en":["Automating project setup for developers using Jira ticket IDs","Generating kebab-case change names for consistent project naming","Deriving project descriptions from user input for clarity and documentation"],"zh":["使用Jira票据ID为开发人员自动设置项目","为项目生成短横线命名以保持一致的项目命名","从用户输入中推导项目描述以提高清晰度和文档记录"],"ja":["JiraチケットIDを使用して開発者のプロジェクトを自動設定する","一貫したプロジェクト命名のためにケバブケースの変更名を生成する","ユーザーの入力からプロジェクトの説明を導き出すことで明確性とドキュメント化を高める"],"ko":["Jira 티켓 ID를 사용하여 개발자의 프로젝트를 자동 설정하는こと","일관된 프로젝트 이름을 위해 케밥 케이스의 변경 이름을 생성하는 것","사용자 입력으로부터 프로젝트 설명을 도출하여 명확성과 문서화를 높이는 것"],"es":["Automatizar la configuración de proyectos para desarrolladores utilizando IDs de ticket de Jira","Generar nombres de cambios en kebab-case para una denominación de proyectos coherente","Derivar descripciones de proyectos de la entrada del usuario para claridad y documentación"],"fr":["Automatiser la configuration de projets pour les développeurs en utilisant les IDs de ticket Jira","Générer des noms de modifications en kebab-case pour une dénomination de projets cohérente","Dériver des descriptions de projets à partir de la saisie de l''utilisateur pour la clarté et la documentation"],"de":["Automatisierung der Projektsetup für Entwickler mithilfe von Jira-Ticket-IDs","Erzeugen von Änderungsnamen im kebab-case-Stil für eine konsistente Projektnamengebung","Ableitung von Projekbeschreibungen aus der Benutzereingabe für Klarheit und Dokumentation"],"pt":["Automatizar a configuração do projeto para desenvolvedores usando IDs de ticket Jira","Gerar nomes de alterações em kebab-case para nomeação de projeto consistente","Derivar descrições de projeto a partir da entrada do usuário para clareza e documentação"],"ru":["Автоматизировать настройку проекта для разработчиков с помощью идентификаторов тикетов Jira","Генерировать имена изменений в kebab-case для последовательного названия проекта","Получать описания проекта из ввода пользователя для ясности и документации"],"ar":["توفير تلقائي لإعداد المشروع للمطورين باستخدام أرقام تذاكر Jira","توليد أسماء التغييرات في kebab-case لتسمية المشروع المنتظمة","استخلاص وصفات المشروع من إدخال المستخدم لتوضيح الوثائق"]},"limitations":{"en":["Requires Jira MCP access for ticket content fetching","Limited to projects with kebab-case change name compatibility","Dependent on user-provided input quality for accurate project setup"],"zh":["需要Jira MCP访问权限以获取票据内容","仅限于支持短横线命名的项目","依赖于用户提供的输入质量以实现准确的项目设置"],"ja":["チケットの内容を取得するためにJira MCPへのアクセスが必要","ケバブケースの変更名との互換性があるプロジェクトに限定される","正確なプロジェクト設定を実現するために、ユーザー提供の入力の品質に依存する"],"ko":["티켓 내용을 가져오기 위해 Jira MCP에 대한 액세스가 필요함","케밥 케이스 변경 이름과 호환되는 프로젝트로 제한됨","정확한 프로젝트 설정을 달성하기 위해 사용자 제공 입력 품질에 의존함"],"es":["Requiere acceso a Jira MCP para la recolección de contenido de ticket","Limitado a proyectos con compatibilidad de nombres de cambios en kebab-case","Dependiente de la calidad de la entrada del usuario para una configuración de proyecto precisa"],"fr":["Nécessite un accès à Jira MCP pour la collecte de contenu de ticket","Limité aux projets avec une compatibilité de noms de modifications en kebab-case","Dépend de la qualité de la saisie de l''utilisateur pour une configuration de projet précise"],"de":["Erfordert Zugriff auf Jira MCP für das Abrufen von Ticketinhalten","Eingeschränkt auf Projekte mit Kompatibilität für Änderungsnamen im kebab-case-Stil","Abhängig von der Qualität der Benutzereingabe für eine genaue Projektsetup"],"pt":["Exige acesso ao Jira MCP para buscar conteúdo de ticket","Limitado a projetos com compatibilidade de nomes de alterações em kebab-case","Dependente da qualidade da entrada fornecida pelo usuário para configuração precisa do projeto"],"ru":["Требует доступа к Jira MCP для извлечения содержимого тикета","Ограничен проектами с совместимостью имен изменений в kebab-case","Зависит от качества ввода, предоставленного пользователем, для точной настройки проекта"],"ar":["يتطلب الوصول إلى Jira MCP لاسترجاع محتوى التذكرة","محدد للمشاريع المتوافقة مع أسماء التغييرات في kebab-case","يعتمد على جودة الإدخال المقدم من المستخدم لإعداد دقيق للمشروع"]},"version":4},"contentHash":"130ad13ff44998927f08fd95c225a5b215bd2e82c7183e97c9f29703f5129c64","qualityScore":55}');
