INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LIDR-academy/AI4Devs-LTI-extended/openspec-ff-change', 'openspec-ff-change', 'LIDR-academy', 'AI4Devs-LTI-extended', 'community', 'openspec-ff-change LIDR-academy AI4Devs-LTI-extended community openspec-ff-change is a repository of experiments that enables fast-forwarding through artifact creation, benefiting developers who need to quickly generate project setup. It automates the process using Jira ticket IDs and custom change names. openspec-ff-change是一个快速生成项目所需文件的工具，支持Jira票据ID、自定义名称和描述 openspec-ff-changeは、JiraチケットID、カスタム名、説明を使用してプロジェクトの必要なファイルを一括生成するツールです openspec-ff-change는 Jira 티켓 ID, 사용자 정의 이름 및 설명을 사용하여 프로젝트에 필요한 파일을 빠르게 생성하는 도구입니다 openspec-ff-change es una herramienta que permite generar artefactos de implementación en un solo paso, utilizando Jira MCP y nombres en kebab-case openspec-ff-change est un outil qui permet de générer des artefacts d''implémentation en un seul étape, en utilisant Jira MCP et des noms en kebab-case openspec-ff-change ist ein Tool, das die Generierung von Implementierungsartefakten in einem Schritt ermöglicht, unter Verwendung von Jira MCP und Kebab-Case-Namen O openspec-ff-change é uma ferramenta que automatiza a criação de artefatos com Jira MCP e kebab-case, permitindo que os desenvolvedores iniciem a implementação rapidamente. openspec-ff-change - это инструмент, который автоматизирует создание артефактов с помощью Jira MCP и kebab-case, позволяя разработчикам быстро приступить к реализации для ИИ Агенты openspec-ff-change هو أداة تلقيم إنشاء الملفات الفنية باستخدام Jira MCP و kebab-case، مما يسمح للمطورين بدء التنفيذ بسرعة لأدوات الذكاء الاصطناعي how to use openspec-ff-change openspec-ff-change setup guide Jira MCP integration with openspec-ff-change openspec-ff-change alternative tools openspec-ff-change vs other development accelerators installing openspec-ff-change for AI agents what is openspec-ff-change and its benefits openspec-ff-change for rapid artifact creation openspec-ff-change and Jira ticket integration openspec-ff-change best practices for developers openspec-ff-change AI工具 快速生成项目文件 Jira票据ID 自定义名称和描述 kebab-case名称 自动derive kebab-case名称 Generates project setup using Jira ticket IDs (e.g., SCRUM-123) and custom kebab-case change names Derives kebab-case names from user-provided descriptions for consistent naming conventions Fetches ticket content using Jira MCP for automated project context determination Determines input type and gets context based on patterns like SCRUM-1 for streamlined processing Supports fast-forwarding through artifact creation for rapid project initialization Uses user-provided descriptions to build project setup for tailored development environments openspec-ff-change is a technical skill that facilitates rapid artifact creation by generating necessary project files and setup in a single step, utilizing Jira MCP for ticket content fetching.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jixoai/openspecui/openspec-verify-change', 'community', 'jixoai', 'openspecui', 'jixoai/openspecui', 'openspec-verify-change', 34, 6, 55, '2026-02-28T09:18:07Z', '2026-03-06T06:38:15.883Z', 'c91dcdb4639dee625ec6e1e72ff32de4512cdcc78825e1e8141d44f6ab207adc', '{"id":"jixoai/openspecui/openspec-verify-change","name":"openspec-verify-change","description":{"en":"The openspec-verify-change skill verifies implementation matches against change artifacts. It benefits developers by ensuring consistency and accuracy in their projects.","zh":"openspec-verify-change是一个用于验证实现是否匹配更改文档的工具，支持命令行接口和用户交互","ja":"openspec-verify-changeは、実装が変更文書と一致するかを検証するツールです。コマンドラインインターフェースとユーザーインタラクションをサポートしています","ko":"openspec-verify-change는 구현이 변경 문서와 일치하는지 검증하는 도구입니다. 명령줄 인터페이스와 사용자 상호작용을 지원합니다","es":"openspec-verify-change es una habilidad que verifica si una implementación coincide con los artefactos de cambio. Utiliza la herramienta AskUserQuestion para seleccionar cambios","fr":"openspec-verify-change est une compétence qui vérifie si une implémentation correspond aux artefacts de modification. Elle utilise l''outil AskUserQuestion pour sélectionner les modifications","de":"openspec-verify-change ist eine Fähigkeit, die überprüft, ob eine Implementierung mit den Änderungsartefakten übereinstimmt. Sie verwendet das Tool AskUserQuestion, um Änderungen auszuwählen","pt":"O openspec-verify-change é uma ferramenta que verifica se a implementação de um projeto corresponde às alterações especificadas. Ele utiliza a ferramenta AskUserQuestion para seleção de alterações.","ru":"Openspec-verify-change - это инструмент, который проверяет, соответствует ли реализация проекта изменениям. Он использует инструмент AskUserQuestion для выбора изменений.","ar":"openspec-verify-change هو أداة تحقق من تطابق تنفيذ المشروع مع التغييرات المحددة. يستخدم أداة AskUserQuestion لاختيار التغييرات."},"seo":{"title":{"en":"openspec-verify-change: Implementation Verification Setup...","zh":"openspec-verify-change 设置指南 - AI工具","ja":"openspec-verify-change のベストプラクティス - AIエージェント","ko":"openspec-verify-change 설정 가이드 - AI 에이전트","es":"Guía de configuración de openspec-verify-change para Agen...","fr":"Guide de mise en place d''openspec-verify-change pour les ...","de":"Einrichtungsleitfaden für openspec-verify-change in KI-Ag...","pt":"Guia de Configuração do openspec-verify-change para Desen...","ru":"Настройка openspec-verify-change: ИИ Агенты для Верификац...","ar":"دليل إعداد openspec-verify-change لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how openspec-verify-change streamlines implementation verification. Learn to use openspec list --json and AskUserQuestion tool for seamless change v...","zh":"了解openspec-verify-change的功能和特点，实现更好的代码验证和管理","ja":"openspec-verify-changeの機能と特徴を解説します。コードの検証と管理を更に効率化する方法を紹介します","ko":"openspec-verify-change의 기능과 특징을 살펴보고 코드 검증 및 관리를 개선하는 방법을 알아보세요","es":"Aprende a verificar cambios en la implementación con openspec-verify-change y los Agentes de IA. Descubre cómo funciona y cómo configurarlo","fr":"Découvrez comment vérifier les modifications d''implémentation avec openspec-verify-change et les Outils d''IA. Consultez notre guide pour en savoir plus","de":"Erfahren Sie, wie Sie Änderungen in der Implementierung mit openspec-verify-change und KI-Agents überprüfen können. Lesen Sie unseren Leitfaden","pt":"Aprenda a configurar o openspec-verify-change para verificar alterações em projetos de desenvolvimento com ferramentas de linha de comando","ru":"Узнайте, как настроить openspec-verify-change для верификации изменений в проектах разработки с помощью инструментов командной строки и ИИ Агентов","ar":"تعرف على كيفية إعداد openspec-verify-change للتحقق من التغييرات في مشاريع التطوير باستخدام أدوات سطر الأوامر وأدوات الذكاء الاصطناعي"},"definition":{"en":"openspec-verify-change is a skill that verifies an implementation matches the change artifacts, such as specs, tasks, and design, using openspec list --json and AskUserQuestion tool.","zh":"openspec-verify-change是一种AI工具，用于验证实现是否匹配更改文档","ja":"openspec-verify-changeは、実装が変更文書と一致するかを検証するAIエージェントの一種です","ko":"openspec-verify-change는 구현이 변경 문서와 일치하는지 검증하는 AI 에이전트의 일종입니다","es":"openspec-verify-change es una habilidad de Agentes de IA que verifica la coincidencia entre implementaciones y artefactos de cambio","fr":"openspec-verify-change est une compétence d''Outils d''IA qui vérifie la correspondance entre les implémentations et les artefacts de modification","de":"openspec-verify-change ist eine Fähigkeit von KI-Agents, die die Übereinstimmung zwischen Implementierungen und Änderungsartefakten überprüft","pt":"O openspec-verify-change é uma ferramenta de verificação de alterações que utiliza a linha de comando para validar a implementação de projetos","ru":"Openspec-verify-change - это инструмент верификации изменений, который использует командную строку для проверки реализации проектов","ar":"openspec-verify-change هو أداة للتحقق من التغييرات التي تستخدم سطر الأوامر لتحقق من تنفيذ المشاريع"},"features":{"en":["Runs openspec list --json to retrieve available changes","Utilizes AskUserQuestion tool for user selection of changes","Prompts for selection when no change name is provided","Displays changes with implementation tasks for efficient validation","Supports inference of change name from conversation context"],"zh":["支持命令行接口","用户交互式选择更改","使用AskUserQuestion工具","运行openspec list --json命令获取可用更改"],"ja":["コマンドラインインターフェースをサポート","ユーザーインタラクションによる変更の選択","AskUserQuestionツールを使用","openspec list --jsonコマンドを実行して利用可能な変更を取得"],"ko":["명령줄 인터페이스 지원","사용자 상호작용을 통한 변경 선택","AskUserQuestion 도구 사용","openspec list --json 명령을 실행하여 사용 가능한 변경을 가져옴"],"es":["Verificación de implementaciones con artefactos de cambio","Uso de la herramienta AskUserQuestion para seleccionar cambios","Compatibilidad con la CLI de openspec","Soporte para la inferencia de cambios a partir del contexto de conversación","Capacidad para mostrar cambios con tareas de implementación"],"fr":["Vérification des implémentations avec les artefacts de modification","Utilisation de l''outil AskUserQuestion pour sélectionner les modifications","Compatibilité avec la CLI d''openspec","Prise en charge de l''inférence des modifications à partir du contexte de conversation","Capacité à afficher les modifications avec des tâches d''implémentation"],"de":["Überprüfung von Implementierungen mit Änderungsartefakten","Verwendung des Tools AskUserQuestion zur Auswahl von Änderungen","Kompatibilität mit der openspec-CLI","Unterstützung für die Inferenz von Änderungen aus dem Konversationskontext","Fähigkeit, Änderungen mit Implementierungsaufgaben anzuzeigen"],"pt":["Utiliza a ferramenta AskUserQuestion para seleção de alterações","Executa o comando `openspec list --json` para obter alterações disponíveis","Verifica a implementação de projetos com base em alterações especificadas","Suporta seleção de alterações por meio de prompts de usuário","Integração com ferramentas de linha de comando para automação de tarefas"],"ru":["Использует инструмент AskUserQuestion для выбора изменений","Выполняет команду `openspec list --json` для получения доступных изменений","Проверяет реализацию проектов на основе изменений","Поддерживает выбор изменений через подсказки пользователя","Интеграция с инструментами командной строки для автоматизации задач"],"ar":["يستخدم أداة AskUserQuestion لاختيار التغييرات","ينفذ الأمر `openspec list --json` للحصول على التغييرات المتاحة","يحقق من تنفيذ المشاريع بناءً على التغييرات المحددة","يدعم اختيار التغييرات من خلال إشعارات المستخدم","التكامل مع أدوات سطر الأوامر للتحكم الآلي في المهام"]},"keywords":{"en":["how to use openspec-verify-change","openspec-verify-change setup guide","openspec-verify-change alternative","openspec-verify-change vs manual validation","openspec-verify-change install","what is openspec-verify-change","openspec-verify-change implementation verification"],"zh":["openspec-verify-change","AI工具","代码验证","命令行接口","用户交互","AskUserQuestion","openspec list --json"],"ja":["openspec-verify-change","AIエージェント","コード検証","コマンドラインインターフェース","ユーザーインタラクション","AskUserQuestion","openspec list --json"],"ko":["openspec-verify-change","AI 에이전트","코드 검증","명령줄 인터페이스","사용자 상호작용","AskUserQuestion","openspec list --json"],"es":["openspec-verify-change","Agentes de IA","verificación de implementaciones","artefactos de cambio","AskUserQuestion","CLI de openspec","inferencia de cambios","tareas de implementación"],"fr":["openspec-verify-change","Outils d''IA","vérification des implémentations","artefacts de modification","AskUserQuestion","CLI d''openspec","inférence des modifications","tâches d''implémentation"],"de":["openspec-verify-change","KI-Agents","Überprüfung von Implementierungen","Änderungsartefakte","AskUserQuestion","openspec-CLI","Inferenz von Änderungen","Implementierungsaufgaben"],"pt":["openspec-verify-change","ferramentas de desenvolvimento","verificação de alterações","linha de comando","AskUserQuestion","automatização de tarefas","desenvolvimento de projetos","ferramentas de código aberto"],"ru":["openspec-verify-change","инструменты разработки","верификация изменений","командная строка","AskUserQuestion","автоматизация задач","разработка проектов","инструменты с открытым исходным кодом","ИИ Агенты"],"ar":["openspec-verify-change","أدوات التطوير","التحقق من التغييرات","سطر الأوامر","AskUserQuestion","التحكم الآلي في المهام","تطوير المشاريع","أدوات مفتوحة المصدر","أدوات الذكاء الاصطناعي"]}},"owner":"jixoai","repo":"openspecui","repoPath":"jixoai/openspecui","stars":34,"forks":6,"updatedAt":"2026-02-28T09:18:07Z","topics":[],"category":"community","skillMd":{"name":"openspec-verify-change","description":"Verify implementation matches change artifacts. Use when the user wants to validate that implementation is complete, correct, and coherent before archiving.","version":"1.0","bodyPreview":"Verify that an implementation matches the change artifacts (specs, tasks, design).\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes. Use the **AskUserQuestion tool** to let the user select.\n\n   Show changes that have implementation tasks (tasks artifa","body":"Verify that an implementation matches the change artifacts (specs, tasks, design).\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes. Use the **AskUserQuestion tool** to let the user select.\n\n   Show changes that have implementation tasks (tasks artifact exists).\n   Include the schema used for each change if available.\n   Mark changes with incomplete tasks as \"(In Progress)\".\n\n   **IMPORTANT**: Do NOT guess or auto-select a change. Always let the user choose.\n\n2. **Check status to understand the schema**\n\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n\n   Parse the JSON to understand:\n   - `schemaName`: The workflow being used (e.g., \"spec-driven\")\n   - Which artifacts exist for this change\n\n3. **Get the change directory and load artifacts**\n\n   ```bash\n   openspec instructions apply --change \"<name>\" --json\n   ```\n\n   This returns the change directory and context files. Read all available artifacts from `contextFiles`.\n\n4. **Initialize verification report structure**\n\n   Create a report structure with three dimensions:\n   - **Completeness**: Track tasks and spec coverage\n   - **Correctness**: Track requirement implementation and scenario coverage\n   - **Coherence**: Track design adherence and pattern consistency\n\n   Each dimension can have CRITICAL, WARNING, or SUGGESTION issues.\n\n5. **Verify Completeness**\n\n   **Task Completion**:\n   - If tasks.md exists in contextFiles, read it\n   - Parse checkboxes: `- [ ]` (incomplete) vs `- [x]` (complete)\n   - Count complete vs total tasks\n   - If incomplete tasks exist:\n     - Add CRITICAL issue for each incomplete task\n     - Recommendation: \"Complete task: <description>\" or \"Mark as done if already implemented\"\n\n   **Spec Coverage**:\n   - If delta specs exist in `openspec/changes/<name>/specs/`:\n     - Extract all requirements (marked with \"### Requirement:\")\n     - For each requirement:\n       - Search codebase for keywords related to the requirement\n       - Assess if implementation likely exists\n     - If requirements appear unimplemented:\n       - Add CRITICAL issue: \"Requirement not found: <requirement name>\"\n       - Recommendation: \"Implement requirement X: <description>\"\n\n6. **Verify Correctness**\n\n   **Requirement Implementation Mapping**:\n   - For each requirement from delta specs:\n     - Search codebase for implementation evidence\n     - If found, note file paths and line ranges\n     - Assess if implementation matches requirement intent\n     - If divergence detected:\n       - Add WARNING: \"Implementation may diverge from spec: <details>\"\n       - Recommendation: \"Review <file>:<lines> against requirement X\"\n\n   **Scenario Coverage**:\n   - For each scenario in delta specs (marked with \"#### Scenario:\"):\n     - Check if conditions are handled in code\n     - Check if tests exist covering the scenario\n     - If scenario appears uncovered:\n       - Add WARNING: \"Scenario not covered: <scenario name>\"\n       - Recommendation: \"Add test or implementation for scenario: <description>\"\n\n7. **Verify Coherence**\n\n   **Design Adherence**:\n   - If design.md exists in contextFiles:\n     - Extract key decisions (look for sections like \"Decision:\", \"Approach:\", \"Architecture:\")\n     - Verify implementation follows those decisions\n     - If contradiction detected:\n       - Add WARNING: \"Design decision not followed: <decision>\"\n       - Recommendation: \"Update implementation or revise design.md to match reality\"\n   - If no design.md: Skip design adherence check, note \"No design.md to verify against\"\n\n   **Code Pattern Consistency**:\n   - Review new code for consistency with project patterns\n   - Check file naming, directory structure, coding style\n   - If significant deviations found:\n     - Add SUGGESTION: \"Code pattern deviation: <details>\"\n     - Recommendation: \"Consider following project pattern: <example>\"\n\n8. **Generate Verification Report**\n\n   **Summary Scorecard**:\n\n   ```\n   ## Verification Report: <change-name>\n\n   ### Summary\n   | Dimension    | Status           |\n   |--------------|------------------|\n   | Completeness | X/Y tasks, N reqs|\n   | Correctness  | M/N reqs covered |\n   | Coherence    | Followed/Issues  |\n   ```\n\n   **Issues by Priority**:\n   1. **CRITICAL** (Must fix before archive):\n      - Incomplete tasks\n      - Missing requirement implementations\n      - Each with specific, actionable recommendation\n\n   2. **WARNING** (Should fix):\n      - Spec/design divergences\n      - Missing scenario coverage\n      - Each with specific recommendation\n\n   3. **SUGGESTION** (Nice to fix):\n      - Pattern inconsistencies\n      - Minor improvements\n      - Each with specific recommendation\n\n   **Final Assessment**:\n   - If CRITICAL issues: \"X critical issue(s) found. Fix before archiving.\"\n   - If only warnings: \"No critical issues. Y warning(s) to consider. Ready for archive (with noted improvements).\"\n   - If all clear: \"All checks passed. Ready for archive.\"\n\n**Verification Heuristics**\n\n- **Completeness**: Focus on objective checklist items (checkboxes, requirements list)\n- **Correctness**: Use keyword search, file path analysis, reasonable inference - don''t require perfect certainty\n- **Coherence**: Look for glaring inconsistencies, don''t nitpick style\n- **False Positives**: When uncertain, prefer SUGGESTION over WARNING, WARNING over CRITICAL\n- **Actionability**: Every issue must have a specific recommendation with file/line references where applicable\n\n**Graceful Degradation**\n\n- If only tasks.md exists: verify task completion only, skip spec/design checks\n- If tasks + specs exist: verify completeness and correctness, skip design\n- If full artifacts: verify all three dimensions\n- Always note which checks were skipped and why\n\n**Output Format**\n\nUse clear markdown with:\n\n- Table for summary scorecard\n- Grouped lists for issues (CRITICAL/WARNING/SUGGESTION)\n- Code references in format: `file.ts:123`\n- Specific, actionable recommendations\n- No vague suggestions like \"consider reviewing\"\n"},"lastSynced":"2026-03-06T06:38:15.883Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing precise implementation verification against change artifacts.","zh":"非常适合需要对变更工件进行精确实现验证的开发代理。","ja":"開発エージェントが変更アーティファクトに対して正確な実装検証を必要とする場合に最適です。","ko":"변경 아티팩트에 대해 정확한 구현 검증이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una verificación de implementación precisa contra artefactos de cambio.","fr":"Parfait pour les agents de développement nécessitant une vérification d''implémentation précise contre les artefacts de modification.","de":"Perfekt für Entwicklungsmittel, die eine präzise Implementierungsverifizierung gegen Änderungsartefakte benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de verificação de implementação precisa contra artefatos de alteração.","ru":"Идеально для агентов разработки, которым требуется точная проверка реализации против артефактов изменений.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى التحقق الدقيق لتنفيذ ضد مادة التغيير."},"recommendation":{"en":"Empowers agents to ensure consistency and accuracy in projects by verifying implementation matches against specs, tasks, and design using the openspec-verify-change skill, which leverages the AskUserQuestion tool and openspec list --json command.","zh":"通过使用openspec-verify-change技能来验证实现是否与规范、任务和设计相符，从而赋予代理确保项目的一致性和准确性，openspec-verify-change技能利用了AskUserQuestion工具和openspec list --json命令。","ja":"openspec-verify-changeスキルを使用して、実装が仕様、タスク、設計と一致することを検証することで、エージェントがプロジェクトの一貫性と正確性を確保できるようにします。openspec-verify-changeスキルは、AskUserQuestionツールとopenspec list --jsonコマンドを活用しています。","ko":"openspec-verify-change 스킬을 사용하여 구현이 사양, 태스크 및 디자인과 일치하는지 확인함으로써 에이전트가 프로젝트의 일관성과 정확성을 보장할 수 있도록 합니다. openspec-verify-change 스킬은 AskUserQuestion 도구와 openspec list --json 명령을 활용합니다.","es":"Habilita a los agentes a garantizar la consistencia y la precisión en los proyectos verificando que la implementación coincida con las especificaciones, tareas y diseño utilizando la habilidad openspec-verify-change, que aprovecha la herramienta AskUserQuestion y el comando openspec list --json.","fr":"Permet aux agents de s''assurer de la cohérence et de l''exactitude des projets en vérifiant que l''implémentation correspond aux spécifications, tâches et conception en utilisant la compétence openspec-verify-change, qui exploite l''outil AskUserQuestion et la commande openspec list --json.","de":"Ermächtigt die Agenten, die Konsistenz und Genauigkeit in den Projekten sicherzustellen, indem sie überprüfen, dass die Implementierung mit den Spezifikationen, Aufgaben und Design übereinstimmt, unter Verwendung der Fähigkeit openspec-verify-change, die das Tool AskUserQuestion und den Befehl openspec list --json nutzt.","pt":"Habilita os agentes a garantir a consistência e a precisão nos projetos, verificando se a implementação corresponde às especificações, tarefas e design usando a habilidade openspec-verify-change, que aproveita a ferramenta AskUserQuestion e o comando openspec list --json.","ru":"Наделяет агентов возможностью обеспечить согласованность и точность в проектах, проверяя соответствие реализации спецификациям, задачам и дизайну с помощью навыка openspec-verify-change, который использует инструмент AskUserQuestion и команду openspec list --json.","ar":"يمنح الوكلاء القدرة على ضمان الاتساق والدقة في المشاريع، من خلال التحقق من تطابق التنفيذ مع المواصفات والمهام والتصميم باستخدام مهارة openspec-verify-change، التي تستفيد من أداة AskUserQuestion وأمر openspec list --json."},"useCases":{"en":["Verifying implementation against change artifacts","Automating consistency checks for development projects","Debugging mismatches between specs and implementation"],"zh":["验证实现是否与变更工件一致","自动化开发项目的一致性检查","调试规范与实现之间的不匹配"],"ja":["実装が変更アーティファクトと一致することを検証する","開発プロジェクトの一貫性チェックを自動化する","仕様と実装の不一致をデバッグする"],"ko":["구현이 변경 아티팩트와 일치하는지 확인하는 것","개발 프로젝트의 일관성 확인을 자동화하는 것","사양과 구현 간의 불일치를 디버깅하는 것"],"es":["Verificar la implementación contra artefactos de cambio","Automatizar las comprobaciones de coherencia para proyectos de desarrollo","Depurar las discordancias entre las especificaciones y la implementación"],"fr":["Vérifier l''implémentation contre les artefacts de modification","Automatiser les vérifications de cohérence pour les projets de développement","Déboguer les discordances entre les spécifications et l''implémentation"],"de":["Überprüfen der Implementierung gegen Änderungsartefakte","Automatisierung von Konsistenzprüfungen für Entwicklungsvorhaben","Fehlerbehebung von Unstimmigkeiten zwischen Spezifikationen und Implementierung"],"pt":["Verificar a implementação contra artefatos de alteração","Automatizar verificações de consistência para projetos de desenvolvimento","Depurar discrepâncias entre especificações e implementação"],"ru":["Проверка реализации против артефактов изменений","Автоматизация проверок согласованности для проектов разработки","Отладка несоответствий между спецификациями и реализацией"],"ar":["التحقق من التنفيذ ضد مادة التغيير","تأتمة فحص الاتساق للمشاريع التطويرية","تصحيح أخطاء عدم مطابقة بين المواصفات والتنفيذ"]},"limitations":{"en":["Requires openspec list --json command accessibility","Needs inference or user input for change name","Limited to projects with available change artifacts"],"zh":["需要openspec list --json命令的可访问性","需要推断或用户输入来获取变更名称","仅限于具有可用变更工件的项目"],"ja":["openspec list --jsonコマンドのアクセシビリティが必要","変更名の入力をユーザーまたは推論から得る必要がある","利用可能な変更アーティファクトを持つプロジェクトに限定される"],"ko":["openspec list --json 명령의 접근성이 필요함","변경 이름을 유추하거나 사용자 입력으로 얻을 필요가 있음","사용 가능한 변경 아티팩트가 있는 프로젝트로 제한됨"],"es":["Requiere accesibilidad al comando openspec list --json","Necesita inferencia o entrada de usuario para el nombre del cambio","Limitado a proyectos con artefactos de cambio disponibles"],"fr":["Nécessite l''accessibilité à la commande openspec list --json","A besoin d''une inférence ou d''une saisie utilisateur pour le nom du changement","Limité aux projets avec des artefacts de modification disponibles"],"de":["Benötigt Zugriff auf den Befehl openspec list --json","Benötigt Inferenz oder Benutzereingabe für den Änderungsnamen","Begrenzt auf Projekte mit verfügbaren Änderungsartefakten"],"pt":["Requer acessibilidade ao comando openspec list --json","Necessita de inferência ou entrada do usuário para o nome da alteração","Limitado a projetos com artefatos de alteração disponíveis"],"ru":["Требует доступности команды openspec list --json","Требует вывода или ввода пользователя для имени изменений","Ограничен проектами с доступными артефактами изменений"],"ar":["يتطلب إمكانية الوصول إلى أمر openspec list --json","يتطلب استنتاجًا أو إدخال المستخدم لاسم التغيير","محدود بالمشاريع التي تحتوي على مادة التغيير المتاحة"]},"version":4},"contentHash":"c91dcdb4639dee625ec6e1e72ff32de4512cdcc78825e1e8141d44f6ab207adc","qualityScore":55}');
