INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jixoai/openspecui/openspec-verify-change', 'openspec-verify-change', 'jixoai', 'openspecui', 'community', 'openspec-verify-change jixoai openspecui community The openspec-verify-change skill verifies implementation matches against change artifacts. It benefits developers by ensuring consistency and accuracy in their projects. openspec-verify-change是一个用于验证实现是否匹配更改文档的工具，支持命令行接口和用户交互 openspec-verify-changeは、実装が変更文書と一致するかを検証するツールです。コマンドラインインターフェースとユーザーインタラクションをサポートしています openspec-verify-change는 구현이 변경 문서와 일치하는지 검증하는 도구입니다. 명령줄 인터페이스와 사용자 상호작용을 지원합니다 openspec-verify-change es una habilidad que verifica si una implementación coincide con los artefactos de cambio. Utiliza la herramienta AskUserQuestion para seleccionar cambios openspec-verify-change est une compétence qui vérifie si une implémentation correspond aux artefacts de modification. Elle utilise l''outil AskUserQuestion pour sélectionner les modifications openspec-verify-change ist eine Fähigkeit, die überprüft, ob eine Implementierung mit den Änderungsartefakten übereinstimmt. Sie verwendet das Tool AskUserQuestion, um Änderungen auszuwählen O openspec-verify-change é uma ferramenta que verifica se a implementação de um projeto corresponde às alterações especificadas. Ele utiliza a ferramenta AskUserQuestion para seleção de alterações. Openspec-verify-change - это инструмент, который проверяет, соответствует ли реализация проекта изменениям. Он использует инструмент AskUserQuestion для выбора изменений. openspec-verify-change هو أداة تحقق من تطابق تنفيذ المشروع مع التغييرات المحددة. يستخدم أداة AskUserQuestion لاختيار التغييرات. how to use openspec-verify-change openspec-verify-change setup guide openspec-verify-change alternative openspec-verify-change vs manual validation openspec-verify-change install what is openspec-verify-change openspec-verify-change implementation verification openspec-verify-change AI工具 代码验证 命令行接口 用户交互 AskUserQuestion openspec list --json Runs openspec list --json to retrieve available changes Utilizes AskUserQuestion tool for user selection of changes Prompts for selection when no change name is provided Displays changes with implementation tasks for efficient validation Supports inference of change name from conversation context openspec-verify-change is a skill that verifies an implementation matches the change artifacts, such as specs, tasks, and design, using openspec list --json and AskUserQuestion tool.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danielsogl/copilot-workflow-demo/openspec-continue-change', 'community', 'danielsogl', 'copilot-workflow-demo', 'danielsogl/copilot-workflow-demo', 'openspec-continue-change', 21, 2, 55, '2026-02-23T09:28:38Z', '2026-03-06T13:02:30.162Z', 'd0fbc067936de6bea93e611b962d6fa0fd58bcd47b1fe8ee529fa0c97c1afd9d', '{"id":"danielsogl/copilot-workflow-demo/openspec-continue-change","name":"openspec-continue-change","description":{"en":"The openspec-continue-change skill allows developers to continue working on a change by creating the next artifact, optionally specifying a change name or inferring it from context.","zh":"openspec-continue-change 是一个用于继续工作的变更的 AI 工具，通过创建下一个构件来继续变更","ja":"openspec-continue-change は、次のアーティファクトを作成することで変更を続行する AIツールです","ko":"openspec-continue-change 는 다음 아티팩트를 생성하여 변경을 계속하는 AI 도구입니다","es":"openspec-continue-change permite a los desarrolladores continuar trabajando en cambios mediante la creación del siguiente artifacto, utilizando herramientas como AskUserQuestion y openspec list","fr":"openspec-continue-change permet aux développeurs de poursuivre des modifications en créant le prochain artifact, en utilisant des outils tels que AskUserQuestion et openspec list","de":"openspec-continue-change ermöglicht es Entwicklern, Änderungen durch die Erstellung des nächsten Artifacts fortzusetzen, indem sie Tools wie AskUserQuestion und openspec list verwenden","pt":"O openspec-continue-change é uma ferramenta que permite criar o próximo artefato de alteração. Ele usa o comando openspec list --json para obter alterações disponíveis.","ru":"openspec-continue-change - это инструмент, который позволяет создать следующий артефакт изменений. Он использует команду openspec list --json для получения доступных изменений.","ar":"openspec-continue-change هو أداة تمكنك من إنشاء الملف التالي لتعديل. يستخدم الأمر openspec list --json لجلب التعديلات المتاحة"},"seo":{"title":{"en":"openspec-continue-change: Setup Guide for AI Agents","zh":"openspec-continue-change 集成指南","ja":"openspec-continue-change 導入ガイド - AIエージェント","ko":"openspec-continue-change 설정 가이드 - AI 도구","es":"Guía de configuración de openspec-continue-change para de...","fr":"Paramétrer openspec-continue-change : Guide pour les déve...","de":"Einrichten von openspec-continue-change: Leitfaden für En...","pt":"Guia de Configuração do openspec-continue-change para Des...","ru":"Настройка openspec-continue-change: Лучшие Практики для Р...","ar":"إعداد openspec-continue-change: دليل المستخدم للاستفادة ا..."},"description":{"en":"Discover how to continue working on a change with openspec-continue-change. Learn how to create the next artifact and infer change names from conversation co...","zh":"了解 openspec-continue-change 的功能和设置方法，提高开发效率","ja":"openspec-continue-change を使用して開発効率を向上させる方法を紹介します - AIエージェント","ko":"openspec-continue-change 설정과 기능을 익히고 개발 생산성을 높이세요 - AI 도구","es":"Aprende a utilizar openspec-continue-change para continuar trabajando en cambios con herramientas como AskUserQuestion y openspec list","fr":"Découvrez comment utiliser openspec-continue-change pour poursuivre des modifications avec des outils comme AskUserQuestion et openspec list","de":"Erfahren Sie, wie Sie openspec-continue-change verwenden, um Änderungen mit Tools wie AskUserQuestion und openspec list fortzusetzen","pt":"Aprenda a usar o openspec-continue-change com nossa guia passo a passo. Descubra como criar o próximo artefato de alteração com facilidade.","ru":"Узнайте, как настроить openspec-continue-change с нашей пошаговой инструкцией. Откройте для себя, как легко создать следующий артефакт изменений.","ar":"تعلم كيفية إعداد openspec-continue-change باستخدام دليلنا المتقدم. اكتشف كيفية إنشاء الملف التالي لتعديل بسهولة"},"definition":{"en":"openspec-continue-change is a skill that enables developers to continue working on a change by creating the next artifact, using commands like openspec list --json.","zh":"openspec-continue-change 是一种 AI 工具，用于继续工作的变更","ja":"openspec-continue-change は、変更を続行するための AIツールです","ko":"openspec-continue-change 는 변경을 계속하는 AI 도구입니다","es":"openspec-continue-change es una habilidad que permite a los desarrolladores continuar trabajando en cambios mediante la creación del siguiente artifacto","fr":"openspec-continue-change est une compétence qui permet aux développeurs de poursuivre des modifications en créant le prochain artifact","de":"openspec-continue-change ist eine Fähigkeit, die es Entwicklern ermöglicht, Änderungen durch die Erstellung des nächsten Artifacts fortzusetzen","pt":"O que é openspec-continue-change? É uma ferramenta de linha de comando que continua um trabalho de alteração criando o próximo artefato.","ru":"Что такое openspec-continue-change? Это командная утилита, которая продолжает работу над изменением, создавая следующий артефакт.","ar":"ما هو openspec-continue-change؟ هو أداة سطر أوامر تتيح لك الاستمرار في تعديل ما عن طريق إنشاء الملف التالي"},"features":{"en":["Runs openspec list --json to get available changes sorted by most recently modified","Uses the AskUserQuestion tool to let users select which change to work on","Presents the top 3-5 available changes for user selection","Infers change names from conversation context if not explicitly provided","Supports prompting for selection if change name is vague or ambiguous"],"zh":["支持通过运行 `openspec list --json` 命令来获取可用变更","使用 AskUserQuestion 工具让用户选择要继续的变更","支持根据最近修改时间对变更进行排序","可选地指定变更名称","如果变更名称不明确，会提示用户选择"],"ja":["『openspec list --json』コマンドを実行して利用可能な変更を取得する機能","AskUserQuestion ツールを使用してユーザーが続行する変更を選択する機能","最近の変更時間に基づいて変更をソートする機能","変更名を任意に指定する機能","変更名が不明確な場合、ユーザーに選択を求める機能"],"ko":["『openspec list --json』 명령을 실행하여 사용 가능한 변경을 가져오는 기능","AskUserQuestion 도구를 사용하여 사용자가 계속할 변경을 선택하는 기능","최근 수정 시간에 따라 변경을 정렬하는 기능","변경 이름을 선택적으로 지정하는 기능","변경 이름이 모호한 경우 사용자에게 선택을 요청하는 기능"],"es":["Utiliza AskUserQuestion para seleccionar el cambio a trabajar","Ejecuta openspec list para obtener los cambios disponibles ordenados por fecha de modificación","Permite la selección del cambio a trabajar mediante la presentación de los 3 cambios más recientes","Soporta la inferencia del nombre del cambio desde el contexto de la conversación","Ofrece la opción de especificar el nombre del cambio de forma explícita"],"fr":["Utilise AskUserQuestion pour sélectionner la modification à travailler","Exécute openspec list pour obtenir les modifications disponibles classées par date de modification","Permet la sélection de la modification à travailler en présentant les 3 modifications les plus récentes","Prend en charge l''inférence du nom de la modification à partir du contexte de la conversation","Offre l''option de spécifier le nom de la modification de manière explicite"],"de":["Verwenden von AskUserQuestion zur Auswahl des zu bearbeitenden Changes","Ausführen von openspec list, um die verfügbaren Changes nach Änderungsdatum zu erhalten","Ermöglicht die Auswahl des zu bearbeitenden Changes durch die Darstellung der 3 aktuellsten Changes","Unterstützt die Ableitung des Change-Namens aus dem Konversationskontext","Bietet die Option, den Change-Namen explizit anzugeben"],"pt":["Cria o próximo artefato de alteração","Usa o comando openspec list --json para obter alterações disponíveis","Permite ao usuário selecionar a alteração a ser continuada","Executa o AskUserQuestion tool para seleção de alterações","Suporta a apresentação dos 3 resultados mais recentes"],"ru":["Создает следующий артефакт изменений","Использует команду openspec list --json для получения доступных изменений","Позволяет пользователю выбрать изменение, которое необходимо продолжить","Выполняет AskUserQuestion tool для выбора изменений","Поддерживает отображение 3 наиболее недавних результатов"],"ar":["ينشئ الملف التالي لتعديل","يستخدم الأمر openspec list --json لجلب التعديلات المتاحة","يسمح للمستخدم باختيار التعديل الذي سيتم استكماله","ينفذ أداة AskUserQuestion لاختيار التعديلات","يدعم عرض 3 نتائج最近"]},"keywords":{"en":["how to use openspec-continue-change","openspec-continue-change setup guide","openspec-continue-change vs other AI skills","openspec-continue-change install","what is openspec-continue-change","openspec-continue-change alternative","openspec-continue-change tutorial","openspec-continue-change documentation","openspec-continue-change examples"],"zh":["openspec-continue-change","AI 工具","变更管理","开发效率","命令行工具","AskUserQuestion","JSON 输出"],"ja":["openspec-continue-change","AIエージェント","変更管理","開発効率","コマンドラインツール","AskUserQuestion","JSON 出力"],"ko":["openspec-continue-change","AI 도구","변경 관리","개발 생산성","명령줄 도구","AskUserQuestion","JSON 출력"],"es":["openspec-continue-change","desarrollo de software","herramientas de desarrollo","AskUserQuestion","openspec list","cambios en el código","desarrollo colaborativo","Agente de IA para desarrollo"],"fr":["openspec-continue-change","développement de logiciels","outils de développement","AskUserQuestion","openspec list","modifications de code","développement collaboratif","Outil d''IA pour les développeurs"],"de":["openspec-continue-change","Software-Entwicklung","Entwicklungstools","AskUserQuestion","openspec list","Änderungen im Code","kollaborative Entwicklung","IA-Tool für Entwickler"],"pt":["openspec-continue-change","ferramenta de linha de comando","alterações de código","AskUserQuestion tool","comando openspec list --json","desenvolvimento de software","ferramentas de desenvolvedor"],"ru":["openspec-continue-change","командная утилита","изменения кода","AskUserQuestion tool","команда openspec list --json","разработка программного обеспечения","инструменты для разработчиков"],"ar":["openspec-continue-change","أداة سطر أوامر","تعديلات الكود","أداة AskUserQuestion","الأمر openspec list --json","تطوير البرمجيات","أدوات المطور"]}},"owner":"danielsogl","repo":"copilot-workflow-demo","repoPath":"danielsogl/copilot-workflow-demo","stars":21,"forks":2,"updatedAt":"2026-02-23T09:28:38Z","topics":[],"category":"community","skillMd":{"name":"openspec-continue-change","description":"Continue working on an OpenSpec change by creating the next artifact. Use when the user wants to progress their change, create the next artifact, or continue their workflow.","version":"1.0","bodyPreview":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-","body":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-4 most recently modified changes as options, showing:\n   - Change name\n   - Schema (from `schema` field if present, otherwise \"spec-driven\")\n   - Status (e.g., \"0/5 tasks\", \"complete\", \"no tasks\")\n   - How recently it was modified (from `lastModified` field)\n\n   Mark the most recently modified change as \"(Recommended)\" since it''s likely what the user wants to continue.\n\n   **IMPORTANT**: Do NOT guess or auto-select a change. Always let the user choose.\n\n2. **Check current status**\n\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n\n   Parse the JSON to understand current state. The response includes:\n   - `schemaName`: The workflow schema being used (e.g., \"spec-driven\")\n   - `artifacts`: Array of artifacts with their status (\"done\", \"ready\", \"blocked\")\n   - `isComplete`: Boolean indicating if all artifacts are complete\n\n3. **Act based on status**:\n\n   ***\n\n   **If all artifacts are complete (`isComplete: true`)**:\n   - Congratulate the user\n   - Show final status including the schema used\n   - Suggest: \"All artifacts created! You can now implement this change or archive it.\"\n   - STOP\n\n   ***\n\n   **If artifacts are ready to create** (status shows artifacts with `status: \"ready\"`):\n   - Pick the FIRST artifact with `status: \"ready\"` from the status output\n   - Get its instructions:\n     ```bash\n     openspec instructions <artifact-id> --change \"<name>\" --json\n     ```\n   - Parse the JSON. The key fields are:\n     - `context`: Project background (constraints for you - do NOT include in output)\n     - `rules`: Artifact-specific rules (constraints for you - do NOT include in output)\n     - `template`: The structure to use for your output file\n     - `instruction`: Schema-specific guidance\n     - `outputPath`: Where to write the artifact\n     - `dependencies`: Completed artifacts to read for context\n   - **Create the artifact file**:\n     - Read any completed dependency files for context\n     - Use `template` as the structure - fill in its sections\n     - Apply `context` and `rules` as constraints when writing - but do NOT copy them into the file\n     - Write to the output path specified in instructions\n   - Show what was created and what''s now unlocked\n   - STOP after creating ONE artifact\n\n   ***\n\n   **If no artifacts are ready (all blocked)**:\n   - This shouldn''t happen with a valid schema\n   - Show status and suggest checking for issues\n\n4. **After creating an artifact, show progress**\n   ```bash\n   openspec status --change \"<name>\"\n   ```\n\n**Output**\n\nAfter each invocation, show:\n\n- Which artifact was created\n- Schema workflow being used\n- Current progress (N/M complete)\n- What artifacts are now unlocked\n- Prompt: \"Want to continue? Just ask me to continue or tell me what to do next.\"\n\n**Artifact Creation Guidelines**\n\nThe artifact types and their purpose depend on the schema. Use the `instruction` field from the instructions output to understand what to create.\n\nCommon artifact patterns:\n\n**spec-driven schema** (proposal → specs → design → tasks):\n\n- **proposal.md**: Ask user about the change if not clear. Fill in Why, What Changes, Capabilities, Impact.\n  - The Capabilities section is critical - each capability listed will need a spec file.\n- **specs/<capability>/spec.md**: Create one spec per capability listed in the proposal''s Capabilities section (use the capability name, not the change name).\n- **design.md**: Document technical decisions, architecture, and implementation approach.\n- **tasks.md**: Break down implementation into checkboxed tasks.\n\nFor other schemas, follow the `instruction` field from the CLI output.\n\n**Guardrails**\n\n- Create ONE artifact per invocation\n- Always read dependency artifacts before creating a new one\n- Never skip artifacts or create out of order\n- If context is unclear, ask the user before creating\n- Verify the artifact file exists after writing before marking progress\n- Use the schema''s artifact sequence, don''t assume specific artifact names\n- **IMPORTANT**: `context` and `rules` are constraints for YOU, not content for the file\n  - Do NOT copy `<context>`, `<rules>`, `<project_context>` blocks into the artifact\n  - These guide what you write, but should never appear in the output\n"},"lastSynced":"2026-03-06T13:02:30.162Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring seamless change management and artifact creation capabilities.","zh":"适合需要无缝变更管理和构件创建能力的开发代理。","ja":"開発エージェントが無断で変更管理とアーティファクトの作成機能を必要とする場合に最適です。","ko":"변경 관리와 아티팩트 생성 기능을无缝으로 처리해야 하는 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren un cambio de gestión y capacidades de creación de artefactos sin problemas.","fr":"Idéal pour les agents de développement nécessitant une gestion de changement transparente et des capacités de création d''artefacts.","de":"Ideal für Entwicklungssagenten, die eine nahtlose Änderungsverwaltung und Artefakt-Erstellungsfunktionen benötigen.","pt":"Ideal para Agentes de Desenvolvimento que exigem gerenciamento de alterações sem interrupção e capacidades de criação de artefatos.","ru":"Идеально для агентов разработки, требующих бесшовного управления изменениями и возможностей создания артефактов.","ar":"مثالي لعميل التطوير الذي يتطلب إدارة التغييرات دون انقطاع وقدرات إنشاء الملفات المكونة."},"recommendation":{"en":"Empowers agents to continue working on a change by creating the next artifact, utilizing the `openspec list --json` command and the AskUserQuestion tool for efficient change selection and management, supporting features like change name inference from conversation context.","zh":"赋予代理继续处理更改的能力，通过创建下一个构件，利用 `openspec list --json` 命令和 AskUserQuestion 工具来高效地选择和管理更改，支持从对话上下文推断更改名称等功能。","ja":"エージェントが変更を続行できるようにし、次のアーティファクトを作成して `openspec list --json` コマンドと AskUserQuestion ツールを使用して、変更の選択と管理を効率化し、会話のコンテキストから変更名を推測する機能などをサポートします。","ko":"에이전트가 변경을 계속할 수 있도록 하며, 다음 아티팩트를 생성하고 `openspec list --json` 명령 및 AskUserQuestion 툴을 사용하여 변경 선택 및 관리를 효율적으로 수행하며, 대화 문脈에서 변경 이름을 추론하는 기능 등을 지원합니다.","es":"Permite a los agentes seguir trabajando en un cambio creando el siguiente artefacto, utilizando el comando `openspec list --json` y la herramienta AskUserQuestion para una selección y gestión de cambios eficientes, que admiten funciones como la inferencia del nombre de cambio del contexto de conversación.","fr":"Permet aux agents de continuer à travailler sur un changement en créant le prochain artefact, en utilisant la commande `openspec list --json` et l''outil AskUserQuestion pour une sélection et une gestion de changements efficaces, prenant en charge des fonctionnalités comme l''inférence du nom de changement à partir du contexte de conversation.","de":"Ermöglicht es Agenten, an einem Änderungsprozess weiterzuarbeiten, indem sie das nächste Artefakt erstellen, unter Verwendung des Befehls `openspec list --json` und des Tools AskUserQuestion für eine effiziente Änderungsauswahl und -verwaltung, die Funktionen wie die Ableitung des Änderungsnamens aus dem Konversationskontext unterstützt.","pt":"Permite que os agentes continuem trabalhando em uma alteração, criando o próximo artefato, utilizando o comando `openspec list --json` e a ferramenta AskUserQuestion para seleção e gerenciamento eficientes de alterações, com recursos como inferência do nome da alteração do contexto da conversa.","ru":"Позволяет агентам продолжать работу над изменением, создавая следующий артефакт, используя команду `openspec list --json` и инструмент AskUserQuestion для эффективного выбора и управления изменениями, поддерживая функции, такие как вывод имени изменения из контекста разговора.","ar":"تمكّن الوكيل من الاستمرار في العمل على تغيير من خلال إنشاء الملف المكون التالي، باستخدام الأمر `openspec list --json` وأداة AskUserQuestion لتحديد التغيير وإدارته بكفاءة، مع دعم ميزات مثل استنتاج اسم التغيير من سياق المحادثة."},"useCases":{"en":["Continuing unfinished changes","Automating artifact creation","Inferring change names from context"],"zh":["继续未完成的更改","自动化构件创建","从上下文推断更改名称"],"ja":["未完了の変更の続行","アーティファクトの自動作成","コンテキストから変更名の推測"],"ko":["미완료 변경의 계속","아티팩트 자동 생성","문脈에서 변경 이름 추론"],"es":["Continuar cambios incompletos","Automatizar la creación de artefactos","Inferir nombres de cambios desde el contexto"],"fr":["Continuer les changements incomplétés","Automatiser la création d''artefacts","Inférer les noms de changement à partir du contexte"],"de":["Unvollendete Änderungen fortsetzen","Artefakt-Erstellung automatisieren","Änderungsnamen aus dem Kontext ableiten"],"pt":["Continuar alterações incompletas","Automatizar a criação de artefatos","Inferir nomes de alterações do contexto"],"ru":["Продолжение незавершенных изменений","Автоматизация создания артефактов","Вывод имен изменений из контекста"],"ar":["استكمال التغييرات غير المكتملة","تأتمة إنشاء الملفات المكونة","استنتاج أسماء التغييرات من السياق"]},"limitations":{"en":["Requires access to conversation context for change name inference","Must use AskUserQuestion tool for user input"],"zh":["需要访问对话上下文以推断更改名称","必须使用 AskUserQuestion 工具进行用户输入"],"ja":["変更名の推測には会話コンテキストへのアクセスが必要","ユーザー入力には AskUserQuestion ツールを使用する必要がある"],"ko":["변경 이름 추론을 위해서는 대화 문脈에 대한 접근이 필요하다","사용자 입력에는 AskUserQuestion 툴을 사용해야 한다"],"es":["Requiere acceso al contexto de conversación para la inferencia del nombre de cambio","Debe utilizar la herramienta AskUserQuestion para la entrada del usuario"],"fr":["Nécessite un accès au contexte de conversation pour l''inférence du nom de changement","Doit utiliser l''outil AskUserQuestion pour la saisie utilisateur"],"de":["Benötigt Zugriff auf den Konversationskontext für die Ableitung des Änderungsnamens","Muss das Tool AskUserQuestion für die Benutzereingabe verwenden"],"pt":["Exige acesso ao contexto da conversa para inferência do nome da alteração","Deve usar a ferramenta AskUserQuestion para entrada do usuário"],"ru":["Требует доступа к контексту разговора для вывода имени изменения","Должен использовать инструмент AskUserQuestion для ввода пользователя"],"ar":["يتطلب الوصول إلى سياق المحادثة لاستنتاج اسم التغيير","يجب استخدام أداة AskUserQuestion لإدخال المستخدم"]},"version":4},"contentHash":"d0fbc067936de6bea93e611b962d6fa0fd58bcd47b1fe8ee529fa0c97c1afd9d","qualityScore":55}');
