INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danielsogl/copilot-workflow-demo/openspec-continue-change', 'openspec-continue-change', 'danielsogl', 'copilot-workflow-demo', 'community', 'openspec-continue-change danielsogl copilot-workflow-demo community The openspec-continue-change skill allows developers to continue working on a change by creating the next artifact, optionally specifying a change name or inferring it from context. openspec-continue-change 是一个用于继续工作的变更的 AI 工具，通过创建下一个构件来继续变更 openspec-continue-change は、次のアーティファクトを作成することで変更を続行する AIツールです openspec-continue-change 는 다음 아티팩트를 생성하여 변경을 계속하는 AI 도구입니다 openspec-continue-change permite a los desarrolladores continuar trabajando en cambios mediante la creación del siguiente artifacto, utilizando herramientas como AskUserQuestion y openspec list openspec-continue-change permet aux développeurs de poursuivre des modifications en créant le prochain artifact, en utilisant des outils tels que AskUserQuestion et openspec list openspec-continue-change ermöglicht es Entwicklern, Änderungen durch die Erstellung des nächsten Artifacts fortzusetzen, indem sie Tools wie AskUserQuestion und openspec list verwenden O openspec-continue-change é uma ferramenta que permite criar o próximo artefato de alteração. Ele usa o comando openspec list --json para obter alterações disponíveis. openspec-continue-change - это инструмент, который позволяет создать следующий артефакт изменений. Он использует команду openspec list --json для получения доступных изменений. openspec-continue-change هو أداة تمكنك من إنشاء الملف التالي لتعديل. يستخدم الأمر openspec list --json لجلب التعديلات المتاحة how to use openspec-continue-change openspec-continue-change setup guide openspec-continue-change vs other AI skills openspec-continue-change install what is openspec-continue-change openspec-continue-change alternative openspec-continue-change tutorial openspec-continue-change documentation openspec-continue-change examples openspec-continue-change AI 工具 变更管理 开发效率 命令行工具 AskUserQuestion JSON 输出 Runs openspec list --json to get available changes sorted by most recently modified Uses the AskUserQuestion tool to let users select which change to work on Presents the top 3-5 available changes for user selection Infers change names from conversation context if not explicitly provided Supports prompting for selection if change name is vague or ambiguous openspec-continue-change is a skill that enables developers to continue working on a change by creating the next artifact, using commands like openspec list --json.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nir-Bhay/markups/popup-cro', 'community', 'Nir-Bhay', 'markups', 'Nir-Bhay/markups', 'popup-cro', 2, 0, 55, '2026-03-04T17:48:20Z', '2026-03-06T07:09:40.704Z', 'ed047d27ed947a6a086031e38719c7ff79e0ef82a73067950cca78a0a353f926', '{"id":"Nir-Bhay/markups/popup-cro","name":"popup-cro","description":{"en":"The popup-cro skill enables experts to create optimized popups and modals for conversion without annoying users. It provides a markdown editor with live preview for precise control.","zh":"popup-cro 是一种专门用于弹窗和模态窗口优化的技术，通过 markdown 编辑器和实时预览功能，帮助开发者创建高转化率的弹窗","ja":"popup-cro は、ポップアップとモーダルウィンドウを最適化するために設計された技術です。Markdown エディターとリアルタイムプレビュー機能を備えています","ko":"popup-cro는 팝업창과 모달 창을 최적화하기 위한 기술로, 마크다운 편집기와 실시간 미리보기 기능을 통해 개발자가 높은 전환률의 팝업창을 생성할 수 있습니다","es":"El popup-cro es una habilidad que permite crear popups personalizados con una vista previa en vivo, utilizando tecnologías como markdown editors.","fr":"Le popup-cro est une compétence qui permet de créer des popups personnalisés avec une prévisualisation en direct, en utilisant des technologies comme les éditeurs de markdown.","de":"Das popup-cro ist eine Fähigkeit, die die Erstellung von benutzerdefinierten Popups mit Live-Vorschau ermöglicht, unter Verwendung von Technologien wie Markdown-Editoren.","pt":"O popup-cro é uma ferramenta de otimização de popups que utiliza markdown editor com pré-visualização ao vivo para melhorar a experiência do usuário.","ru":"popup-cro - это инструмент оптимизации попапов, который использует редактор markdown с живой предварительной версией для улучшения пользовательского опыта.","ar":"popup-cro هو أداة لتحسين نافذة المنبثقة التي تستخدم محرر markdown مع معاينة مباشرة لتحسين تجربة المستخدم."},"seo":{"title":{"en":"popup-cro: Expert Popup Optimization Setup Guide | AI Age...","zh":"popup-cro 设置指南：优化弹窗转化率","ja":"popup-cro 導入ガイド：AIエージェントによるポップアップ最適化","ko":"popup-cro 설정 가이드: 최적의 팝업창 생성","es":"Guía de configuración de popup-cro para optimización de m...","fr":"Guide de setup de popup-cro pour l''optimisation des modales","de":"Einrichtungsleitfaden für popup-cro zur Optimierung von P...","pt":"Guia de Configuração do popup-cro: Otimização de Popups c...","ru":"Настройка popup-cro: Лучшие Практики Оптимизации Попапов ...","ar":"إعداد مرشد popup-cro: تحسين نافذة المنبثقة مع أدوات الذكا..."},"description":{"en":"Unlock conversion-boosting popups without damaging brand perception. Learn how to use popup-cro for expert popup optimization and modal refinement","zh":"了解 popup-cro 技术，优化弹窗转化率，不打扰用户，提升品牌知名度","ja":"AIエージェントによるポップアップ最適化を実現する popup-cro 技術の概要","ko":"사용자에게 방해가 되지 않는 팝업창을 생성하고 전환률을 높이는 popup-cro 기술","es":"Aprende a crear popups que conviertan sin molestar a los usuarios, con nuestra guía de popup-cro y herramientas de AI Agent como ''herramientas de inteligenci...","fr":"Découvrez comment créer des popups qui convertissent sans agacer les utilisateurs, avec notre guide de popup-cro et des outils d''AI Agent comme ''outils d''int...","de":"Erfahren Sie, wie Sie Popups erstellen, die umwandeln, ohne Benutzer zu stören, mit unserem Leitfaden für popup-cro und AI-Tools wie ''KI-Tools''","pt":"Aprenda a configurar o popup-cro para melhorar a experiência do usuário e aumentar as conversões com nossa guia de otimização de popups","ru":"Узнайте, как настроить popup-cro, чтобы улучшить пользовательский опыт и увеличить конверсии с нашей инструкцией по оптимизации попапов","ar":"تعلم كيفية cấu hình popup-cro لتحسين تجربة المستخدم وزيادة التحويلات مع دليلنا لتحسين نافذة المنبثقة"},"definition":{"en":"popup-cro is a specialized skill for optimizing popup and modal interactions to enhance conversion rates while preserving brand integrity","zh":"popup-cro 是一种用于优化弹窗和模态窗口的技术，帮助开发者创建高转化率的弹窗","ja":"popup-cro は、ポップアップとモーダルウィンドウを最適化する技術です","ko":"popup-cro는 팝업창과 모달 창을 최적화하기 위한 기술입니다","es":"El popup-cro es una habilidad de optimización de popups que utiliza tecnologías como markdown editors para crear popups personalizados.","fr":"Le popup-cro est une compétence d''optimisation de popups qui utilise des technologies comme les éditeurs de markdown pour créer des popups personnalisés.","de":"Das popup-cro ist eine Fähigkeit zur Optimierung von Popups, die Technologien wie Markdown-Editoren verwendet, um benutzerdefinierte Popups zu erstellen.","pt":"O que é popup-cro? É uma ferramenta de otimização de popups que ajuda a criar popups personalizados com markdown editor.","ru":"Что такое popup-cro? Это инструмент оптимизации попапов, который помогает создавать индивидуальные попапы с редактором markdown.","ar":"ما هو popup-cro؟ إنه أداة لتحسين نافذة المنبثقة التي تساعد على إنشاء نافذة منبثقة مخصصة مع محرر markdown."},"features":{"en":["Utilizes markdown editor for precise popup content control","Provides live preview for instant feedback on design changes","Checks for product marketing context via .agents/product-marketing-context.md","Supports reading of .claude/product-marketing-context.md in older setups","Enables creation of popups that convert without damaging brand perception"],"zh":["markdown 编辑器","实时预览功能","弹窗和模态窗口优化","提高转化率","不打扰用户"],"ja":["Markdown エディター","リアルタイムプレビュー機能","ポップアップとモーダルウィンドウの最適化","変換率の向上","ユーザーへの妨害なし"],"ko":["마크다운 편집기","실시간 미리보기 기능","팝업창과 모달 창의 최적화","전환률 향상","사용자에게 방해가 되지 않음"],"es":["Edición de markdown con vista previa en vivo","Optimización de popups para conversiones","Creación de popups personalizados","Integración con herramientas de AI Agent","Compatibilidad con tecnologías como React y Python"],"fr":["Édition de markdown avec prévisualisation en direct","Optimisation de popups pour les conversions","Création de popups personnalisés","Intégration avec des outils d''AI Agent","Compatibilité avec des technologies comme React et Python"],"de":["Bearbeitung von Markdown mit Live-Vorschau","Optimierung von Popups für Umwandlungen","Erstellung von benutzerdefinierten Popups","Integration mit AI-Tools","Kompatibilität mit Technologien wie React und Python"],"pt":["Utiliza markdown editor com pré-visualização ao vivo","Otimização de popups personalizados","Integração com contextos de marketing de produtos","Análise de desempenho de popups","Criação de popups que convertem sem danificar a percepção da marca"],"ru":["Использует редактор markdown с живой предварительной версией","Оптимизация индивидуальных попапов","Интеграция с контекстами маркетинга продуктов","Анализ производительности попапов","Создание попапов, которые конвертируют без повреждения восприятия бренда"],"ar":["يستخدم محرر markdown مع معاينة مباشرة","تحسين نافذة المنبثقة المخصصة","التكامل مع السياقات التسويقية للمنتجات","تحليل أداء نافذة المنبثقة","إنشاء نافذة منبثقة تتحول دون الإضرار bằng الإدراك العلامة التجارية"]},"keywords":{"en":["how to use popup-cro","popup-cro alternative","popup-cro setup guide","what is popup-cro","popup-cro vs competitors","popup-cro install","expert popup optimization","modal refinement techniques","conversion-boosting popups"],"zh":["popup-cro","弹窗优化","模态窗口优化","markdown 编辑器","实时预览","转化率提高","AIエージェント","技术开发"],"ja":["popup-cro","ポップアップ最適化","モーダルウィンドウ最適化","Markdown エディター","リアルタイムプレビュー","変換率の向上","AIエージェント","技術開発"],"ko":["popup-cro","팝업창 최적화","모달 창 최적화","마크다운 편집기","실시간 미리보기","전환률 향상","AI 에이전트","기술 개발"],"es":["popup-cro","optimización de popups","herramientas de inteligencia artificial","markdown editors","creación de popups personalizados","integración con AI Agent","React","Python","CLI"],"fr":["popup-cro","optimisation de popups","outils d''intelligence artificielle","éditeurs de markdown","création de popups personnalisés","intégration avec des outils d''AI Agent","React","Python","CLI"],"de":["popup-cro","Optimierung von Popups","KI-Tools","Markdown-Editoren","Erstellung von benutzerdefinierten Popups","Integration mit AI-Tools","React","Python","CLI"],"pt":["popup-cro","otimização de popups","markdown editor","pré-visualização ao vivo","ferramentas de AI","desenvolvimento web","experiência do usuário","conversões","marca"],"ru":["popup-cro","оптимизация попапов","редактор markdown","живая предварительная версия","ИИ Агенты","веб-разработка","пользовательский опыт","конверсии","бренд"],"ar":["popup-cro","تحسين نافذة المنبثقة","محرر markdown","معاينة مباشرة","أدوات الذكاء الاصطناعي","تطوير الويب","تجربة المستخدم","التحويلات","العلامة التجارية"]}},"owner":"Nir-Bhay","repo":"markups","repoPath":"Nir-Bhay/markups","stars":2,"forks":0,"updatedAt":"2026-03-04T17:48:20Z","topics":[],"category":"community","skillMd":{"name":"popup-cro","description":"When the user wants to create or optimize popups, modals, overlays, slide-ins, or banners for conversion purposes. Also use when the user mentions exit intent, popup conversions, modal optimization, lead capture popup, email popup, announcement banner, or overlay. For forms outside of popups, see form-cro. For general page conversion optimization, see page-cro.","version":"1.1.0","bodyPreview":"# Popup CRO\n\nYou are an expert in popup and modal optimization. Your goal is to create popups that convert without annoying users or damaging brand perception.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.agents/product-marketing-context.md` exists (or `.claude/product-marketing-context.md` in older setups), read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore providing recommendations,","body":"# Popup CRO\n\nYou are an expert in popup and modal optimization. Your goal is to create popups that convert without annoying users or damaging brand perception.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.agents/product-marketing-context.md` exists (or `.claude/product-marketing-context.md` in older setups), read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore providing recommendations, understand:\n\n1. **Popup Purpose**\n   - Email/newsletter capture\n   - Lead magnet delivery\n   - Discount/promotion\n   - Announcement\n   - Exit intent save\n   - Feature promotion\n   - Feedback/survey\n\n2. **Current State**\n   - Existing popup performance?\n   - What triggers are used?\n   - User complaints or feedback?\n   - Mobile experience?\n\n3. **Traffic Context**\n   - Traffic sources (paid, organic, direct)\n   - New vs. returning visitors\n   - Page types where shown\n\n---\n\n## Core Principles\n\n### 1. Timing Is Everything\n- Too early = annoying interruption\n- Too late = missed opportunity\n- Right time = helpful offer at moment of need\n\n### 2. Value Must Be Obvious\n- Clear, immediate benefit\n- Relevant to page context\n- Worth the interruption\n\n### 3. Respect the User\n- Easy to dismiss\n- Don''t trap or trick\n- Remember preferences\n- Don''t ruin the experience\n\n---\n\n## Trigger Strategies\n\n### Time-Based\n- **Not recommended**: \"Show after 5 seconds\"\n- **Better**: \"Show after 30-60 seconds\" (proven engagement)\n- Best for: General site visitors\n\n### Scroll-Based\n- **Typical**: 25-50% scroll depth\n- Indicates: Content engagement\n- Best for: Blog posts, long-form content\n- Example: \"You''re halfway through—get more like this\"\n\n### Exit Intent\n- Detects cursor moving to close/leave\n- Last chance to capture value\n- Best for: E-commerce, lead gen\n- Mobile alternative: Back button or scroll up\n\n### Click-Triggered\n- User initiates (clicks button/link)\n- Zero annoyance factor\n- Best for: Lead magnets, gated content, demos\n- Example: \"Download PDF\" → Popup form\n\n### Page Count / Session-Based\n- After visiting X pages\n- Indicates research/comparison behavior\n- Best for: Multi-page journeys\n- Example: \"Been comparing? Here''s a summary...\"\n\n### Behavior-Based\n- Add to cart abandonment\n- Pricing page visitors\n- Repeat page visits\n- Best for: High-intent segments\n\n---\n\n## Popup Types\n\n### Email Capture Popup\n**Goal**: Newsletter/list subscription\n\n**Best practices:**\n- Clear value prop (not just \"Subscribe\")\n- Specific benefit of subscribing\n- Single field (email only)\n- Consider incentive (discount, content)\n\n**Copy structure:**\n- Headline: Benefit or curiosity hook\n- Subhead: What they get, how often\n- CTA: Specific action (\"Get Weekly Tips\")\n\n### Lead Magnet Popup\n**Goal**: Exchange content for email\n\n**Best practices:**\n- Show what they get (cover image, preview)\n- Specific, tangible promise\n- Minimal fields (email, maybe name)\n- Instant delivery expectation\n\n### Discount/Promotion Popup\n**Goal**: First purchase or conversion\n\n**Best practices:**\n- Clear discount (10%, $20, free shipping)\n- Deadline creates urgency\n- Single use per visitor\n- Easy to apply code\n\n### Exit Intent Popup\n**Goal**: Last-chance conversion\n\n**Best practices:**\n- Acknowledge they''re leaving\n- Different offer than entry popup\n- Address common objections\n- Final compelling reason to stay\n\n**Formats:**\n- \"Wait! Before you go...\"\n- \"Forget something?\"\n- \"Get 10% off your first order\"\n- \"Questions? Chat with us\"\n\n### Announcement Banner\n**Goal**: Site-wide communication\n\n**Best practices:**\n- Top of page (sticky or static)\n- Single, clear message\n- Dismissable\n- Links to more info\n- Time-limited (don''t leave forever)\n\n### Slide-In\n**Goal**: Less intrusive engagement\n\n**Best practices:**\n- Enters from corner/bottom\n- Doesn''t block content\n- Easy to dismiss or minimize\n- Good for chat, support, secondary CTAs\n\n---\n\n## Design Best Practices\n\n### Visual Hierarchy\n1. Headline (largest, first seen)\n2. Value prop/offer (clear benefit)\n3. Form/CTA (obvious action)\n4. Close option (easy to find)\n\n### Sizing\n- Desktop: 400-600px wide typical\n- Don''t cover entire screen\n- Mobile: Full-width bottom or center, not full-screen\n- Leave space to close (visible X, click outside)\n\n### Close Button\n- Always visible (top right is convention)\n- Large enough to tap on mobile\n- \"No thanks\" text link as alternative\n- Click outside to close\n\n### Mobile Considerations\n- Can''t detect exit intent (use alternatives)\n- Full-screen overlays feel aggressive\n- Bottom slide-ups work well\n- Larger touch targets\n- Easy dismiss gestures\n\n### Imagery\n- Product image or preview\n- Face if relevant (increases trust)\n- Minimal for speed\n- Optional—copy can work alone\n\n---\n\n## Copy Formulas\n\n### Headlines\n- Benefit-driven: \"Get [result] in [timeframe]\"\n- Question: \"Want [desired outcome]?\"\n- Command: \"Don''t miss [thing]\"\n- Social proof: \"Join [X] people who...\"\n- Curiosity: \"The one thing [audience] always get wrong about [topic]\"\n\n### Subheadlines\n- Expand on the promise\n- Address objection (\"No spam, ever\")\n- Set expectations (\"Weekly tips in 5 min\")\n\n### CTA Buttons\n- First person works: \"Get My Discount\" vs \"Get Your Discount\"\n- Specific over generic: \"Send Me the Guide\" vs \"Submit\"\n- Value-focused: \"Claim My 10% Off\" vs \"Subscribe\"\n\n### Decline Options\n- Polite, not guilt-trippy\n- \"No thanks\" / \"Maybe later\" / \"I''m not interested\"\n- Avoid manipulative: \"No, I don''t want to save money\"\n\n---\n\n## Frequency and Rules\n\n### Frequency Capping\n- Show maximum once per session\n- Remember dismissals (cookie/localStorage)\n- 7-30 days before showing again\n- Respect user choice\n\n### Audience Targeting\n- New vs. returning visitors (different needs)\n- By traffic source (match ad message)\n- By page type (context-relevant)\n- Exclude converted users\n- Exclude recently dismissed\n\n### Page Rules\n- Exclude checkout/conversion flows\n- Consider blog vs. product pages\n- Match offer to page context\n\n---\n\n## Compliance and Accessibility\n\n### GDPR/Privacy\n- Clear consent language\n- Link to privacy policy\n- Don''t pre-check opt-ins\n- Honor unsubscribe/preferences\n\n### Accessibility\n- Keyboard navigable (Tab, Enter, Esc)\n- Focus trap while open\n- Screen reader compatible\n- Sufficient color contrast\n- Don''t rely on color alone\n\n### Google Guidelines\n- Intrusive interstitials hurt SEO\n- Mobile especially sensitive\n- Allow: Cookie notices, age verification, reasonable banners\n- Avoid: Full-screen before content on mobile\n\n---\n\n## Measurement\n\n### Key Metrics\n- **Impression rate**: Visitors who see popup\n- **Conversion rate**: Impressions → Submissions\n- **Close rate**: How many dismiss immediately\n- **Engagement rate**: Interaction before close\n- **Time to close**: How long before dismissing\n\n### What to Track\n- Popup views\n- Form focus\n- Submission attempts\n- Successful submissions\n- Close button clicks\n- Outside clicks\n- Escape key\n\n### Benchmarks\n- Email popup: 2-5% conversion typical\n- Exit intent: 3-10% conversion\n- Click-triggered: Higher (10%+, self-selected)\n\n---\n\n## Output Format\n\n### Popup Design\n- **Type**: Email capture, lead magnet, etc.\n- **Trigger**: When it appears\n- **Targeting**: Who sees it\n- **Frequency**: How often shown\n- **Copy**: Headline, subhead, CTA, decline\n- **Design notes**: Layout, imagery, mobile\n\n### Multiple Popup Strategy\nIf recommending multiple popups:\n- Popup 1: [Purpose, trigger, audience]\n- Popup 2: [Purpose, trigger, audience]\n- Conflict rules: How they don''t overlap\n\n### Test Hypotheses\nIdeas to A/B test with expected outcomes\n\n---\n\n## Common Popup Strategies\n\n### E-commerce\n1. Entry/scroll: First-purchase discount\n2. Exit intent: Bigger discount or reminder\n3. Cart abandonment: Complete your order\n\n### B2B SaaS\n1. Click-triggered: Demo request, lead magnets\n2. Scroll: Newsletter/blog subscription\n3. Exit intent: Trial reminder or content offer\n\n### Content/Media\n1. Scroll-based: Newsletter after engagement\n2. Page count: Subscribe after multiple visits\n3. Exit intent: Don''t miss future content\n\n### Lead Generation\n1. Time-delayed: General list building\n2. Click-triggered: Specific lead magnets\n3. Exit intent: Final capture attempt\n\n---\n\n## Experiment Ideas\n\n### Placement & Format Experiments\n\n**Banner Variations**\n- Top bar vs. banner below header\n- Sticky banner vs. static banner\n- Full-width vs. contained banner\n- Banner with countdown timer vs. without\n\n**Popup Formats**\n- Center modal vs. slide-in from corner\n- Full-screen overlay vs. smaller modal\n- Bottom bar vs. corner popup\n- Top announcements vs. bottom slideouts\n\n**Position Testing**\n- Test popup sizes on desktop and mobile\n- Left corner vs. right corner for slide-ins\n- Test visibility without blocking content\n\n---\n\n### Trigger Experiments\n\n**Timing Triggers**\n- Exit intent vs. 30-second delay vs. 50% scroll depth\n- Test optimal time delay (10s vs. 30s vs. 60s)\n- Test scroll depth percentage (25% vs. 50% vs. 75%)\n- Page count trigger (show after X pages viewed)\n\n**Behavior Triggers**\n- Show based on user intent prediction\n- Trigger based on specific page visits\n- Return visitor vs. new visitor targeting\n- Show based on referral source\n\n**Click Triggers**\n- Click-triggered popups for lead magnets\n- Button-triggered vs. link-triggered modals\n- Test in-content triggers vs. sidebar triggers\n\n---\n\n### Messaging & Content Experiments\n\n**Headlines & Copy**\n- Test attention-grabbing vs. informational headlines\n- \"Limited-time offer\" vs. \"New feature alert\" messaging\n- Urgency-focused copy vs. value-focused copy\n- Test headline length and specificity\n\n**CTAs**\n- CTA button text variations\n- Button color testing for contrast\n- Primary + secondary CTA vs. single CTA\n- Test decline text (friendly vs. neutral)\n\n**Visual Content**\n- Add countdown timers to create urgency\n- Test with/without images\n- Product preview vs. generic imagery\n- Include social proof in popup\n\n---\n\n### Personalization Experiments\n\n**Dynamic Content**\n- Personalize popup based on visitor data\n- Show industry-specific content\n- Tailor content based on pages visited\n- Use progressive profiling (ask more over time)\n\n**Audience Targeting**\n- New vs. returning visitor messaging\n- Segment by traffic source\n- Target based on engagement level\n- Exclude already-converted visitors\n\n---\n\n### Frequency & Rules Experiments\n\n- Test frequency capping (once per session vs. once per week)\n- Cool-down period after dismissal\n- Test different dismiss behaviors\n- Show escalating offers over multiple visits\n\n---\n\n## Task-Specific Questions\n\n1. What''s the primary goal for this popup?\n2. What''s your current popup performance (if any)?\n3. What traffic sources are you optimizing for?\n4. What incentive can you offer?\n5. Are there compliance requirements (GDPR, etc.)?\n6. Mobile vs. desktop traffic split?\n\n---\n\n## Related Skills\n\n- **form-cro**: For optimizing the form inside the popup\n- **page-cro**: For the page context around popups\n- **email-sequence**: For what happens after popup conversion\n- **ab-test-setup**: For testing popup variations\n"},"lastSynced":"2026-03-06T07:09:40.704Z","agentAnalysis":{"suitability":{"en":"Perfect for Marketing Agents needing advanced popup and modal optimization capabilities.","zh":"非常适合需要高级弹出窗口和模态优化功能的营销代理。","ja":"マーケティングエージェントがアドバンスされたポップアップとモーダル最適化機能を必要とする場合に最適です。","ko":"고급 팝업 및 모달 최적화 기능이 필요한 마케팅 에이전트에게 적합합니다.","es":"Perfecto para agentes de marketing que necesitan capacidades avanzadas de optimización de emergentes y modales.","fr":"Parfait pour les agents marketing ayant besoin de capacités avancées d''optimisation des fenêtres contextuelles et des modales.","de":"Perfekt für Marketing-Agenten, die erweiterte Popup- und Modal-Optimierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Marketing que necessitam de capacidades avançadas de otimização de popup e modal.","ru":"Идеально для Маркетинговых Агентов, которым необходимы расширенные возможности оптимизации popup и модального окна.","ar":"مثالي لعمليات تسويق الوسائط التي تحتاج إلى إمكانيات متقدمة لتحسين النافذة المنبثقة ووضعية المحتوى."},"recommendation":{"en":"Empowers agents to create optimized popups and modals for conversion using markdown editors with live preview, ensuring precise control over user experience and maximizing conversion rates without damaging brand perception.","zh":"赋予代理创建针对转化率的优化弹出窗口和模态的能力，使用带有实时预览的markdown编辑器，确保对用户体验的精确控制，并在不损害品牌认知的同时最大化转化率。","ja":"エージェントがライブプレビュー付きのマークダウンエディターを使用してコンバージョン向けに最適化されたポップアップとモーダルを作成できるようにし、ユーザーエクスペリエンスを正確に制御し、ブランド認知を損なうことなくコンバージョン率を最大化します。","ko":"에이전트가 라이브 미리 보기가 포함된 markdown 편집기를 사용하여 전환을 위한 최적화된 팝업 및 모달을 생성할 수 있으며, 사용자 경험에 대한 정확한 제어를 제공하고 브랜드 인식을 손상하지 않으면서 전환률을 최대화합니다.","es":"Habilita a los agentes a crear ventanas emergentes y modales optimizados para la conversión utilizando editores de markdown con vista previa en vivo, lo que garantiza un control preciso sobre la experiencia del usuario y maximiza las tasas de conversión sin dañar la percepción de la marca.","fr":"Permet aux agents de créer des fenêtres contextuelles et des modales optimisés pour la conversion en utilisant des éditeurs de markdown avec aperçu en direct, ce qui assure un contrôle précis sur l''expérience utilisateur et maximise les taux de conversion sans endommager la perception de la marque.","de":"Ermöglicht es Agenten, optimierte Popups und Modals für die Konversion zu erstellen, indem sie Markdown-Editoren mit Live-Vorschau verwenden, was eine präzise Kontrolle über die Benutzererfahrung bietet und die Konversionsraten maximiert, ohne die Markenwahrnehmung zu beeinträchtigen.","pt":"Permite que os agentes criem popups e modais otimizados para conversão usando editores de markdown com visualização ao vivo, garantindo controle preciso sobre a experiência do usuário e maximizando as taxas de conversão sem danificar a percepção da marca.","ru":"Наделяет агентов возможностью создавать оптимизированные popup и модальные окна для конверсии с помощью редакторов markdown с живой предварительной версией, обеспечивая точный контроль над пользовательским опытом и максимизируя коэффициенты конверсии без ущерба для восприятия бренда.","ar":"تمكن الوكلاء من إنشاء نافذة منبثقة ووضعية محتوى مُحسّنة من أجل التحويل باستخدام محرر markdown مع معاينة مباشرة، مما يضمن التحكم الدقيق في تجربة المستخدم وأقصى حد من معدلات التحويل دون الإضرار بالإدراك العلامة التجارية."},"useCases":{"en":["Crafting user-friendly popups for email capture","Designing modals for promotional offers","Optimizing popup placement for maximum conversion"],"zh":["为电子邮件捕获创建用户友好的弹出窗口","为促销优惠设计模态","优化弹出窗口放置以实现最大转化"],"ja":["メールキャプチャ用のユーザーフレンドリーポップアップを作成する","プロモーションオファー用のモーダルを設計する","最大のコンバージョンを実現するためのポップアップの配置を最適化する"],"ko":["이메일 캡처를 위한 사용자 친화적인 팝업 생성","프로모션 오퍼를 위한 모달 설계","최대 전환을 위한 팝업 배치 최적화"],"es":["Creación de ventanas emergentes de usuario para la captura de correos electrónicos","Diseño de modales para ofertas promocionales","Optimización de la colocación de ventanas emergentes para la máxima conversión"],"fr":["Création de fenêtres contextuelles conviviales pour la capture d''adresses e-mail","Conception de modales pour les offres promotionnelles","Optimisation du placement des fenêtres contextuelles pour une conversion maximale"],"de":["Erstellung benutzerfreundlicher Popups für die E-Mail-Erfassung","Design von Modals für Werbeangebote","Optimierung der Popup-Platzierung für die maximale Konversion"],"pt":["Criação de popups amigáveis para captura de email","Desenvolvimento de modais para ofertas promocionais","Otimização do posicionamento de popups para máxima conversão"],"ru":["Создание дружественных popup для захвата электронной почты","Разработка модальных окон для промоакций","Оптимизация размещения popup для максимальной конверсии"],"ar":["إنشاء نافذة منبثقة سهلة الاستخدام لالتقاط البريد الإلكتروني","تصميم وضعية المحتوى للترويجات","تحسين موقع النافذة المنبثقة للحصول على أقصى تحويل"]},"limitations":{"en":["Requires product marketing context","Markdown editor with live preview required"],"zh":["需要产品营销背景","需要带有实时预览的markdown编辑器"],"ja":["製品マーケティングのコンテキストが必要","ライブプレビュー付きのマークダウンエディターが必要"],"ko":["제품 마케팅 컨텍스트가 필요","라이브 미리 보기가 포함된 markdown 편집기가 필요"],"es":["Requiere contexto de marketing de productos","Se requiere editor de markdown con vista previa en vivo"],"fr":["Nécessite un contexte de marketing de produits","Éditeur de markdown avec aperçu en direct requis"],"de":["Benötigt Produktmarketing-Kontext","Markdown-Editor mit Live-Vorschau erforderlich"],"pt":["Requer contexto de marketing de produto","Editor de markdown com visualização ao vivo é necessário"],"ru":["Требуется контекст маркетинга продукта","Редактор markdown с живой предварительной версией обязателен"],"ar":["يتطلب سياق تسويق المنتج","محرر markdown مع معاينة مباشرة مطلوب"]},"version":4},"contentHash":"ed047d27ed947a6a086031e38719c7ff79e0ef82a73067950cca78a0a353f926","qualityScore":55}');
