INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nir-Bhay/markups/popup-cro', 'popup-cro', 'Nir-Bhay', 'markups', 'community', 'popup-cro Nir-Bhay markups community The popup-cro skill enables experts to create optimized popups and modals for conversion without annoying users. It provides a markdown editor with live preview for precise control. popup-cro 是一种专门用于弹窗和模态窗口优化的技术，通过 markdown 编辑器和实时预览功能，帮助开发者创建高转化率的弹窗 popup-cro は、ポップアップとモーダルウィンドウを最適化するために設計された技術です。Markdown エディターとリアルタイムプレビュー機能を備えています popup-cro는 팝업창과 모달 창을 최적화하기 위한 기술로, 마크다운 편집기와 실시간 미리보기 기능을 통해 개발자가 높은 전환률의 팝업창을 생성할 수 있습니다 El popup-cro es una habilidad que permite crear popups personalizados con una vista previa en vivo, utilizando tecnologías como markdown editors. Le popup-cro est une compétence qui permet de créer des popups personnalisés avec une prévisualisation en direct, en utilisant des technologies comme les éditeurs de markdown. Das popup-cro ist eine Fähigkeit, die die Erstellung von benutzerdefinierten Popups mit Live-Vorschau ermöglicht, unter Verwendung von Technologien wie Markdown-Editoren. O popup-cro é uma ferramenta de otimização de popups que utiliza markdown editor com pré-visualização ao vivo para melhorar a experiência do usuário. popup-cro - это инструмент оптимизации попапов, который использует редактор markdown с живой предварительной версией для улучшения пользовательского опыта. popup-cro هو أداة لتحسين نافذة المنبثقة التي تستخدم محرر markdown مع معاينة مباشرة لتحسين تجربة المستخدم. how to use popup-cro popup-cro alternative popup-cro setup guide what is popup-cro popup-cro vs competitors popup-cro install expert popup optimization modal refinement techniques conversion-boosting popups popup-cro 弹窗优化 模态窗口优化 markdown 编辑器 实时预览 转化率提高 AIエージェント 技术开发 Utilizes markdown editor for precise popup content control Provides live preview for instant feedback on design changes Checks for product marketing context via .agents/product-marketing-context.md Supports reading of .claude/product-marketing-context.md in older setups Enables creation of popups that convert without damaging brand perception popup-cro is a specialized skill for optimizing popup and modal interactions to enhance conversion rates while preserving brand integrity');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lobehub/lobehub/chat-sdk', 'community', 'lobehub', 'lobehub', 'lobehub/lobehub', 'chat-sdk', 72987, 14715, 55, '2026-03-04T01:42:12Z', '2026-03-06T06:24:04.521Z', '3f877134b4e042433542589620011fe41dd9efefa6eb089089fb8f304f5415ac', '{"id":"lobehub/lobehub/chat-sdk","name":"chat-sdk","description":{"en":"The chat-sdk is a unified TypeScript SDK for building chat bots across Slack, Teams, Google Chat, Discord, GitHub, and Linear, enabling developers to write bot logic once and deploy everywhere.","zh":"Chat SDK是一个统一的TypeScript SDK，用于构建跨多个平台的聊天机器人。它允许您一次编写代码，处处部署。","ja":"Chat SDKは、複数のプラットフォームでチャットボットを構築するための統一されたTypeScript SDKです。コードを1回書くだけで、どこでもデプロイできます。","ko":"Chat SDK는 여러 플랫폼에서 챗봇을 구축하기 위한統一された TypeScript SDK입니다. 코드를 한 번 작성하면 어디서나 배포할 수 있습니다.","es":"chat-sdk es un kit de desarrollo unificado en TypeScript para crear bots de chat en varias plataformas. Escribe la lógica del bot una vez y despliégalo en todas partes.","fr":"chat-sdk est un kit de développement unifié en TypeScript pour créer des bots de chat sur plusieurs plateformes. Écrivez la logique du bot une fois et déployez-le partout.","de":"chat-sdk ist ein einheitliches TypeScript-Kit für die Erstellung von Chat-Bots auf mehreren Plattformen. Schreiben Sie die Bot-Logik einmal und deployen Sie sie überall.","pt":"O Chat SDK é uma biblioteca TypeScript unificada para construir bots de chat em várias plataformas. Ele permite escrever lógica de bot uma vez e implantá-la em todas as plataformas suportadas.","ru":"Чат SDK — это унифицированная библиотека TypeScript для создания чат-ботов на нескольких платформах. Он позволяет написать логику бота один раз и развернуть ее на всех поддерживаемых платформах для ИИ Агентов","ar":"kit المحادثة هو مكتبة TypeScript موحدة لبناء بوتات المحادثة على منصات متعددة. يسمح بكتابة منطق البوت مرة واحدة وتنفيذه على جميع المنصات المدعومة"},"seo":{"title":{"en":"chat-sdk: Unified TypeScript SDK for AI Agents | AI Agent...","zh":"聊天机器人SDK集成指南 - Chat SDK","ja":"チャットSDKのセットアップガイド - AIエージェント開発","ko":"챗봇 SDK 설정 가이드 - Chat SDK","es":"Guía de configuración de chat-sdk para agentes de IA","fr":"Guide d''installation de chat-sdk pour les agents d''IA","de":"Einrichtungsanleitung für chat-sdk für KI-Agents","pt":"Guia de Configuração do Chat SDK para Desenvolvedores","ru":"Настройка Чат SDK: Руководство для Разработчиков ИИ Агентов","ar":"دليل إعداد-kit المحادثة للبرمجيين"},"description":{"en":"Discover how to build chat bots across multiple platforms with chat-sdk. Learn how to write bot logic once and deploy everywhere, and get started with our se...","zh":"使用Chat SDK构建跨Slack、Teams、Google Chat、Discord、GitHub和Linear的聊天机器人。一次编写，处处部署。","ja":"Chat SDKを使用して、Slack、Teams、Google Chat、Discord、GitHub、Linearなどのチャットボットを構築する方法を学びます。","ko":"Chat SDK를 사용하여 Slack, Teams, Google Chat, Discord, GitHub 및 Linear를 위한 챗봇을 구축하는 방법을 알아보세요.","es":"Aprende a configurar chat-sdk para crear bots de chat en múltiples plataformas como Slack, Teams y Google Chat","fr":"Découvrez comment configurer chat-sdk pour créer des bots de chat sur plusieurs plateformes comme Slack, Teams et Google Chat","de":"Erfahren Sie, wie Sie chat-sdk konfigurieren, um Chat-Bots auf mehreren Plattformen wie Slack, Teams und Google Chat zu erstellen","pt":"Aprenda a configurar o Chat SDK para construir bots de chat em várias plataformas, incluindo Slack, Teams e Google Chat","ru":"Узнайте, как настроить Чат SDK для создания чат-ботов на нескольких платформах, включая Slack, Teams и Google Chat для ИИ Агентов","ar":"تعلم كيفية إعداد kit المحادثة لبناء بوتات المحادثة على منصات متعددة، بما في ذلك Slack و Teams و Google Chat"},"definition":{"en":"chat-sdk is a unified TypeScript SDK for building chat bots across multiple platforms, providing a single interface for deploying bot logic.","zh":"Chat SDK是一种用于构建跨多个平台的聊天机器人的软件开发工具包。","ja":"Chat SDKは、複数のプラットフォームでチャットボットを構築するためのソフトウェア開発キットです。","ko":"Chat SDK는 여러 플랫폼에서 챗봇을 구축하기 위한 소프트웨어 개발 키트입니다.","es":"chat-sdk es un kit de desarrollo de software que permite crear bots de chat en varias plataformas","fr":"chat-sdk est un kit de développement de logiciels qui permet de créer des bots de chat sur plusieurs plateformes","de":"chat-sdk ist ein Software-Development-Kit, das die Erstellung von Chat-Bots auf mehreren Plattformen ermöglicht","pt":"O Chat SDK é uma biblioteca de software que permite construir bots de chat em várias plataformas","ru":"Чат SDK — это библиотека программного обеспечения, которая позволяет создавать чат-ботов на нескольких платформах для ИИ Агентов","ar":"kit المحادثة هو مكتبة برمجية تسمح ببناء بوتات المحادثة على منصات متعددة"},"features":{"en":["Provides a unified interface for building chat bots across Slack, Teams, Google Chat, Discord, GitHub, and Linear","Allows developers to write bot logic once and deploy everywhere","Includes full documentation in MDX files and TypeScript source types","Supports deployment on multiple platforms using a single codebase","Enables effortless agent team design and multi-agent collaboration"],"zh":["支持Slack、Teams、Google Chat、Discord、GitHub和Linear等多个平台","统一的TypeScript SDK","一次编写，处处部署","提供全面的文档和TypeScript源代码类型"],"ja":["Slack、Teams、Google Chat、Discord、GitHub、Linearなどの複数のプラットフォームをサポート","統一されたTypeScript SDK","コードを1回書くだけで、どこでもデプロイ","包括的なドキュメントとTypeScriptソースコードタイプを提供"],"ko":["Slack, Teams, Google Chat, Discord, GitHub 및 Linear 등 여러 플랫폼 지원","統一された TypeScript SDK","코드를 한 번 작성하면 어디서나 배포","전체적인 문서 및 TypeScript 소스 코드 유형 제공"],"es":["Kit de desarrollo unificado en TypeScript","Compatibilidad con múltiples plataformas como Slack, Teams y Google Chat","Escribe la lógica del bot una vez y despliégalo en todas partes","Documentación completa en MDX y tipos de fuente de TypeScript","Soporte para colaboración de agentes y diseño de equipos de agentes"],"fr":["Kit de développement unifié en TypeScript","Compatibilité avec plusieurs plateformes comme Slack, Teams et Google Chat","Écrivez la logique du bot une fois et déployez-le partout","Documentation complète en MDX et types de source de TypeScript","Prise en charge de la collaboration d''agents et de la conception d''équipes d''agents"],"de":["Einheitliches TypeScript-Kit","Kompatibilität mit mehreren Plattformen wie Slack, Teams und Google Chat","Schreiben Sie die Bot-Logik einmal und deployen Sie sie überall","Vollständige Dokumentation in MDX und TypeScript-Quelltypen","Unterstützung für Agenten-Kollaboration und Agenten-Team-Design"],"pt":["Suporte a várias plataformas, incluindo Slack, Teams, Google Chat, Discord, GitHub e Linear","Escrita de lógica de bot uma vez e implantação em todas as plataformas suportadas","Tipos de fonte TypeScript e documentação completa em MDX","Suporte a colaboração multi-agente e design de equipe de agentes","Integração com conhecimento base e MCP"],"ru":["Поддержка нескольких платформ, включая Slack, Teams, Google Chat, Discord, GitHub и Linear для ИИ Агентов","Написание логики бота один раз и развертывание на всех поддерживаемых платформах","Источники TypeScript и полная документация в MDX","Поддержка многоАгентной коллаборации и设计 команды агентов","Интеграция с базой знаний и MCP"],"ar":["دعم منصات متعددة، بما في ذلك Slack و Teams و Google Chat و Discord و GitHub و Linear","كتابة منطق البوت مرة واحدة وتنفيذه على جميع المنصات المدعومة","أنواع مصدر TypeScript ووثائق كاملة في MDX","دعم التعاون المتعدد للوكلاء وتصميم فريق الوكلاء","التكامل مع قاعدة المعرفة و MCP"]},"keywords":{"en":["how to use chat-sdk","what is chat-sdk","chat-sdk alternative","chat-sdk vs openai","chat-sdk install","chat-sdk setup guide","typescript sdk for chat bots","multi-platform chat bot development","ai agent development with chat-sdk"],"zh":["Chat SDK","聊天机器人","TypeScript","Slack","Teams","Google Chat","Discord","GitHub","Linear","AIエージェント"],"ja":["Chat SDK","チャットボット","TypeScript","Slack","Teams","Google Chat","Discord","GitHub","Linear","AIエージェント"],"ko":["Chat SDK","챗봇","TypeScript","Slack","Teams","Google Chat","Discord","GitHub","Linear","AI 에이전트"],"es":["chat-sdk","agentes de IA","bots de chat","desarrollo de software","TypeScript","Slack","Teams","Google Chat","colaboración de agentes","diseño de equipos de agentes"],"fr":["chat-sdk","agents d''IA","bots de chat","développement de logiciels","TypeScript","Slack","Teams","Google Chat","collaboration d''agents","conception d''équipes d''agents"],"de":["chat-sdk","KI-Agents","Chat-Bots","Software-Entwicklung","TypeScript","Slack","Teams","Google Chat","Agenten-Kollaboration","Agenten-Team-Design"],"pt":["chat sdk","desenvolvimento de bots de chat","plataformas de chat","typescript","slack","teams","google chat","discord","github","linear"],"ru":["чат sdk","разработка чат-ботов","платформы чата","typescript","slack","teams","google chat","discord","github","linear","ИИ Агенты"],"ar":["kit المحادثة","تطوير بوتات المحادثة","منصات المحادثة","typescript","slack","teams","google chat","discord","github","linear","وكلاء الذكاء الاصطناعي"]}},"owner":"lobehub","repo":"lobehub","repoPath":"lobehub/lobehub","stars":72987,"forks":14715,"updatedAt":"2026-03-04T01:42:12Z","topics":["agent","agent-collaboration","agent-harness","ai","chatgpt","claude","deepseek","gemini","gpt","knowledge-base","mcp","openai"],"category":"community","skillMd":{"name":"chat-sdk","description":">","bodyPreview":"# Chat SDK\n\nUnified TypeScript SDK for building chat bots across Slack, Teams, Google Chat, Discord, GitHub, and Linear. Write bot logic once, deploy everywhere.\n\n## Critical: Read the bundled docs\n\nThe `chat` package ships with full documentation in `node_modules/chat/docs/` and TypeScript source types. **Always read these before writing code:**\n\n```\nnode_modules/chat/docs/           # Full documentation (MDX files)\nnode_modules/chat/dist/           # Built types (.d.ts files)\n```\n\nKey docs to","body":"# Chat SDK\n\nUnified TypeScript SDK for building chat bots across Slack, Teams, Google Chat, Discord, GitHub, and Linear. Write bot logic once, deploy everywhere.\n\n## Critical: Read the bundled docs\n\nThe `chat` package ships with full documentation in `node_modules/chat/docs/` and TypeScript source types. **Always read these before writing code:**\n\n```\nnode_modules/chat/docs/           # Full documentation (MDX files)\nnode_modules/chat/dist/           # Built types (.d.ts files)\n```\n\nKey docs to read based on task:\n\n- `docs/getting-started.mdx` — setup guides\n- `docs/usage.mdx` — event handlers, threads, messages, channels\n- `docs/streaming.mdx` — AI streaming with AI SDK\n- `docs/cards.mdx` — JSX interactive cards\n- `docs/actions.mdx` — button/dropdown handlers\n- `docs/modals.mdx` — form dialogs (Slack only)\n- `docs/adapters/*.mdx` — platform-specific adapter setup\n- `docs/state/*.mdx` — state adapter config (Redis, ioredis, memory)\n\nAlso read the TypeScript types from `node_modules/chat/dist/` to understand the full API surface.\n\n## Quick start\n\n```typescript\nimport { Chat } from ''chat'';\nimport { createSlackAdapter } from ''@chat-adapter/slack'';\nimport { createRedisState } from ''@chat-adapter/state-redis'';\n\nconst bot = new Chat({\n  userName: ''mybot'',\n  adapters: {\n    slack: createSlackAdapter({\n      botToken: process.env.SLACK_BOT_TOKEN!,\n      signingSecret: process.env.SLACK_SIGNING_SECRET!,\n    }),\n  },\n  state: createRedisState({ url: process.env.REDIS_URL! }),\n});\n\nbot.onNewMention(async (thread) => {\n  await thread.subscribe();\n  await thread.post(\"Hello! I''m listening to this thread.\");\n});\n\nbot.onSubscribedMessage(async (thread, message) => {\n  await thread.post(`You said: ${message.text}`);\n});\n```\n\n## Core concepts\n\n- **Chat** — main entry point, coordinates adapters and routes events\n- **Adapters** — platform-specific (Slack, Teams, GChat, Discord, GitHub, Linear)\n- **State** — pluggable persistence (Redis for prod, memory for dev)\n- **Thread** — conversation thread with `post()`, `subscribe()`, `startTyping()`\n- **Message** — normalized format with `text`, `formatted` (mdast AST), `raw`\n- **Channel** — container for threads, supports listing and posting\n\n## Event handlers\n\n| Handler                    | Trigger                                           |\n| -------------------------- | ------------------------------------------------- |\n| `onNewMention`             | Bot @-mentioned in unsubscribed thread            |\n| `onSubscribedMessage`      | Any message in subscribed thread                  |\n| `onNewMessage(regex)`      | Messages matching pattern in unsubscribed threads |\n| `onSlashCommand(\"/cmd\")`   | Slash command invocations                         |\n| `onReaction(emojis)`       | Emoji reactions added/removed                     |\n| `onAction(actionId)`       | Button clicks and dropdown selections             |\n| `onAssistantThreadStarted` | Slack Assistants API thread opened                |\n| `onAppHomeOpened`          | Slack App Home tab opened                         |\n\n## Streaming\n\nPass any `AsyncIterable<string>` to `thread.post()`. Works with AI SDK''s `textStream`:\n\n```typescript\nimport { ToolLoopAgent } from ''ai'';\nconst agent = new ToolLoopAgent({ model: ''anthropic/claude-4.5-sonnet'' });\n\nbot.onNewMention(async (thread, message) => {\n  const result = await agent.stream({ prompt: message.text });\n  await thread.post(result.textStream);\n});\n```\n\n## Cards (JSX)\n\nSet `jsxImportSource: \"chat\"` in tsconfig. Components: `Card`, `CardText`, `Button`, `Actions`, `Fields`, `Field`, `Select`, `SelectOption`, `Image`, `Divider`, `LinkButton`, `Section`, `RadioSelect`.\n\n```tsx\nawait thread.post(\n  <Card title=\"Order #1234\">\n    <CardText>Your order has been received!</CardText>\n    <Actions>\n      <Button id=\"approve\" style=\"primary\">\n        Approve\n      </Button>\n      <Button id=\"reject\" style=\"danger\">\n        Reject\n      </Button>\n    </Actions>\n  </Card>,\n);\n```\n\n## Packages\n\n| Package                       | Purpose                       |\n| ----------------------------- | ----------------------------- |\n| `chat`                        | Core SDK                      |\n| `@chat-adapter/slack`         | Slack                         |\n| `@chat-adapter/teams`         | Microsoft Teams               |\n| `@chat-adapter/gchat`         | Google Chat                   |\n| `@chat-adapter/discord`       | Discord                       |\n| `@chat-adapter/github`        | GitHub Issues                 |\n| `@chat-adapter/linear`        | Linear Issues                 |\n| `@chat-adapter/state-redis`   | Redis state (production)      |\n| `@chat-adapter/state-ioredis` | ioredis state (alternative)   |\n| `@chat-adapter/state-memory`  | In-memory state (development) |\n\n## Changesets (Release Flow)\n\nThis monorepo uses [Changesets](https://github.com/changesets/changesets) for versioning and changelogs. Every PR that changes a package''s behavior must include a changeset.\n\n```bash\npnpm changeset\n# → select affected package(s) (e.g. @chat-adapter/slack, chat)\n# → choose bump type: patch (fixes), minor (features), major (breaking)\n# → write a short summary for the CHANGELOG\n```\n\nThis creates a file in `.changeset/` — commit it with the PR. When merged to `main`, the Changesets GitHub Action opens a \"Version Packages\" PR to bump versions and update CHANGELOGs. Merging that PR publishes to npm.\n\n## Webhook setup\n\nEach adapter exposes a webhook handler via `bot.webhooks.{platform}`. Wire these to your HTTP framework''s routes (e.g. Next.js API routes, Hono, Express).\n"},"lastSynced":"2026-03-06T06:24:04.521Z","agentAnalysis":{"suitability":{"en":"Perfect for Multichannel Chat Agents needing unified bot logic deployment across Slack, Teams, Google Chat, Discord, GitHub, and Linear.","zh":"非常适合需要在Slack、Teams、Google Chat、Discord、GitHub和Linear上统一部署多渠道聊天机器人逻辑的场景。","ja":"Slack、Teams、Google Chat、Discord、GitHub、Linearで統一されたボットロジックをデプロイする必要があるマルチチャネルチャットエージェントに最適です。","ko":"Slack, Teams, Google Chat, Discord, GitHub 및 Linear에서 통일된 봇 로직을 배포해야 하는 멀티 채널 채팅 에이전트에 적합합니다.","es":"Perfecto para Agentes de Chat Multicanal que necesitan una implementación de lógica de bot unificada en Slack, Teams, Google Chat, Discord, GitHub y Linear.","fr":"Idéal pour les Agents de Chat Multicanal ayant besoin d''un déploiement de logique de bot unifié sur Slack, Teams, Google Chat, Discord, GitHub et Linear.","de":"Perfekt für Multichannel-Chat-Agenten, die eine einheitliche Bot-Logik-Bereitstellung über Slack, Teams, Google Chat, Discord, GitHub und Linear benötigen.","pt":"Perfeito para Agentes de Chat Multicanal que precisam de uma lógica de bot unificada implantada em Slack, Teams, Google Chat, Discord, GitHub e Linear.","ru":"Идеально подходит для многоканальных агентов чата, которым необходима унифицированная логика бота, развернутая в Slack, Teams, Google Chat, Discord, GitHub и Linear.","ar":"مثالي للوكلاء المحادثة المتعددة القنوات الذين يحتاجون إلى منطق بوت موحد يُستخدم عبر Slack و Teams و Google Chat و Discord و GitHub و Linear."},"recommendation":{"en":"Empowers agents to write bot logic once and deploy everywhere using the unified TypeScript SDK, leveraging MDX documentation and TypeScript source types for seamless integration with platforms like Slack, Teams, and Google Chat via protocols and libraries.","zh":"通过统一的TypeScript SDK，利用MDX文档和TypeScript源类型，使得与Slack、Teams、Google Chat等平台的集成更加顺畅，能够让代理写一次机器人逻辑并在所有地方部署。","ja":"統一されたTypeScript SDKを使用して、MDXドキュメントとTypeScriptソースタイプを活用し、Slack、Teams、Google Chatなどのプラットフォームとのシームレスな統合を可能にし、エージェントがボットロジックを1回書いてどこにでもデプロイできるようにします。","ko":"통일된 TypeScript SDK를 사용하여 MDX 문서 및 TypeScript 소스 유형을 활용하여 Slack, Teams, Google Chat 등의 플랫폼과 더 나은 통합을 가능하게 하며, 에이전트가 봇 로직을 한 번만 작성하고 모든 곳에 배포할 수 있도록 합니다.","es":"Habilita a los agentes a escribir la lógica del bot una sola vez y desplegarla en todas partes utilizando el SDK unificado de TypeScript, aprovechando la documentación MDX y los tipos de fuente de TypeScript para una integración sin problemas con plataformas como Slack, Teams y Google Chat a través de protocolos y bibliotecas.","fr":"Permet aux agents d''écrire la logique du bot une seule fois et de la déployer partout en utilisant le SDK TypeScript unifié, en exploitant la documentation MDX et les types de source TypeScript pour une intégration transparente avec des plateformes comme Slack, Teams et Google Chat via des protocoles et des bibliothèques.","de":"Ermöglicht es Agents, die Bot-Logik einmal zu schreiben und überall bereitzustellen, indem sie das einheitliche TypeScript-SDK verwenden, das MDX-Dokumentation und TypeScript-Quelltypen für eine nahtlose Integration mit Plattformen wie Slack, Teams und Google Chat über Protokolle und Bibliotheken nutzt.","pt":"Habilita os agentes a escreverem lógica de bot uma vez e implantá-la em todos os lugares usando o SDK unificado do TypeScript, aproveitando a documentação MDX e os tipos de origem do TypeScript para integração sem problemas com plataformas como Slack, Teams e Google Chat por meio de protocolos e bibliotecas.","ru":"Наделяет агентов возможностью писать логику бота один раз и развертывать ее везде с помощью унифицированного SDK TypeScript, используя документацию MDX и исходные типы TypeScript для бесшовной интеграции с платформами như Slack, Teams и Google Chat через протоколы и библиотеки.","ar":"تمكّن الوكلاء من كتابة منطق البوت مرة واحدة وتنفيذه في كل مكان باستخدام SDK TypeScript الموحد، واستخدام توثيق MDX وأنواع المصدر TypeScript لتكامل بدون مشاكل مع منصات مثل Slack و Teams و Google Chat من خلال البروتوكولات والمكتبات."},"useCases":{"en":["Deploying chatbots across multiple platforms","Building unified bot logic for Slack and Teams","Integrating chat functionality with GitHub and Discord"],"zh":["跨多个平台部署聊天机器人","为Slack和Teams构建统一的机器人逻辑","将聊天功能集成到GitHub和Discord"],"ja":["複数のプラットフォームにチャットボットをデプロイする","SlackとTeamsのための統一されたボットロジックを構築する","GitHubとDiscordにチャット機能を統合する"],"ko":["여러 플랫폼에 채팅 봇을 배포하는 것","Slack 및 Teams를 위한統一された 봇 로직을 구축하는 것","GitHub 및 Discord와 채팅 기능을 통합하는 것"],"es":["Implementar chatbots en varias plataformas","Crear una lógica de bot unificada para Slack y Teams","Integrar la funcionalidad de chat con GitHub y Discord"],"fr":["Déployer des chatbots sur plusieurs plateformes","Créer une logique de bot unifiée pour Slack et Teams","Intégrer la fonctionnalité de chat avec GitHub et Discord"],"de":["Chatbots über mehrere Plattformen bereitstellen","Eine einheitliche Bot-Logik für Slack und Teams erstellen","Chat-Funktionalität mit GitHub und Discord integrieren"],"pt":["Implantação de chatbots em várias plataformas","Construção de lógica de bot unificada para Slack e Teams","Integração de funcionalidade de chat com GitHub e Discord"],"ru":["Развертывание чат-ботов на нескольких платформах","Создание унифицированной логики бота для Slack и Teams","Интеграция функциональности чата с GitHub и Discord"],"ar":["تثبيت المحادثة البوتات عبر منصات متعددة","بناء منطق بوت موحد لبرامج Slack و Teams","دمج وظيفة المحادثة مع GitHub و Discord"]},"limitations":{"en":["Requires node_modules/chat/docs/ and TypeScript source types for full documentation","Limited to supported platforms: Slack, Teams, Google Chat, Discord, GitHub, and Linear"],"zh":["需要node_modules/chat/docs/和TypeScript源类型以获取完整文档","仅限支持的平台：Slack、Teams、Google Chat、Discord、GitHub和Linear"],"ja":["完全なドキュメントを取得するにはnode_modules/chat/docs/とTypeScriptソースタイプが必要","サポートされているプラットフォームのみ：Slack、Teams、Google Chat、Discord、GitHub、Linear"],"ko":["완전한 문서를 얻으려면 node_modules/chat/docs/ 및 TypeScript 소스 유형이 필요합니다.","지원되는 플랫폼만 해당: Slack, Teams, Google Chat, Discord, GitHub 및 Linear"],"es":["Requiere node_modules/chat/docs/ y tipos de fuente de TypeScript para la documentación completa","Limitado a plataformas compatibles: Slack, Teams, Google Chat, Discord, GitHub y Linear"],"fr":["Nécessite node_modules/chat/docs/ et des types de source TypeScript pour la documentation complète","Limité aux plateformes prises en charge : Slack, Teams, Google Chat, Discord, GitHub et Linear"],"de":["Benötigt node_modules/chat/docs/ und TypeScript-Quelltypen für die vollständige Dokumentation","Begrenzt auf unterstützte Plattformen: Slack, Teams, Google Chat, Discord, GitHub und Linear"],"pt":["Exige node_modules/chat/docs/ e tipos de origem do TypeScript para documentação completa","Limitado às plataformas suportadas: Slack, Teams, Google Chat, Discord, GitHub e Linear"],"ru":["Требует node_modules/chat/docs/ и исходных типов TypeScript для полной документации","Ограничен поддерживаемыми платформами: Slack, Teams, Google Chat, Discord, GitHub и Linear"],"ar":["يتطلب node_modules/chat/docs/ وأنواع المصدر TypeScript للتوثيق الكامل","محدود بالمنصات المدعومة: Slack و Teams و Google Chat و Discord و GitHub و Linear"]},"version":4},"contentHash":"3f877134b4e042433542589620011fe41dd9efefa6eb089089fb8f304f5415ac","qualityScore":55}');
