INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pytorch/pytorch/pr-review', 'pr-review', 'pytorch', 'pytorch', 'community', 'pr-review pytorch pytorch community PyTorch PR Review Skill 是一种用于检查 PyTorch 代码质量、测试覆盖、安全漏洞和向后兼容性的工具 PyTorch PR レビュー スキルは、PyTorch コードの品質、テストカバレッジ、セキュリティ脆弱性、バックワード互換性をチェックするツールです PyTorch PR 리뷰 스킬은 PyTorch 코드의 품질, 테스트 커버리지, 보안 취약성, 후방 호환성을 확인하는 도구입니다 Pr-review es una habilidad de revisión de solicitudes de extracción de PyTorch que se enfoca en la calidad del código y la seguridad Pr-review est une compétence de révision de demandes de tirage de PyTorch qui se concentre sur la qualité du code et la sécurité Pr-review ist eine Fähigkeit zur Überprüfung von Pull-Requests für PyTorch, die sich auf Code-Qualität und Sicherheit konzentriert O pr-review é uma ferramenta para revisar código PyTorch com foco em qualidade, cobertura de testes e segurança, utilizando tensors e redes neurais dinâmicas em Python com aceleração GPU Пр-review - это инструмент для проверки кода PyTorch с фокусом на качестве, покрытии тестов и безопасности, использующий тензоры и динамические нейронные сети на Python с ускорением GPU pr-review هو أداة لمراجعة كود PyTorch مع التركيز على الجودة وتغطية الاختبار والأمن، باستخدام تензورات وشبكات عصبونية ديناميكية في بايثون مع تسريع GPU Tensors and Dynamic neural networks in Python with strong GPU acceleration PyTorch PR Review AI エージェント 代码质量检查 测试覆盖 安全漏洞检查 向后兼容性 GPU 加速 Python 动态神经网络 Tensors and Dynamic neural networks in Python with strong GPU acceleration');
