INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agentuity/discord-help-agent/agentuity-cli-dev', 'agentuity-cli-dev', 'agentuity', 'discord-help-agent', 'community', 'agentuity-cli-dev agentuity discord-help-agent community The agentuity-cli-dev skill allows developers to build and run a development server, providing a seamless development experience. It benefits developers working with AI agents. Agentuity-CLI-Dev 是一个用于搭建本地开发服务器的命令行工具，支持自定义端口和本地模式 Agentuity-CLI-Dev は、ローカル開発サーバーを構築するためのコマンドラインツールで、カスタムポートとローカルモードをサポートしています Agentuity-CLI-Dev는 로컬 개발 서버를 구축하기 위한 명령줄 툴로 커스텀 포트와 로컬 모드를 지원합니다 Agentuity-cli-dev es una herramienta de línea de comandos para desarrolladores que permite compilar y ejecutar servidores de desarrollo Agentuity-cli-dev est un outil en ligne de commande pour les développeurs qui permet de compiler et d''exécuter des serveurs de développement Agentuity-cli-dev ist ein Kommandozeilen-Tool für Entwickler, mit dem Sie Entwicklungsserver kompilieren und ausführen können O Agentuity-CLI-Dev é uma ferramenta de linha de comando para desenvolvedores que permite construir e executar servidores de desenvolvimento de forma eficiente Agentuity-CLI-Dev — это командный инструмент для разработчиков, который позволяет строить и запускать серверы разработки эффективно Agentuity-CLI-Dev هو أداة سطر أوامر للاستخدام مع أدوات الذكاء الاصطناعي، مما يسمح بتشغيل خادم التطوير بفعالية how to use agentuity-cli-dev agentuity-cli-dev setup guide agentuity-cli-dev alternative agentuity-cli-dev vs cli tools agentuity-cli-dev install bunx command tutorial development server setup ai agent development tools agentuity-cli-dev documentation Agentuity-CLI-Dev 本地开发服务器 AIエージェント 命令行工具 自定义端口 本地模式 公用 URL 开发工具 Starts development server using the `bunx @agentuity/cli dev` command Supports custom port specification with the `--port` flag Allows running in local mode with the `--local` flag Disables public URL with the `--no-public` flag Utilizes the bunx command for development server management agentuity-cli-dev is a command-line interface tool for building and running development servers, utilizing the bunx command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kivo360/quickhooks/moai-alfred-language-detection', 'community', 'kivo360', 'quickhooks', 'kivo360/quickhooks', 'moai-alfred-language-detection', 0, 0, 55, '2026-03-08T01:57:15.364Z', '2026-03-08T02:04:20.773Z', '422efe2971e16efb7630b01fdd216a0f4124cfa0e0b8e0728b17c89ef6af33e4', '{"id":"kivo360/quickhooks/moai-alfred-language-detection","name":"moai-alfred-language-detection","description":{"en":"The moai-alfred-language-detection skill auto-detects project languages and frameworks, benefiting developers by streamlining their workflow. It supports best practices enforcement for the Alfred domain.","zh":"moai-alfred-language-detection是一种Claude代码钩子库，用于自动检测项目语言和框架，支持多种文件格式","ja":"moai-alfred-language-detectionは、プロジェクト言語とフレームワークを自動検出するClaudeコードフックライブラリです","ko":"moai-alfred-language-detection은 프로젝트 언어와 프레임워크를 자동으로 감지하는 Claude 코드 훅 라이브러리입니다","es":"moai-alfred-language-detection es una biblioteca de hooks que detecta automáticamente el lenguaje y el marco de trabajo de un proyecto","fr":"moai-alfred-language-detection est une bibliothèque de hooks qui détecte automatiquement le langage et le framework d''un projet","de":"moai-alfred-language-detection ist eine Hook-Bibliothek, die automatisch die Sprache und das Framework eines Projekts erkennt","pt":"O moai-alfred-language-detection é uma biblioteca de hooks que detecta automaticamente a linguagem e o framework de um projeto. Ele suporta package.json e pyproject.toml.","ru":"Moai-alfred-language-detection - это библиотека хуков, которая автоматически определяет язык и фреймворк проекта. Она поддерживает package.json и pyproject.toml.","ar":"moai-alfred-language-detection هي مكتبة-hooks تقوم بالكشف التلقائي عن لغة و إطار المشروع. تدعم package.json و pyproject.toml."},"seo":{"title":{"en":"moai-alfred-language-detection: Auto-Detection Setup Guid...","zh":"moai-al