INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kivo360/quickhooks/moai-alfred-language-detection', 'moai-alfred-language-detection', 'kivo360', 'quickhooks', 'community', 'moai-alfred-language-detection kivo360 quickhooks community The moai-alfred-language-detection skill auto-detects project languages and frameworks, benefiting developers by streamlining their workflow. It supports best practices enforcement for the Alfred domain. moai-alfred-language-detection是一种Claude代码钩子库，用于自动检测项目语言和框架，支持多种文件格式 moai-alfred-language-detectionは、プロジェクト言語とフレームワークを自動検出するClaudeコードフックライブラリです moai-alfred-language-detection은 프로젝트 언어와 프레임워크를 자동으로 감지하는 Claude 코드 훅 라이브러리입니다 moai-alfred-language-detection es una biblioteca de hooks que detecta automáticamente el lenguaje y el marco de trabajo de un proyecto moai-alfred-language-detection est une bibliothèque de hooks qui détecte automatiquement le langage et le framework d''un projet moai-alfred-language-detection ist eine Hook-Bibliothek, die automatisch die Sprache und das Framework eines Projekts erkennt O moai-alfred-language-detection é uma biblioteca de hooks que detecta automaticamente a linguagem e o framework de um projeto. Ele suporta package.json e pyproject.toml. Moai-alfred-language-detection - это библиотека хуков, которая автоматически определяет язык и фреймворк проекта. Она поддерживает package.json и pyproject.toml. moai-alfred-language-detection هي مكتبة-hooks تقوم بالكشف التلقائي عن لغة و إطار المشروع. تدعم package.json و pyproject.toml. how to use moai-alfred-language-detection moai-alfred-language-detection setup guide moai-alfred-language-detection alternative moai-alfred-language-detection vs claude auto-detect project language alfred domain best practices moai-alfred-language-detection AI工具 项目语言检测 自动检测框架 Claude代码钩子库 package.json pyproject.toml Bash Read Auto-detects project language and framework from package.json and pyproject.toml files Enforces best practices for the Alfred domain Supports Read (read_file) and Bash (terminal) tools Auto-loads on demand when specific keywords are detected moai-alfred-language-detection is a claude code hooks library that auto-detects project language and framework from files like package.json and pyproject.toml.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jtordoya-dev/Antigravity_setup/popup-cro', 'community', 'jtordoya-dev', 'Antigravity_setup', 'jtordoya-dev/Antigravity_setup', 'popup-cro', 0, 0, 55, '2026-03-08T01:57:15.402Z', '2026-03-08T02:06:46.589Z', '0d37211c60d0ef1a67deef75f2f31feb79788cf33a0a7ed573a6c119c83219ae', '{"id":"jtordoya-dev/Antigravity_setup/popup-cro","name":"popup-cro","description":{"en":"popup-cro is a skill that helps experts optimize popups for conversion. It benefits developers and marketers by providing guidance on creating effective popups.","zh":"弹出窗口CRO优化专家，创建高转化率弹出窗口，提升品牌形象。","ja":"ポップアップCRO最適化のエキスパート、コンバージョン率の高いポップアップを作成し、ブランドイメージを向上させる","ko":"팝업 CRO 최적화 전문가, 높은 전환률을 가진 팝업을 생성하여 브랜드 이미지를 향상시키는 것을 목표로 합니다.","es":"El kit de inicio popup-cro te permite crear popups que convierten sin molestar a los usuarios","fr":"Le kit de démarrage popup-cro vous permet de créer des popups qui convertissent sans déranger les utilisateurs","de":"Das Starter-Kit popup-cro ermöglicht es Ihnen, Popups zu erstellen, die konvertieren, ohne die Benutzer zu stören","pt":"O popup-cro é um kit de início para otimização de conversão de popups e modais, visando criar experiências de usuário eficazes.","ru":"ИИ Агент popup-cro является стартовым китом для оптимизации конверсий попапов и модальных окон, направленным на создание эффективных пользовательских опытов.","ar":"وحدة popup-cro هي حزمة بدء تشغيل لتحسين التحويلات لنوافذ المنبثق والتعليمة، تهدف إلى إنشاء تجارب مستخدم فعالة."},"seo":{"title":{"en":"popup-cro: Expert Popup Optimization Guide | AI Agent Skill","zh":"弹出窗口CRO优化设置指南","ja":"ポップアップCRO最適化ガイド","ko":"팝업 CRO 최적화 설정 가이드","es":"Guía de configuración de popup-cro para maximizar la conv...","fr":"Guide de mise en place de popup-cro pour optimiser les co...","de":"Einrichtungsleitfaden für popup-cro zur Konversionssteige...","pt":"Guia de Configuração do popup-cro para Otimização de Conv...","ru":"Настройка ИИ Агента popup-cro для оптимизации конверсий","ar":"دليل إعداد popup-cro لتحسين التحويلات"},"description":{"en":"Unlock the secrets of popup conversion optimization with popup-cro. Learn how to create effective popups without annoying users. Get started now!","zh":"了解弹出窗口CRO优化的技术细节，创建不打扰用户的高转化率弹出窗口，提升品牌形象","ja":"ポップアップCRO最適化のテクニカルな詳細を学び、ユーザーを妨げない高コンバージョン率のポップアップを作成し、ブランドイメージを向上させる","ko":"팝업 CRO 최적화의 기술적 세부 사항을 파악하고, 사용자를 방해하지 않는 높은 전환률을 가진 팝업을 생성하여 브랜드 이미지를 향상시키세요","es":"Aprende a crear popups personalizados con popup-cro y mejora la conversión sin dañar la percepción de la marca","fr":"Découvrez comment créer des popups personnalisés avec popup-cro et améliorer la conversion sans nuire à la perception de la marque","de":"Erfahren Sie, wie Sie mit popup-cro personalisierte Popups erstellen und die Konversion steigern, ohne die Markenwahrnehmung zu beeinträchtigen","pt":"Aprenda a criar popups que convertem sem irritar os usuários, com o kit de início do popup-cro","ru":"Узнайте, как создавать попапы, которые конвертируют без раздражения пользователей, с помощью кита ИИ Агента popup-cro","ar":"تعلم كيفية إنشاء نوافذ منبثقة تحول دون إزعاج المستخدمين، باستخدام حزمة بدء تشغيل popup-cro"},"definition":{"en":"popup-cro is a specialized skill for optimizing popup and modal windows to improve conversion rates without compromising user experience.","zh":"弹出窗口CRO优化是指创建不打扰用户的高转化率弹出窗口，提升品牌形象的技术","ja":"ポップアップCRO最適化とは、ユーザーを妨げない高コンバージョン率のポップアップを作成し、ブランドイメージを向上させる技術","ko":"팝업 CRO 최적화란 사용자를 방해하지 않는 높은 전환률을 가진 팝업을 생성하여 브랜드 이미지를 향상시키는 기술입니다.","es":"popup-cro es una herramienta de optimización de popups y modales para mejorar la conversión","fr":"popup-cro est un outil d''optimisation de popups et de modales pour améliorer la conversion","de":"popup-cro ist ein Tool zur Optimierung von Popups und Modals, um die Konversion zu verbessern","pt":"O que é popup-cro? Um kit de início para otimização de conversão de popups e modais.","ru":"Что такое ИИ Агент popup-cro? Стартовый кит для оптимизации конверсий попапов и модальных окон.","ar":"ما هي وحدة popup-cro؟ حزمة بدء تشغيل لتحسين التحويلات لنوافذ المنبثق والتعليمة."},"features":{"en":["Checks for product marketing context in .claude/product-marketing-context.md","Understands popup purpose, including email/newsletter capture","Provides recommendations based on specific task requirements","Optimizes popups for conversion without damaging brand perception","Follows critical rules for effective popup creation","Reads context from .claude/product-marketing-context.md before asking questions"],"zh":["弹出窗口目的分析","Email/Newsletter 捕获优化","产品营销背景检查","高转化率弹出窗口创建"],"ja":["ポップアップの目的分析","Email/Newsletter キャプチャー最適化","プロダクトマーケティングコンテキストの確認","高コンバージョン率のポップアップ作成"],"ko":["팝업 목적 분석","이메일/뉴스레터 캡처 최적화","제품 마케팅 콘텍스트 확인","높은 전환률을 가진 팝업 생성"],"es":["Optimización de popups y modales para maximizar la conversión","Creación de popups personalizados con fines de marketing","Análisis de la percepción de la marca para evitar daños","Integración con contextos de marketing de productos","Capacidad para capturar direcciones de correo electrónico y boletines","Compatibilidad con tecnologías como CLI y archivos markdown"],"fr":["Optimisation de popups et de modales pour maximiser la conversion","Création de popups personnalisés à des fins de marketing","Analyse de la perception de la marque pour éviter les dommages","Intégration avec les contextes de marketing de produits","Capacité à capturer les adresses électroniques et les bulletins","Compatibilité avec des technologies comme CLI et des fichiers markdown"],"de":["Optimierung von Popups und Modals, um die Konversion zu maximieren","Erstellung von personalisierten Popups für Marketingzwecke","Analyse der Markenwahrnehmung, um Schäden zu vermeiden","Integration mit Produktmarketing-Kontexten","Fähigkeit, E-Mail-Adressen und Newsletter zu erfassen","Kompatibilität mit Technologien wie CLI und Markdown-Dateien"],"pt":["Otimização de propósito de popup","Verificação de contexto de marketing de produto","Criação de popups que convertem sem irritar os usuários","Análise de captação de email e newsletter","Integração com tecnologias de desenvolvimento web"],"ru":["Оптимизация цели попапа","Проверка контекста маркетинга продукта","Создание попапов, которые конвертируют без раздражения пользователей","Анализ сбора электронной почты и новостей","Интеграция с технологиями веб-разработки"],"ar":["تحسين هدف نافذة المنبثق","التحقق من سياق تسويق المنتج","إنشاء نوافذ منبثقة تحول دون إزعاج المستخدمين","تحليل جمع البريد الإلكتروني والنشرة الإخبارية","التكامل مع teknolojies التطوير الويب"]},"keywords":{"en":["how to use popup-cro","popup-cro alternative","popup-cro setup guide","what is popup-cro","popup-cro vs other optimization tools","popup-cro install","popup conversion optimization","effective popup creation","popup-cro expert guide"],"zh":["弹出窗口CRO优化","高转化率弹出窗口","产品营销背景检查","Email/Newsletter 捕获优化","弹出窗口目的分析","AIエージェント","弹出窗口设置指南"],"ja":["ポップアップCRO最適化","高コンバージョン率のポップアップ","プロダクトマーケティングコンテキストの確認","Email/Newsletter キャプチャー最適化","ポップアップの目的分析","AIエージェント","ポップアップ設定ガイド"],"ko":["팝업 CRO 최적화","높은 전환률을 가진 팝업","제품 마케팅 콘텍스트 확인","이메일/뉴스레터 캡처 최적화","팝업 목적 분석","AI 에이전트","팝업 설정 가이드"],"es":["popup-cro","optimización de popups","marketing de productos","conversión","percepción de la marca","herramientas de AI","Agentes de IA","tecnologías de marketing","CLI","markdown"],"fr":["popup-cro","optimisation de popups","marketing de produits","conversion","perception de la marque","outils d''IA","Agents d''IA","technologies de marketing","CLI","markdown"],"de":["popup-cro","Optimierung von Popups","Produktmarketing","Konversion","Markenwahrnehmung","AI-Tools","KI-Agenten","Marketingtechnologien","CLI","Markdown"],"pt":["popup-cro","otimização de conversão","popups","modais","experiência de usuário","desenvolvimento web","marketing de produto","captação de email","newsletter"],"ru":["ИИ Агент popup-cro","оптимизация конверсий","попапы","модальные окна","пользовательский опыт","веб-разработка","маркетинг продукта","сбор электронной почты","новости"],"ar":["وحدة popup-cro","تحسين التحويلات","نوافذ المنبثق","نوافذ التعليمة","تجربة المستخدم","تطوير الويب","تسويق المنتج","جمع البريد الإلكتروني","النشرة الإخبارية"]}},"owner":"jtordoya-dev","repo":"Antigravity_setup","repoPath":"jtordoya-dev/Antigravity_setup","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.402Z","topics":[],"category":"community","skillMd":{"name":"popup-cro","description":"When the user wants to create or optimize popups, modals, overlays, slide-ins, or banners for conversion purposes. Also use when the user mentions exit intent, popup conversions, modal optimization, lead capture popup, email popup, announcement banner, or overlay. For forms outside of popups, see form-cro. For general page conversion optimization, see page-cro.","version":"1.0.0","bodyPreview":"# Popup CRO\n\nYou are an expert in popup and modal optimization. Your goal is to create popups that convert without annoying users or damaging brand perception.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.claude/product-marketing-context.md` exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore providing recommendations, understand:\n\n1. **Popup Purpose**\n   - Email/newsletter cap","body":"# Popup CRO\n\nYou are an expert in popup and modal optimization. Your goal is to create popups that convert without annoying users or damaging brand perception.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.claude/product-marketing-context.md` exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore providing recommendations, understand:\n\n1. **Popup Purpose**\n   - Email/newsletter capture\n   - Lead magnet delivery\n   - Discount/promotion\n   - Announcement\n   - Exit intent save\n   - Feature promotion\n   - Feedback/survey\n\n2. **Current State**\n   - Existing popup performance?\n   - What triggers are used?\n   - User complaints or feedback?\n   - Mobile experience?\n\n3. **Traffic Context**\n   - Traffic sources (paid, organic, direct)\n   - New vs. returning visitors\n   - Page types where shown\n\n---\n\n## Core Principles\n\n### 1. Timing Is Everything\n- Too early = annoying interruption\n- Too late = missed opportunity\n- Right time = helpful offer at moment of need\n\n### 2. Value Must Be Obvious\n- Clear, immediate benefit\n- Relevant to page context\n- Worth the interruption\n\n### 3. Respect the User\n- Easy to dismiss\n- Don''t trap or trick\n- Remember preferences\n- Don''t ruin the experience\n\n---\n\n## Trigger Strategies\n\n### Time-Based\n- **Not recommended**: \"Show after 5 seconds\"\n- **Better**: \"Show after 30-60 seconds\" (proven engagement)\n- Best for: General site visitors\n\n### Scroll-Based\n- **Typical**: 25-50% scroll depth\n- Indicates: Content engagement\n- Best for: Blog posts, long-form content\n- Example: \"You''re halfway through—get more like this\"\n\n### Exit Intent\n- Detects cursor moving to close/leave\n- Last chance to capture value\n- Best for: E-commerce, lead gen\n- Mobile alternative: Back button or scroll up\n\n### Click-Triggered\n- User initiates (clicks button/link)\n- Zero annoyance factor\n- Best for: Lead magnets, gated content, demos\n- Example: \"Download PDF\" → Popup form\n\n### Page Count / Session-Based\n- After visiting X pages\n- Indicates research/comparison behavior\n- Best for: Multi-page journeys\n- Example: \"Been comparing? Here''s a summary...\"\n\n### Behavior-Based\n- Add to cart abandonment\n- Pricing page visitors\n- Repeat page visits\n- Best for: High-intent segments\n\n---\n\n## Popup Types\n\n### Email Capture Popup\n**Goal**: Newsletter/list subscription\n\n**Best practices:**\n- Clear value prop (not just \"Subscribe\")\n- Specific benefit of subscribing\n- Single field (email only)\n- Consider incentive (discount, content)\n\n**Copy structure:**\n- Headline: Benefit or curiosity hook\n- Subhead: What they get, how often\n- CTA: Specific action (\"Get Weekly Tips\")\n\n### Lead Magnet Popup\n**Goal**: Exchange content for email\n\n**Best practices:**\n- Show what they get (cover image, preview)\n- Specific, tangible promise\n- Minimal fields (email, maybe name)\n- Instant delivery expectation\n\n### Discount/Promotion Popup\n**Goal**: First purchase or conversion\n\n**Best practices:**\n- Clear discount (10%, $20, free shipping)\n- Deadline creates urgency\n- Single use per visitor\n- Easy to apply code\n\n### Exit Intent Popup\n**Goal**: Last-chance conversion\n\n**Best practices:**\n- Acknowledge they''re leaving\n- Different offer than entry popup\n- Address common objections\n- Final compelling reason to stay\n\n**Formats:**\n- \"Wait! Before you go...\"\n- \"Forget something?\"\n- \"Get 10% off your first order\"\n- \"Questions? Chat with us\"\n\n### Announcement Banner\n**Goal**: Site-wide communication\n\n**Best practices:**\n- Top of page (sticky or static)\n- Single, clear message\n- Dismissable\n- Links to more info\n- Time-limited (don''t leave forever)\n\n### Slide-In\n**Goal**: Less intrusive engagement\n\n**Best practices:**\n- Enters from corner/bottom\n- Doesn''t block content\n- Easy to dismiss or minimize\n- Good for chat, support, secondary CTAs\n\n---\n\n## Design Best Practices\n\n### Visual Hierarchy\n1. Headline (largest, first seen)\n2. Value prop/offer (clear benefit)\n3. Form/CTA (obvious action)\n4. Close option (easy to find)\n\n### Sizing\n- Desktop: 400-600px wide typical\n- Don''t cover entire screen\n- Mobile: Full-width bottom or center, not full-screen\n- Leave space to close (visible X, click outside)\n\n### Close Button\n- Always visible (top right is convention)\n- Large enough to tap on mobile\n- \"No thanks\" text link as alternative\n- Click outside to close\n\n### Mobile Considerations\n- Can''t detect exit intent (use alternatives)\n- Full-screen overlays feel aggressive\n- Bottom slide-ups work well\n- Larger touch targets\n- Easy dismiss gestures\n\n### Imagery\n- Product image or preview\n- Face if relevant (increases trust)\n- Minimal for speed\n- Optional—copy can work alone\n\n---\n\n## Copy Formulas\n\n### Headlines\n- Benefit-driven: \"Get [result] in [timeframe]\"\n- Question: \"Want [desired outcome]?\"\n- Command: \"Don''t miss [thing]\"\n- Social proof: \"Join [X] people who...\"\n- Curiosity: \"The one thing [audience] always get wrong about [topic]\"\n\n### Subheadlines\n- Expand on the promise\n- Address objection (\"No spam, ever\")\n- Set expectations (\"Weekly tips in 5 min\")\n\n### CTA Buttons\n- First person works: \"Get My Discount\" vs \"Get Your Discount\"\n- Specific over generic: \"Send Me the Guide\" vs \"Submit\"\n- Value-focused: \"Claim My 10% Off\" vs \"Subscribe\"\n\n### Decline Options\n- Polite, not guilt-trippy\n- \"No thanks\" / \"Maybe later\" / \"I''m not interested\"\n- Avoid manipulative: \"No, I don''t want to save money\"\n\n---\n\n## Frequency and Rules\n\n### Frequency Capping\n- Show maximum once per session\n- Remember dismissals (cookie/localStorage)\n- 7-30 days before showing again\n- Respect user choice\n\n### Audience Targeting\n- New vs. returning visitors (different needs)\n- By traffic source (match ad message)\n- By page type (context-relevant)\n- Exclude converted users\n- Exclude recently dismissed\n\n### Page Rules\n- Exclude checkout/conversion flows\n- Consider blog vs. product pages\n- Match offer to page context\n\n---\n\n## Compliance and Accessibility\n\n### GDPR/Privacy\n- Clear consent language\n- Link to privacy policy\n- Don''t pre-check opt-ins\n- Honor unsubscribe/preferences\n\n### Accessibility\n- Keyboard navigable (Tab, Enter, Esc)\n- Focus trap while open\n- Screen reader compatible\n- Sufficient color contrast\n- Don''t rely on color alone\n\n### Google Guidelines\n- Intrusive interstitials hurt SEO\n- Mobile especially sensitive\n- Allow: Cookie notices, age verification, reasonable banners\n- Avoid: Full-screen before content on mobile\n\n---\n\n## Measurement\n\n### Key Metrics\n- **Impression rate**: Visitors who see popup\n- **Conversion rate**: Impressions → Submissions\n- **Close rate**: How many dismiss immediately\n- **Engagement rate**: Interaction before close\n- **Time to close**: How long before dismissing\n\n### What to Track\n- Popup views\n- Form focus\n- Submission attempts\n- Successful submissions\n- Close button clicks\n- Outside clicks\n- Escape key\n\n### Benchmarks\n- Email popup: 2-5% conversion typical\n- Exit intent: 3-10% conversion\n- Click-triggered: Higher (10%+, self-selected)\n\n---\n\n## Output Format\n\n### Popup Design\n- **Type**: Email capture, lead magnet, etc.\n- **Trigger**: When it appears\n- **Targeting**: Who sees it\n- **Frequency**: How often shown\n- **Copy**: Headline, subhead, CTA, decline\n- **Design notes**: Layout, imagery, mobile\n\n### Multiple Popup Strategy\nIf recommending multiple popups:\n- Popup 1: [Purpose, trigger, audience]\n- Popup 2: [Purpose, trigger, audience]\n- Conflict rules: How they don''t overlap\n\n### Test Hypotheses\nIdeas to A/B test with expected outcomes\n\n---\n\n## Common Popup Strategies\n\n### E-commerce\n1. Entry/scroll: First-purchase discount\n2. Exit intent: Bigger discount or reminder\n3. Cart abandonment: Complete your order\n\n### B2B SaaS\n1. Click-triggered: Demo request, lead magnets\n2. Scroll: Newsletter/blog subscription\n3. Exit intent: Trial reminder or content offer\n\n### Content/Media\n1. Scroll-based: Newsletter after engagement\n2. Page count: Subscribe after multiple visits\n3. Exit intent: Don''t miss future content\n\n### Lead Generation\n1. Time-delayed: General list building\n2. Click-triggered: Specific lead magnets\n3. Exit intent: Final capture attempt\n\n---\n\n## Experiment Ideas\n\n### Placement & Format Experiments\n\n**Banner Variations**\n- Top bar vs. banner below header\n- Sticky banner vs. static banner\n- Full-width vs. contained banner\n- Banner with countdown timer vs. without\n\n**Popup Formats**\n- Center modal vs. slide-in from corner\n- Full-screen overlay vs. smaller modal\n- Bottom bar vs. corner popup\n- Top announcements vs. bottom slideouts\n\n**Position Testing**\n- Test popup sizes on desktop and mobile\n- Left corner vs. right corner for slide-ins\n- Test visibility without blocking content\n\n---\n\n### Trigger Experiments\n\n**Timing Triggers**\n- Exit intent vs. 30-second delay vs. 50% scroll depth\n- Test optimal time delay (10s vs. 30s vs. 60s)\n- Test scroll depth percentage (25% vs. 50% vs. 75%)\n- Page count trigger (show after X pages viewed)\n\n**Behavior Triggers**\n- Show based on user intent prediction\n- Trigger based on specific page visits\n- Return visitor vs. new visitor targeting\n- Show based on referral source\n\n**Click Triggers**\n- Click-triggered popups for lead magnets\n- Button-triggered vs. link-triggered modals\n- Test in-content triggers vs. sidebar triggers\n\n---\n\n### Messaging & Content Experiments\n\n**Headlines & Copy**\n- Test attention-grabbing vs. informational headlines\n- \"Limited-time offer\" vs. \"New feature alert\" messaging\n- Urgency-focused copy vs. value-focused copy\n- Test headline length and specificity\n\n**CTAs**\n- CTA button text variations\n- Button color testing for contrast\n- Primary + secondary CTA vs. single CTA\n- Test decline text (friendly vs. neutral)\n\n**Visual Content**\n- Add countdown timers to create urgency\n- Test with/without images\n- Product preview vs. generic imagery\n- Include social proof in popup\n\n---\n\n### Personalization Experiments\n\n**Dynamic Content**\n- Personalize popup based on visitor data\n- Show industry-specific content\n- Tailor content based on pages visited\n- Use progressive profiling (ask more over time)\n\n**Audience Targeting**\n- New vs. returning visitor messaging\n- Segment by traffic source\n- Target based on engagement level\n- Exclude already-converted visitors\n\n---\n\n### Frequency & Rules Experiments\n\n- Test frequency capping (once per session vs. once per week)\n- Cool-down period after dismissal\n- Test different dismiss behaviors\n- Show escalating offers over multiple visits\n\n---\n\n## Task-Specific Questions\n\n1. What''s the primary goal for this popup?\n2. What''s your current popup performance (if any)?\n3. What traffic sources are you optimizing for?\n4. What incentive can you offer?\n5. Are there compliance requirements (GDPR, etc.)?\n6. Mobile vs. desktop traffic split?\n\n---\n\n## Related Skills\n\n- **form-cro**: For optimizing the form inside the popup\n- **page-cro**: For the page context around popups\n- **email-sequence**: For what happens after popup conversion\n- **ab-test-setup**: For testing popup variations\n"},"lastSynced":"2026-03-08T02:06:46.589Z","agentAnalysis":{"suitability":{"en":"Perfect for Marketing Agents needing expert popup optimization for conversion rate improvement.","zh":"适合需要弹出窗口优化专家知识以提高转化率的营销代理。","ja":"マーケティングエージェントがコンバージョン率の向上のためにポップアップの最適化の専門知識を必要とする場合に適しています。","ko":"컨버젼율 향상을 위한 팝업 최적화를 전문적으로 수행해야 하는 마케팅 에이전트에게 적합합니다.","es":"Perfecto para agentes de marketing que necesitan una optimización de emergentes experta para mejorar la tasa de conversión.","fr":"Parfait pour les agents marketing ayant besoin d''une optimisation d''appels à l''action experte pour améliorer le taux de conversion.","de":"Perfekt für Marketingagenten, die eine Experten-Optimierung von Popups für die Verbesserung der Konvertierungsrate benötigen.","pt":"Perfeito para Agentes de Marketing que precisam de otimização de popup especializada para melhorar a taxa de conversão.","ru":"Идеально для маркетинговых агентов, которым требуется экспертная оптимизация всплывающих окон для улучшения коэффициента конверсии.","ar":"مثالي لوكلاء التسويق الذين يحتاجون إلى تحسين إكساء الخروج المتقدم لتحسين معدل التحويل."},"recommendation":{"en":"Empowers agents to create effective popups that convert without annoying users, leveraging expertise in popup and modal optimization, and understanding of product marketing context through .claude/product-marketing-context.md files, and optimizing for specific purposes like email or newsletter capture.","zh":"赋予代理创建有效的弹出窗口的能力，这些弹出窗口可以在不打扰用户的情况下实现转化，利用弹出窗口和模态优化的专业知识以及通过 .claude/product-marketing-context.md 文件了解产品营销背景，并针对特定目的（如电子邮件或新闻稿采集）进行优化。","ja":"エージェントが効果的なポップアップを作成できるようにし、ユーザーを混乱させないでコンバージョンを実現できる。ポップアップおよびモーダル最適化の専門知識と、.claude/product-marketing-context.md ファイルを介した製品マーケティングコンテキストの理解、および電子メールまたはニュースレターのキャプチャなどの特定の目的の最適化を利用する。","ko":"에이전트가 사용자를 방해하지 않고 컨버젼을 달성할 수 있는 효과적인 팝업을 생성할 수 있도록하며, 이는 팝업 및 모달 최적화의 전문 지식과 .claude/product-marketing-context.md 파일을 통해 제품 마케팅 문脈을 이해하는 것 그리고 특정 목적을 위한 최적화(예: 이메일 또는 뉴스레터 캡처)를 통해 달성됩니다.","es":"Habilita a los agentes a crear llamadas a la acción efectivas que convierten sin molestar a los usuarios, aprovechando la experiencia en optimización de popups y modales, y la comprensión del contexto de marketing de productos a través de archivos .claude/product-marketing-context.md, y optimizando para propósitos específicos como la captura de correo electrónico o boletín.","fr":"Habilite les agents à créer des appels à l''action efficaces qui convertissent sans agacer les utilisateurs, en exploitant l''expertise dans l''optimisation des popups et des modales, et la compréhension du contexte de marketing de produits via des fichiers .claude/product-marketing-context.md, et en optimisant pour des objectifs spécifiques comme la capture d''e-mail ou de newsletter.","de":"Ermöglicht es Agenten, effektive Popups zu erstellen, die konvertieren, ohne Benutzer zu belästigen, indem es die Expertise in der Optimierung von Popups und Modals nutzt und das Verständnis des Produktmarketing-Kontexts durch .claude/product-marketing-context.md-Dateien und die Optimierung für spezifische Zwecke wie E-Mail- oder Newsletter-Erfassung.","pt":"Habilita os agentes a criar popups eficazes que convertem sem irritar os usuários, aproveitando a expertise em otimização de popup e modal, e compreensão do contexto de marketing de produto por meio de arquivos .claude/product-marketing-context.md, e otimizando para propósitos específicos como captura de email ou boletim.","ru":"Наделяет агентов возможностью создавать эффективные всплывающие окна, которые конвертируют без раздражения пользователей, используя экспертизу в области оптимизации всплывающих окон и модальных окон, а также понимание контекста продукта маркетинга через файлы .claude/product-marketing-context.md, и оптимизируя для конкретных целей, таких как захват электронной почты или новостей.","ar":"يُخول للوكلاء إنشاء نافذة منبثقة فعالة تتحول دون إزعاج المستخدمين، مستفيدًا من الخبرة في تحسين نافذة المنبثق و سياق تسويق المنتج من خلال ملفات .claude/product-marketing-context.md، وضبطها لغايات محددة مثل الاستحواذ على البريد الإلكتروني أو النشرة الإخبارية."},"useCases":{"en":["Optimizing popup placement for maximum conversion","Creating targeted popup content for specific user segments","Analyzing popup performance for data-driven optimization decisions"],"zh":["最大化转化率的弹出窗口放置优化","针对特定用户段的目标弹出窗口内容创建","弹出窗口性能分析以进行数据驱动的优化决策"],"ja":["コンバージョン率の最大化のためのポップアップの配置最適化","特定のユーザーセグメント向けのターゲットポップアップコンテンツの作成","ポップアップのパフォーマンス分析によるデータドリブンの最適化決定"],"ko":["최대 컨버젼율을 위한 팝업 배치 최적화","특정 사용자 세그먼트를 위한 타겟팅된 팝업 콘텐츠 생성","데이터 기반의 최적화 결정을 위한 팝업 성능 분석"],"es":["Optimizar la colocación de popups para una máxima conversión","Crear contenido de popup dirigido a segmentos de usuarios específicos","Analizar el rendimiento de los popups para tomar decisiones de optimización basadas en datos"],"fr":["Optimiser le placement des appels à l''action pour une conversion maximale","Créer un contenu ciblé d''appel à l''action pour des segments d''utilisateurs spécifiques","Analyser les performances des appels à l''action pour prendre des décisions d''optimisation basées sur les données"],"de":["Optimieren der Platzierung von Popups für eine maximale Konvertierung","Erstellen von gezieltem Popup-Inhalt für bestimmte Benutzersegmente","Analyse der Leistung von Popups für datengetriebene Optimierungsentscheidungen"],"pt":["Otimizando a posição do popup para máxima conversão","Criando conteúdo de popup direcionado para segmentos de usuário específicos","Analysando o desempenho do popup para decisões de otimização baseadas em dados"],"ru":["Оптимизация размещения всплывающих окон для максимальной конверсии","Создание целевого контента всплывающих окон для конкретных сегментов пользователей","Анализ производительности всплывающих окон для принятия решений об оптимизации на основе данных"],"ar":["تحسين وضع نافذة المنبثق لتحقيق أقصى درجة تحويل","إنشاء محتوى نافذة المنبثق المستهدفة ل قطاعات المستخدمين المحددة","تحليل أداء نافذة المنبثق لاتخاذ قرارات تحسين قائمة على البيانات"]},"limitations":{"en":["Requires understanding of product marketing context","Limited to popup and modal optimization","May require additional development or design expertise for implementation"],"zh":["需要了解产品营销背景","仅限于弹出窗口和模态优化","可能需要额外的开发或设计专业知识以实现实施"],"ja":["製品マーケティングコンテキストの理解が必要","ポップアップおよびモーダル最適化のみに限定される","実装には追加の開発またはデザインの専門知識が必要になる場合がある"],"ko":["제품 마케팅 문脈에 대한 이해가 필요함","팝업 및 모달 최적화에만 국한됨","구현을 위해 추가적인 개발 또는 디자인 전문 지식이 필요할 수 있음"],"es":["Requiere una comprensión del contexto de marketing de productos","Limitado a la optimización de popups y modales","Puede requerir experiencia adicional en desarrollo o diseño para la implementación"],"fr":["Nécessite une compréhension du contexte de marketing de produits","Limité à l''optimisation des popups et des modales","Peut nécessiter une expertise supplémentaire en développement ou en conception pour la mise en œuvre"],"de":["Erfordert ein Verständnis des Produktmarketing-Kontexts","Begrenzt auf die Optimierung von Popups und Modals","Kann zusätzliche Entwicklung oder Design-Expertise für die Implementierung erfordern"],"pt":["Exige compreensão do contexto de marketing de produto","Limitado à otimização de popup e modal","Pode exigir conhecimento adicional de desenvolvimento ou design para implementação"],"ru":["Требует понимания контекста продукта маркетинга","Ограничен оптимизацией всплывающих окон и модальных окон","Может требовать дополнительной экспертизы в области разработки или дизайна для реализации"],"ar":["يتطلب فهمًا لسياق تسويق المنتج","محدود بتحسين نافذة المنبثق و نافذة الحوار"," قد يتطلب مهارات إضافية في مجال التطوير أو التصميم للتنفيذ"]},"version":4},"contentHash":"0d37211c60d0ef1a67deef75f2f31feb79788cf33a0a7ed573a6c119c83219ae","qualityScore":55}');
