INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jtordoya-dev/Antigravity_setup/popup-cro', 'popup-cro', 'jtordoya-dev', 'Antigravity_setup', 'community', 'popup-cro jtordoya-dev Antigravity_setup community popup-cro is a skill that helps experts optimize popups for conversion. It benefits developers and marketers by providing guidance on creating effective popups. 弹出窗口CRO优化专家，创建高转化率弹出窗口，提升品牌形象。 ポップアップCRO最適化のエキスパート、コンバージョン率の高いポップアップを作成し、ブランドイメージを向上させる 팝업 CRO 최적화 전문가, 높은 전환률을 가진 팝업을 생성하여 브랜드 이미지를 향상시키는 것을 목표로 합니다. El kit de inicio popup-cro te permite crear popups que convierten sin molestar a los usuarios Le kit de démarrage popup-cro vous permet de créer des popups qui convertissent sans déranger les utilisateurs Das Starter-Kit popup-cro ermöglicht es Ihnen, Popups zu erstellen, die konvertieren, ohne die Benutzer zu stören O popup-cro é um kit de início para otimização de conversão de popups e modais, visando criar experiências de usuário eficazes. ИИ Агент popup-cro является стартовым китом для оптимизации конверсий попапов и модальных окон, направленным на создание эффективных пользовательских опытов. وحدة popup-cro هي حزمة بدء تشغيل لتحسين التحويلات لنوافذ المنبثق والتعليمة، تهدف إلى إنشاء تجارب مستخدم فعالة. how to use popup-cro popup-cro alternative popup-cro setup guide what is popup-cro popup-cro vs other optimization tools popup-cro install popup conversion optimization effective popup creation popup-cro expert guide 弹出窗口CRO优化 高转化率弹出窗口 产品营销背景检查 Email/Newsletter 捕获优化 弹出窗口目的分析 AIエージェント 弹出窗口设置指南 Checks for product marketing context in .claude/product-marketing-context.md Understands popup purpose, including email/newsletter capture Provides recommendations based on specific task requirements Optimizes popups for conversion without damaging brand perception Follows critical rules for effective popup creation Reads context from .claude/product-marketing-context.md before asking questions popup-cro is a specialized skill for optimizing popup and modal windows to improve conversion rates without compromising user experience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SwitchbackTech/compass/codex-a11y-audit', 'community', 'SwitchbackTech', 'compass', 'SwitchbackTech/compass', 'codex-a11y-audit', 0, 0, 55, '2026-03-08T01:57:15.423Z', '2026-03-08T02:07:25.661Z', 'f471d1d3a8f3013c119671ec28b060ee361c2c1b0ef07db415802784cbae8706', '{"id":"SwitchbackTech/compass/codex-a11y-audit","name":"codex-a11y-audit","description":{"en":"codex-a11y-audit is a task manager for engineers that audits UI changes for accessibility regressions. It helps developers review and propose minimal fixes for UI diffs.","zh":"codex-a11y-audit是一款无障碍审计工具，用于审查UI变更的无障碍回归和缺失改进","ja":"codex-a11y-auditはアクセシビリティ監査ツールであり、UIの変更を審査してアクセシビリティの回帰と改善を提案します","ko":"codex-a11y-audit는 접근성 감사 도구로서 UI 변경 사항을審查하여 접근성의 회귀와 개선을 제안합니다","es":"codex-a11y-audit es una herramienta de auditoría de accesibilidad que analiza cambios en la interfaz de usuario para detectar regresiones y mejoras","fr":"codex-a11y-audit est un outil d''audit d''accessibilité qui analyse les modifications de l''interface utilisateur pour détecter les régressions et les améliorations","de":"codex-a11y-audit ist ein Tool zur Überprüfung der Barrierefreiheit, das Änderungen an der Benutzeroberfläche analysiert, um Rückschritte und Verbesserungen zu erkennen","pt":"O Codex-A11y-Audit é uma ferramenta de auditoria de acessibilidade para diffs de UI, ajudando a identificar regressões e melhorias","ru":"Codex-A11y-Audit - это инструмент для аудита доступности в diffs UI, помогающий выявлять регрессии и улучшения","ar":"Codex-A11y-Audit هو أداة فحص إمكانية الوصول ل diffs واجهة المستخدم، مما يساعد في تحديد الانحدارات والتغييرات"},"seo":{"title":{"en":"codex-a11y-audit: Accessibility Audit Setup Guide | AI Ag...","zh":"codex-a11y-audit 无障碍审计工具设置指南","ja":"codex-a11y-audit アクセシビリティ監査ツールのベストプラクティス","ko":"codex-a11y-audit 접근성 감사 도구 사용 방법","es":"Guía de configuración de codex-a11y-audit para auditorías...","fr":"Guide de mise en place de codex-a11y-audit pour les audit...","de":"Einrichtungsleitfaden für codex-a11y-audit zur Durchführu...","pt":"Guia de Configuração do Codex-A11y-Audit: Auditoria de Ac...","ru":"ИИ Агент Codex-A11y-Audit: Руководство по Настройке","ar":"دليل إعداد Codex-A11y-Audit: فحص إمكانية الوصول"},"description":{"en":"Unlock UI accessibility with codex-a11y-audit. Discover how to audit UI diffs for semantics, keyboard access, and ARIA correctness. Get started now!","zh":"了解codex-a11y-audit的功能和特点，掌握无障碍审计工具的设置和使用方法，提高开发效率","ja":"codex-a11y-auditの機能と特徴を紹介します。アクセシビリティ監査ツールの設定と使用方法をマスターして開発効率を向上させましょう","ko":"codex-a11y-audit의 기능과 특징을 소개합니다. 접근성 감사 도구의 설정과 사용 방법을 익혀 개발 효율성을 높여보세요","es":"Aprende a utilizar codex-a11y-audit para auditar cambios en la interfaz de usuario y garantizar la accesibilidad","fr":"Découvrez comment utiliser codex-a11y-audit pour auditer les modifications de l''interface utilisateur et assurer l''accessibilité","de":"Erfahren Sie, wie Sie codex-a11y-audit verwenden, um Änderungen an der Benutzeroberfläche zu überprüfen und die Barrierefreiheit zu gewährleisten","pt":"Aprenda a configurar o Codex-A11y-Audit para auditorias de acessibilidade em diffs de UI, melhorando a experiência do usuário","ru":"Узнайте, как настроить Codex-A11y-Audit для аудита доступности в diffs UI, повышая опыт пользователя","ar":"تعلم كيفية إعداد Codex-A11y-Audit لفحص إمكانية الوصول في diffs واجهة المستخدم، وتحسين تجربة المستخدم"},"definition":{"en":"codex-a11y-audit is a diff-first accessibility audit tool that evaluates changed lines and their immediate context for semantics, keyboard access, and ARIA correctness.","zh":"codex-a11y-audit是一款AIエージェント工具，用于审查UI变更的无障碍问题","ja":"codex-a11y-auditはAIエージェントの一種で、UIの変更を審査してアクセシビリティの問題を特定します","ko":"codex-a11y-audit는 AI 도구 중 하나로, UI 변경 사항을審查하여 접근성 문제를 파악합니다","es":"codex-a11y-audit es una herramienta de auditoría de accesibilidad que evalúa cambios en la interfaz de usuario","fr":"codex-a11y-audit est un outil d''audit d''accessibilité qui évalue les modifications de l''interface utilisateur","de":"codex-a11y-audit ist ein Tool zur Überprüfung der Barrierefreiheit, das Änderungen an der Benutzeroberfläche bewertet","pt":"O que é Codex-A11y-Audit? Uma ferramenta de auditoria de acessibilidade para diffs de UI","ru":"Что такое Codex-A11y-Audit? Инструмент для аудита доступности в diffs UI","ar":"ما هو Codex-A11y-Audit? أداة فحص إمكانية الوصول ل diffs واجهة المستخدم"},"features":{"en":["Audits UI diffs for semantics and accessibility regressions","Evaluates keyboard access and focus management in changed lines","Checks ARIA correctness and contrast in UI components","Supports diff-first evaluation for efficient auditing","Proposes minimal fixes tied to the diff for easy implementation"],"zh":["审查UI变更的语义和键盘访问性","评估焦点管理和ARIA正确性","检查对比度和测试性","仅评估更改的行和其周围环境"],"ja":["UIの変更のセマンティクスとキーボードアクセシビリティを審査する","フォーカス管理とARIAの正確性を評価する","コントラストとテスト可能性を確認する","変更された行とその周囲の環境のみを評価する"],"ko":["UI 변경 사항의 의미와 키보드 접근성을審查한다","포커스 관리와 ARIA의 정확성을 평가한다","대비와 테스트 가능성을 확인한다","변경된 행과その周囲의 환경만을 평가한다"],"es":["Análisis de cambios en la interfaz de usuario para detectar regresiones y mejoras","Evaluación de la accesibilidad semántica","Verificación de la accesibilidad mediante teclado","Análisis de la gestión del foco","Comprobación de la corrección de ARIA","Análisis de la contrastabilidad"],"fr":["Analyse des modifications de l''interface utilisateur pour détecter les régressions et les améliorations","Évaluation de l''accessibilité sémantique","Vérification de l''accessibilité au clavier","Analyse de la gestion du focus","Vérification de la correction de ARIA","Analyse de la contrastabilité"],"de":["Analyse von Änderungen an der Benutzeroberfläche, um Rückschritte und Verbesserungen zu erkennen","Bewertung der semantischen Barrierefreiheit","Überprüfung der Barrierefreiheit mit der Tastatur","Analyse der Fokushandhabung","Überprüfung der ARIA-Korrektheit","Analyse der Kontrastierbarkeit"],"pt":["Análise de diffs de UI para regressões de acessibilidade","Verificação de semântica e acessibilidade por teclado","Análise de gerenciamento de foco e ARIA","Verificação de contraste e testabilidade","Integração com diffs, PRs e listas de alterações"],"ru":["Анализ diffs UI для регрессий доступности","Проверка семантики и доступности с клавиатуры","Анализ управления фокусом и ARIA","Проверка контраста и тестируемости","Интеграция с diffs, PR и списками изменений"],"ar":["تحليل diffs واجهة المستخدم لانحدارات إمكانية الوصول","فحص الدقة والوصول باللوحة المفاتيح","تحليل إدارة التركيز و ARIA","فحص التباين والاختبار","التكامل مع diffs و PRs وقوائم التغيير"]},"keywords":{"en":["how to use codex-a11y-audit","codex-a11y-audit setup guide","accessibility audit tools","codex-a11y-audit alternative","codex-a11y-audit vs axe","codex-a11y-audit install","UI accessibility testing","ARIA correctness auditing","keyboard access evaluation"],"zh":["codex-a11y-audit","无障碍审计工具","AIエージェント","UI审查","语义和键盘访问性","焦点管理和ARIA正确性"],"ja":["codex-a11y-audit","アクセシビリティ監査ツール","AIエージェント","UIの変更","セマンティクスとキーボードアクセシビリティ","フォーカス管理とARIAの正確性"],"ko":["codex-a11y-audit","접근성 감사 도구","AI 도구","UI 변경 사항","의미와 키보드 접근성","포커스 관리와 ARIA의 정확성"],"es":["auditoría de accesibilidad","herramientas de accesibilidad","accessibilidad web","ARIA","accesibilidad semántica","accesibilidad mediante teclado","gestión del foco","contrastabilidad","codex-a11y-audit"],"fr":["audit d''accessibilité","outils d''accessibilité","accessibilité web","ARIA","accessibilité sémantique","accessibilité au clavier","gestion du focus","contrastabilité","codex-a11y-audit"],"de":["Barrierefreiheitsaudit","Barrierefreiheitstools","Web-Barrierefreiheit","ARIA","semantische Barrierefreiheit","Barrierefreiheit mit der Tastatur","Fokushandhabung","Kontrastierbarkeit","codex-a11y-audit"],"pt":["auditoria de acessibilidade","diffs de UI","regressões de acessibilidade","semântica","acessibilidade por teclado","gerenciamento de foco","ARIA","contraste","testabilidade","ferramentas de acessibilidade"],"ru":["аудит доступности","diffs UI","регрессии доступности","семантика","доступность с клавиатуры","управление фокусом","ARIA","контраст","тестируемость","инструменты доступности"],"ar":["فحص إمكانية الوصول","diffs واجهة المستخدم","انحدارات إمكانية الوصول","الدقة","الوصول باللوحة المفاتيح","إدارة التركيز","ARIA","التباين","الاختبار","أدوات إمكانية الوصول"]}},"owner":"SwitchbackTech","repo":"compass","repoPath":"SwitchbackTech/compass","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.423Z","topics":[],"category":"community","skillMd":{"name":"codex-a11y-audit","description":"Use when reviewing UI diffs, accessibility audits, or flaky UI tests to catch a11y regressions, semantic issues, keyboard/focus problems, and to recommend minimal fixes plus role-based test selectors.","version":"1.0.0","tags":"","bodyPreview":"# Accessibility Change Audit\n\nBrief purpose: review UI changes for accessibility regressions and missing improvements, then propose minimal fixes tied to the diff.\n\n## Overview\n\nThis skill audits UI diffs for semantics, keyboard access, focus management, ARIA correctness, contrast, and testability. It is diff-first: only evaluate changed lines and their immediate context.\n\n## Prerequisites\n\n- A diff, PR, or change list that includes relevant UI files.\n- Optional: a screenshot or description of t","body":"# Accessibility Change Audit\n\nBrief purpose: review UI changes for accessibility regressions and missing improvements, then propose minimal fixes tied to the diff.\n\n## Overview\n\nThis skill audits UI diffs for semantics, keyboard access, focus management, ARIA correctness, contrast, and testability. It is diff-first: only evaluate changed lines and their immediate context.\n\n## Prerequisites\n\n- A diff, PR, or change list that includes relevant UI files.\n- Optional: a screenshot or description of the changed UI state.\n\n## Instructions\n\n### Step 1: Scope the audit to the diff\n\nIdentify changed UI elements, interactions, and styles. Ignore unrelated files.\n\n### Step 2: Run the diff-first checklist\n\nFocus on changes that alter semantics, interaction, or visual affordances.\n\n### Step 3: Produce findings and minimal fixes\n\nTie each issue to a specific change and propose the smallest reasonable fix.\n\n### Step 4: Improve test reliability\n\nRecommend role- and name-based queries for tests instead of data or class selectors.\n\n## Audit Checklist (Diff-First)\n\nSemantics and structure\n\n- Headings follow order and are not skipped.\n- Interactive elements are buttons/links, not divs/spans.\n- Landmarks are present for new regions (main, nav, header, footer, aside).\n- Lists and tables use correct elements (ul/ol/li, th/thead/tbody).\n\nLabels and names\n\n- Inputs have labels or aria-label/aria-labelledby.\n- Icon-only controls have accessible names.\n- Helper text ties to inputs via aria-describedby.\n\nKeyboard and focus\n\n- All interactive elements are keyboard reachable and operable.\n- Focus order follows DOM order (avoid tabIndex > 0).\n- Dialogs/menus trap focus and return focus to trigger.\n\nARIA correctness\n\n- ARIA only when native semantics are insufficient.\n- aria-expanded/controls/pressed reflect actual state.\n- role is correct and not redundant.\n\nVisual and motion\n\n- Text and focus indicators meet contrast requirements.\n- Color is not the only indicator.\n- Motion respects reduced-motion preferences.\n\nMedia and imagery\n\n- Images have meaningful alt or empty alt for decorative.\n- Media controls are accessible and labeled.\n\nTesting reliability\n\n- New elements can be found by role and accessible name.\n- Interaction tests use user flows and semantic queries.\n\n## Minimal Fix Patterns\n\n1. Icon-only button\n\n- Add visible text or aria-label.\n\n2. Clickable non-button\n\n- Convert to <button> or add role=\"button\", tabIndex=0, and Enter/Space handling.\n\n3. Form label\n\n- Add <label htmlFor> or aria-labelledby and connect helper text with aria-describedby.\n\n4. Disclosure\n\n- Toggle uses aria-expanded and aria-controls; update on state change.\n\n5. Dialog\n\n- Use role=\"dialog\", aria-modal, label by heading, and return focus on close.\n\n## Output Format\n\nFindings (ordered by severity):\n\n- [severity] path:line - problem and impact\n  Fix: minimal change suggestion\n\nTests:\n\n- Recommend updates that use role/name queries and user-driven events.\n\nUX/Speed Note:\n\n- Call out any change that impacts perceived speed (layout shifts, heavy DOM, over-rendering).\n\nSeverity scale: blocker, high, medium, low.\n\n## Example Review Output\n\nFindings:\n\n- high `packages/web/src/views/Example.tsx:42` - Clickable div lacks keyboard support; keyboard users cannot activate it.\n  Fix: convert to <button type=\"button\"> or add role, tabIndex, and Enter/Space handlers.\n- medium `packages/web/src/views/Example.tsx:60` - Icon-only control has no accessible name.\n  Fix: add aria-label=\"Add event\".\n\nTests:\n\n- Add a role-based query: getByRole(\"button\", { name: /add event/i }).\n\nUX/Speed Note:\n\n- No layout shift detected; DOM complexity unchanged.\n"},"lastSynced":"2026-03-08T02:07:25.661Z","agentAnalysis":{"suitability":{"en":"Perfect for Accessibility Audit Agents needing to review UI changes for accessibility regressions and propose minimal fixes.","zh":"非常适合需要审查UI更改以发现可访问性回归并提出最小修复的可访问性审计代理。","ja":"アクセシビリティの審査エージェントがUIの変更を審査してアクセシビリティの後退を発見し、最小限の修正を提案するのに最適です。","ko":"접근성 감시 에이전트가 UI 변경 사항을 검토하여 접근성 후퇴를 발견하고 최소한의 수정을 제안하는 데 적합합니다.","es":"Perfecto para Agentes de Auditoría de Accesibilidad que necesitan revisar los cambios de la interfaz de usuario para detectar regresiones de accesibilidad y proponer soluciones mínimas.","fr":"Parfait pour les Agents d''Audit d''Accessibilité qui ont besoin d''examiner les modifications de l''interface utilisateur pour détecter les régressions d''accessibilité et proposer des solutions minimales.","de":"Perfekt für Accessibility-Audit-Agenten, die Benutzeroberflächenänderungen auf Zugriffsregressionen überprüfen und minimale Lösungen vorschlagen müssen.","pt":"Perfeito para Agentes de Auditoria de Acessibilidade que precisam revisar alterações de UI para regressões de acessibilidade e propor correções mínimas.","ru":"Идеально для агентов аудита доступности, которым необходимо просматривать изменения пользовательского интерфейса для регрессий доступности и предлагать минимальные исправления.","ar":"مثالي لعميل تدقيق إمكانية الوصول الذين يحتاجون إلى مراجعة التغييرات في واجهة المستخدم للانحدار في إمكانية الوصول وتقديم إصلاحات mínima."},"recommendation":{"en":"Empowers agents to audit UI diffs for semantics, keyboard access, focus management, ARIA correctness, contrast, and testability, providing diff-first evaluations and proposing minimal fixes tied to the diff using UI files and optional screenshots or descriptions.","zh":"赋予代理审计UI差异的语义、键盘访问、焦点管理、ARIA正确性、对比度和可测试性，提供差异优先评估并提出与差异相关的最小修复，使用UI文件和可选的屏幕截图或描述。","ja":"エージェントにUIの差分の意味、キーボードアクセス、フォーカス管理、ARIAの正しさ、コントラスト、テスト可能性を審査する力を与え、差分優先の評価を提供し、UIファイルとオプションのスクリーンショットまたは説明を使用して差分に結び付けられた最小限の修正を提案します。","ko":"에이전트가 UI의 차이를审査하여 의미, 키보드 접근, 포커스 관리, ARIA의 正确性, 대조 및 테스트 가능성을 제공하고, 차이優先의 평가를 제공하며, UI 파일 및 선택적 스크린샷 또는 설명을 사용하여 차이와 관련된 최소한의 수정을 제안합니다.","es":"Habilita a los agentes a auditar las diferencias de la interfaz de usuario para la semántica, el acceso desde el teclado, la gestión del foco, la corrección de ARIA, el contraste y la posibilidad de prueba, proporcionando evaluaciones dif-first y proponiendo soluciones mínimas vinculadas a la dif mediante archivos de interfaz de usuario y capturas de pantalla o descripciones opcionales.","fr":"Permet aux agents d''auditer les différences d''interface utilisateur pour la sémantique, l''accès au clavier, la gestion du focus, la correction ARIA, le contraste et la testabilité, en fournissant des évaluations diff-first et en proposant des solutions minimales liées à la diff à l''aide de fichiers d''interface utilisateur et de captures d''écran ou de descriptions facultatives.","de":"Ermächtigt Agenten, Benutzeroberflächendifferenzen für Semantik, Tastaturzugriff, Fokusverwaltung, ARIA-Korrektheit, Kontrast und Testbarkeit zu überprüfen und diff-First-Bewertungen bereitzustellen sowie minimale Lösungen vorzuschlagen, die an die Differenz geknüpft sind, unter Verwendung von Benutzeroberflächen-Dateien und optionalen Screenshots oder Beschreibungen.","pt":"Habilita os agentes a auditar diferenças de UI para semântica, acesso ao teclado, gerenciamento de foco, correção da ARIA, contraste e testabilidade, fornecendo avaliações dif-first e propondo correções mínimas vinculadas à diferença usando arquivos de UI e capturas de tela ou descrições opcionais.","ru":"Наделяет агентов возможностью аудита различий пользовательского интерфейса для семантики, доступа с клавиатуры, управления фокусом, правильности ARIA, контраста и тестируемости, предоставляя оценки diff-first и предлагая минимальные исправления, привязанные к различию, используя файлы пользовательского интерфейса и необязательные скриншоты или описания.","ar":"يمنح الوكيل القدرة على تدقيق الفروق في واجهة المستخدم من أجل الدلالات و إمكانية الوصول باللوحة و إدارة التوجيه و دقة ARIA و التباين و الاختبار ، و يقدم تقييمات diff-first و يقترح إصلاحات mínima مرتبطة بالفروق باستخدام ملفات واجهة المستخدم و لقطات شاشة أو описания إختيارية."},"useCases":{"en":["Auditing UI changes for accessibility regressions","Proposing minimal fixes for UI diffs","Evaluating semantics and keyboard access in UI files","Reviewing ARIA correctness and contrast in UI changes"],"zh":["审查UI更改以发现可访问性回归","为UI差异提议最小修复","评估UI文件中的语义和键盘访问","审查UI更改中的ARIA正确性和对比度"],"ja":["アクセシビリティの後退を発見するためのUIの変更の審査","UIの差分の最小限の修正の提案","UIファイル内の意味とキーボードアクセスの評価","UIの変更内のARIAの正しさとコントラストの審査"],"ko":["접근성 후퇴를 발견하기 위한 UI 변경 사항의 검토","UI 차이의 최소한의 수정 제안","UI 파일 내의 의미 및 키보드 접근 평가","UI 변경 사항 내의 ARIA의 正确性 및 대조 검토"],"es":["Auditoría de cambios de la interfaz de usuario para regresiones de accesibilidad","Propuesta de soluciones mínimas para diferencias de la interfaz de usuario","Evaluación de la semántica y el acceso desde el teclado en archivos de la interfaz de usuario","Revisión de la corrección de ARIA y el contraste en los cambios de la interfaz de usuario"],"fr":["Audit des modifications d''interface utilisateur pour les régressions d''accessibilité","Proposition de solutions minimales pour les différences d''interface utilisateur","Évaluation de la sémantique et de l''accès au clavier dans les fichiers d''interface utilisateur","Révision de la correction ARIA et du contraste dans les modifications d''interface utilisateur"],"de":["Überprüfung von Benutzeroberflächenänderungen auf Zugriffsregressionen","Vorschlag von minimalen Lösungen für Benutzeroberflächendifferenzen","Bewertung der Semantik und der Tastaturzugriff in Benutzeroberflächen-Dateien","Überprüfung der ARIA-Korrektheit und des Kontrasts in Benutzeroberflächenänderungen"],"pt":["Auditoria de alterações de UI para regressões de acessibilidade","Propor correções mínimas para diferenças de UI","Avaliar semântica e acesso ao teclado em arquivos de UI","Revisar correção da ARIA e contraste em alterações de UI"],"ru":["Аудит изменений пользовательского интерфейса для регрессий доступности","Предложение минимальных исправлений для различий пользовательского интерфейса","Оценка семантики и доступа с клавиатуры в файлах пользовательского интерфейса","Проверка правильности ARIA и контраста в изменениях пользовательского интерфейса"],"ar":["تدقيق التغييرات في واجهة المستخدم للانحدار في إمكانية الوصول ","اقتراح إصلاحات mínima للفروق في واجهة المستخدم","تقييم الدلالات و إمكانية الوصول باللوحة في ملفات واجهة المستخدم","مراجعة دقة ARIA و التباين في التغييرات في واجهة المستخدم"]},"limitations":{"en":["Requires a diff, PR, or change list that includes relevant UI files","Optional: requires a screenshot or description of the UI change"],"zh":["需要包含相关UI文件的差异、PR或更改列表","可选：需要UI更改的屏幕截图或描述"],"ja":["関連するUIファイルを含む差分、PR、または変更リストが必要","オプション：UIの変更のスクリーンショットまたは説明が必要"],"ko":["관련 UI 파일을 포함하는 차이, PR 또는 변경 목록이 필요","선택적：UI 변경 사항의 스크린샷 또는 설명이 필요"],"es":["Requiere una diferencia, una solicitud de extracción o una lista de cambios que incluya archivos de la interfaz de usuario relevantes","Opcional: requiere una captura de pantalla o una descripción del cambio de la interfaz de usuario"],"fr":["Nécessite une différence, une demande d''extraction ou une liste de modifications qui inclut des fichiers d''interface utilisateur pertinents","Facultatif : nécessite une capture d''écran ou une description du changement d''interface utilisateur"],"de":["Benötigt eine Differenz, einen Pull-Request oder eine Änderungsliste, die relevante Benutzeroberflächen-Dateien enthält","Optional: Benötigt einen Screenshot oder eine Beschreibung der Benutzeroberflächenänderung"],"pt":["Exige uma diferença, PR ou lista de alterações que inclua arquivos de UI relevantes","Opcional: exige uma captura de tela ou descrição da alteração de UI"],"ru":["Требует различия, PR или списка изменений, включающего соответствующие файлы пользовательского интерфейса","Необязательно: требует скриншота или описания изменения пользовательского интерфейса"],"ar":["يتطلب فروقا أو PR أو قائمة التغييرات التي تشمل ملفات واجهة المستخدم ذات الصلة ","إختياري: يتطلب لقطة شاشة أو وصف للتغيير في واجهة المستخدم"]},"version":4},"contentHash":"f471d1d3a8f3013c119671ec28b060ee361c2c1b0ef07db415802784cbae8706","qualityScore":55}');
