INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SwitchbackTech/compass/codex-a11y-audit', 'codex-a11y-audit', 'SwitchbackTech', 'compass', 'community', 'codex-a11y-audit SwitchbackTech compass community codex-a11y-audit is a task manager for engineers that audits UI changes for accessibility regressions. It helps developers review and propose minimal fixes for UI diffs. codex-a11y-audit是一款无障碍审计工具，用于审查UI变更的无障碍回归和缺失改进 codex-a11y-auditはアクセシビリティ監査ツールであり、UIの変更を審査してアクセシビリティの回帰と改善を提案します codex-a11y-audit는 접근성 감사 도구로서 UI 변경 사항을審查하여 접근성의 회귀와 개선을 제안합니다 codex-a11y-audit es una herramienta de auditoría de accesibilidad que analiza cambios en la interfaz de usuario para detectar regresiones y mejoras codex-a11y-audit est un outil d''audit d''accessibilité qui analyse les modifications de l''interface utilisateur pour détecter les régressions et les améliorations codex-a11y-audit ist ein Tool zur Überprüfung der Barrierefreiheit, das Änderungen an der Benutzeroberfläche analysiert, um Rückschritte und Verbesserungen zu erkennen O Codex-A11y-Audit é uma ferramenta de auditoria de acessibilidade para diffs de UI, ajudando a identificar regressões e melhorias Codex-A11y-Audit - это инструмент для аудита доступности в diffs UI, помогающий выявлять регрессии и улучшения Codex-A11y-Audit هو أداة فحص إمكانية الوصول ل diffs واجهة المستخدم، مما يساعد في تحديد الانحدارات والتغييرات how to use codex-a11y-audit codex-a11y-audit setup guide accessibility audit tools codex-a11y-audit alternative codex-a11y-audit vs axe codex-a11y-audit install UI accessibility testing ARIA correctness auditing keyboard access evaluation codex-a11y-audit 无障碍审计工具 AIエージェント UI审查 语义和键盘访问性 焦点管理和ARIA正确性 Audits UI diffs for semantics and accessibility regressions Evaluates keyboard access and focus management in changed lines Checks ARIA correctness and contrast in UI components Supports diff-first evaluation for efficient auditing Proposes minimal fixes tied to the diff for easy implementation codex-a11y-audit is a diff-first accessibility audit tool that evaluates changed lines and their immediate context for semantics, keyboard access, and ARIA correctness.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eurofit/store/programmatic-seo', 'community', 'eurofit', 'store', 'eurofit/store', 'programmatic-seo', 0, 0, 55, '2026-03-07T12:46:33.437Z', '2026-03-07T12:54:09.340Z', '48c12d98242175255f39e4b39417b7ba47fa23897e6306d36c632ab41006e289', '{"id":"eurofit/store/programmatic-seo","name":"programmatic-seo","description":{"en":"Programmatic SEO generates SEO-optimized pages at scale using templates and data, helping developers create valuable content and avoid penalties. This skill benefits developers and marketers seeking to improve page ranking.","zh":"程序化SEO是使用模板和数据创建SEO优化页面的技术，帮助开发者避免薄内容惩罚","ja":"プログラムSEOは、テンプレートとデータを使用してSEO最適化されたページを作成する技術で、薄内容ペナルティを回避するのに役立ちます","ko":"프로그램적 SEO는 템플릿 및 데이터를 사용하여 SEO 최적화된 페이지를 생성하는 기술로, 얇은 콘텐츠 페널티를 피하는 데 도움이 됩니다","es":"El SEO programático implica la creación de páginas optimizadas a escala utilizando plantillas y datos","fr":"Le SEO programmatique consiste à créer des pages optimisées à grande échelle en utilisant des modèles et des données","de":"Das programmatische SEO beinhaltet die Erstellung von optimierten Seiten im großen Maßstab mit Hilfe von Vorlagen und Daten","pt":"A otimização de SEO programática permite criar páginas otimizadas para SEO em escala usando templates e dados.","ru":"Программная SEO-оптимизация позволяет создавать SEO-оптимизированные страницы в масштабе с помощью шаблонов и данных.","ar":"تحسين محركات البحث البرمجي يسمح بإنشاء صفحات محسّنة للبحث في الكتلة باستخدام القوالب والبيانات."},"seo":{"title":{"en":"Programmatic SEO: Setup Guide for AI Agents","zh":"程序化SEO搭建指南","ja":"プログラムSEOのベストプラクティス","ko":"프로그램적 SEO 설정 가이드","es":"Guía de configuración de SEO programático","fr":"Mise en place de la stratégie SEO programmatique","de":"Leitfaden für programmatisches SEO-Setup","pt":"Guia de Configuração de Otimização de SEO Programática","ru":"Настройка Программной SEO-Оптимизации: Руководство","ar":"دليل إعداد تحسين محركات البحث البرمجي"},"description":{"en":"Unlock the power of programmatic SEO and create scalable, SEO-optimized pages with our expert guide - learn how to avoid thin content penalties","zh":"了解程序化SEO的技术细节，学习如何使用模板和数据创建SEO优化页面","ja":"プログラムSEOのテクニカルな詳細をマスターし、SEO最適化されたページを作成する方法を学びましょう","ko":"프로그램적 SEO의 기술적인 세부 사항을 배우고 템플릿 및 데이터를 사용하여 SEO 최적화된 페이지를 생성하는 방법을 알아보세요","es":"Aprende a crear páginas optimizadas para motores de búsqueda a escala con plantillas y datos","fr":"Découvrez comment créer des pages optimisées pour les moteurs de recherche à grande échelle avec des modèles et des données","de":"Erfahren Sie, wie Sie suchmaschinenoptimierte Seiten im großen Maßstab mit Vorlagen und Daten erstellen","pt":"Aprenda a criar páginas otimizadas para SEO em escala usando templates e dados com a nossa ferramenta de SEO programática","ru":"Используйте наш ИИ Агент для создания SEO-оптимизированных страниц в масштабе с помощью шаблонов и данных","ar":"استخدم أداة تحسين محركات البحث البرمجي لإنشاء صفحات محسّنة للبحث في الكتلة باستخدام القوالب والبيانات"},"definition":{"en":"programmatic-seo is a technique for building SEO-optimized pages at scale using templates and data to provide value and avoid thin content penalties","zh":"程序化SEO是使用模板和数据创建SEO优化页面的技术","ja":"プログラムSEOは、テンプレートとデータを使用してSEO最適化されたページを作成する技術です","ko":"프로그램적 SEO는 템플릿 및 데이터를 사용하여 SEO 최적화된 페이지를 생성하는 기술입니다","es":"El SEO programático es una técnica para crear páginas web optimizadas","fr":"Le SEO programmatique est une technique pour créer des pages web optimisées","de":"Das programmatische SEO ist eine Technik zur Erstellung von optimierten Webseiten","pt":"Otimização de SEO programática é uma técnica que usa templates e dados para criar páginas otimizadas para SEO em escala.","ru":"Программная SEO-оптимизация - это техника, использующая шаблоны и данные для создания SEO-оптимизированных страниц в масштабе.","ar":"تحسين محركات البحث البرمجي هو تقنية تستخدم القوالب والبيانات لإنشاء صفحات محسّنة للبحث في الكتلة."},"features":{"en":["Checks for product marketing context using .cursor/product-marketing-context.md","Designs programmatic SEO strategies to create pages that rank","Avoids thin content penalties using data-driven templates","Utilizes scalable templates for efficient page creation","Reads context from .cursor/product-marketing-context.md to inform SEO decisions"],"zh":["使用模板创建SEO优化页面","数据驱动的SEO优化","避免薄内容惩罚","大规模创建SEO优化页面","使用产品营销上下文优化页面"],"ja":["テンプレートを使用してSEO最適化されたページを作成","データ駆動のSEO最適化","薄内容ペナルティを回避","大規模にSEO最適化されたページを作成","製品マーケティングコンテキストを使用してページを最適化"],"ko":["템플릿을 사용하여 SEO 최적화된 페이지 생성","데이터 주도 SEO 최적화","얇은 콘텐츠 페널티 피하기","대규모 SEO 최적화된 페이지 생성","제품 마케팅 컨텍스트 사용 페이지 최적화"],"es":["Uso de plantillas para la creación de páginas","Integración de datos para la optimización de contenido","Evitación de penalizaciones por contenido delgado","Creación de páginas que aportan valor y clasifican en los motores de búsqueda","Uso de contexto de marketing de productos para la optimización","Creación de páginas a escala utilizando técnicas de programación"],"fr":["Utilisation de modèles pour la création de pages","Intégration de données pour l''optimisation de contenu","Évitement des pénalités pour contenu mince","Création de pages qui apportent de la valeur et classent dans les moteurs de recherche","Utilisation du contexte de marketing de produits pour l''optimisation","Création de pages à grande échelle en utilisant des techniques de programmation"],"de":["Verwendung von Vorlagen für die Erstellung von Seiten","Integration von Daten für die Optimierung von Inhalten","Vermeidung von Strafen für dünnen Inhalt","Erstellung von Seiten, die Wert bieten und in Suchmaschinen gelistet werden","Verwendung des Produktmarketing-Kontexts für die Optimierung","Erstellung von Seiten im großen Maßstab mit Hilfe von Programmiertechniken"],"pt":["Criação de páginas otimizadas para SEO em escala","Uso de templates e dados para personalizar o conteúdo","Evita penalidades por conteúdo fino","Otimização para motores de busca","Integração com ferramentas de marketing de produto","Análise de contexto de marketing de produto"],"ru":["Создание SEO-оптимизированных страниц в масштабе","Использование шаблонов и данных для персонализации контента","Избежание штрафов за тонкий контент","Оптимизация для поисковых систем","Интеграция с инструментами маркетинга продукта","Анализ контекста маркетинга продукта"],"ar":["إنشاء صفحات محسّنة للبحث في الكتلة","استخدام القوالب والبيانات لتحسين المحتوى","تجنب العقوبات لعدم وجود محتوى كاف","تحسين محركات البحث","التكامل مع أدوات تسويق المنتج","تحليل سياق تسويق المنتج"]},"keywords":{"en":["how to use programmatic-seo","programmatic-seo setup guide","programmatic-seo vs traditional seo","programmatic-seo install","what is programmatic-seo","programmatic-seo alternative","programmatic-seo for ai agents","programmatic-seo best practices","programmatic-seo template creation"],"zh":["程序化SEO","SEO优化页面","模板创建页面","数据驱动SEO","薄内容惩罚","产品营销上下文","AIエージェント","SEO技术"],"ja":["プログラムSEO","SEO最適化されたページ","テンプレートを作成ページ","データ駆動のSEO","薄内容ペナルティ","製品マーケティングコンテキスト","AIエージェント","SEO技術"],"ko":["프로그램적 SEO","SEO 최적화된 페이지","템플릿 생성 페이지","데이터 주도 SEO","얇은 콘텐츠 페널티","제품 마케팅 컨텍스트","AI 에이전트","SEO 기술"],"es":["SEO programático","optimización de motores de búsqueda","creación de páginas a escala","plantillas de página","integración de datos","evitación de penalizaciones","contenido de valor","clasificación en motores de búsqueda","Herramientas de AI para SEO","Agentes de IA para marketing"],"fr":["SEO programmatique","optimisation des moteurs de recherche","création de pages à grande échelle","modèles de page","intégration de données","évitement des pénalités","contenu de valeur","classement dans les moteurs de recherche","Outils d''IA pour le SEO","Agents d''IA pour le marketing"],"de":["programmatisches SEO","Suchmaschinenoptimierung","Erstellung von Seiten im großen Maßstab","Seitenvorlagen","Datenintegration","Vermeidung von Strafen","wertvoller Inhalt","Listung in Suchmaschinen","AI-Tools für SEO","KI-Agents für Marketing"],"pt":["otimização de SEO programática","SEO em escala","templates e dados para SEO","evitar penalidades por conteúdo fino","otimização para motores de busca","ferramentas de marketing de produto","análise de contexto de marketing de produto","Guia de configuração de SEO programática"],"ru":["Программная SEO-оптимизация","SEO в масштабе","шаблоны и данные для SEO","избежание штрафов за тонкий контент","оптимизация для поисковых систем","инструменты маркетинга продукта","анализ контекста маркетинга продукта","Настройка программной SEO-оптимизации"],"ar":["تحسين محركات البحث البرمجي","تحسين محركات البحث في الكتلة","القوالب والبيانات لتحسين محركات البحث","تجنب العقوبات لعدم وجود محتوى كاف","تحسين محركات البحث","أدوات تسويق المنتج","تحليل سياق تسويق المنتج","دليل إعداد تحسين محركات البحث البرمجي"]}},"owner":"eurofit","repo":"store","repoPath":"eurofit/store","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.437Z","topics":[],"category":"community","skillMd":{"name":"programmatic-seo","description":"When the user wants to create SEO-driven pages at scale using templates and data. Also use when the user mentions programmatic SEO, template pages, pages at scale, directory pages, location pages, [keyword] + [city] pages, comparison pages, integration pages, or building many pages for SEO. For auditing existing SEO issues, see seo-audit.","version":"1.0.0","bodyPreview":"# Programmatic SEO\n\nYou are an expert in programmatic SEO—building SEO-optimized pages at scale using templates and data. Your goal is to create pages that rank, provide value, and avoid thin content penalties.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.cursor/product-marketing-context.md` exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore designing a programmatic SEO strate","body":"# Programmatic SEO\n\nYou are an expert in programmatic SEO—building SEO-optimized pages at scale using templates and data. Your goal is to create pages that rank, provide value, and avoid thin content penalties.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.cursor/product-marketing-context.md` exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore designing a programmatic SEO strategy, understand:\n\n1. **Business Context**\n   - What''s the product/service?\n   - Who is the target audience?\n   - What''s the conversion goal for these pages?\n\n2. **Opportunity Assessment**\n   - What search patterns exist?\n   - How many potential pages?\n   - What''s the search volume distribution?\n\n3. **Competitive Landscape**\n   - Who ranks for these terms now?\n   - What do their pages look like?\n   - Can you realistically compete?\n\n---\n\n## Core Principles\n\n### 1. Unique Value Per Page\n\n- Every page must provide value specific to that page\n- Not just swapped variables in a template\n- Maximize unique content—the more differentiated, the better\n\n### 2. Proprietary Data Wins\n\nHierarchy of data defensibility:\n\n1. Proprietary (you created it)\n2. Product-derived (from your users)\n3. User-generated (your community)\n4. Licensed (exclusive access)\n5. Public (anyone can use—weakest)\n\n### 3. Clean URL Structure\n\n**Always use subfolders, not subdomains**:\n\n- Good: `yoursite.com/templates/resume/`\n- Bad: `templates.yoursite.com/resume/`\n\n### 4. Genuine Search Intent Match\n\nPages must actually answer what people are searching for.\n\n### 5. Quality Over Quantity\n\nBetter to have 100 great pages than 10,000 thin ones.\n\n### 6. Avoid Google Penalties\n\n- No doorway pages\n- No keyword stuffing\n- No duplicate content\n- Genuine utility for users\n\n---\n\n## The 12 Playbooks (Overview)\n\n| Playbook     | Pattern                               | Example                   |\n| ------------ | ------------------------------------- | ------------------------- |\n| Templates    | \"[Type] template\"                     | \"resume template\"         |\n| Curation     | \"best [category]\"                     | \"best website builders\"   |\n| Conversions  | \"[X] to [Y]\"                          | \"$10 USD to GBP\"          |\n| Comparisons  | \"[X] vs [Y]\"                          | \"webflow vs wordpress\"    |\n| Examples     | \"[type] examples\"                     | \"landing page examples\"   |\n| Locations    | \"[service] in [location]\"             | \"dentists in austin\"      |\n| Personas     | \"[product] for [audience]\"            | \"crm for real estate\"     |\n| Integrations | \"[product A] [product B] integration\" | \"slack asana integration\" |\n| Glossary     | \"what is [term]\"                      | \"what is pSEO\"            |\n| Translations | Content in multiple languages         | Localized content         |\n| Directory    | \"[category] tools\"                    | \"ai copywriting tools\"    |\n| Profiles     | \"[entity name]\"                       | \"stripe ceo\"              |\n\n**For detailed playbook implementation**: See [references/playbooks.md](references/playbooks.md)\n\n---\n\n## Choosing Your Playbook\n\n| If you have...            | Consider...           |\n| ------------------------- | --------------------- |\n| Proprietary data          | Directories, Profiles |\n| Product with integrations | Integrations          |\n| Design/creative product   | Templates, Examples   |\n| Multi-segment audience    | Personas              |\n| Local presence            | Locations             |\n| Tool or utility product   | Conversions           |\n| Content/expertise         | Glossary, Curation    |\n| Competitor landscape      | Comparisons           |\n\nYou can layer multiple playbooks (e.g., \"Best coworking spaces in San Diego\").\n\n---\n\n## Implementation Framework\n\n### 1. Keyword Pattern Research\n\n**Identify the pattern:**\n\n- What''s the repeating structure?\n- What are the variables?\n- How many unique combinations exist?\n\n**Validate demand:**\n\n- Aggregate search volume\n- Volume distribution (head vs. long tail)\n- Trend direction\n\n### 2. Data Requirements\n\n**Identify data sources:**\n\n- What data populates each page?\n- Is it first-party, scraped, licensed, public?\n- How is it updated?\n\n### 3. Template Design\n\n**Page structure:**\n\n- Header with target keyword\n- Unique intro (not just variables swapped)\n- Data-driven sections\n- Related pages / internal links\n- CTAs appropriate to intent\n\n**Ensuring uniqueness:**\n\n- Each page needs unique value\n- Conditional content based on data\n- Original insights/analysis per page\n\n### 4. Internal Linking Architecture\n\n**Hub and spoke model:**\n\n- Hub: Main category page\n- Spokes: Individual programmatic pages\n- Cross-links between related spokes\n\n**Avoid orphan pages:**\n\n- Every page reachable from main site\n- XML sitemap for all pages\n- Breadcrumbs with structured data\n\n### 5. Indexation Strategy\n\n- Prioritize high-volume patterns\n- Noindex very thin variations\n- Manage crawl budget thoughtfully\n- Separate sitemaps by page type\n\n---\n\n## Quality Checks\n\n### Pre-Launch Checklist\n\n**Content quality:**\n\n- [ ] Each page provides unique value\n- [ ] Answers search intent\n- [ ] Readable and useful\n\n**Technical SEO:**\n\n- [ ] Unique titles and meta descriptions\n- [ ] Proper heading structure\n- [ ] Schema markup implemented\n- [ ] Page speed acceptable\n\n**Internal linking:**\n\n- [ ] Connected to site architecture\n- [ ] Related pages linked\n- [ ] No orphan pages\n\n**Indexation:**\n\n- [ ] In XML sitemap\n- [ ] Crawlable\n- [ ] No conflicting noindex\n\n### Post-Launch Monitoring\n\nTrack: Indexation rate, Rankings, Traffic, Engagement, Conversion\n\nWatch for: Thin content warnings, Ranking drops, Manual actions, Crawl errors\n\n---\n\n## Common Mistakes\n\n- **Thin content**: Just swapping city names in identical content\n- **Keyword cannibalization**: Multiple pages targeting same keyword\n- **Over-generation**: Creating pages with no search demand\n- **Poor data quality**: Outdated or incorrect information\n- **Ignoring UX**: Pages exist for Google, not users\n\n---\n\n## Output Format\n\n### Strategy Document\n\n- Opportunity analysis\n- Implementation plan\n- Content guidelines\n\n### Page Template\n\n- URL structure\n- Title/meta templates\n- Content outline\n- Schema markup\n\n---\n\n## Task-Specific Questions\n\n1. What keyword patterns are you targeting?\n2. What data do you have (or can acquire)?\n3. How many pages are you planning?\n4. What does your site authority look like?\n5. Who currently ranks for these terms?\n6. What''s your technical stack?\n\n---\n\n## Related Skills\n\n- **seo-audit**: For auditing programmatic pages after launch\n- **schema-markup**: For adding structured data\n- **competitor-alternatives**: For comparison page frameworks\n"},"lastSynced":"2026-03-07T12:54:09.340Z","agentAnalysis":{"suitability":{"en":"Perfect for Marketing Agents needing automated SEO-optimized page generation at scale.","zh":"非常适合需要在大规模生成SEO优化页面的营销代理","ja":"マーケティングエージェントが大規模にSEO最適化されたページを自動生成する必要がある場合に最適","ko":"대규모 SEO 최적화 페이지 생성이 필요한 마케팅 에이전트에게 적합","es":"Perfecto para agentes de marketing que necesitan generación de páginas automatizadas y optimizadas para SEO a gran escala.","fr":"Parfait pour les agents de marketing qui ont besoin d''une génération de pages automatisée et optimisée pour le SEO à grande échelle.","de":"Perfekt für Marketing-Agenten, die eine automatisierte Erstellung von SEO-optimierten Seiten im großen Maßstab benötigen.","pt":"Perfeito para Agentes de Marketing que precisam de geração de páginas otimizadas para SEO de forma automatizada em larga escala.","ru":"Идеально подходит для маркетинговых агентов, которым требуется автоматизированная генерация страниц, оптимизированных для SEO, в крупном масштабе.","ar":"مثالي لوسائل الإعلام الترويجية التي تحتاج إلى توليد صفحات محسّنة لـ SEO آليًا على نطاق واسع."},"recommendation":{"en":"Empowers agents to generate valuable content using templates and data, avoiding thin content penalties and improving page ranking through SEO-optimized pages, leveraging data-driven approaches and template-based content creation.","zh":"赋予代理商使用模板和数据生成有价值内容的能力，避免薄内容惩罚并通过SEO优化页面提高页面排名，利用数据驱动的方法和基于模板的内容创建","ja":"エージェントがテンプレートとデータを使用して有価値なコンテンツを生成する能力を与え、薄コンテンツのペナルティを回避し、SEO最適化されたページを使用してページランキングを向上させ、データドリブンアプローチとテンプレートベースのコンテンツ作成を利用","ko":"에이전트가 템플릿과 데이터를 사용하여 가치 있는 콘텐츠를 생성할 수 있는 능력을 부여하여 얇은 콘텐츠의 패널티를 피하고 SEO 최적화된 페이지를 통해 페이지 랭킹을 향상시키고 데이터 주도 접근 방식과 템플릿 기반 콘텐츠 생성을 활용","es":"Habilita a los agentes a generar contenido valioso utilizando plantillas y datos, evitando penalizaciones por contenido delgado y mejorando el posicionamiento de la página a través de páginas optimizadas para SEO, aprovechando enfoques basados en datos y creación de contenido basada en plantillas.","fr":"Permet aux agents de générer du contenu précieux en utilisant des modèles et des données, en évitant les pénalités de contenu mince et en améliorant le classement des pages via des pages optimisées pour le SEO, en exploitant les approches basées sur les données et la création de contenu basée sur des modèles.","de":"Ermächtigt Agenten, wertvollen Inhalt mit Hilfe von Vorlagen und Daten zu erstellen, indem es Strafmaßnahmen wegen dünner Inhalte vermeidet und die Seitenplatzierung durch SEO-optimierte Seiten verbessert, indem es datengetriebene Ansätze und vorlagenbasierte Inhaltserschaffung nutzt.","pt":"Habilita os agentes a gerar conteúdo valioso usando templates e dados, evitando penalidades por conteúdo fino e melhorando o ranqueamento de páginas por meio de páginas otimizadas para SEO, aproveitando abordagens baseadas em dados e criação de conteúdo baseada em templates.","ru":"Наделяет агентов возможн