INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/create-pr', 'create-pr', 'getsentry', 'skills', 'official', 'create-pr getsentry skills official tag-production The create-pr skill redirects to sentry-skills:pr-writer, providing a canonical workflow for creating and editing pull requests, benefiting developers who need to manage code changes efficiently. create-pr 是 Sentry-Skills 中的 PR 编写器的别名，用于创建和编辑拉取请求 create-pr は Sentry-Skills の PR 作成ツールの別名で、プルリクエストの作成と編集に使用されます create-pr은 Sentry-Skills의 PR 작성기의 別名으로, 풀 리퀘스트의 생성과 편집에 사용됩니다 Create-pr es un alias de sentry-skills:pr-writer que permite crear y editar solicitudes de extracción de forma compatible Create-pr est un alias de sentry-skills:pr-writer qui permet de créer et d''éditer des demandes d''extraction de manière compatible Create-pr ist ein Alias von sentry-skills:pr-writer, der die Erstellung und Bearbeitung von Pull-Requests in kompatibler Weise ermöglicht O Create-PR é um alias para sentry-skills:pr-writer, usado para criar e editar pull requests de forma eficiente. Create-PR является псевдонимом для sentry-skills:pr-writer, используемым для создания и редактирования pull requests эффективным образом для ИИ Агентов Create-PR هو اسم مستعار لسentry-skills:pr-writer ، يستخدم لإنشاء وتحرير طلبات السحب بفعالية لأدوات الذكاء الاصطناعي how to use create-pr create-pr alternative create-pr setup guide what is create-pr create-pr vs sentry-skills:pr-writer create-pr install sentry-skills:pr-writer workflow create-pr Sentry-Skills PR 编写器 拉取请求 代码审查 AI 工具 AI エージェント 代码管理 版本控制 Redirects to sentry-skills:pr-writer for a unified PR writing workflow Utilizes the same workflow and conventions as the canonical PR writing skill Supports invocation via create-pr for compatibility Runs the same workflow as sentry-skills:pr-writer when invoked Maintains compatibility with legacy skill names create-pr is an alias for sentry-skills:pr-writer, maintaining compatibility while utilizing the same workflow and conventions as the canonical PR writing skill');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/skill-creator', 'official', 'getsentry', 'skills', 'getsentry/skills', 'skill-creator', 360, 11, 55, '2026-03-06T00:20:36Z', '2026-03-06T05:14:49.777Z', '5322732a00a418d0b77aa61ace28df67ad765541724e63b4c946f3e7ef24daf7', '{"id":"getsentry/skills/skill-creator","name":"skill-creator","description":{"en":"The skill-creator skill is an alias for sentry-skills:skill-writer, used for compatibility, and redirects to the canonical skill authoring workflow, benefiting developers who need to create and update skills.","zh":"Skill Creator是sentry-skills:skill-writer的别名，用于兼容性目的。它遵循相同的工作流程和约定","ja":"Skill Creatorはsentry-skills:skill-writerのエイリアスです。互換性のために使用され、同じワークフローと規約に従います","ko":"Skill Creator는 sentry-skills:skill-writer의 별칭으로 호환성을 위해 사용됩니다. 동일한 워크플로와 규약을 따릅니다","es":"El skill-creator es un alias de sentry-skills:skill-writer que permite a los desarrolladores crear y actualizar habilidades utilizando tecnologías como CLI.","fr":"Le skill-creator est un alias de sentry-skills:skill-writer qui permet aux développeurs de créer et de mettre à jour des compétences en utilisant des technologies comme CLI.","de":"Der skill-creator ist ein Alias von sentry-skills:skill-writer, der es Entwicklern ermöglicht, Fähigkeiten mit Technologien wie CLI zu erstellen und zu aktualisieren.","pt":"O skill-creator é um alias para sentry-skills:skill-writer, permitindo a criação e atualização de habilidades de forma compatível","ru":"Skill-creator является псевдонимом для sentry-skills:skill-writer,允яя создавать и обновлять навыки ИИ Агентов в совместимом режиме","ar":"skill-creator هو اسم مستعار ل sentry-skills:skill-writer، مما يسمح بإنشاء وتحديث المهارات بطريقة متوافقة"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"]