INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/skill-creator', 'skill-creator', 'getsentry', 'skills', 'official', 'skill-creator getsentry skills official tag-production The skill-creator skill is an alias for sentry-skills:skill-writer, used for compatibility, and redirects to the canonical skill authoring workflow, benefiting developers who need to create and update skills. Skill Creator是sentry-skills:skill-writer的别名，用于兼容性目的。它遵循相同的工作流程和约定 Skill Creatorはsentry-skills:skill-writerのエイリアスです。互換性のために使用され、同じワークフローと規約に従います Skill Creator는 sentry-skills:skill-writer의 별칭으로 호환성을 위해 사용됩니다. 동일한 워크플로와 규약을 따릅니다 El skill-creator es un alias de sentry-skills:skill-writer que permite a los desarrolladores crear y actualizar habilidades utilizando tecnologías como CLI. Le skill-creator est un alias de sentry-skills:skill-writer qui permet aux développeurs de créer et de mettre à jour des compétences en utilisant des technologies comme CLI. Der skill-creator ist ein Alias von sentry-skills:skill-writer, der es Entwicklern ermöglicht, Fähigkeiten mit Technologien wie CLI zu erstellen und zu aktualisieren. O skill-creator é um alias para sentry-skills:skill-writer, permitindo a criação e atualização de habilidades de forma compatível Skill-creator является псевдонимом для sentry-skills:skill-writer,允яя создавать и обновлять навыки ИИ Агентов в совместимом режиме skill-creator هو اسم مستعار ل sentry-skills:skill-writer، مما يسمح بإنشاء وتحديث المهارات بطريقة متوافقة how to use skill-creator what is skill-creator skill-creator alternative sentry-skills:skill-writer vs skill-creator skill-creator setup guide skill-creator install skill-creator documentation skill-creator workflow skill-creator conventions AIエージェント Skill Creator sentry-skills:skill-writer 兼容性 canonical skill authoring workflow AI工具 Redirects to sentry-skills:skill-writer for canonical skill authoring Maintains compatibility with legacy skill name Runs the same workflow as sentry-skills:skill-writer Follows conventions documented in sentry-skills:skill-writer Invoked via skill-creator for skill creation and updates skill-creator is an alias for sentry-skills:skill-writer, maintaining compatibility and redirecting to the canonical skill authoring workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('qwibitai/nanoclaw/debug', 'community', 'qwibitai', 'nanoclaw', 'qwibitai/nanoclaw', 'debug', 14853, 2286, 55, '2026-02-26T04:54:01Z', '2026-02-26T08:26:19.181Z', 'd774a2bc45d62e2e388a7f3de72afd761b0025f6666c3cc698c496c1805fa10e', '{"id":"qwibitai/nanoclaw/debug","name":"debug","description":{"zh":"Debug - A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security and efficiency","ja":"Debug - A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security and efficiency","ko":"Debug - A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security and efficiency","es":"El agente de depuración es una herramienta de AI ligera que conecta con WhatsApp y ofrece memoria y trabajos programados","fr":"L''agent de débogage est un outil d''AI léger qui se connecte à WhatsApp et offre une mémoire et des tâches planifiées","de":"Der Debug-Agent ist ein leichtes AI-Tool, das mit WhatsApp verbindet und Speicher und geplante Aufgaben bietet","pt":"O Depurar é uma ferramenta de Agente de IA leve e segura que conecta ao WhatsApp e executa tarefas agendadas diretamente no Agents SDK da Anthropic","ru":"Отладка - это легковесный и безопасный инструмент ИИ Агенты, который подключается к WhatsApp и выполняет запланированные задачи непосредственно в Agents SDK от Anthropic","ar":"تصحيح أخطاء هو أداة خفيفة وآمنة لتقنيات الذكاء الاصطناعي، تتمثل في الاتصال بWhatsApp وتشغيل المهمات المجدولة مباشرة على واجهة برمجة تطبيقات Agents SDK من Anthropic","en":"A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security. Connects to WhatsApp, has memory, scheduled jobs, and runs directly on Anthropic''s Agents SDK"},"seo":{"title":{"zh":"AI Agents - Debug","ja":"AIエージェント - Debug","ko":"AI Tools - Debug","es":"Agente de depuración: Alternativa li