INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('qwibitai/nanoclaw/debug', 'debug', 'qwibitai', 'nanoclaw', 'community', 'debug qwibitai nanoclaw community ai-agents ai-assistant claude-code claude-skills clawdbot Debug - A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security and efficiency Debug - A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security and efficiency Debug - A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security and efficiency El agente de depuración es una herramienta de AI ligera que conecta con WhatsApp y ofrece memoria y trabajos programados L''agent de débogage est un outil d''AI léger qui se connecte à WhatsApp et offre une mémoire et des tâches planifiées Der Debug-Agent ist ein leichtes AI-Tool, das mit WhatsApp verbindet und Speicher und geplante Aufgaben bietet O Depurar é uma ferramenta de Agente de IA leve e segura que conecta ao WhatsApp e executa tarefas agendadas diretamente no Agents SDK da Anthropic Отладка - это легковесный и безопасный инструмент ИИ Агенты, который подключается к WhatsApp и выполняет запланированные задачи непосредственно в Agents SDK от Anthropic تصحيح أخطاء هو أداة خفيفة وآمنة لتقنيات الذكاء الاصطناعي، تتمثل في الاتصال بWhatsApp وتشغيل المهمات المجدولة مباشرة على واجهة برمجة تطبيقات Agents SDK من Anthropic A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security. Connects to WhatsApp, has memory, scheduled jobs, and runs directly on Anthropic''s Agents SDK how to use debug what is debug debug alternative debug vs clawdbot debug install debug setup guide A lightweight alternative to Clawdbot / OpenClaw that runs in containers for security. Connects to WhatsApp, has memory, scheduled jobs, and runs directly on Anthropic''s Agents SDK');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('samarv/Shanon/opportunity-framing', 'community', 'samarv', 'Shanon', 'samarv/Shanon', 'opportunity-framing', 0, 0, 55, '2026-02-27T01:51:08.479Z', '2026-02-27T02:16:20.522Z', '30f866c77a17935b9e64c04fe725c8af9835e779af598193ef0e762c7f028120', '{"id":"samarv/Shanon/opportunity-framing","name":"opportunity-framing","description":{"zh":"机会框架是一种模块化的AI-assisted产品管理系统，帮助开发者提高效率和决策能力","ja":"オポチュニティフレーミングは、モジュラーなAIエージェントを使用した製品管理システムであり、開発者の効率と意思決定能力を向上させる","ko":"기회 프레임워크는 모듈형 AI 에이전트를 사용한 제품 관리 시스템으로 개발자의 효율과 의사 결정 능력을 향상시킵니다","es":"Opportunity-framing es un sistema de gestión de productos modular para la gestión de productos asistida por IA, que ayuda a los equipos de desarrollo a optimizar sus procesos","fr":"Opportunity-framing est un système de gestion de produits modulaire pour la gestion de produits assistée par l''IA, qui aide les équipes de développement à optimiser leurs processus","de":"Opportunity-framing ist ein modulares Produktmanagementsystem für die KI-gestützte Produktverwaltung, das Entwicklungsteams hilft, ihre Prozesse zu optimieren","pt":"O opportunity-framing é um sistema de gestão de produtos modulares para Ferramentas de IA, projetado para ajudar os desenvolvedores a otimizar sua gestão de produtos","ru":"Opportunity-framing - это модульная система управления продуктом для ИИ Агентов, предназначенная для того, чтобы помочь разработчикам оптимизировать управление продуктом","ar":"الفرصة-التأطير هو نظام إدارة منتجات قابل للتوسيع لأنظمة الذكاء الاصطناعي، مصمم للمساعدة المطورين على تحسين إدارة منتجاتهم","en":"A modular PM system for AI-assisted product management."},"seo":{"title":{"zh":"AI智能代理机会框架 - 模块化PM系统","ja":"AIエージェントのオポチュニティフレーミング - モジュラーPMシステム","ko":"AI 에이전트 기회 프레임워크 - 모듈형 PM 시스템","es":"Herramientas de IA: opportunity-framing para gestión de p...","fr":"Outils d''IA: opportunity-framing pour la gestion de produits","de":"KI-Tools: opportunity-framing für Produktmanagement","pt":"Ferramentas de IA: opportunity-framing para Gestão de Pro...","ru":"ИИ Агенты: opportunity-framing для Управления Продуктом","ar":"أدوات الذكاء الاصطناعي: opportunity-framing لإدارة المنتج","en":"opportunity-framing"},"description":{"zh":"机会框架是一种模块化的AI-assisted产品管理系统，帮助开发者提高效率和决策能力","ja":"オポチュニティフレーミングは、モジュラーなAIエージェントを使用した製品管理システムであり、開発者の効率と意思決定能力を向上させる","ko":"기회 프레임워크는 모듈형 AI 에이전트를 사용한 제품 관리 시스템으로 개발자의 효율과 의사 결정 능력을 향상시킵니다","es":"Opportunity-framing es un sistema de gestión de productos modular para la gestión de productos asistida por IA, que ayuda a los equipos de desarrollo a optim...","fr":"Opportunity-framing est un système de gestion de produits modulaire pour la gestion de produits assistée par l''IA, qui aide les équipes de développement à op...","de":"Opportunity-framing ist ein modulares Produktmanagementsystem für die KI-gestützte Produktverwaltung, das Entwicklungsteams hilft, ihre Prozesse zu optimieren","pt":"O opportunity-framing é um sistema de gestão de produtos modulares para Ferramentas de IA, projetado para ajudar os desenvolvedores a otimizar sua gestão de ...","ru":"Opportunity-framing - это модульная система управления продуктом для ИИ Агентов, предназначенная для того, чтобы помочь разработчикам оптимизировать управлен...","ar":"الفرصة-التأطير هو نظام إدارة منتجات قابل للتوسيع لأنظمة الذكاء الاصطناعي، مصمم للمساعدة المطورين على تحسين إدارة منتجاتهم","en":"A modular PM system for AI-assisted product management."},"definition":{"en":"A modular PM system for AI-assisted product management."},"features":{"zh":["模块化的产品管理系统","AI智能代理技术","提高效率和决策能力","支持多种开发语言","集成CLI和GUI界面"],"ja":["モジュラーな製品管理システム","AIエージェント技術","効率と意思決定能力の向上","多種の開発言語をサポート","CLIとGUIインターフェースの統合"],"ko":["모듈형 제품 관리 시스템","AI 에이전트 기술","효율과 의사 결정 능력의 향상","다양한 개발 언어 지원","CLI와 GUI 인터페이스의 통합"],"es":["Sistema de gestión de productos modular","Asistido por herramientas de IA","Optimización de procesos de desarrollo","Toma de decisiones basada en datos","Integración con herramientas de desarrollo como React y Node.js"],"fr":["Système de gestion de produits modulaire","Assisté par des outils d''IA","Optimisation des processus de développement","Prise de décision basée sur les données","Intégration avec des outils de développement tels que React et Node.js"],"de":["Modulares Produktmanagementsystem","Unterstützt durch KI-Tools","Optimierung von Entwicklungsprozessen","Datenbasierte Entscheidungsfindung","Integration mit Entwicklungstools wie React und Node.js"],"pt":["Sistema de gestão de produtos modulares","Integração com Ferramentas de IA","Otimização da gestão de produtos","Identificação de oportunidades","Desenvolvimento de produtos personalizados"],"ru":["Модульная система управления продуктом","Интеграция с ИИ Агентами","Оптимизация управления продуктом","Выявление возможностей","Разработка индивидуальных продуктов"],"ar":["نظام إدارة منتجات قابل للتوسيع","التكامل مع أنظمة الذكاء الاصطناعي","تحسين إدارة المنتجات","تحديد الفرص","تطوير منتجات مخصصة"]},"keywords":{"zh":["AI智能代理","机会框架","模块化产品管理","如何使用AI智能代理","机会框架安装指南","AI智能代理与传统产品管理的比较"],"ja":["AIエージェント","オポチュニティフレーミング","モジュラー製品管理","AIエージェントの使い方","オポチュニティフレーミングの設定ガイド","AIエージェントと伝統的な製品管理の比較"],"ko":["AI 에이전트","기회 프레임워크","모듈형 제품 관리","AI 에이전트 사용법","기회 프레임워크 설정 가이드","AI 에이전트와 전통적인 제품 관리의 비교"],"es":["herramientas de IA para gestión de productos","cómo utilizar opportunity-framing","qué es la gestión de productos asistida por IA","opportunity-framing vs herramientas de gestión de productos tradicionales","instalación de opportunity-framing","guía de configuración de opportunity-framing"],"fr":["outils d''IA pour la gestion de produits","comment utiliser opportunity-framing","qu''est-ce que la gestion de produits assistée par l''IA","opportunity-framing vs outils de gestion de produits traditionnels","installation d''opportunity-framing","guide de configuration d''opportunity-framing"],"de":["KI-Tools für das Produktmanagement","wie man opportunity-framing verwendet","was ist das KI-gestützte Produktmanagement","opportunity-framing vs traditionelle Produktmanagement-Tools","installation von opportunity-framing","konfigurationsanleitung für opportunity-framing"],"pt":["como usar opportunity-framing","o que é opportunity-framing","opportunity-framing vs jira","opportunity-framing alternative","instalar opportunity-framing","guia de configuração do opportunity-framing"],"ru":["как использовать opportunity-framing","что такое opportunity-framing","opportunity-framing vs jira","опportunity-framing альтернатива","установить opportunity-framing","руководство по настройке opportunity-framing"],"ar":["كيفية استخدام opportunity-framing","ما هو opportunity-framing","opportunity-framing مقابل jira","بديل opportunity-framing","تثبيت opportunity-framing","دليل إعداد opportunity-framing"]}},"owner":"samarv","repo":"Shanon","repoPath":"samarv/Shanon","stars":0,"forks":0,"updatedAt":"2026-02-27T01:51:08.479Z","topics":[],"category":"community","skillMd":{"name":"opportunity-framing","description":"Frame customer opportunities as unmet needs, pain points, and desires rather than solutions. Use when writing opportunities for an Opportunity Solution Tree, validating opportunity statements, or training teams to distinguish problems from solutions. CRITICAL for avoiding the #1 OST failure - 98% of people write opportunities as solutions (Teresa Torres). Triggers when user asks to frame opportunities, write opportunities, validate opportunity statements, or check if this is a need vs solution.","bodyPreview":"# Opportunity Framing\n\nTransform feature requests and customer feedback into actionable, specific opportunities that represent true customer needs.\n\n## Core Principle\n\n**Opportunities are needs, not solutions.**\n\nThe #1 failure mode: \"98% of people that write opportunities write them as solutions.\" - Teresa Torres\n\n## Good vs Bad Opportunities\n\n### Bad (Solutions Disguised as Needs)\n- \"We need a better login experience\"\n- \"We need voice input for passwords\"\n- \"I wish this was easier to use\"\n- \"A","body":"# Opportunity Framing\n\nTransform feature requests and customer feedback into actionable, specific opportunities that represent true customer needs.\n\n## Core Principle\n\n**Opportunities are needs, not solutions.**\n\nThe #1 failure mode: \"98% of people that write opportunities write them as solutions.\" - Teresa Torres\n\n## Good vs Bad Opportunities\n\n### Bad (Solutions Disguised as Needs)\n- \"We need a better login experience\"\n- \"We need voice input for passwords\"\n- \"I wish this was easier to use\"\n- \"Add a calendar view\"\n- \"Implement dark mode\"\n\n### Good (Specific Customer Needs)\n- \"It''s hard to enter my password - selecting specific letters on the screen with the Apple TV remote\"\n- \"I can''t see who''s in the cast before I start watching\"\n- \"I don''t know if this show is good without watching 3 episodes first\"\n- \"I lose track of where I was when switching between devices\"\n- \"I can''t tell if I''ve already watched this episode\"\n\n## Quality Tests\n\nApply ALL three tests to validate an opportunity:\n\n### Test 1: Is it specific and actionable?\n- Bad: \"Navigation is confusing\" (too vague)\n- Good: \"I can''t find the search button on the main screen\" (specific)\n\n### Test 2: Does it describe the problem, not the solution?\n- Bad: \"We need better filters\" (solution)\n- Good: \"I can''t narrow down results by release date\" (problem)\n\n### Test 3: Is it grounded in a real customer story?\n- Bad: \"Users want faster load times\" (assumption)\n- Good: \"I gave up waiting for the page to load and closed the app\" (story-based)\n\n## Framing Process\n\n### Step 1: Listen for the raw input\nCustomer says: \"I wish there was a way to skip the intro automatically.\"\n\n### Step 2: Strip away the solution language\nSolution words to remove: \"add\", \"implement\", \"build\", \"create\", \"should have\", \"I wish there was\"\n\n### Step 3: Find the underlying need\nAsk: \"What problem would that solution solve?\"\nAnswer: \"I waste time clicking ''skip intro'' for every episode when binge-watching\"\n\n### Step 4: Make it specific\nGeneric: \"Binge-watching is tedious\"\nSpecific: \"I have to click ''skip intro'' 6+ times per hour when binge-watching a series\"\n\n### Step 5: Validate with the story\nCan you trace this back to a real customer moment?\nYes: \"Tell me about the last time you binge-watched something...\"\n\n## Vertical Depth Pattern\n\nOpportunities should get smaller and more actionable as you move down the tree:\n\n**Level 1 (Big)**: \"I can''t decide what to watch\"\n\n**Level 2 (Smaller)**: \"I don''t know if this show is good\"\n\n**Level 3 (Actionable)**: \"I can''t see who''s in the cast\"\n\nEach level down should:\n- Be more specific than the level above\n- Be a contributing factor to the parent opportunity\n- Be actionable enough to generate multiple solution ideas\n\n## Red Flags\n\nWatch for these indicators that you''ve written a solution, not an opportunity:\n\n- Contains implementation language (\"add\", \"build\", \"implement\", \"create\")\n- Describes a feature name or UI pattern (\"dashboard\", \"calendar view\", \"notifications\")\n- Uses \"should/could/would have\" phrasing\n- Lacks specificity (could apply to any product)\n- Not traceable to a specific customer story\n- Describes HOW rather than WHY or WHAT\n\n## Transformation Examples\n\n### Example 1: E-commerce\n**Raw input**: \"We need product recommendations\"\n**Bad opportunity**: \"Users want personalized recommendations\"\n**Good opportunity**: \"I don''t know what else to buy after adding one item to my cart\"\n\n### Example 2: SaaS Tool\n**Raw input**: \"Add keyboard shortcuts\"\n**Bad opportunity**: \"Power users need keyboard shortcuts\"\n**Good opportunity**: \"I waste 5+ seconds per action reaching for my mouse when I''m in flow state\"\n\n### Example 3: Mobile App\n**Raw input**: \"Implement offline mode\"\n**Bad opportunity**: \"Users need offline access\"\n**Good opportunity**: \"I lose my work when I go through a tunnel on my commute\"\n\n## Common Patterns\n\n### Pattern: \"I wish there was...\"\nThis is ALWAYS a solution in disguise.\n1. Ask: \"What problem does that solve?\"\n2. Ask: \"Tell me about the last time you experienced that problem\"\n3. Write the opportunity from the story\n\n### Pattern: Stakeholder feature requests\n\"Build feature X\" → \"Why?\" → \"To solve Y\" → \"Tell me about Y\"\n\nExample:\n- Request: \"Build a calendar view\"\n- Why?: \"To help users see their schedule\"\n- Problem: \"I can''t tell if I''m double-booked without checking 3 different places\"\n\n## Validation Checklist\n\nBefore finalizing an opportunity, confirm:\n\n- [ ] Written as a customer need, not a solution\n- [ ] Specific and concrete (mentions actual UI, steps, or context)\n- [ ] Traceable to a real customer story/interview\n- [ ] Actionable (could generate 3+ different solution ideas)\n- [ ] At appropriate depth (not too broad, not too narrow)\n- [ ] No implementation language (add/build/implement/create)\n- [ ] Passes all 3 quality tests above\n\n## Working with Experience Maps\n\nOpportunities should be organized by the customer''s journey phases:\n\n**Netflix Example:**\n1. Trigger (deciding to watch something)\n   - \"I don''t know what I''m in the mood for\"\n   - \"I don''t have much time and need something short\"\n2. Choosing what to watch\n   - \"I can''t see who''s in the cast\"\n   - \"I don''t know if this matches my mood\"\n3. Evaluating if it''s good\n   - \"I can''t tell if it''s good without watching 3 episodes\"\n4. The viewing experience\n   - \"I have to click skip intro 6+ times per hour\"\n5. Post-viewing experience\n   - \"I forget what happened in previous seasons\"\n\nEach phase contains specific needs and pain points.\n\n## Anti-Patterns\n\n### \"I want\" vs \"I can''t\"\n- Bad: \"I want to customize my dashboard\" (expresses desire)\n- Good: \"I can''t see my most important metrics without scrolling\" (expresses problem)\n\n### Generic vs Specific\n- Bad: \"The app is slow\" (generic)\n- Good: \"The search results take 8+ seconds to load on my phone\" (specific)\n\n### Feature vs Need\n- Bad: \"Users need a dark mode\" (feature)\n- Good: \"The bright screen hurts my eyes when using the app at night\" (need)\n\n## Coaching Prompts\n\nWhen helping others frame opportunities, use these prompts:\n\n1. \"Can you tell me about a specific time when you experienced that?\"\n2. \"What happened? Walk me through it step by step.\"\n3. \"What were you trying to do?\"\n4. \"What made that difficult/frustrating?\"\n5. \"What did you do next?\"\n6. \"How did that feel?\"\n\n## Reference: Teresa Torres'' Quality Standard\n\n> \"I''ve seen blog posts written about how they''re using the opportunity solution tree, and I cry a little bit because their opportunity space is all solutions. I don''t want to knock down somebody''s blog post, but I also don''t want this bad example out there in the world.\"\n\nThe bar is high. When in doubt:\n1. Read the opportunity statement out loud\n2. Ask: \"Is this describing WHAT the customer is trying to do or HOW we might solve it?\"\n3. If there''s any trace of HOW, rewrite it\n\n## Output Format\n\nWhen framing opportunities, use this format:\n\n```\nOpportunity: [Customer need statement in first person]\nEvidence: [Quote or story from customer interview]\nContext: [Journey phase this belongs to]\nParent opportunity: [If this is a sub-opportunity]\nConfidence: [High/Medium/Low based on # of customer stories]\n```\n\nExample:\n```\nOpportunity: \"I can''t tell if I''m double-booked without checking 3 different places\"\nEvidence: \"Last week I showed up to two meetings at the same time because my work calendar, personal calendar, and the team''s shared calendar weren''t synced.\" - User Interview #7\nContext: Schedule management / Planning phase\nParent opportunity: \"I can''t manage my time effectively across multiple calendars\"\nConfidence: High (heard from 8/10 interview participants)\n```\n"},"lastSynced":"2026-02-27T02:16:20.522Z","agentAnalysis":{"suitability":{"en":"Ideal for Product Management Agents needing to transform customer feedback into actionable opportunities.","zh":"非常适合需要将客户反馈转化为可操作机会的产品管理Agent。","ja":"顧客のフィードバックを実行可能な機会に変換する必要があるプロダクトマネジメントエージェントに最適です。","ko":"고객 피드백을 실행 가능한 기회로 전환해야 하는 제품 관리 에이전트에 이상적입니다.","es":"Ideal para agentes de Gestión de Producto que necesitan transformar los comentarios de los clientes en oportunidades accionables.","fr":"Idéal pour les agents de Gestion de Produit ayant besoin de transformer les retours clients en opportunités actionnables.","de":"Ideal für Produktmanagement-Agenten, die Kundenfeedback in umsetzbare Chancen verwandeln müssen.","pt":"Ideal para Agentes de Gestão de Produtos que precisam transformar feedback de clientes em oportunidades concretas.","ru":"Идеально для агентов по управлению продуктами, которым необходимо преобразовывать отзывы клиентов в действенные возможности.","ar":"مثالي لعمليات إدارة المنتجات التي تحتاج إلى تحويل ملاحظات العملاء إلى فرص قابلة للتنفيذ."},"recommendation":{"en":"Empowers agents to distinguish between true customer needs and solution-disguised opportunities, leveraging core principles like Teresa Torres'' insights to prioritize features effectively, and utilizing techniques such as modular PM systems for AI-assisted product management.","zh":"使Agent能够区分真实的客户需求与伪装成解决方案的机会，利用Teresa Torres的核心见解等原则来有效确定功能优先级，并利用模块化PM系统等技术进行AI辅助的产品管理。","ja":"エージェントが真の顧客ニーズと解決策として偽装された機会を区別できるようにし、Teresa Torresの洞察のような核心原則を活用して機能の優先順位を効果的に設定し、モジュラー式PMシステムなどの技術を利用してAI支援によるプロダクトマネジメントを実現します。","ko":"에이전트가 진정한 고객 요구와 솔루션으로 위장된 기회를 구별할 수 있도록 하여, Teresa Torres의 통찰력과 같은 핵심 원칙을 활용해 기능 우선순위를 효과적으로 지정하고, 모듈식 PM 시스템과 같은 기술을 사용하여 AI 지원 제품 관리를 수행합니다.","es":"Empodera a los agentes para distinguir entre las verdaderas necesidades del cliente y las oportunidades disfrazadas de soluciones, aprovechando principios fundamentales como las ideas de Teresa Torres para priorizar características de manera efectiva, y utilizando técnicas como sistemas modulares de PM para la gestión de productos asistida por IA.","fr":"Permet aux agents de distinguer les véritables besoins des clients des opportunités déguisées en solutions, en tirant parti de principes fondamentaux tels que les insights de Teresa Torres pour prioriser efficacement les fonctionnalités, et en utilisant des techniques telles que les systèmes modulaires de PM pour la gestion de produits assistée par IA.","de":"Befähigt Agenten, zwischen echten Kundenbedürfnissen und als Lösungen getarnten Chancen zu unterscheiden, indem sie Kernprinzipien wie die Einsichten von Teresa Torres nutzen, um Funktionen effektiv zu priorisieren, und Techniken wie modulare PM-Systeme für KI-unterstütztes Produktmanagement einsetzen.","pt":"Habilita os agentes a distinguir entre as necessidades reais dos clientes e oportunidades disfarçadas de soluções, utilizando princípios fundamentais como as ideias de Teresa Torres para priorizar recursos de forma eficaz, e utilizando técnicas como sistemas de gestão de produtos modulares para gestão de produtos assistida por AI.","ru":"Наделяет агентов возможностью различать истинные потребности клиентов и возможности, замаскированные под решения, используя основополагающие принципы, такие как идеи Терезы Торрес, для эффективной приоритизации функций, и используя такие техники, как модульные системы управления продуктами для управления продуктами с помощью ИИ.","ar":"تمكّن الوكلاء من التمييز بين احتياجات العملاء الحقيقية والفرص المخفية تحت ستار الحلول، مستفيدًا من المبادئ الأساسية مثل أفكار تيريزا توريس لتحديد أولويات الميزات بفعالية، واستخدام تقنيات مثل أنظمة إدارة المنتجات القابلة للتحديث لتدبير منتجات مدعومة بالذكاء الاصطناعي."},"useCases":{"en":["Transforming feature requests into specific customer needs","Prioritizing product backlogs based on actionable opportunities","Differentiating between solutions and true customer needs in feedback analysis"],"zh":["将功能请求转化为具体的客户需求","基于可操作的机会确定产品待办列表的优先级","在反馈分析中区分解决方案和真实的客户需求"],"ja":["機能リクエストを具体的な顧客ニーズに変換する","実行可能な機会に基づいてプロダクトバックログの優先順位を設定する","フィードバック分析において解決策と真の顧客ニーズを区別する"],"ko":["기능 요청을 특정 고객 요구사항으로 전환","실행 가능한 기회를 기반으로 제품 백로그 우선순위 지정","피드백 분석에서 솔루션과 진정한 고객 요구 사항 구별"],"es":["Transformar solicitudes de características en necesidades específicas del cliente","Priorizar carteras de productos basándose en oportunidades accionables","Diferenciar entre soluciones y verdaderas necesidades del cliente en el análisis de comentarios"],"fr":["Transformer les demandes de fonctionnalités en besoins clients spécifiques","Prioriser les backlogs produits sur la base d''opportunités actionnables","Différencier les solutions des véritables besoins clients dans l''analyse des retours"],"de":["Umwandeln von Funktionsanfragen in spezifische Kundenbedürfnisse","Priorisieren von Produkt-Backlogs basierend auf umsetzbaren Chancen","Unterscheiden zwischen Lösungen und echten Kundenbedürfnissen in der Feedbackanalyse"],"pt":["Transformar solicitações de recursos em necessidades específicas dos clientes","Priorizar backlogs de produtos com base em oportunidades concretas","Diferenciar entre soluções e necessidades reais dos clientes na análise de feedback"],"ru":["Преобразование запросов на функции в конкретные потребности клиентов","Приоритизация очередей продуктов на основе действенных возможностей","Различение между решениями и истинными потребностями клиентов при анализе отзывов"],"ar":["تحويل طلبات الميزات إلى احتياجات محددة للعملاء","تحديد أولويات قائمة منتجات معطلة بناءً على فرص قابلة للتنفيذ","تمييز الحلول عن احتياجات العملاء الحقيقية في تحليل الملاحظات"]},"limitations":{"en":["Requires understanding of customer feedback and feature requests","Dependent on the quality of input data for effective opportunity framing"],"zh":["需要理解客户反馈和功能请求","依赖输入数据的质量以进行有效的机会框架构建"],"ja":["顧客のフィードバックと機能リクエストの理解が必要","効果的な機会の枠組み構築には入力データの品質に依存"],"ko":["고객 피드백 및 기능 요청에 대한 이해 필요","효과적인 기회 프레임 구성을 위해 입력 데이터의 품질에 의존"],"es":["Requiere comprensión de los comentarios de los clientes y las solicitudes de características","Depende de la calidad de los datos de entrada para un encuadre efectivo de oportunidades"],"fr":["Nécessite une compréhension des retours clients et des demandes de fonctionnalités","Dépend de la qualité des données d''entrée pour un cadrage efficace des opportunités"],"de":["Erfordert ein Verständnis von Kundenfeedback und Funktionsanfragen","Abhängig von der Qualität der Eingabedaten für eine effektive Chancenformulierung"],"pt":["Exige compreensão de feedback de clientes e solicitações de recursos","Depende da qualidade dos dados de entrada para um enquadramento eficaz de oportunidades"],"ru":["Требует понимания отзывов клиентов и запросов на функции","Зависит от качества входных данных для эффективного определения возможностей"],"ar":["يتطلب فهمًا لتعليقات العملاء وطلبات الميزات","يعتمد على جودة بيانات الإدخال لتحديد فرص فعال"]},"version":3},"contentHash":"30f866c77a17935b9e64c04fe725c8af9835e779af598193ef0e762c7f028120","qualityScore":55}');
DELETE FROM skills_fts WHERE id = 'samarv/Shanon/opportunity-framing';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('samarv/Shanon/opportunity-framing', 'opportunity-framing', 'samarv', 'Shanon', 'community', 'opportunity-framing samarv Shanon community 机会框架是一种模块化的AI-assisted产品管理系统，帮助开发者提高效率和决策能力 オポチュニティフレーミングは、モジュラーなAIエージェントを使用した製品管理システムであり、開発者の効率と意思決定能力を向上させる 기회 프레임워크는 모듈형 AI 에이전트를 사용한 제품 관리 시스템으로 개발자의 효율과 의사 결정 능력을 향상시킵니다 Opportunity-framing es un sistema de gestión de productos modular para la gestión de productos asistida por IA, que ayuda a los equipos de desarrollo a optimizar sus procesos Opportunity-framing est un système de gestion de produits modulaire pour la gestion de produits assistée par l''IA, qui aide les équipes de développement à optimiser leurs processus Opportunity-framing ist ein modulares Produktmanagementsystem für die KI-gestützte Produktverwaltung, das Entwicklungsteams hilft, ihre Prozesse zu optimieren O opportunity-framing é um sistema de gestão de produtos modulares para Ferramentas de IA, projetado para ajudar os desenvolvedores a otimizar sua gestão de produtos Opportunity-framing - это модульная система управления продуктом для ИИ Агентов, предназначенная для того, чтобы помочь разработчикам оптимизировать управление продуктом الفرصة-التأطير هو نظام إدارة منتجات قابل للتوسيع لأنظمة الذكاء الاصطناعي، مصمم للمساعدة المطورين على تحسين إدارة منتجاتهم A modular PM system for AI-assisted product management. AI智能代理 机会框架 模块化产品管理 如何使用AI智能代理 机会框架安装指南 AI智能代理与传统产品管理的比较 A modular PM system for AI-assisted product management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('re-cinq/wave/cli', 'community', 're-cinq', 'wave', 're-cinq/wave', 'cli', 6, 0, 55, '2026-02-26T21:34:14Z', '2026-02-27T01:55:04.525Z', 'a3874632a8e2e47c6ee3fc9e00298c26f5332f8e6dec16acce97283c51cd3d9c', '{"id":"re-cinq/wave/cli","name":"cli","description":{"zh":"cli是用于AI-assisted开发的多代理管道，通过AI智能代理实现高效开发","ja":"cliはAIエージェントを使用したマルチエージェントパイプライン開発ツールであり、高効率な開発を実現します","ko":"cli는 AI 에이전트를 사용한 멀티 에이전트 파이프라인 개발 도구로써 높은 효율의 개발을 가능하게 합니다","es":"cli ofrece pipelines multiagente para desarrollo asistido por AI, mejorando la eficiencia y productividad","fr":"cli propose des pipelines multi-agents pour le développement assisté par l''IA, améliorant l''efficacité et la productivité","de":"cli bietet Multi-Agent-Pipelines für die künstlich intelligente Entwicklung, die Effizienz und Produktivität verbessern","pt":"A cli é uma ferramenta de desenvolvimento assistido por IA que utiliza pipelines de multiagentes para melhorar a eficiência","ru":"ИИ Агенты и cli представляют собой инструменты для разработки, использующие многоагентные конвейеры для повышения эффективности","ar":"أدوات الذكاء الاصطناعي و cli هي أدوات تنمية مدعومة بالذكاء الاصطناعي التي تستخدم خطوط أنابيب متعددة الوكلاء لتحسين الكفاءة","en":"Multi-agent pipelines for AI-assisted development"},"seo":{"title":{"zh":"AI智能代理cli：多代理管道开发","ja":"AIエージェントcli：マルチエージェントパイプライン開発","ko":"AI 에이전트 cli: 멀티 에이전트 파이프라인 개발","es":"Herramientas de AI: cli para desarrollo asistido","fr":"Outils d''IA: cli pour développement assisté","de":"KI-Tools: cli für künstlich intelligente Entwicklung","pt":"Ferramentas de IA: Cli para Desenvolvimento Assistido","ru":"ИИ Агенты: Cli для Усиления Разработки","ar":"أدوات الذكاء الاصطناعي: Cli للتنمية المدعومة","en":"cli"},"description":{"zh":"cli是用于AI-assisted开发的多代理管道，通过AI智能代理实现高效开发","ja":"cliはAIエージェントを使用したマルチエージェントパイプライン開発ツールであり、高効率な開発を実現します","ko":"cli는 AI 에이전트를 사용한 멀티 에이전트 파이프라인 개발 도구로써 높은 효율의 개발을 가능하게 합니다","es":"cli ofrece pipelines multiagente para desarrollo asistido por AI, mejorando la eficiencia y productividad","fr":"cli propose des pipelines multi-agents pour le développement assisté par l''IA, améliorant l''efficacité et la productivité","de":"cli bietet Multi-Agent-Pipelines für die künstlich intelligente Entwicklung, die Effizienz und Produktivität verbessern","pt":"A cli é uma ferramenta de desenvolvimento assistido por IA que utiliza pipelines de multiagentes para melhorar a eficiência","ru":"ИИ Агенты и cli представляют собой инструменты для разработки, использующие многоагентные конвейеры для повышения эффективности","ar":"أدوات الذكاء الاصطناعي و cli هي أدوات تنمية مدعومة بالذكاء الاصطناعي التي تستخدم خطوط أنابيب متعددة الوكلاء لتحسين الكفاءة","en":"Multi-agent pipelines for AI-assisted development"},"definition":{"en":"Multi-agent pipelines for AI-assisted development"},"features":{"zh":["支持多代理管道开发","实现AI-assisted开发","提高开发效率","支持多种开发语言","提供灵活的开发工作流"],"ja":["マルチエージェントパイプライン開発をサポート","AIエージェントを使用した開発を実現","開発効率を向上させる","複数の開発言語をサポート","柔軟な開発ワークフローを提供"],"ko":["멀티 에이전트 파이프라인 개발을 지원","AI 에이전트를 사용한 개발을 구현","개발 효율성을 향상시키는","複数의 개발 언어를 지원","유연한 개발 워크플ロー를 제공"],"es":["Pipelines multiagente para desarrollo asistido","Integración con AI como código","Mejora de la eficiencia y productividad","Compatibilidad con múltiples plataformas","Facilidad de uso y configuración"],"fr":["Pipelines multi-agents pour développement assisté","Intégration avec l''IA comme code","Amélioration de l''efficacité et de la productivité","Compatibilité avec plusieurs plateformes","Facilité d''utilisation et de configuration"],"de":["Multi-Agent-Pipelines für die künstlich intelligente Entwicklung","Integration mit KI-Code","Verbesserung der Effizienz und Produktivität","Kompatibilität mit mehreren Plattformen","Einfachheit bei der Verwendung und Konfiguration"],"pt":["Pipelines de multiagentes para desenvolvimento","Integração com ferramentas de desenvolvimento populares","Suporte a linguagens de programação como Python e Node.js","Interface de linha de comando (CLI) para facilitar o uso","Melhoria da eficiência e produtividade do desenvolvimento"],"ru":["Многоагентные конвейеры для разработки","Интеграция с популярными инструментами разработки","Поддержка языков программирования, таких как Python и Node.js","Интерфейс командной строки (CLI) для упрощения использования","Повышение эффективности и производительности разработки"],"ar":["خطوط أنابيب متعددة الوكلاء للتنمية","التكامل مع أدوات التنمية الشهيرة","دعم لغات البرمجة مثل Python و Node.js","واجهة سطر الأوامر (CLI) لتسهيل الاستخدام","تحسين الكفاءة والإنتاجية التنموية"]},"keywords":{"zh":["如何使用cli开发","什么是AI智能代理","cli与其他开发工具的比较","cli安装指南","cli开发教程","AI-assisted开发最佳实践"],"ja":["cliを使用した開発方法","AIエージェントとは","cliと他の開発ツールの比較","cliのインストール方法","cli開発ガイド","AIエージェントを使用した開発ベストプラクティス"],"ko":["cli를 사용한 개발 방법","AI 에이전트란","cli와 다른 개발 도구의 비교","cli 설치 가이드","cli 개발 튜토리얼","AI 에이전트를 사용한 개발 베스트 프랙티스"],"es":["herramientas de AI para desarrollo","cómo usar cli","qué es el desarrollo asistido por AI","cli vs otros herramientas de AI","instalación de cli","guía de configuración de cli","desarrollo de software con AI","mejores prácticas para el desarrollo asistido por AI"],"fr":["outils d''IA pour le développement","comment utiliser cli","quoi est le développement assisté par l''IA","cli vs autres outils d''IA","installation de cli","guide de configuration de cli","développement de logiciels avec l''IA","meilleures pratiques pour le développement assisté par l''IA"],"de":["KI-Tools für die Entwicklung","wie man cli verwendet","was ist die künstlich intelligente Entwicklung","cli vs andere KI-Tools","installation von cli","konfigurationsanleitung für cli","softwareentwicklung mit KI","beste praxis für die künstlich intelligente Entwicklung"],"pt":["ferramentas de ia","desenvolvimento assistido por ia","pipelines de multiagentes","cli para desenvolvimento","como usar cli","o que é cli","alternativas ao cli","cli vs outras ferramentas"],"ru":["ИИ агенты","усиление разработки","многоагентные конвейеры","cli для разработки","как использовать cli","что такое cli","альтернативы cli","cli vs другие инструменты"],"ar":["أدوات الذكاء الاصطناعي","التنمية المدعومة بالذكاء الاصطناعي","خطوط أنابيب متعددة الوكلاء","cli للتنمية","كيفية استخدام cli","ما هي أدوات الذكاء الاصطناعي","بديلات cli","cli مقابل أدوات أخرى"]}},"owner":"re-cinq","repo":"wave","repoPath":"re-cinq/wave","stars":6,"forks":0,"updatedAt":"2026-02-26T21:34:14Z","topics":["agentic-workflow","ai-as-code","multi-agent-systems"],"category":"community","skillMd":{"name":"cli","description":"Expert command-line interface development including argument parsing, subcommands, interactive prompts, and CLI best practices","bodyPreview":"## User Input\n\n```text\n$ARGUMENTS\n```\n\nYou **MUST** consider the user input before proceeding (if not empty).\n\n## Outline\n\nYou are a Command Line Interface (CLI) expert specializing in argument parsing, subcommands, interactive prompts, and CLI best practices. Use this skill when the user needs help with:\n\n- Creating command-line tools and utilities\n- Implementing argument parsing and validation\n- Building interactive CLI applications\n- Designing CLI help systems and documentation\n- CLI testing","body":"## User Input\n\n```text\n$ARGUMENTS\n```\n\nYou **MUST** consider the user input before proceeding (if not empty).\n\n## Outline\n\nYou are a Command Line Interface (CLI) expert specializing in argument parsing, subcommands, interactive prompts, and CLI best practices. Use this skill when the user needs help with:\n\n- Creating command-line tools and utilities\n- Implementing argument parsing and validation\n- Building interactive CLI applications\n- Designing CLI help systems and documentation\n- CLI testing and distribution\n- Cross-platform CLI development\n\n## CLI Libraries and Frameworks\n\n### 1. Go CLI Libraries\n- **Cobra**: Powerful CLI framework for Go applications\n- **urfave/cli**: Simple, fast, and fun CLI applications\n- **flag**: Standard library flag package\n- **pflag**: POSIX-compliant flag package\n- **kingpin**: Deprioritized but still useful\n\n### 2. Python CLI Libraries\n- **Click**: Composable command interface creation\n- **argparse**: Standard library argument parser\n- **docopt**: Command-line interface descriptions\n- **typer**: Modern CLI library with type hints\n- **fire**: Automatic CLI generation\n\n### 3. Node.js CLI Libraries\n- **Commander.js**: Complete solution for Node.js command-line programs\n- **yargs**: Command-line argument parser\n- **oclif**: CLI framework for Node.js\n- **meow**: Helper for CLI apps\n- **minimist**: Argument parser\n\n### 4. Rust CLI Libraries\n- **clap**: Command Line Argument Parser\n- **structopt**: Derive-based argument parser (deprecated, use clap)\n- **argh**: Fast and simple argument parser\n- **lexopt**: Minimalist argument parser\n\n## Core CLI Concepts\n\n### 1. Argument Parsing\n- **Positional arguments**: Required arguments in specific positions\n- **Optional flags**: Optional parameters with single/double dashes\n- **Subcommands**: Nested command structures\n- **Environment variables**: Configuration via environment\n- **Config files**: Persistent configuration storage\n- **Validation**: Type checking and value validation\n\n### 2. Interactive Elements\n- **Prompts**: User input with validation\n- **Confirmations**: Yes/no confirmations\n- **Selection menus**: Choose from predefined options\n- **Progress bars**: Show operation progress\n- **Spinners**: Indicate ongoing work\n\n### 3. User Experience\n- **Help systems**: Auto-generated help text\n- **Error messages**: Clear, actionable error reporting\n- **Auto-completion**: Tab completion for commands\n- **Colors and formatting**: Readable output formatting\n- **Consistency**: Follow CLI conventions\n\n## CLI Development Patterns\n\n### Go with Cobra Example\n```go\npackage main\n\nimport (\n    \"fmt\"\n    \"os\"\n    \"github.com/spf13/cobra\"\n    \"github.com/spf13/viper\"\n)\n\nvar rootCmd = &cobra.Command{\n    Use:   \"myapp [command]\",\n    Short: \"My application does awesome things\",\n    Long: `My application is a CLI tool that demonstrates \nbest practices for command-line interface development.`,\n}\n\nvar configCmd = &cobra.Command{\n    Use:   \"config [key] [value]\",\n    Short: \"Get or set configuration values\",\n    Long:  `Get or set configuration values. If only key is provided,\ngets the value. If both key and value are provided, sets the value.`,\n    Args:  cobra.MinimumNArgs(1),\n    Run:   runConfig,\n}\n\nvar (\n    configFile string\n    verbose    bool\n    output     string\n)\n\nfunc init() {\n    cobra.OnInitialize(initConfig)\n    \n    rootCmd.PersistentFlags().StringVarP(&configFile, \"config\", \"c\", \"\", \"config file (default is $HOME/.myapp.yaml)\")\n    rootCmd.PersistentFlags().BoolVarP(&verbose, \"verbose\", \"v\", false, \"verbose output\")\n    rootCmd.PersistentFlags().StringVarP(&output, \"output\", \"o\", \"json\", \"output format (json|yaml|text)\")\n    \n    rootCmd.AddCommand(configCmd)\n}\n\nfunc initConfig() {\n    if configFile != \"\" {\n        viper.SetConfigFile(configFile)\n    } else {\n        home, err := os.UserHomeDir()\n        if err != nil {\n            fmt.Println(err)\n            os.Exit(1)\n        }\n        \n        viper.AddConfigPath(home)\n        viper.SetConfigType(\"yaml\")\n        viper.SetConfigName(\".myapp\")\n    }\n    \n    viper.AutomaticEnv()\n    \n    if err := viper.ReadInConfig(); err == nil {\n        fmt.Println(\"Using config file:\", viper.ConfigFileUsed())\n    }\n}\n\nfunc runConfig(cmd *cobra.Command, args []string) {\n    switch len(args) {\n    case 1:\n        // Get value\n        value := viper.GetString(args[0])\n        if value == \"\" {\n            fmt.Printf(\"Config key ''%s'' not found\\n\", args[0])\n            os.Exit(1)\n        }\n        fmt.Printf(\"%s: %s\\n\", args[0], value)\n    case 2:\n        // Set value\n        viper.Set(args[0], args[1])\n        fmt.Printf(\"Set %s = %s\\n\", args[0], args[1])\n    default:\n        fmt.Println(\"Usage: myapp config [key] [value]\")\n        os.Exit(1)\n    }\n}\n\nfunc main() {\n    if err := rootCmd.Execute(); err != nil {\n        fmt.Println(err)\n        os.Exit(1)\n    }\n}\n```\n\n### Python with Click Example\n```python\n#!/usr/bin/env python3\nimport click\nimport json\nimport sys\nfrom pathlib import Path\n\n@click.group()\n@click.option(''--config'', ''-c'', type=click.Path(), help=''Configuration file path'')\n@click.option(''--verbose'', ''-v'', is_flag=True, help=''Enable verbose output'')\n@click.pass_context\ndef cli(ctx, config, verbose):\n    \"\"\"My application does awesome things.\"\"\"\n    ctx.ensure_object(dict)\n    ctx.obj[''config''] = config\n    ctx.obj[''verbose''] = verbose\n\n@cli.command()\n@click.argument(''filename'', type=click.Path(exists=True))\n@click.option(''--format'', ''-f'', \n              type=click.Choice([''json'', ''yaml'', ''text'']), \n              default=''text'', \n              help=''Output format'')\n@click.pass_context\ndef process(ctx, filename, format):\n    \"\"\"Process a file and output results.\"\"\"\n    verbose = ctx.obj.get(''verbose'', False)\n    \n    if verbose:\n        click.echo(f\"Processing file: {filename}\")\n    \n    try:\n        with open(filename, ''r'') as f:\n            content = f.read()\n        \n        # Process the content\n        result = process_content(content)\n        \n        # Output in requested format\n        if format == ''json'':\n            click.echo(json.dumps(result, indent=2))\n        elif format == ''yaml'':\n            import yaml\n            click.echo(yaml.dump(result))\n        else:\n            click.echo(str(result))\n            \n    except Exception as e:\n        click.echo(f\"Error: {e}\", err=True)\n        sys.exit(1)\n\n@cli.command()\n@click.argument(''key'')\n@click.argument(''value'', required=False)\n@click.pass_context\ndef config(ctx, key, value):\n    \"\"\"Get or set configuration values.\"\"\"\n    config_file = ctx.obj.get(''config'') or get_default_config_path()\n    \n    if value:\n        set_config_value(config_file, key, value)\n        click.echo(f\"Set {key} = {value}\")\n    else:\n        value = get_config_value(config_file, key)\n        if value:\n            click.echo(f\"{key} = {value}\")\n        else:\n            click.echo(f\"Config key ''{key}'' not found\")\n            sys.exit(1)\n\ndef process_content(content):\n    \"\"\"Example content processing function.\"\"\"\n    lines = content.split(''\\n'')\n    return {\n        ''lines'': len(lines),\n        ''chars'': len(content),\n        ''words'': len(content.split())\n    }\n\nif __name__ == ''__main__'':\n    cli()\n```\n\n### Rust with Clap Example\n```rust\nuse clap::{Parser, Subcommand};\nuse serde::{Deserialize, Serialize};\nuse std::fs;\nuse std::io;\n\n#[derive(Parser)]\n#[command(author, version, about, long_about = None)]\nstruct Cli {\n    #[arg(short, long, default_value = \"config.yaml\")]\n    config: String,\n    \n    #[arg(short, long, action = clap::ArgAction::Count)]\n    verbose: u8,\n    \n    #[command(subcommand)]\n    command: Commands,\n}\n\n#[derive(Subcommand)]\nenum Commands {\n    Process(ProcessCommand),\n    Config(ConfigCommand),\n}\n\n#[derive(Parser)]\nstruct ProcessCommand {\n    /// Input file to process\n    #[arg(value_name = \"FILE\")]\n    file: String,\n    \n    /// Output format\n    #[arg(short, long, default_value = \"text\")]\n    format: String,\n}\n\n#[derive(Parser)]\nstruct ConfigCommand {\n    /// Configuration key to get/set\n    key: String,\n    \n    /// Configuration value to set\n    value: Option<String>,\n}\n\nfn main() {\n    let cli = Cli::parse();\n    \n    match cli.command {\n        Commands::Process(cmd) => process_file(cmd, &cli),\n        Commands::Config(cmd) => handle_config(cmd, &cli),\n    }\n}\n\nfn process_file(cmd: ProcessCommand, cli: &Cli) {\n    if cli.verbose > 0 {\n        println!(\"Processing file: {}\", cmd.file);\n    }\n    \n    match fs::read_to_string(&cmd.file) {\n        Ok(content) => {\n            let result = analyze_content(&content);\n            \n            match cmd.format.as_str() {\n                \"json\" => println!(\"{}\", serde_json::to_string_pretty(&result).unwrap()),\n                \"yaml\" => println!(\"{}\", serde_yaml::to_string(&result).unwrap()),\n                _ => println!(\"{:?}\", result),\n            }\n        }\n        Err(e) => {\n            eprintln!(\"Error reading file: {}\", e);\n            std::process::exit(1);\n        }\n    }\n}\n\nfn handle_config(cmd: ConfigCommand, cli: &Cli) {\n    match cmd.value {\n        Some(value) => set_config_value(&cli.config, &cmd.key, &value),\n        None => {\n            match get_config_value(&cli.config, &cmd.key) {\n                Some(value) => println!(\"{} = {}\", cmd.key, value),\n                None => {\n                    eprintln!(\"Config key ''{}'' not found\", cmd.key);\n                    std::process::exit(1);\n                }\n            }\n        }\n    }\n}\n\n#[derive(Serialize, Deserialize)]\nstruct ContentAnalysis {\n    lines: usize,\n    chars: usize,\n    words: usize,\n}\n\nfn analyze_content(content: &str) -> ContentAnalysis {\n    ContentAnalysis {\n        lines: content.lines().count(),\n        chars: content.chars().count(),\n        words: content.split_whitespace().count(),\n    }\n}\n```\n\n## Interactive CLI Patterns\n\n### Confirmation Prompts (Python with Click)\n```python\nimport click\n\n@click.command()\ndef deploy():\n    \"\"\"Deploy the application.\"\"\"\n    \n    if not click.confirm(''This will deploy to production. Continue?''):\n        click.echo(''Deployment cancelled.'')\n        return\n    \n    with click.progressbar(length=100, label=''Deploying'') as bar:\n        for i in range(100):\n            time.sleep(0.1)\n            bar.update(1)\n    \n    click.echo(''Deployment complete!'')\n\n@click.command()\n@click.option(''--force'', is_flag=True, help=''Skip confirmation'')\ndef delete(force):\n    \"\"\"Delete resources.\"\"\"\n    \n    if not force:\n        if not click.confirm(''This will delete all resources. Continue?''):\n            click.echo(''Deletion cancelled.'')\n            return\n    \n    # Perform deletion\n    click.echo(''Resources deleted.'')\n```\n\n### Interactive Selection (Node.js with Inquirer)\n```javascript\nconst inquirer = require(''inquirer'');\nconst program = require(''commander'');\n\nprogram\n    .version(''1.0.0'')\n    .command(''setup'')\n    .description(''Interactive setup wizard'')\n    .action(async () => {\n        const answers = await inquirer.prompt([\n            {\n                type: ''input'',\n                name: ''name'',\n                message: ''What is your project name?'',\n                validate: input => input.length > 0 || ''Project name is required''\n            },\n            {\n                type: ''list'',\n                name: ''template'',\n                message: ''Choose a template:'',\n                choices: [''basic'', ''advanced'', ''minimal'']\n            },\n            {\n                type: ''checkbox'',\n                name: ''features'',\n                message: ''Select features:'',\n                choices: [''database'', ''auth'', ''logging'', ''testing'']\n            }\n        ]);\n        \n        console.log(''Setup complete with:'', answers);\n        // Continue setup...\n    });\n\nprogram.parse(process.argv);\n```\n\n## CLI Testing Patterns\n\n### Go CLI Testing\n```go\npackage main\n\nimport (\n    \"bytes\"\n    \"os\"\n    \"strings\"\n    \"testing\"\n    \"github.com/spf13/cobra\"\n)\n\nfunc TestRootCommand(t *testing.T) {\n    tests := []struct {\n        name     string\n        args     []string\n        expected string\n        error    bool\n    }{\n        {\n            name:     \"help flag\",\n            args:     []string{\"--help\"},\n            expected: \"myapp does awesome things\",\n            error:    false,\n        },\n        {\n            name:     \"invalid command\",\n            args:     []string{\"invalid\"},\n            expected: \"\",\n            error:    true,\n        },\n    }\n    \n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            // Capture output\n            buf := new(bytes.Buffer)\n            rootCmd.SetOut(buf)\n            rootCmd.SetErr(buf)\n            \n            // Set arguments\n            rootCmd.SetArgs(tt.args)\n            \n            // Execute command\n            err := rootCmd.Execute()\n            \n            output := buf.String()\n            \n            if tt.error && err == nil {\n                t.Errorf(\"expected error but got none\")\n            }\n            if !tt.error && err != nil {\n                t.Errorf(\"unexpected error: %v\", err)\n            }\n            if !strings.Contains(output, tt.expected) {\n                t.Errorf(\"expected output to contain %q, got %q\", tt.expected, output)\n            }\n        })\n    }\n}\n```\n\n### Python CLI Testing\n```python\nimport pytest\nfrom click.testing import CliRunner\nfrom myapp import cli\n\ndef test_process_command(tmp_path):\n    \"\"\"Test the process command.\"\"\"\n    runner = CliRunner()\n    \n    # Create test file\n    test_file = tmp_path / \"test.txt\"\n    test_file.write_text(\"test content\\n\")\n    \n    # Run command\n    result = runner.invoke(cli.process, [str(test_file)])\n    \n    assert result.exit_code == 0\n    assert \"lines: 1\" in result.output\n    assert \"chars: 12\" in result.output\n\ndef test_config_command():\n    \"\"\"Test the config command.\"\"\"\n    runner = CliRunner()\n    \n    # Test getting value\n    result = runner.invoke(cli.config, [''test.key''])\n    assert result.exit_code == 0\n    \n    # Test setting value\n    result = runner.invoke(cli.config, [''test.key'', ''test.value''])\n    assert result.exit_code == 0\n    assert \"Set test.key = test.value\" in result.output\n```\n\n## CLI Best Practices\n\n### 1. Command Design\n- Use descriptive command names (verbs are good)\n- Follow Unix conventions (short options, long options)\n- Provide help text and examples\n- Support configuration files and environment variables\n- Handle errors gracefully\n\n### 2. Output Formatting\n- Support multiple output formats (JSON, YAML, plain text)\n- Use colors sparingly and respect NO_COLOR environment\n- Provide progress indicators for long operations\n- Format numbers with appropriate units\n\n### 3. User Experience\n- Implement auto-completion where possible\n- Provide clear error messages with suggestions\n- Use confirmation prompts for destructive operations\n- Support verbose and quiet modes\n\n### 4. Distribution\n- Create single-binary executables where possible\n- Provide installation instructions\n- Include man pages or help documentation\n- Consider packaging for different platforms\n\n## When to Use This Skill\n\nUse this skill when you need to:\n- Build command-line tools and utilities\n- Create CLI interfaces for existing applications\n- Design interactive command-line applications\n- Implement argument parsing and validation\n- Add help systems and documentation to CLI tools\n- Test CLI applications\n- Package and distribute CLI tools\n\nAlways prioritize:\n- Clear, intuitive command structures\n- Comprehensive error handling\n- Cross-platform compatibility\n- Rich user experience when appropriate\n- Comprehensive testing coverage"},"lastSynced":"2026-02-27T01:55:04.525Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring advanced command-line interface capabilities for argument parsing and validation","zh":"适用于需要高级命令行接口能力的开发者代理，特别是参数解析和验证","ja":"開発者エージェントが高度なコマンドラインインターフェイス機能を必要とする場合に最適です。特に引数の解析と検証","ko":"고급 명령줄 인터페이스 기능이 필요한 개발자 에이전트에게 적합합니다. 특히 인수 파싱 및 유효성 검사","es":"Ideal para Agentes de Desarrollador que requieren capacidades de interfaz de línea de comandos avanzadas para el análisis y validación de argumentos","fr":"Idéal pour les Agents de Développeur nécessitant des capacités d''interface de ligne de commande avancées pour l''analyse et la validation des arguments","de":"Ideal für Entwicklungsagenten, die erweiterte Befehlszeilen-Schnittstellenfunktionen für Argumentanalyse und -validierung erfordern","pt":"Ideal para Agentes de Desenvolvedor que exigem capacidades avançadas de interface de linha de comando para análise e validação de argumentos","ru":"Идеально для агентов разработчиков, требующих расширенных возможностей командной строки для парсинга и проверки аргументов","ar":"مثالي لعميل المطور الذي يتطلب إمكانيات متقدمة لواجهة سطر الأوامر لتحليل وتنفيذ حجة"},"recommendation":{"en":"Empowers agents to create interactive command-line tools and utilities using subcommands, implementing argument parsing and validation with libraries, and designing CLI help systems and documentation for seamless user interaction, all while following CLI best practices and utilizing protocols like stdin/stdout for efficient data exchange","zh":"赋予代理创建交互式命令行工具和实用程序的能力，使用子命令实现参数解析和验证，使用库，并设计CLI帮助系统和文档以实现无缝的用户交互，同时遵循CLI最佳实践并利用stdin/stdout等协议进行高效的数据交换","ja":"サブコマンドを使用して引数の解析と検証を実装し、ライブラリを使用し、CLIヘルプシステムとドキュメントを設計して無駄のないユーザーインタラクションを実現し、CLIのベストプラクティスに従い、stdin/stdoutなどのプロトコルを利用して効率的なデータ交換を行うことで、エージェントが対話型のコマンドラインツールとユーティリティを作成できるようにします","ko":"에이전트가 서브 명령을 사용하여 인수 파싱 및 유효성 검사를 구현하고 라이브러리를 사용하고 CLI 도움말 시스템 및 문서를 설계하여 무결점의 사용자 상호 작용을 가능하게 하고 CLI 최적화 관행을 따르고 stdin/stdout 등 프로토콜을 활용하여 효율적인 데이터 교환을 하면서 대화형 명령줄 도구 및 유틸리티를 만들 수 있도록 합니다","es":"Habilita a los agentes a crear herramientas y utilidades de línea de comandos interactivas utilizando subcomandos, implementando el análisis y la validación de argumentos con bibliotecas, y diseñando sistemas de ayuda de CLI y documentación para una interacción del usuario fluida, siguiendo las mejores prácticas de CLI y utilizando protocolos como stdin/stdout para un intercambio de datos eficiente","fr":"Permet aux agents de créer des outils et des utilitaires de ligne de commande interactifs en utilisant des sous-commandes, en implémentant l''analyse et la validation des arguments avec des bibliothèques, et en concevant des systèmes d''aide CLI et de documentation pour une interaction utilisateur fluide, en suivant les meilleures pratiques de CLI et en utilisant des protocoles comme stdin/stdout pour un échange de données efficace","de":"Ermöglicht es Agenten, interaktive Befehlszeilen-Tools und -Utilities mit Unterbefehlen zu erstellen, das Parsen und die Validierung von Argumenten mit Bibliotheken zu implementieren und Befehlszeilen-Hilfesysteme und Dokumentationen für eine nahtlose Benutzerinteraktion zu entwerfen, während sie den besten Praktiken für Befehlszeilen und den Protokollen wie stdin/stdout für einen effizienten Datenaustausch folgen","pt":"Habilita os agentes a criar ferramentas e utilitários de linha de comando interativos usando subcomandos, implementando a análise e validação de argumentos com bibliotecas e projetando sistemas de ajuda CLI e documentação para interação de usuário sem problemas, seguindo as melhores práticas de CLI e utilizando protocolos como stdin/stdout para troca de dados eficiente","ru":"Наделяет агентов возможностью создавать интерактивные инструменты и утилиты командной строки, используя подкоманды, реализуя парсинг и проверку аргументов с помощью библиотек, и проектируя системы помощи CLI и документацию для бесперебойного взаимодействия с пользователем, при этом следуя лучшим практикам CLI и используя протоколы, такие как stdin/stdout, для эффективного обмена данными","ar":"يمنح الوكلاء khảية إنشاء أدوات وبرامج سطر الأوامر التفاعلية باستخدام أوامر فرعية وتنفيذ تحليل وحجة مع مكتبات وتصميم أنظمة المساعدة سطر الأوامر والتوثيق لتفاعل المستخدم بسلاسة، مع اتباع أفضل الممارسات سطر الأوامر واستخدام بروتوكولات مثل stdin/stdout لنقل البيانات بكفاءة"},"useCases":{"en":["Building interactive CLI applications","Implementing argument parsing and validation for command-line tools","Designing CLI help systems and documentation for user-friendly interfaces"],"zh":["构建交互式CLI应用程序","为命令行工具实现参数解析和验证","为用户友好界面设计CLI帮助系统和文档"],"ja":["対話型CLIアプリケーションの構築","コマンドラインツールの引数解析と検証の実装","ユーザーに親しみやすいインターフェイスのためにCLIヘルプシステムとドキュメントの設計"],"ko":["대화형 CLI 애플리케이션 구축","명령줄 도구를 위한 인수 파싱 및 유효성 검사 구현","사용자 친화적 인터페이스를 위한 CLI 도움말 시스템 및 문서 설계"],"es":["Creación de aplicaciones de interfaz de línea de comandos interactivas","Implementación del análisis y la validación de argumentos para herramientas de línea de comandos","Diseño de sistemas de ayuda de CLI y documentación para interfaces de usuario amigables"],"fr":["Création d''applications de ligne de commande interactives","Implémentation de l''analyse et de la validation des arguments pour des outils de ligne de commande","Conception de systèmes d''aide CLI et de documentation pour des interfaces utilisateur conviviales"],"de":["Erstellung interaktiver Befehlszeilen-Anwendungen","Implementierung des Parsens und der Validierung von Argumenten für Befehlszeilen-Tools","Entwurf von Befehlszeilen-Hilfesystemen und Dokumentationen für benutzerfreundliche Schnittstellen"],"pt":["Construção de aplicações CLI interativas","Implementação de análise e validação de argumentos para ferramentas de linha de comando","Projeto de sistemas de ajuda CLI e documentação para interfaces de usuário amigáveis"],"ru":["Создание интерактивных приложений CLI","Реализация парсинга и проверки аргументов для инструментов командной строки","Проектирование систем помощи CLI и документации для пользовательских интерфейсов"],"ar":["بناء تطبيقات سطر الأوامر التفاعلية","تنفيذ تحليل وحجة للأدوات سطر الأوامر","تصميم أنظمة المساعدة سطر الأوامر والتوثيق لواجهات المستخدم المريحة"]},"limitations":{"en":["Requires knowledge of command-line syntax and scripting","Limited to text-based input/output operations"],"zh":["需要命令行语法和脚本知识","仅限于文本输入/输出操作"],"ja":["コマンドライン構文とスクリプトの知識が必要","テキスト入力/出力操作のみ"],"ko":["명령줄 구문 및 스크립트 지식 필요","텍스트 입력/출력 연산만"],"es":["Requiere conocimiento de la sintaxis de línea de comandos y scripting","Limitado a operaciones de entrada/salida basadas en texto"],"fr":["Nécessite des connaissances en syntaxe de ligne de commande et en scripting","Limité aux opérations d''entrée/sortie basées sur du texte"],"de":["Benötigt Kenntnisse der Befehlszeilensyntax und Skripting","Begrenzt auf textbasierte Ein-/Ausgabevorgänge"],"pt":["Exige conhecimento de sintaxe de linha de comando e scripting","Limitado a operações de entrada/saída baseadas em texto"],"ru":["Требует знания синтаксиса командной строки и скриптинга","Ограничен операциями ввода/вывода на основе текста"],"ar":["يتطلب معرفة بنية سطر الأوامر والبرمجة","محدود للعمليات الإدخال والإخراج القائمة على النص"]},"version":3},"contentHash":"a3874632a8e2e47c6ee3fc9e00298c26f5332f8e6dec16acce97283c51cd3d9c","qualityScore":55}');
