INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('re-cinq/wave/cli', 'cli', 're-cinq', 'wave', 'community', 'cli re-cinq wave community agentic-workflow ai-as-code multi-agent-systems cli是用于AI-assisted开发的多代理管道，通过AI智能代理实现高效开发 cliはAIエージェントを使用したマルチエージェントパイプライン開発ツールであり、高効率な開発を実現します cli는 AI 에이전트를 사용한 멀티 에이전트 파이프라인 개발 도구로써 높은 효율의 개발을 가능하게 합니다 cli ofrece pipelines multiagente para desarrollo asistido por AI, mejorando la eficiencia y productividad cli propose des pipelines multi-agents pour le développement assisté par l''IA, améliorant l''efficacité et la productivité cli bietet Multi-Agent-Pipelines für die künstlich intelligente Entwicklung, die Effizienz und Produktivität verbessern A cli é uma ferramenta de desenvolvimento assistido por IA que utiliza pipelines de multiagentes para melhorar a eficiência ИИ Агенты и cli представляют собой инструменты для разработки, использующие многоагентные конвейеры для повышения эффективности أدوات الذكاء الاصطناعي و cli هي أدوات تنمية مدعومة بالذكاء الاصطناعي التي تستخدم خطوط أنابيب متعددة الوكلاء لتحسين الكفاءة Multi-agent pipelines for AI-assisted development 如何使用cli开发 什么是AI智能代理 cli与其他开发工具的比较 cli安装指南 cli开发教程 AI-assisted开发最佳实践 Multi-agent pipelines for AI-assisted development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nxy7/streampai-elixir/document', 'community', 'nxy7', 'streampai-elixir', 'nxy7/streampai-elixir', 'document', 0, 0, 55, '2026-02-27T13:08:04.205Z', '2026-02-27T13:58:06.657Z', '325a76f8ffc046cc6f0fae06380db01fb6182f85df73416f8d7142c9ce8e1276', '{"id":"nxy7/streampai-elixir/document","name":"document","description":{"zh":"Streampai是实时应用AI工具，帮助管理LiveStreams。它提供实时应用管理功能，帮助开发者高效管理LiveStreams","ja":"StreampaiはリアルタイムアプリケーションAIエージェントであり、LiveStreamsを管理するために役立ちます。開発者はこのツールを使用して、高効率でLiveStreamsを管理できます","ko":"Streampai는 실시간 애플리케이션 AI 에이전트로 LiveStreams를 관리하는 데 도움이 됩니다. 개발자는 이 도구를 사용하여 효율적으로 LiveStreams를 관리할 수 있습니다","es":"Streampai es una aplicación en tiempo real que ayuda a gestionar LiveStreams con herramientas de AI. Mejora tu desarrollo con nuestra documentación","fr":"Streampai est une application en temps réel qui aide à gérer les LiveStreams avec des outils d''IA. Améliorez votre développement avec notre documentation","de":"Streampai ist eine Echtzeit-Anwendung, die bei der Verwaltung von LiveStreams mit KI-Tools hilft. Verbessern Sie Ihre Entwicklung mit unserer Dokumentation","pt":"Streampai é uma aplicação em tempo real que ajuda a gerenciar transmissões ao vivo, oferecendo recursos e documentação para desenvolvedores","ru":"Streampai - это приложение реального времени, которое помогает управлять прямыми трансляциями, предоставляя разработчикам ресурсы и документацию","ar":"Streampai هو تطبيق زمني حقيقي يساعد في إدارة البث المباشر، يقدم موارد ووثائق للمطورين","en":"Streampai is realtime application helping manage LiveStreams."},"seo":{"title":{"zh":"实时应用AI工具：Streampai文档","ja":"リアルタイムアプリケーションAIエージェント：Streampai文書","ko":"실시간 애플리케이션 AI 에이전트: Streampai 문서","es":"Herramientas de AI: Documentación para Streams en Tiempo ...","fr":"Outils d''IA: Document pour les Streams en Direct","de":"KI-Tools: Dokumentation fü