INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nxy7/streampai-elixir/document', 'document', 'nxy7', 'streampai-elixir', 'community', 'document nxy7 streampai-elixir community Streampai是实时应用AI工具，帮助管理LiveStreams。它提供实时应用管理功能，帮助开发者高效管理LiveStreams StreampaiはリアルタイムアプリケーションAIエージェントであり、LiveStreamsを管理するために役立ちます。開発者はこのツールを使用して、高効率でLiveStreamsを管理できます Streampai는 실시간 애플리케이션 AI 에이전트로 LiveStreams를 관리하는 데 도움이 됩니다. 개발자는 이 도구를 사용하여 효율적으로 LiveStreams를 관리할 수 있습니다 Streampai es una aplicación en tiempo real que ayuda a gestionar LiveStreams con herramientas de AI. Mejora tu desarrollo con nuestra documentación Streampai est une application en temps réel qui aide à gérer les LiveStreams avec des outils d''IA. Améliorez votre développement avec notre documentation Streampai ist eine Echtzeit-Anwendung, die bei der Verwaltung von LiveStreams mit KI-Tools hilft. Verbessern Sie Ihre Entwicklung mit unserer Dokumentation Streampai é uma aplicação em tempo real que ajuda a gerenciar transmissões ao vivo, oferecendo recursos e documentação para desenvolvedores Streampai - это приложение реального времени, которое помогает управлять прямыми трансляциями, предоставляя разработчикам ресурсы и документацию Streampai هو تطبيق زمني حقيقي يساعد في إدارة البث المباشر، يقدم موارد ووثائق للمطورين Streampai is realtime application helping manage LiveStreams. 如何使用Streampai 什么是实时应用AI工具 Streampai替代品 Streampai vs 其他工具 Streampai安装 Streampai设置指南 实时应用管理 LiveStreams管理 Streampai is realtime application helping manage LiveStreams.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('6/nitrocop/fix-department', 'community', '6', 'nitrocop', '6/nitrocop', 'fix-department', 1, 0, 55, '2026-03-03T00:49:32Z', '2026-03-03T02:08:58.405Z', '66f9059bf22b2f8ecd011aa570a0247d600603b664b4be9560e9d07ca91ba7c0', '{"id":"6/nitrocop/fix-department","name":"fix-department","description":{"zh":"fix-department 是一个用 Rust 语言实验性重写的 RuboCop 工具。它旨在利用 Rust 的高性能优势，为 Ruby 代码提供更快速、更高效的静态分析和自动修复功能。","ja":"fix-department は、RuboCop を Rust で実験的に書き直した AIエージェントです。Rust の高性能を活用し、Ruby コードのためのより高速で効率的な静的解析と自動修正を提供します。","ko":"fix-department는 RuboCop을 Rust로 실험적으로 재작성한 AI 에이전트입니다. Rust의 높은 성능을 활용하여 Ruby 코드에 더 빠르고 효율적인 정적 분석 및 자동 수정 기능을 제공합니다.","es":"Fix-department es una reescritura experimental de RuboCop en Rust, diseñada para mejorar la eficiencia y el rendimiento","fr":"Fix-department est une réécriture expérimentale de RuboCop en Rust, conçue pour améliorer l''efficacité et les performances","de":"Fix-department ist eine experimentelle Neuschreibung von RuboCop in Rust, die darauf abzielt, die Effizienz und Leistung zu verbessern","pt":"O fix-department é uma reescrita experimental do RuboCop em Rust, visando melhorar a eficiência e a velocidade no desenvolvimento de projetos Ruby.","ru":"Fix-department - это экспериментальная переписанная версия RuboCop на Rust, направленная на улучшение эффективности и скорости разработки проектов Ruby.","ar":"_fix-department هو إعادة كتابة تجريبية لبرنامج RuboCop باستخدام Rust، تهدف إلى تحسين الكفاءة والسرعة في تطوير مشاريع Ruby.","en":"Experimental RuboCop rewrite in Rust"},"seo":{"title":{"zh":"fix-department: Rust 重写的 RuboCop AI 工具 | 实验性","ja":"fix-department: RuboCop を Rust で書き直した AIエージェント","ko":"fix-department: Rust로 재작성된 실험적 RuboCop AI 에이전트","es":"Herramientas de IA: fix-department, reescritura de RuboCo...","fr":"Outils IA: fix-department, réécriture de RuboCop en Rust","de":"KI-Tools: fix-department, RuboCop-Neuschreibung in Rust","pt":"Ferramentas de IA: fix-department, reescrita do RuboCop e...","ru":"ИИ Агенты: fix-department, экспериментальная переписанная...","ar":"أدوات الذكاء الاصطناعي: fix-department، إعادة كتابة RuboC...","en":"fix-department"},"description":{"zh":"fix-department 是一个用 Rust 语言实验性重写的 RuboCop 工具。它旨在利用 Rust 的高性能优势，为 Ruby 代码提供更快速、更高效的静态分析和自动修复功能。","ja":"fix-department は、RuboCop を Rust で実験的に書き直した AIエージェントです。Rust の高性能を活用し、Ruby コードのためのより高速で効率的な静的解析と自動修正を提供します。","ko":"fix-department는 RuboCop을 Rust로 실험적으로 재작성한 AI 에이전트입니다. Rust의 높은 성능을 활용하여 Ruby 코드에 더 빠르고 효율적인 정적 분석 및 자동 수정 기능을 제공합니다.","es":"Fix-department es una reescritura experimental de RuboCop en Rust, diseñada para mejorar la eficiencia y el rendimiento","fr":"Fix-department est une réécriture expérimentale de RuboCop en Rust, conçue pour améliorer l''efficacité et les performances","de":"Fix-department ist eine experimentelle Neuschreibung von RuboCop in Rust, die darauf abzielt, die Effizienz und Leistung zu verbessern","pt":"O fix-department é uma reescrita experimental do RuboCop em Rust, visando melhorar a eficiência e a velocidade no desenvolvimento de projetos Ruby.","ru":"Fix-department - это экспериментальная переписанная версия RuboCop на Rust, направленная на улучшение эффективности и скорости разработки проектов Ruby.","ar":"_fix-department هو إعادة كتابة تجريبية لبرنامج RuboCop باستخدام Rust، تهدف إلى تحسين الكفاءة والسرعة في تطوير مشاريع Ruby.","en":"Experimental RuboCop rewrite in Rust"},"definition":{"en":"Experimental RuboCop rewrite in Rust"},"features":{"zh":["使用 Rust 语言重写，性能显著提升","提供与 RuboCop 兼容的代码检查和自动修复","实验性项目，探索 RuboCop 的高性能替代方案","利用 Rust 的强类型和内存安全特性","专注于为 Ruby 开发社区提供更快的开发工具"],"ja":["Rust での書き直しによりパフォーマンスが大幅向上","RuboCop 互換のコード検査と自動修正を提供","RuboCop の高性能な代替手段を探る実験的プロジェクト","Rust の強力な型システムとメモリ安全性を活用","Ruby 開発コミュニティに高速な開発ツールを提供することに焦点"],"ko":["Rust로 재작성되어 성능이 크게 향상됨","RuboCop과 호환되는 코드 검사 및 자동 수정 제공","RuboCop의 고성능 대안을 탐구하는 실험적 프로젝트","Rust의 강력한 타입 시스템 및 메모리 안전성 활용","Ruby 개발 커뮤니티에 더 빠른 개발 도구 제공에 중점"],"es":["Reescritura de RuboCop en Rust","Mejora de la eficiencia y el rendimiento","Compatibilidad con Ruby","Integración con herramientas de desarrollo","Código abierto y personalizable"],"fr":["Réécriture de RuboCop en Rust","Amélioration de l''efficacité et des performances","Compatibilité avec Ruby","Intégration avec les outils de développement","Code ouvert et personnalisable"],"de":["Neuschreibung von RuboCop in Rust","Verbesserung der Effizienz und Leistung","Kompatibilität mit Ruby","Integration mit Entwicklungstools","Open-Source-Code und anpassbar"],"pt":["Reescrita do RuboCop em Rust","Melhoria da eficiência no desenvolvimento de projetos Ruby","Análise de código mais rápida","Compatibilidade com projetos Ruby","Código aberto e personalizável"],"ru":["Переписанная версия RuboCop на Rust","Улучшение эффективности разработки проектов Ruby","Быстрый анализ кода","Совместимость с проектами Ruby","Открытый и настраиваемый код"],"ar":["إعادة كتابة برنامج RuboCop باستخدام Rust","تحسين الكفاءة في تطوير مشاريع Ruby","تحليل الشفرة الأسرع","التوافق مع مشاريع Ruby","شفرة مفتوحة وقابلة للتعديل"]},"keywords":{"zh":["RuboCop Rust 重写","Ruby 代码分析工具","fix-department 安装","RuboCop 替代方案","Rust 静态分析","如何用 Rust 写 RuboCop","fix-department 使用指南","高性能代码检查"],"ja":["RuboCop Rust 書き直し","Ruby コード解析ツール","fix-department インストール","RuboCop 代替","Rust 静的解析","Rust で RuboCop を書く方法","fix-department 使い方","高性能コードチェック"],"ko":["RuboCop Rust 재작성","Ruby 코드 분석 도구","fix-department 설치","RuboCop 대안","Rust 정적 분석","Rust로 RuboCop 작성 방법","fix-department 사용 가이드","고성능 코드 검사"],"es":["herramientas de ia","rubocop","rust","ruby","mejora de la eficiencia","desarrollo de software","herramientas de desarrollo","código abierto","fix-department vs rubocop"],"fr":["outils ia","rubocop","rust","ruby","amélioration de l''efficacité","développement de logiciels","outils de développement","code ouvert","fix-department vs rubocop"],"de":["ki-tools","rubocop","rust","ruby","verbesserung der effizienz","software-entwicklung","entwicklungstools","open-source-code","fix-department vs rubocop"],"pt":["como usar fix-department","o que é fix-department","alternativas para RuboCop","fix-department vs RuboCop","instalar fix-department","guia de configuração do fix-department","desenvolvimento de projetos Ruby","ferramentas de análise de código"],"ru":["как использовать fix-department","что такое fix-department","альтернативы для RuboCop","fix-department vs RuboCop","установить fix-department","руководство по настройке fix-department","разработка проектов Ruby","инструменты для анализа кода"],"ar":["كيفية استخدام fix-department","ما هو fix-department","بديلات لبرنامج RuboCop","fix-department مقابل RuboCop","تثبيت fix-department","دليل إعداد fix-department","تطوير مشاريع Ruby","أدوات تحليل الشفرة"]}},"owner":"6","repo":"nitrocop","repoPath":"6/nitrocop","stars":1,"forks":0,"updatedAt":"2026-03-03T00:49:32Z","topics":["rubocop","ruby","rust"],"category":"community","skillMd":{"name":"fix-department","description":"Get all cops in a gem to 100% corpus conformance. Assesses, triages, and fixes all diverging cops in a target gem using worktree-isolated teammates.","bodyPreview":"# Fix Department — Gem-Level 100% Conformance\n\nThis skill targets a specific gem (e.g., rubocop-performance) and fixes ALL diverging\ncops until it reaches 100% corpus conformance (0 FP + 0 FN). Unlike `/fix-cops` which\nfixes the globally worst cops, this focuses on *completing* one gem at a time to unlock\nincremental adoption.\n\nIf you edit code yourself (without dispatching teammates), do that work in a dedicated\ngit worktree by default. Only skip this when the user explicitly asks to use the cu","body":"# Fix Department — Gem-Level 100% Conformance\n\nThis skill targets a specific gem (e.g., rubocop-performance) and fixes ALL diverging\ncops until it reaches 100% corpus conformance (0 FP + 0 FN). Unlike `/fix-cops` which\nfixes the globally worst cops, this focuses on *completing* one gem at a time to unlock\nincremental adoption.\n\nIf you edit code yourself (without dispatching teammates), do that work in a dedicated\ngit worktree by default. Only skip this when the user explicitly asks to use the current tree.\n\n## Workflow\n\n### Phase 0: Assess (you do this)\n\n1. **Always start with the scoreboard.** Run the script and **paste its full output verbatim\n   to the user** (the table IS the primary output — do not summarize or skip it):\n   ```bash\n   python3 .claude/skills/fix-department/scripts/gem_progress.py --summary\n   ```\n   The script automatically detects cops fixed since the last corpus oracle run by\n   scanning git commit messages, and shows them as \"Fixed (pending corpus confirmation)\"\n   so the scoreboard reflects reality between corpus runs.\n   The script also prints a recommendation at the bottom.\n\n2. **If no gem was specified**, after showing the table, let the user pick a gem.\n\n3. **Once a gem is chosen** (by user or from args), run the deep-dive:\n   ```bash\n   python3 .claude/skills/fix-department/scripts/gem_progress.py --gem <gem-name>\n   ```\n\n4. Show the user the gem status and confirm the target.\n\n### Phase 1: Plan Batch (you do this)\n\nFrom the deep-dive output, select **up to 4 cops** for this batch. Priority order:\n\n1. **FP-only cops** (FP>0, FN=0) — pure false alarms, usually straightforward to fix\n2. **Both FP+FN cops** with highest FP — fix the FP side first\n3. **FN-only cops** (FP=0, FN>0) — missing detections, lower priority but needed for 100%\n\nSkip Layout/ alignment cops unless they''re the only ones remaining (complex multi-line state machines).\n\nFor each selected cop, investigate the FP/FN pattern:\n```bash\npython3 scripts/investigate-cop.py Department/CopName --context --fp-only --limit 10\npython3 scripts/investigate-cop.py Department/CopName --context --fn-only --limit 10\n```\n\n**Run the delta reducer** on up to 3 examples per cop (mix of FP and FN) to get minimal reproductions:\n```bash\npython3 scripts/reduce-mismatch.py Department/CopName repo_id filepath:line            # FP\npython3 scripts/reduce-mismatch.py Department/CopName repo_id filepath:line --type fn   # FN\n```\nPick examples from different repos when possible. The reduced files (typically 5–20 lines) go\nto `/tmp/nitrocop-reduce/` — read them and include them in the teammate prompt.\n\nSummarize: cop name, FP/FN counts, minimal repro(s), root cause hypothesis.\n\n### Phase 2: Dispatch (you do this)\n\n1. Create a team:\n   ```\n   TeamCreate(team_name=\"fix-department\", description=\"Bring <gem-name> to 100% conformance\")\n   ```\n\n2. Create tasks for each cop fix.\n\n3. Spawn one teammate per cop using the Task tool. **Critical settings:**\n   - `isolation: \"worktree\"` — each teammate gets its own git worktree\n   - `subagent_type: \"general-purpose\"` — needs full edit/bash access\n   - `team_name: \"fix-department\"`\n   - `mode: \"bypassPermissions\"` — teammates need to run cargo test etc.\n\n4. Each teammate prompt MUST include:\n   - The exact cop name (e.g., `Performance/AncestorsInclude`)\n   - The FP/FN counts and root cause hypothesis from your investigation\n   - **The minimal repro(s) from the delta reducer** — paste the reduced Ruby source directly\n   - Whether to focus on FP fixes, FN fixes, or both\n   - A reminder that parallel-agent activity often leaves unrelated local modifications; those files are off-limits\n   - The teammate workflow (Phase 3 below) — paste the full instructions\n\n### Phase 3: Teammate Workflow (paste this into each teammate''s prompt)\n\n```\nYou are fixing false positives/negatives in a single nitrocop cop to bring its gem\nto 100% corpus conformance. Follow the CLAUDE.md rules strictly.\n\n**NEVER use git stash or git stash pop.** You are in an isolated git worktree — just commit directly.\nParallel-agent activity is common. If you see unrelated modified files, do not edit/revert them.\n\n## Steps\n\n1. **Read the cop source** at `src/cop/<dept>/<cop_name>.rs`\n   Read the vendor RuboCop spec at `vendor/rubocop*/spec/rubocop/cop/<dept>/<cop_name>_spec.rb`\n   **Check for existing investigation comments** (marked with \"Known false positives\" or\n   \"reverted\") — these document previously attempted fixes that regressed on corpus\n   validation. Do NOT repeat the same approach. Either find a different root cause or\n   extend the prior approach to avoid its documented failure mode.\n\n2. **Understand the FP/FN pattern** from the examples provided in your prompt.\n   If needed, read the actual source files from `vendor/corpus/<repo_id>/<path>` to see more context.\n\n3. **Add test cases (TDD)**:\n   - For FP fixes: add the false-positive pattern to `tests/fixtures/cops/<dept>/<cop_name>/no_offense.rb`\n   - For FN fixes: add the missed detection to `tests/fixtures/cops/<dept>/<cop_name>/offense.rb`\n   - Run `cargo test --release -p nitrocop --lib -- <cop_name_snake>` to verify the test FAILS\n\n4. **Fix the cop implementation** in `src/cop/<dept>/<cop_name>.rs`\n\n5. **Verify**:\n   - `cargo test --release -p nitrocop --lib -- <cop_name_snake>` — all tests pass\n   - `cargo fmt`\n   - `cargo clippy --release -- -D warnings`\n\n6. **Commit your fix**:\n   ```bash\n   git add src/cop/<dept>/<cop_name>.rs tests/fixtures/cops/<dept>/<cop_name>/\n   # Add any other changed files\n   git commit -m \"Fix <Department/CopName> false positives/negatives\n\n   <one-line description of what was wrong>\n\n   Co-Authored-By: Claude Opus 4.6 <noreply@anthropic.com>\"\n   ```\n   Stage only files for this cop fix. Do not include unrelated modified files.\n\n7. **Report back** via SendMessage with:\n   - What the root cause was\n   - What you changed\n   - Whether tests pass\n   - The commit SHA\n   - If you could NOT fix it: explain why and whether it should be deferred\n```\n\n### Phase 4: Collect + Loop (you do this)\n\n1. Wait for all teammates to report back.\n\n2. For each completed fix:\n   - Note the worktree branch name from the Task result\n   - Cherry-pick or merge the commit into your working branch\n\n3. Run full verification:\n   ```bash\n   cargo fmt\n   cargo clippy --release -- -D warnings\n   cargo test --release\n   ```\n\n4. Verify each fixed cop against the corpus:\n   ```bash\n   python3 scripts/check-cop.py Department/CopName --verbose --rerun\n   ```\n   **Corpus validation is the acceptance gate** — unit tests passing is necessary but\n   NOT sufficient.\n\n5. **Handle regressions**: if a fix increases FP count (even if unit tests pass), revert\n   the code change but **add a detailed investigation comment** to the cop source file\n   documenting what was tried, exactly where code changed, acceptance-gate numbers\n   before/after, why it regressed, and what a correct fix would need. Use:\n   ```rust\n   /// ## Known false positives (N FP in corpus as of YYYY-MM-DD)\n   ///\n   /// An attempt was made to ... (commit XXXXXXXX, reverted). The approach: ...\n   /// Code path changed: <file::function and condition changed>.\n   /// Acceptance gate before: expected=?, actual=?, excess=?, missing=?\n   /// Acceptance gate after: expected=?, actual=?, excess=?, missing=?\n   /// This fixed the target FPs but introduced N NEW false positives (X→Y FP).\n   /// Root cause of regression: ...\n   /// A correct fix needs to: ...\n   ```\n\n6. Re-run the gem deep-dive to see updated progress:\n   ```bash\n   python3 .claude/skills/fix-department/scripts/gem_progress.py --gem <gem-name>\n   ```\n   Note: This still reads the original corpus data. Per-cop verification via check-cop.py\n   gives the ground truth for fixed cops.\n\n6. If diverging cops remain, go back to Phase 1 for the next batch.\n\n7. For cops that teammates couldn''t fix, decide whether to:\n   - Retry with more context in the next batch\n   - Defer with a documented reason\n\n### Phase 5: Declare Done (you do this)\n\nWhen all cops in the gem are at 0 FP + 0 FN (or explicitly deferred):\n\n1. Run full verification:\n   ```bash\n   cargo fmt\n   cargo clippy --release -- -D warnings\n   cargo test --release\n   ```\n\n2. Report to the user:\n   - Gem name and total cops\n   - How many cops were fixed (with FP/FN reduction)\n   - How many cops were already perfect\n   - Any deferred cops with reasons\n   - Summary: \"rubocop-performance: 100% corpus conformance (N cops, M fixed in this session)\"\n\n3. Remind the user to trigger a fresh corpus oracle run to confirm the result.\n\n### Phase 6: Integrate Back to Main (Default)\n\nDo not leave retained progress only in a worktree/collector branch.\n\n1. Ensure all retained progress is committed:\n   - Accepted cop fixes: one commit per cop (preferred).\n   - Useful investigation artifacts retained in repo (for example, reverted-attempt notes): separate commit.\n\n2. Integrate those commit(s) into `main` immediately (unless the user explicitly says not to):\n   ```bash\n   git -C /path/to/main checkout main\n   git -C /path/to/main cherry-pick <sha1> [<sha2> ...]\n   ```\n   If a merge is preferred, use a normal non-interactive merge.\n\n3. Verify integration on `main`:\n   ```bash\n   git -C /path/to/main log --oneline -n 10\n   git -C /path/to/main status --short --branch\n   ```\n\n4. Report exactly what was integrated (commit SHA(s) and short subjects).\n\n5. If there is truly no repo-retained progress, explicitly report that no commit was made.\n\n## Arguments\n\n- `/fix-department` — **show the scoreboard, recommend a gem, and ask** which to target\n- `/fix-department rubocop-performance` — target rubocop-performance directly\n- `/fix-department rubocop-rspec` — target rubocop-rspec directly\n- `/fix-department --input /path/to/corpus-results.json` — use local corpus file\n\n## How to Choose the Next Gem\n\nThe scoreboard (`gem_progress.py --summary`) shows per-gem stats. Prioritize by:\n\n1. **Zero untested cops** — only gems where every cop triggered on the corpus\n   can claim true 100% conformance. Gems with untested cops get an asterisk. The \"Untest\"\n   column in the scoreboard shows this.\n2. **Fewest diverging cops** — less work to complete the gem. The \"Dvrg\" column shows this.\n3. **Adoption value** — rubocop-performance is the most commonly added plugin, so completing\n   it has more impact than rubocop-factory_bot, even if factory_bot is smaller.\n4. **FP-free first** — a gem with 0 FP but some FN is already safe to adopt (no false alarms).\n   Fix FNs later for completeness.\n"},"lastSynced":"2026-03-03T02:08:58.405Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Refactoring Agents needing advanced RuboCop integration and 100% corpus conformance","zh":"适用于需要高级 RuboCop 集成和 100% 语料库一致性的代码重构代理","ja":"React や Python などのコードリファクタリングエージェントに適し、RuboCop の高度な統合と 100% のコーパスの一致性が必要","ko":"고급 RuboCop 통합과 100% 코퍼스 일치성이 필요한 코드 리팩토링 에이전트에 적합","es":"Perfecto para agentes de refactorización de código que necesitan una integración avanzada de RuboCop y un 100% de conformidad del corpus","fr":"Parfait pour les agents de refactoring de code nécessitant une intégration avancée de RuboCop et une conformité de corpus à 100%","de":"Perfekt für Code-Refactoring-Agents, die eine erweiterte RuboCop-Integration und 100%ige Korpus-Konformität benötigen","pt":"Perfeito para Agentes de Refatoração de Código que necessitam de integração avançada do RuboCop e conformidade de corpus de 100%","ru":"Идеально подходит для агентов рефакторинга кода, требующих расширенной интеграции RuboCop и 100% соответствия корпуса","ar":"مثالي لعميل إعادة هيكلة الكود الذي يحتاج إلى إدماج RuboCop متقدم وامتثال شبه completo من 100%"},"recommendation":{"en":"Empowers agents to achieve 100% gem-level conformance by fixing all diverging cops using Rust-based RuboCop rewrite, enabling incremental adoption and ensuring 0 FP + 0 FN, while utilizing dedicated git worktrees for seamless code editing","zh":"赋予代理实现 100% 宝石级别一致性的能力，通过使用基于 Rust 的 RuboCop 重写来修复所有偏离的警察，从而实现增量采纳和确保 0 FP + 0 FN，同时利用专用 git 工作树实现无缝的代码编辑","ja":"Rust ベースの RuboCop の書き換えを使用して、すべての乖離コップを修正し、100% の Gem レベルの一致性を実現し、増分導入を可能にし、0 FP + 0 FN を保証し、専用の git ワークツリーを使用してシームレスなコード編集を実現する","ko":"루비코프의 고급 통합을 통해 100%의 젬 레벨 일치성을 달성하고, 러스트 기반의 루비코프 리ライト를 사용하여 모든 나가는 경찰을 수정하여 증분적採用와 0 FP + 0 FN를 보장하며,専用 git 작업 트리를 사용하여 무결점의 코드 편집을 가능하게 함","es":"Habilita a los agentes a lograr una conformidad a nivel de gema del 100% al corregir todos los policías divergentes utilizando la reescritura de RuboCop basada en Rust, permitiendo una adopción incremental y garantizando 0 FP + 0 FN, mientras utiliza árboles de trabajo de git dedicados para una edición de código sin problemas","fr":"Permet aux agents d''atteindre une conformité à 100% au niveau des gemmes en corrigeant tous les policiers divergents en utilisant la réécriture de RuboCop basée sur Rust, permettant une adoption incrémentale et garantissant 0 FP + 0 FN, tout en utilisant des working trees git dédiés pour une édition de code sans problème","de":"Ermöglicht es den Agenten, 100%ige Konformität auf Gema-Ebene zu erreichen, indem alle divergierenden Cops mithilfe der auf Rust basierenden RuboCop-Neuschreibung korrigiert werden, was eine inkrementelle Übernahme ermöglicht und 0 FP + 0 FN garantiert, während dedizierte Git-Arbeitsbereiche für eine nahtlose Codebearbeitung verwendet werden","pt":"Habilita os agentes a alcançar 100% de conformidade de nível de gem, corrigindo todos os policiais divergentes usando a reescrita do RuboCop baseada em Rust, permitindo a adoção incremental e garantindo 0 FP + 0 FN, enquanto utiliza árvores de trabalho dedicadas do git para edição de código sem interrupções","ru":"Наделяет агентов возможностью достичь 100% соответствия на уровне gem, исправляя все расходящиеся копы, используя переписывание RuboCop на основе Rust, обеспечивая инкрементальное внедрение и гарантируя 0 FP + 0 FN, а также использует выделенные рабочие деревья git для бесшовного редактирования кода","ar":"يمكّن الوكلاء من تحقيق 100% من الامتثال على مستوى الجوهرة ، من خلال إصلاح جميع رجال الشرطة المتفرقة باستخدام إعادة كتابة RuboCop المعتمدة على Rust ، وتمكين اعتماد تدريجي وضمان 0 FP + 0 FN ، بينما يستخدم أشجار عمل مخصصة من git لتحرير الكود بدون انقطاع"},"useCases":{"en":["Automating gem-level conformance for rubocop-performance","Fixing diverging cops to reach 100% corpus conformance","Streamlining code refactoring with dedicated git worktrees"],"zh":["为 rubocop-performance 实现宝石级别一致性自动化","修复偏离的警察以达到 100% 语料库一致性","使用专用 git 工作树简化代码重构"],"ja":["rubocop-performance の Gem レベルの一致性自動化","乖離コップの修正による 100% コーパスの一致性の達成","専用の git ワークツリーを使用したコードリファクタリングの合理化"],"ko":["루비코프-퍼포먼스에 대한 젬 레벨 일치성 자동화","나가는 경찰을 수정하여 100% 코퍼스 일치성을 달성","전용 git 작업 트리를 사용한 코드 리팩토링의 간소화"],"es":["Automatización de la conformidad a nivel de gema para rubocop-performance","Corrección de los policías divergentes para alcanzar una conformidad del corpus del 100%","Optimización del refactorizado de código con árboles de trabajo de git dedicados"],"fr":["Automatisation de la conformité au niveau des gemmes pour rubocop-performance","Correction des policiers divergents pour atteindre une conformité de corpus à 100%","Optimisation du refactoring de code avec des working trees git dédiés"],"de":["Automatisierung der Konformität auf Gema-Ebene für rubocop-performance","Korrektur der divergierenden Cops, um eine 100%ige Konformität des Korpus zu erreichen","Optimierung des Code-Refactorings mit dedizierten Git-Arbeitsbereichen"],"pt":["Automatizar a conformidade de nível de gem para rubocop-performance","Corrigir policiais divergentes para alcançar 100% de conformidade de corpus","Otimizar a refatoração de código com árvores de trabalho dedicadas do git"],"ru":["Автоматизировать соответствие на уровне gem для rubocop-performance","Исправить расходящиеся копы, чтобы достичь 100% соответствия корпуса","Оптимизировать рефакторинг кода с помощью выделенных рабочих деревьев git"],"ar":["تأتمتة الامتثال على مستوى الجوهرة لrubocop-performance","إصلاح رجال الشرطة المتفرقة للوصول إلى 100% من الامتثال الشبه","تبسيط إعادة هيكلة الكود مع أشجار العمل المخصصة من git"]},"limitations":{"en":["Requires Rust-based RuboCop rewrite","Gem-level conformance focus may limit global cop fixing","Explicit user request required to bypass dedicated git worktree"],"zh":["需要基于 Rust 的 RuboCop 重写","宝石级别一致性焦点可能限制全局警察修复","需要明确的用户请求来绕过专用 git 工作树"],"ja":["Rust ベースの RuboCop の書き換えが必要","Gem レベルの一致性焦点により、グローバルコップの修正が制限される可能性","専用の git ワークツリーを回避するには、明示的なユーザー要求が必要"],"ko":["러스트 기반의 루비코프 리ライト 필요","젬 레벨 일치성에 대한 중점으로 인해 전역 경찰 수정이 제한될 수 있음","전용 git 작업 트리를 우회하려면 명시적인 사용자 요청이 필요"],"es":["Requiere una reescritura de RuboCop basada en Rust","El enfoque en la conformidad a nivel de gema puede limitar la corrección global de los policías","Se requiere una solicitud explícita del usuario para omitir el árbol de trabajo de git dedicado"],"fr":["Nécessite une réécriture de RuboCop basée sur Rust","L''accent mis sur la conformité au niveau des gemmes peut limiter la correction globale des policiers","Une demande explicite de l''utilisateur est requise pour contourner l''arbre de travail git dédié"],"de":["Erfordert eine auf Rust basierende RuboCop-Neuschreibung","Der Fokus auf die Konformität auf Gema-Ebene kann die globale Korrektur der Cops einschränken","Eine explizite Benutzeranfrage ist erforderlich, um den dedizierten Git-Arbeitsbereich zu umgehen"],"pt":["Exige reescrita do RuboCop baseada em Rust","O foco na conformidade de nível de gem pode limitar a correção global de policiais","Requer solicitação explícita do usuário para contornar a árvore de trabalho dedicada do git"],"ru":["Требует переписывания RuboCop на основе Rust","Фокус на соответствии на уровне gem может ограничить глобальное исправление копов","Требует явного запроса пользователя для обхода выделенной рабочей деревни git"],"ar":["يتطلب إعادة كتابة RuboCop المعتمدة على Rust","التركيز على الامتثال على مستوى الجوهرة قد يقيد إصلاح رجال الشرطة العالمي","يتطلب طلبًا صريحًا من المستخدم للتحايل على شجرة العمل المخصصة من git"]},"version":3},"contentHash":"66f9059bf22b2f8ecd011aa570a0247d600603b664b4be9560e9d07ca91ba7c0","qualityScore":55}');
